# -*- coding: utf-8 -*-
"""测谎小游戏的目标追踪器（M2a：离线回放用；实机接线在 M3，见 docs/测谎设计.md）。

问题本质（素材实证，见 docs/测谎设计.md §2 / SKILL 147）：
  · 开局目标是一块**白色实体**形状 —— 画面里唯一"高亮 + 低饱和"的东西
    （倒计时数字是**蓝色** ✓ 饱和度滤波正好把它排掉 ✓）；
  · 倒计时结束目标开始运动并**渐透明**，几秒后单帧不可辨认 ⇒ 只能靠**时序**追；
  · 干扰形状与背景一起滚动 ⇒ **帧间全局运动补偿之后，唯一还有残差的就是目标** ✓
    —— 这正是选运动路线的原因：对透明免疫、对形状免疫（用户 2026-09-29 确认：
    "其实是不是一个形状无所谓，只要找到运动方式不同的那个就行" ✓）。

用法（离线回放）：
    tr = LieTracker()
    for bgr in frames:                       # 全分辨率弹窗视口帧（750×500）
        out = tr.process(bgr, ts=t)          # {"state","pos","area","lost_n",...}
    # state: "init"（还没认出目标）/ "track"（融合/锁定/预测三态都在里面 ✓ `lost` 已废除 ✓）

口径纪律：
  · 追踪器**不认识形状**（任何形状都能用 ✓）、**不认识颜色**（白色只用在建档那一步 ✓）；
  · 丢了就**如实报 lost**（不猜 ✗）；回放器据此扣分。
"""
import math

import cv2
import numpy as np

from perception import geom
from perception.kf import KF4
from perception.lie_group import GroupMotion
from perception.lie_registry import ShapeRegistry, _BOARD_OVERLAP_DEF

# ---- 参数（全部集中在头部，回放迭代就在这里调 ✗ 别散进函数体）----
_SCALE = 0.5              # 跟踪阶段的工作分辨率（0.5 = 半分辨率，噪声/算力折中 ✓）
# ⭐⭐⭐ 重构（2026-09-30 用户认可 ✓）：框只当**事件**用，不当位置测量 ✓
_MERGE_RATIO = 1.4        # 框面积 > 标准 × 它 ⇒ **并集块/融合框**（融合期 ✓ 用户事实 5）——
                          #   ⚠ **2026-10-03 起它只是"内部面积倍率"**（不再可配 ✗）：用户把界面上
                          #   那个配置**换成 IoU**了 ✓（见 `_MERGE_IOU` ✓ 原话："把『融合框判定
                          #   阈值』换成『**融合框判定 IoU**』：**小于这个 IoU 才行**，之前配的
                          #   1.2 改成 **0.5**" ✓）⇒ 本常量只留给"没有砖框可算 IoU"的**粗判**用 ✓
                          #   （`_box_flags` 的"并集块"识别 ✓）。
_MERGE_IOU_OUT = 0.5      # ⭐⭐⭐ **「融合框判定 IoU · 退出」默认值 = 与进入相同 ⇒ 迟滞默认【关】**
                          #   ⚠⚠ **实测定案（2026-10-03 ✓ 对照台 `tools/ab_compare.py` ✓）**：
                          #     迟滞挪到**保持侧**（`_iou_below_out` ✓）之后，效果**一半有效** ✗✓：
                          #       · `10月1日.mp4` 融合 23 → **55** 帧 ✓✓（折角 103.7 → 87.5 ✓）
                          #       · `10月3日.mp4` 26 → **28** ✓（折角 72.9 → 73.7 ✓ 持平）
                          #       · `10月2日.mp4` 23 → **4** ✗✗（折角 ↓ 到 34.9 ✓ 但会话没了 ✗）
                          #       · `9月30日(1).mp4` 22 → **2** ✗✗（折角 100.5 → 124.5 ✗）
                          #     ⇒ 净效果**因素材而异** ⇒ **默认关**（= 与本值相同 ⇒ 退回单阈值 ✓）
                          #       让用户在界面上按素材决定开不开 ✓（"退出 IoU"控件 ✓）。
                          #   ⚠ 另一条教训（务必保留 ✗）：**迟滞绝不能做在"进入判据"上** ✗✗ ——
                          #     那样会"更多框被当融合候选 ⇒ 选框更爱换框 ⇒ 会话更碎"（实测 10月2日
                          #     融合 23 → **1** 帧 ✗✗）。
                          #   （历史：第 1 步初版取 **0.75** ✓ 就是上面那组实测用的值 ✓
                          #     要试它就填 0.75 ✓）
                          #   "迟滞双阈值" ✓ —— 治"参数太松放大错误 / 太严没有指导值"那条两难 ✓）：
                          #   · **进入**用 `merge_iou`（严 ✓ `IoU < 它` 才算并集 ✓）；
                          #   · **已在融合保持期** ⇒ 用**本值**（松 ✓）：要 `IoU > 它`（= 两框已经
                          #     **明显是同一格** ✗ 不再像并集 ✓）才**掉出**融合 ✓。
                          #   ⇒ 一个值管进、一个值管出 ⇒ 边界不再"进进出出"横跳 ✓
                          #     （同一对值也能直接退回单阈值：把本值设成 = `merge_iou` ✓）。
                          #   ⚠ 用户已试过这两个数 ✓（0.5 = 进入 ✓、0.75 ≈ 旧面积比 1.33 ✓ = 退出 ✓）。
_RING_COV_SEP = 0.80      # ⭐⭐⭐ **「分离期 · 圆外接矩形与检出框相交的比例 >」默认值**（用户
                          #   2026-10-03 ✓ 口径修订 ✓ 原话："将所有的『**检出框与圆外接矩形 IoU > ___
                          #   时，与内砖 IoU < ___ 判定为融合**』改为『**圆外接矩形与检出框相交的
                          #   比例 > ___ 时，检出框与内砖 IoU < ___ 判定为融合**』" ✓）：
                          #   融合判定的**第①条前置** ✓（见 `_ring_cov` ✓）。
                          #   ⚠⚠ **分母换了 ⇒ 量级整个抬了一档**（务必知悉 ✗）：**旧** = 交÷**并集**
                          #     （IoU ✗ 框一大就摊薄 ⇒ 同局面只有 0.35~0.5 ✗）；**新** = 交÷**圆外接
                          #     矩形面积** ✓（单向 ✓ "绿圈那块地方有多少落在框里" ✓ ⇒ **同局面 = 1.0**
                          #     ✓）⇒ **别再拿 0.35 来配** ✗（那等于"35% 的绿圈落在框里就算" ⇒ 形同
                          #     虚设 ✗）；**可用区 ≈ 0.7~0.95** ✓，默认 **0.80** = "**八成落在框里**" ✓。
_RING_COV_FUSE = 0.80     # ⭐⭐⭐ **「融合期 · 圆外接矩形与检出框相交的比例 >」默认值**（用户
                          #   2026-10-03 ✓ 第 3 行 ✓ 原话："第3行融合期：……**否则就算分离**" ✓）——
                          #   融合期每拍用**这一对**判"还该不该继续融合" ✓ 不满足 ⇒ **判分离** ✓。
                          #   ⚠ 量级同 `_RING_COV_SEP`（相交比例 ✓ 不是 IoU ✗）。
_BRICK_IOU_SEP = 0.5      # ⭐⭐⭐ **「分离期 · 框↔内砖 IoU <」默认值**（用户 2026-10-03 ✓ 第 2 行 ✓）：
                          #   `IoU(检出框, 它压着的那块砖) < 它` ⇒ 才算"**两框不是同一格**（并集）" ✓
                          #   ⚠ 这就是"迟滞的下半段" ✓（**进=分离期阈值严** ✓ **守=融合期阈值松** ✓）；
                          #   取默认 `0.5` = 与第 1 行"同检出 IoU"同值 ✓（= 退回单阈值 ✓）。
_BRICK_IOU_FUSE = 0.7     # ⭐⭐⭐ **「融合期 · 框↔内砖 IoU <」默认值**（用户 2026-10-03 ✓ 第 3 行 ✓）：
                          #   融合保持期内用它 ✓ ⇒ **>` 它**（两框已明显同一格 ✗ 不像并集了）⇒
                          #   **掉出融合（判分离）** ✓。取 **0.70**（用户界面当时用的值 ✓）。
_MERGE_IOU = 0.5          # ⭐⭐⭐ **「融合框判定 IoU」默认值**（用户 2026-10-03 ✓ 原话："把
                          #   『融合框判定阈值』换成『**融合框判定 IoU**』：**小于这个 IoU 才行**，
                          #   之前配的 1.2 改成 **0.5**" ✓）：
                          #   · **判据** = `IoU(检出框, 该砖的登记框) < 本值` ⇒ 才算融合框 ✓
                          #     （对称地：`IoU ≥ 本值` ⇒ 两者**基本是同一格** ⇒ 那是"砖自己那一格"
                          #      ✗ 不是并集 ✗ 见 `_brick_owned` ✓）；
                          #   · 语义比面积比**尺度无关** ✓（大框套小砖：面积比恒 > 1.4 ✗ 但 IoU
                          #     只有 0.2~0.5 ✓ ⇒ 面积比在"框远大于砖"时**分不出**"并集"与
                          #     "框只是大"✗；IoU 能 ✓）；
                          #   · **0 = 关**（= 不靠这条判融合 ✓ 但规则② 照旧 ✓）；越**小**越严 ✓
                          #     （要求框与砖**越不重叠**才算并集 ✓）；夹进 `[0, 1]` ✓。
_ALLOW_BACK_RATIO = 0.0   # ⭐⭐⭐ **「融合框挑选允许倒退距离(绿圆半径比例)」默认值**（用户 2026-10-02 ✓
                          #   可配 ✓ 界面在第二行 ✓）：融合框候选第二条闸（"落位会不会把圆拽向
                          #   反方向" ✓ 见 `_merge_fix_safe` ✓）的**容差** ✓ —— 落位点在白箭头
                          #   方向上的**位移分量** ≥ `−它 × 绿圈半径` 就算安全 ✓。
                          #   ⭐ 用户 2026-10-02 口径修订（原话："『融合框挑选允许倒退距离(px)』
                          #   改为『**融合框挑选允许倒退距离(绿圆半径比例)**』" ✓）：物理量不变，
                          #   只是**换成以绿圈半径为尺** ⇒ 半径变了（实测 56~61px）判别不变 ✓。
                          #   · **0 = 一点都不能倒退**（= 上一版的布尔判据 ✓ 默认 ✓ 最保守 ✓）；
                          #   · 调大 ⇒ 允许"倒退一点点"的框也当候选 ✓ ⇒ 候选变多、融合段更连续 ✓
                          #     （代价：圆偶尔会被落位往反方向拽几像素 ✓）。
                          #   ⚠ 换算参考：旧配置 20px ÷ 实测半径中位 60.8 ⇒ 约 **0.33** ✓。
_SWAP_OV = 0.5            # ⭐⭐⭐ **融合"续任"的重叠门槛 = IoU**（用户 2026-10-03 ✓ 方案 ② ✓ 原话：
                          #   "9月30日(1)，帧44→45 融合框被替换了检出框，有什么方法能够判定并
                          #   屏蔽掉这种现象吗" ✓；⭐ 同日**口径修订** ✓ 原话："**改成 IoU
                          #   （交集 ÷ 并集）**" ✓）：融合**保持期内**，先找"上一拍那个融合框在
                          #   这一拍的**延续格**" = 与上一拍红框 **IoU 最大**的门内格 ✓；够这个
                          #   门槛（默认 0.5 ✓）才认作"还是那个框" ✓。
                          #   ⚠⚠ 为什么必须换口径 ✗（实测 `10月1日.mp4` 帧 23 踩到 ✓）：旧口径
                          #     "交集 ÷ **较小面积**"下，**小框被大框整个包住 ⇒ 恒≈1** ✗ ⇒
                          #     conf 0.80 的那个小框以 **0.901** 赢了 **0.897** ✗（而两者 IoU 是
                          #     **0.503 vs 0.790** ✓）⇒ 红框被换成"缩下来的一小块" ✗；换成 IoU ⇒
                          #     "谁跟上一拍那格**更像同一格**"一目了然 ✓ 见 `_box_iou` ✓。
                          #   · 延续格仍够格 ⇒ **这一拍只许用它** ✓（不许被别的格抢走 ✗）；
                          #   · 不够门槛 ⇒ `_succ = None` ⇒ 照旧自由挑 ✓（不阻新会话 ✓）。
                          #   ⚠ 2026-10-03 起"延续格命中分离信号 ⇒ 判分离"**已删** ✗（用户：
                          #     "只留『框丢了』，其余删" ✓）⇒ 延续格现在**只**用于"只许用它" ✓。
_SEP_VEL_MAX = 1.0        # ⭐⭐⭐ **「真目标预测最大速度倍率」默认值**（用户 2026-10-03 ✓ 原话：
                          #   "将**分离期（淡粉色框时期）**的**最大相对假目标群速度（白箭头）**
                          #   = a × **假目标群体的标准速度**，a 为新配置『**真目标预测最大速度
                          #   倍率**』默认 1.0" ✓）：分离期（= **红框丢失、淡粉接力框那段预测期**
                          #   ✓ `self._tbox is None` ✓）里，白箭头（`vel_rel` ✓ 相对假目标群的
                          #   速度 ✓）的**模长上限** = `a × 当拍实测群体速度模长` ✓。
                          #   · **只压不抬** ✓（没超上限就一个字不动 ✓）；
                          #   · 方向不变 ✓ ⇒ "白箭头 = 圆心真的会走多少"仍成立 ✓；
                          #   · 群体速度判不出（`_group_vel` 回 `None` ✓ 没观测 ✓）⇒ **不夹** ✓。
_EDGE_MAX = 4             # ⭐⭐⭐ **「砖最多拥有融合框边数量」默认值**（用户 2026-10-02 ✓ 原话：
                          #   "增加参数：『**砖最多拥有融合框边数量**』(1~4)，注意在多条边选取
                          #   最近的**前 x 条**" ✓ 可配 ✓ 界面在配置行 ✓）：融合框四边的「边归属」
                          #   （`_edge_ownership` ✓）里，归砖的边**只保留距离最近的这么条** ✓
                          #   ⇒ 更远的那几条改判"真目标提供的边" ✓。
                          #   · **4（默认）= 不截断**（老行为一字不变 ✓）；
                          #   · 1~3 ⇒ 一块砖最多占住这么多条边 ⇒ 落位五档里"三假边"那一档
                          #     （d ✓）的触发条件随之变化 ✓、"四假边 ⇒ 不落位"（e ✓）在
                          #     `edge_max<4` 时**根本不会发生** ✓。
_INHERIT_DIST_ON = False  # ⭐⭐⭐ **「融合框继承距离限制」的开关**（用户 2026-10-03 ✓ 原话："**有了
                          #   这个逻辑，就不需要『融合框继承距离限制』了，先屏蔽相关逻辑**" ✓
                          #   —— "这个逻辑" = 上一条「**分离前不许换内砖**」（`_same_inner_brick` ✓））：
                          #   · **False（现行）= 屏蔽** ⇒ `_inherit_dist_ok` **恒放行** ✓（这条闸不再
                          #     筛候选 ✓；界面控件一并置灰 ✓ 免得调了不生效 ✗）；
                          #   · **True = 恢复**这条闸（= 2026-10-02 那版老行为 ✓ 便于回退/对照 ✓）。
                          #   ⚠ 为什么不需要它（用户口径）：候选框已经由两道把关 ——
                          #     ① **内砖同一性**（`_same_inner_brick` ✓ "分离前不许换内砖" ✓）、
                          #     ② **允许倒退距离**（`_merge_fix_safe` ✓ "当选后会不会把圆拽着倒退" ✓）
                          #     ⇒ 再问"圆心离框边够不够远"（= 本项）就多余了 ✓。
                          #   ⚠ 只屏蔽"筛选"，**判据函数与配置项都保留** ✓（`_inner_edge_dist_ratio`
                          #     / `_inherit_dist_ok` 照旧在 ✓ 自检可用开关做 A/B ✓）。
_INHERIT_DIST = 0.0       # ⭐⭐⭐ **「融合框继承距离限制」默认值**（用户 2026-10-02 ✓ 可配 ✓
                          #   ⚠⚠ **本项已屏蔽**（2026-10-03 ✓ 见 `_INHERIT_DIST_ON` ✓）：值照旧
                          #   落盘/回填 ✓ 但**不再参与筛选** ✓）：融合框候选的**第一条**
                          #   界面在「分离判定阈值」**右边** ✓）：融合框候选的**第一条**
                          #   —— **`绿圈圆心到框最近一条边的垂直距离 ÷ 绿圈半径` > 它** ✓
                          #   （用户 2026-10-02 原话："『S = 框∩绿圈外接矩形 ÷ 绿圈外接矩形 >
                          #   「融合框继承面积限制」』改为『**绿圈圆心到框最近一条边的垂直距离
                          #   (绿圆半径比例) > 「融合框继承距离限制」**』" ✓ 取代 `_INHERIT_RATIO` ✗）。
                          #   ⚠ 口径：距离**有符号** —— 圆心在框内为正、出框为负 ✓
                          #     （否则"越大越安全"的单调性会反 ⇒ 圆心跑得越远越算合格 ✗✗；
                          #      见 `_inner_edge_dist_ratio` ✓）。
                          #   · **0（默认）= 圆心必须落在框内**（贴边不算 ✓ 直观、保守 ✓）；
                          #   · **负值** ⇒ 允许"圆心出框 `|它| × 半径` 以内"的框也算候选 ✓。
                          #   ⚠ 标定参考（两段素材、容差 28：融合候选 61 个、旧口径 S > 0.5
                          #     通过 49 个 ✓）：旧通过的这组"距离比"分位 = min 0.067 ／ 5% 0.207
                          #     ／ 中位 0.950；旧拒绝的那组中位 −0.182、max 0.208 ⇒ 取 **0.0**
                          #     比旧口径略严（拒掉的都是圆心出框的 ✓ 正是要拒的 ✓）；若要
                          #     "与旧通过集合差异最小"则取 **−0.10**（差异 2 个 ✓）。
_SEP_RATIO = 1.3          # ⭐⭐⭐ **「分离判定阈值」默认值**（用户 2026-10-02 ✓ 可配 ✓ 界面在
                          #   「融合框判定阈值」**右边** ✓）：分离信号第三条 —— **融合期间**
                          #   融合框的**最大面积 ≥ 最小面积 × 它** ⇒ 才算"框真的缩过" ✓。
                          #   用户原话："**框缩成砖 && 框中心在轨迹预测方向的反方向 && 融合
                          #   期间融合框的最大面积 >= 融合期间融合框的最小面积 * x**" ✓。
                          #   语义：融合框从"并集最大"缩回"砖大小"是分离的物理前提 ✓；全程
                          #   面积没怎么变（max ≈ min ✗）⇒ 不可能是"缩回砖"⇒ 不判分离 ✓。
                          #   ⚠ 无融合期面积记录（`None`）⇒ 第三条**不成立** ⇒ 不判分离 ✓（保守 ✓）。
_NOISE_TOL = 2.0          # ⭐ **「噪声容差(px)」默认值**（用户 2026-10-02 ✓ 可配 ✓）：规则①
                          #   "圆心在框内"的判定把框**四边各外扩它**再判 ✓ —— 吸收检出框
                          #   边缘的亚像素噪声（实测帧 16 圆心只出框 0.7px ✗ 严格判会漏 ✓）；
                          #   0 = 关（严格在框内 ✓）。界面「噪声容差(px)」= `LieTracker.noise_tol` ✓
_CONSIST_OK = 0.90        # 群体一致性 ≥ 它 ⇒ 这个框**完全随群体平移** ⇒ 是背景/假目标 ✗
                          #   不许当目标观测 ✗（实测：改动前正是它把位置拽到背景上的 ✓）
_IOU_BRICK = 0.7          # ⭐⭐⭐ **「缩成砖判定 · 最小 IoU」默认值**（用户 2026-10-03 ✓ 原话："我才
                          #   学到 IoU 这个算法，我认为我们很多判定都可以换成这个算法（例如
