_X_RADIUS = 26.0          # 两条基线的"新位"残影的重合半径（半分辨率 ✓）
_EMA_TH = 11.0            # 双窗均值差的二值化阈值（两窗各 4/6 帧平均 ⇒ 噪声 σ≈8 ⇒ ~1.4σ ✓）
_BLOB_AREA = (50, 12000)  # 残差连通域面积（半分辨率像素 ✓）
_GATE = 95.0              # 残差候选与预测位置的关联门（半分辨率；= 全分辨率 190 ✓）
_LOST_AFTER = 8           # 连续这么多步没有候选 ⇒ 报 lost（不猜 ✗）
_VEL_KEEP = 0.6           # 速度平滑：新速度权重 0.4（防单帧抖动把预测带飞 ✗）
_BOX_REL_MAX = 60.0      # ⭐ 「红框相对群体」的**单帧上限**（px/帧 ✓）：目标的自身运动本来就小 ✓
                          #   （背景滚动由群体分量负责 ✓）⇒ 超过它就说明**框身份换了 / 量错了** ✗
                          #   ⇒ 这一拍不采信 ✓（宁可沿用上一次 ✓）。
_GAP_HOLD_N = 0        # ⚠ 我试过「缺口补上后继续采信首尾值 3 帧」⇒ 合成台判据略降 ✗
                       #   （≤30px 64% → 62% ✓）⇒ **撤掉** ✗。用户的口径只是「用首尾两点 / 时间」✓，
                       #   第 17 帧那一下已经生效 ✓；后面几帧由单帧差分接着走 ✓。留 0 = 关闭 ✓
                       #   （代码路径保留 ✓ 想开就把 3 填回来 ✓）。
_GAP_VEL_KEEP = 0.15    # ⭐ 「**缺口首尾**」那个量的平滑系数（= 新测量给 85% ✓ 用户 2026-10-01 ✓）：
                        #   缺口 ≥2 帧时用它 —— 分母是整个缺口（实测 0.6s ✓）⇒ 框心抖动被摊薄
                        #   6 倍 ✓✓ ⇒ 比单帧差分可信得多 ✓。
_BOX_REL_MAX_GAP = 200.0  # ⭐ 缺口版的相对位移上限（px ✓）：分母大了 ⇒ 绝对量也大 ✓
                        #   （实测 6 帧缺口给 `(31,108)` px ✓ ⇒ 单帧上限 60 会把它误杀 ✗）。
_OVERLAP_RATIO = 1.10  # ⭐ 规则②（"面积与砖相等 ⇒ 也算融合" ✓）的**上界**：框面积 / 那块砖的登记
                       #   面积 **≤ 它**才算"完全重叠"那一档 ✓ —— 比它大就不是"完全重叠"、也不一定
                       #   够得上配置阈值 ⇒ 不算融合 ✓（用户 2026-10-01 ✓ 帧 16 口径：面积 1.22 倍
                       #   的框"从尺寸判定上属于检出砖(528,340)的框 ⇒ 不能作为红框" ✓）。
                       #   ⚠ 现值 1.10 = 允许检出框尺寸抖动 ±10% ✓（再大就开始混进"目标+一小块砖"✗）。
_HIST_N = 3000        # ⭐ **白线（每拍圆心）最多留多少点**（用户 2026-10-01 口径："把每拍圆心连
                      #   起来就行" ✓ 只做长度截断 ✓ 10fps ⇒ 3000 点 ≈ 5 分钟 ✓ 够长视频用 ✓）
_PATH_REL_MAX = 12.0  # 单帧【相对群体】位移上限（半域 px）：超过它的样本不进曲线，
                       # 因为限速追赶/错观测那一下不是目标的真实运动，会把切向带反。
_CLAMP_SKIP_MIN = 3.0  # ⭐⭐ **"夹取"才算数的最小位移**（半域 px ✓ 用户 2026-10-01 白线修复 ✓）：
                       #   `_clamped` 只该在**明显**的夹取（外推/咬错那种几十 px ✗）时置位 ⇒ 跳过路径样本 ✗；
                       #   而"内接"每帧把圆心往退化安全区中心**微调 1~2 px** ✗ 不算污染 ✗ ——
                       #   低于它就不置位 ⇒ 路径样本不会**全被滤空**（实测：原来 `_path` 只剩首帧 1 个
                       #   样本 ⇒ 白线画不出、切向预测全废 ✗✗）。
_PATH_MS = 500.0        # ⭐⭐ **轨迹预测的观察窗**（毫秒 ✓ 用户 2026-10-01 让我定 ✓）：素材 10fps
                        #   ⇒ 正好 **5 个采样点** ✓ —— <3 个拟不出曲率 ✗；>7 个会把转弯前的
                        #   旧方向也带进来 ✗（目标相对群体每帧 ~10px ⇒ 500ms ≈ 50px ✓ 正好是
                        #   一段能看出"在往哪拐"的弧 ✓）。
_BOX_VEL_KEEP = 0.35    # ⭐ 「红框相对群体」那个量的**平滑系数**（比 `_VEL_KEEP` 快 ✓）：它是
                        #   **直接测量** ✓（YOLO 框心 ✓），而且常常只**连着两三帧**就因为目标
                        #   透明而断掉 ✗（用户："第10帧→第11帧…这个运动在12帧丢失红框后**需要
                        #   延续**" ✓）⇒ 慢增益**来不及学到** ✗（实测帧 11：真值 +12.8px/帧、
                        #   只学到 +2.4 ✗）⇒ 新测量给 **65%** 权重 ✓。
_REL_V_MAX = 400.0        # ⭐ **"自身速度（相对群体）"的限幅**（px/s ✓ 用户 2026-10-01 口径 ✓）：
                          #   拆分后"自身分量"只该是**目标相对群体的运动** ✓（小量 ✓）——
                          #   背景滚动已由**群体分量**负责 ✓ ⇒ 自身分量超过它就说明这一拍
                          #   **没拆干净**（群体速度缺失/被污染 ✗）⇒ 直接不信这一拍 ✓。
_LEAD_S = 0.28            # ⭐ **超前补偿**：当前窗是 4 帧均值 ⇒ 残影质心落后真值约半窗
                          #   （~0.28s × 速度）⇒ 报告位置按速度补回（用户：考虑预测轨迹 ✓）
_LEAD_FRAMES = 2.0        # ⭐⭐ 补偿量的**单位是帧**（2026-09-30 用户口径："轨迹追踪最小
                          #   精度应该是图片帧长" ✓）：= 窗口半宽（4 帧均值 ⇒ 落后 2 帧 ✓）。
                          #   ⚠ **别写成固定秒数**：素材换帧率就错 ✗ 实测 —— 现场素材去重后
                          #   是 **10fps**（0.1s/帧）⇒ 固定 0.28s = **2.8 帧**的预测 ✗；按帧
                          #   表达 ⇒ 0.2s = **正好 2 帧** ✓ 帧率无关 ✓（合成自检 0.14s/帧
                          #   ⇒ 2×0.14 = 0.28s ✓ 与旧行为逐位一致 ✓ 自检绿 ✓）
# ---- M2b：**YOLO 检测器 = 校验/复活通道**（2026-09-30 ✓ docs/测谎设计.md §M2b）----
# v2 检测器（用户标 792 帧 → mAP50 99.5%）对**残差看不见的淡轮廓**也能出框 ⇒ 三处用：
# ① init 种子；② track 吸附（残差没候选时防丢）；③ lost 复活（连续稳定才复活 ✓）。
# ⚠ 定位是**辅助**：主追踪仍是残差路线（合成自检不传 dets ⇒ 行为一点不变 ✓）。
_RECAP_N = 2              # 预测态太久后，连续这么多帧检测框"稳定移动"才复活（防复活到干扰 ✓）
_RECAP_GATE = 120.0       # 复活时检测框与预测位置的门（全分辨率；丢失期间靠滑行预测 ✓）
_RECAP_MOVE_MIN = 2.0     # 复活门②：两帧框位移 ≥ 它（= 在动 ✓）且 ≤ 速度×dt×3（= 不跳变 ✓）
_DET_GATE = 130.0         # track 吸附：残差没候选时检测框离预测的最大距离（全分辨率 ✓）
_AGREE_D = 20.0           # 校验：det 与残差候选重合半径（内 = 一致 ⇒ 信残差；外 = 换 det ✓）
# ---- ⭐⭐ **运动向量自我纠错**（2026-09-30 用户要求 ① ✓ 原话："目标图形移动时可能会与
# 其他图形重叠，所以需要不停的比对所有目标的运动速度向量，找到差异最大的那个（自我纠错）"）
# 原理：干扰图形与背景**一起滚**（速度一致 ✓）⇒ 所有候选速度的**中位数**就是"背景漂移"，
# **偏差最大**的那个才是目标 ✓ —— 目标被别的图形压住/短暂看不见也能靠"运动不同"认出来 ✓。
_TRK_GATE = 28.0          # 检测框跨帧关联门（全分辨率 px ✓）—— ⚠ 别放大：现场图形
                          #   间距才 40~60px，门太宽会**张冠李戴**（一步跳 40px ⇒ 速度
                          #   噪声 ~2400px/s ✗ 实测就是它在挑噪声 ✓）
_TRK_HIST = 8             # ⭐ 每条轨迹的**位置样本数**（速度用**整窗端点差**算 ✗ 不是逐帧
                          #   差分 —— 逐帧差分在 60fps 下被检测框抖动主宰 ✗ 实测：
                          #   σ≈3px / (1/60s) = ±180px/s 噪声 > 真运动信号 ⇒ 挑中噪声 ✗✗）
_TRK_MIN_AGE = 6          # ⭐ 轨迹至少这么多样本才算"成熟"（3 → **6** ✓ 2026-09-30 用户
                          #   逐帧复核：**刚建 3 帧的噪声轨迹**（现场 tid=63：|v|=1px/s、
                          #   dev=232）反复抢走判据 ✗✗ ⇒ 门槛提到 6（≈0.5s 观测 ✓）
_TRK_VMAX = 3000.0        # 轨迹速度限幅（px/s ✓ 防错配把速度炸掉 ✗）
_TRK_MAX_MISS = 5         # 连续这么多帧没配上 ⇒ 删轨迹（⚠ 只用在没有 dt 的老路上 ✓
                          #   有 dt 时按 `_TRK_MEM_S` 的**秒数**判 ✓ 见下）
_TRK_MEM_S = 2.5          # ⭐⭐ **速度记忆时长（秒）**（用户 2026-09-30 要求 ③ 原话：
                          #   "让每个检测出来的目标按照当前速度的方向跟着预测做防抖，下次
                          #   检测出来了再刷新防抖时间？这样即使 yolo 短暂的没识别出来也
                          #   不会永久丢失其速度记录" ✓✓）—— 丢失期间轨迹**滑行**（位置按
                          #   速度外推 ✓）、**保留速度**，被重新检出的框在预测门内就**接回
                          #   原轨迹**（继承速度 ✓ 刷新计时 ✓），不再重新建一条从零开始的 ✗。
_TRK_MISS_CAP = 90        # 没有 dt（时间戳缺失）时的帧数兜底（≈2.5s@13fps ✓）
_TRK_V_SPREAD = 70.0      # ⭐ **速度稳定度**门（px/s ✓）：窗口内逐段速度与中位速度的偏差
                          #   **中位值**超过它 ⇒ 这条轨迹"速度不稳"（刚建/配错/忽快忽慢 ✓）
                          #   ⇒ **不许进判据**（现场 77 帧那种"检测误差指向左上的假目标"
                          #   正是短命+方向突变 ⇒ 被这道闸挡掉 ✓ 用户复核 ④ ⑤ ✓）
_TRK_STABLE_N = 4         # 稳定度至少要有这么多**速度段**才敢判（少了不算 ✓）
# ---- ⭐⭐ 「重叠 / 分离」怀疑链（用户 2026-09-30 要求 ④ 条 ✓）----
# 用户原话（口径就是判据本身 ✓）：
#   ① "当跟踪器附近的某框**突然变大** → 说明真目标与假目标可能**部分重叠**了，跟踪器根据
#      **轨迹预测**移动" ⇒ 怀疑期内**不许**被这个框的中心牵着走（合并质心是两者的中点 ✗）；
#   ② "当跟踪器指着的大框**突然变小**，且有**新目标出现** → 说明可能**分离**了，**严查新多
#      出来的边**" ⇒ 给新出现的框打 `must_check`（放宽成熟门槛、但要更久的不合群证据 ✓）；
#   ③ "突然变小，但**无新目标出现** → 真目标很可能就在**面积消失的地方**，只是 yolo 没检
#      出来" ⇒ 记 `hidden` 怀疑 ⇒ 位置**锚在原地**靠预测撑（别被残差路线带跑 ✗）；
#   ④ "以上只是<可能>，**仅记录怀疑**；当**不合群的速度向量持续够久**（自己拍一个值）⇒ 那
#      个框是真目标的可能性最大" ⇒ `dev_s` 累计"不合群"的**秒数**，满 `_DEV_HOLD_S` 才敢换 ✓。
_SUSPECT_HOLD_S = 1.5     # 怀疑的**保持时长**（秒 ✓ 期间按各自的规矩处理，过期自动清 ✓）
_MERGE_GROW = 1.5         # 面积涨到 1.5× ⇒ 怀疑**重叠**（合并块面积 ≈ 二者之和 ✓）
_SPLIT_SHRINK = 0.7       # 面积掉到 0.7× ⇒ 怀疑**分离**（碎片 ✓）
_SPLIT_GATE = 120.0       # "新多出来的框"离收缩位置多近算（全分辨率 px ✓）
_DEV_HOLD_S = 0.6         # ⭐ 判据④：**不合群速度持续这么多秒**才敢换目标（≈8 帧@13fps ✓
                          #   比 `_SWITCH_N`=3 帧严 ✓ —— 用户："持续够久…可能性最大" ✓）
_GROUP_BORROW = True      # ⭐⭐ **假目标群体的速度互相修正**（用户 2026-09-30 第③问 ✓ 原话：
                          #   "有一件确定的事：假目标群体的速度向量几乎一致，可以互相修正"
                          #   ✓）—— 新出现的框 / 刚接回原轨迹的框**还没有自己的速度**时，
                          #   先**借群体中位速度**（= 背景/干扰的共同漂移 ✓）⇒
                          #   ① 速度向量**立刻画得出来**（用户第②问："它就应该跟着轨迹预测
                          #      显示" ✓）；② 程序马上"认为它还在动"（用户第②问下半句 ✓）。
                          #   ⚠ 借来的速度 = 中位速度 ⇒ 它的 `dev`≈0 ⇒ **永远赢不了判据** ✓
                          #     （不会把噪声抬成目标 ✓ 安全 ✓）。
_AREA_SEG_SKIP = 1.3      # ⭐⭐ **面积一变，这一段就不算速度**（用户 2026-09-30 第④问 ✓
                          #   实测：第 23 帧目标框 190×189 → 149×139，质心跟着跳
                          #   (-30.5,-9.9)px ⇒ 被当成速度 ⇒ 第 24 帧速度被带飞 ✗✗）——
                          #   合并/分离那一拍的**质心位移主要是"形状变了"**、不是运动 ✗
                          #   ⇒ 该段**跳过**（速度保持上一次可信值 ✓ 不清零、也不采信 ✗）。
_AREA_PRIOR_K = 0.5       # （旧）面积变化那一拍按 `_area_dir()` 融合速度的方向 ✓
_AREA_DOMINANT = 0.85     # ⭐⭐⭐ **面积变化指示 > 框移动指示**（用户 2026-09-30 定口径 ✓
                          #   原话："18帧→21帧，红框面积朝下持续变大、右侧往左缩小 ⇒ 真目标
                          #   在**贴着边往左下方拉**，轨迹朝左下（而白箭头因为**红框向上移动**
                          #   而朝上，错）……**面积变化的指示 > 框移动指示**" ✓）。
                          #   ⚠ 实测现场：面积指示"下" vs 框移动指示"上"，**夹角 104~107°**
                          #     ✗（框心/质心会被合并、切边拖着走 ✗ ⇒ 它只是"框移动"，
                          #     不等于"目标移动" ✓）⇒ 面积变化生效期间**速度主导权交给它** ✓
                          #     （并把观测带来的速度更新**掐掉** ✓ 见 `_area_busy` ✓）。
_AREA_SPAN = 3            # ⭐⭐ 面积方向对**跨度**算（用户 2026-09-30 观察尺度："18帧→
                          #   19帧→20帧→21帧……面积朝下**持续**变大" ✓ = 跨 4 帧 ✓）：
                          #   逐帧边长差只有 ±10px 级、还夹着亚像素噪声 ⇒ 方向**帧间乱翻**
                          #   ✗（实测：18"下"、19"上"、21"左"、22"右" ✗✗ 速度跟着甩 ⇒ 报告位置
                          #   来回摆 ✗）；对 3 帧跨度算 = **净变化方向** ✓ 稳、且仍跟得上 ✓。
_AREA_FOLLOW = 1.0        # ⭐⭐ 持续面积变化时**方向的跟随比**（用户："面积朝下**持续**变大" ✓
                          #   + "面积变化的指示 > 框移动指示" ✓）：取 **1.0 = 直接采用最新
                          #   方向** ✓ —— 平滑没必要 ✗：`_area_dir` 对**纯平移返回零**（框只是
                          #   整体移动时它根本不动 ✓），所以"非零"本身就意味着**形状真变了** ✓
                          #   已经是稳的信号 ✓。⚠ 实测：0.35 时老方向还占 65% ⇒ 8 帧前那次
                          #   事件的"上"迟迟压不过来 ✗（而框明明在往下长 ✓）
_AREA_MIN_SPEED = 90.0    # 面积方向推速度时的**速度下限**（px/s ✓ 真目标实测 ~90~160 ✓）：
                          #   手头速度是 0（刚建档/刚换目标）时，也按它给一个**像样的量级** ✓
                          #   而不是"有方向没速度 ⇒ 推不动" ✗
_STICKY_K = 0.5           # ⭐⭐ **"粘滞"速度融合比**（用户 2026-09-30 第④问 ✓ 原话："当
                          #   检测目标消失时…根据轨迹预测移动并绘制（程序也认为），直到该
                          #   位置（附近）有新的权威速度向量来修正这个'粘滞'的速度向量
                          #   （可以按一定比例把两个向量加起来？）" ✓）= 轨迹速度占一半、
                          #   自车速度留一半 ✓（有观测时自然被新观测修正 ✓ 不用额外开关）。
_HIDDEN_DAMP = 0.3        # 法③（"真目标就在面积消失的地方"）下的**速度阻尼**：位置锚住、
                          #   速度只借 30% ⇒ 既不远走、也不完全僵住 ✓
_MUSTCHECK_AGE = 3        # 被判"严查"的新框：成熟门槛放宽到 3（只放它进来考，不放噪声 ✗）
_MUSTCHECK_DEV_HOLD = 1.2 # 但"严查"的框要**更长**的不合群证据（1.2s ✓）才许当目标 ✓
_TRK_MIN_N = 3            # 至少这么多条成熟轨迹才敢算中位（少了没有"多数"可言 ✗）
_DEV_MIN = 40.0           # 与中位速度的偏差 ≥ 它才认（px/s ✓ 窗口 8 帧时噪声 ~25 ✓）
_DEV_LEAD = 1.3           # ⭐ **置信判据**：冠军偏差 ≥ 亚军 × 它 ⇒ 才敢用运动判据
                          #   （≈ 噪声打架 ⇒ **退回残差路线** ✓ 宁可不用也别乱认 ✗✗）
_DEV_MARGIN = 1.4         # 换目标：新候选偏差 ≥ 当前 × 它才算"明显更大"（滞回 ✓ 防抖）
_SWITCH_N = 3             # 连续这么多帧都该换 ⇒ 才真换（**自我纠错** ✓ 单帧幻觉不换 ✗）
                          #   ⚠ 别放大：真贴住时两者质心差只有个位数 ✓；鬼影距真目标
                          #   刚丢失时才 ~27px ⇒ 45 会把鬼影也当"一致" ✗（实测踩过 ✓）
# ---- M2b 现场翻车三连的护栏（2026-09-30 全量归因 00046 后 ✓）----
_V_MAX = 600.0            # 速度限幅（全分辨率 px/s ✓）：目标实际 ~几十 px/s，超它的
                          #   "速度"只能是咬错观测/乱序 dt ⇒ 不更新（防飞出画面 ✗ 实测：
                          #   pos 冲到 (3429,6258) ⇒ det 门 120 永远够不着 ⇒ 复活无门 ✗）
_LEAD_MAX = 60.0          # ⭐ **超前补偿量上限**（全分辨率 px ✓）：`pos = raw + vel×_LEAD_S`
                          #   —— vel 一旦爆（微小 dt 的除法 ✗）pos 就**瞬移几千 px** ✗；
                          #   而 M2a 的离线口径（比上一拍输出）反而给瞬移记**命中**（do=0 ✓）
                          #   ⇒ 假命中 ✗、闭环（真鼠标/限幅光标）白丢 14% ✗ 实测 ✓
_STEP_SPEED = 320.0       # ⭐⭐ **输出速率限制 = 速度**（全分辨率 px/s ✓ 用户 2026-09-30
                          #   第③问："十字标位置突变太远了，是否需要限制一下跟踪器的最大
                          #   速度？" ✓）。原写法是"每帧 `_STEP_MAX=45px`" ✗ ⇒ **帧率一变
                          #   语义就变**（10fps 里 45px/帧 = 450px/s ✗ 太松、60fps 里 = 2700px/s
                          #   ✗✗）；改成速度 × dt 才帧率无关 ✓（45px @0.14s/帧 = 321px/s ✓
                          #   与老标定一致 ✓）。
_STEP_DT_DEF = 0.14       # dt 缺失时的兜底帧间隔（= 老 `_STEP_MAX=45` 的标定帧长 ✓）
_STEP_MAX = 45.0          # ⭐ **输出速率限制**（全分辨率 px/帧 ✓ ~320px/s）：游戏里目标
                          #   是匀速滑的，**一帧跳 100px+** 只能是单帧错检/身份切换 ✗。
                          #   M2a 的离线口径对这种跳变只记 1 帧 miss（合成鼠标会瞬移 ✗），
                          #   真实鼠标要 2 帧才追上 ⇒ 闭环白丢 ✗ 实测（M2c）✓。限速后
                          #   两条口径面对的是**同一条可跟随的曲线** ✓。


def _contours_of(bw):
    """OpenCV 5 的 `findContours` 回 `(轮廓元组, 层级)`、点集形状是 (1,n,1,2)
    （与 4.x 不同 ✗）⇒ 这里统一成「轮廓数组迭代 + (n,1,2)/float32」✓。"""
    res = cv2.findContours(bw, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    cs = res[0] if isinstance(res, tuple) else res
    for c in cs:
        yield np.asarray(c, dtype=np.float32).reshape(-1, 1, 2)


def _edge_seg_dist(x1, a1, b1, x2, a2, b2):
    """两条**轴向平行**边线段的距离（px ✓）：垂直间距 ⊕ 段间空隙 的合距 ✓。
    竖边传 `(x, y上, y下)` ×2 ✓；横边传 `(y, x左, x右)` ×2 ✓（同一把尺 ✓）。
    「边归属」用（`_edge_ownership` ✓）—— 框边与砖边**错开一段**时不会被同侧坐标误判 ✓。"""
    dx = abs(float(x1) - float(x2))
    gap = max(0.0, max(float(a1), float(a2)) - min(float(b1), float(b2)))
    return math.hypot(dx, gap)


def _white_blobs(bw, area_range, min_fill=0.0):
    """二值图 → [(cx, cy, area)]（面积在范围内、**填充率** ≥ `min_fill` ✓ 按面积降序）。

    ⭐ 填充率 = 轮廓面积 / 外接矩形面积：**细笔画**（倒计时数字 ✓）低、**实心块**
    （目标幽灵 ✓）高 —— 这就是"盯白色图形而不是盯数字"的判据 ✓（用户 2026-09-30 ✓）。
    """
    out = []
    for arr in _contours_of(bw):
        a = cv2.contourArea(arr)
        if not (area_range[0] <= a <= area_range[1]):
            continue
        _x, _y, bw_, bh_ = cv2.boundingRect(arr)
        if bw_ * bh_ <= 0 or (a / float(bw_ * bh_)) < min_fill:
            continue
        m = cv2.moments(arr)
        if m["m00"] <= 0:
            continue
        out.append((m["m10"] / m["m00"], m["m01"] / m["m00"], a))
    out.sort(key=lambda b: -b[2])
    return out


def _dominant_blob(dom, blobs):
    """主导白块 ⇒ `(最大块, 次大块面积)`（都没有 ⇒ `(None, 0.0)` ✓）。

    ⭐ **达标块优先、没有就退回最大白块**（2026-09-30 修 ✓）：
    · `dom` = 过了**填充率**那关的白块（防"一大片浅色背景"✓）—— 正常帧用它 ✓；
    · 但倒计时数字与目标**会合并成一帧**（现场：质心 251→217 跳一下 ✗）⇒ 合并块的
      填充率掉到阈值下 ⇒ `dom` **空** ⇒ 老代码落到"谁动了谁是目标"⇒ 锁错 + 假初速度 ✗✗；
    · 退回 `blobs[0]`（最大白块）仍然**要过 `_INIT_DOMINANT` 的倍数判据**（最大 ≥ 次大
      × 1.5 ✓）⇒ 顶部那几片亮背景（面积相近、倍数不够）照样进不来 ✓。
    """
    if dom:
        return dom[0], (dom[1][2] if len(dom) > 1 else 0.0)
    if blobs:
        return blobs[0], (blobs[1][2] if len(blobs) > 1 else 0.0)
    return None, 0.0


def _blobs_of(bw, area_range):
    """二值图 → [(cx, cy, area)]（面积在范围内的连通域，按面积降序 ✓）。"""
    out = []
    for arr in _contours_of(bw):
        a = cv2.contourArea(arr)
        if not (area_range[0] <= a <= area_range[1]):
            continue
        m = cv2.moments(arr)
        if m["m00"] <= 0:
            continue
        out.append((m["m10"] / m["m00"], m["m01"] / m["m00"], a))
    out.sort(key=lambda b: -b[2])
    return out


def _shift_img(img, dx, dy):
    """整数平移（**边界复制、不回绕** ✗ —— `np.roll` 会把对边卷过来产生假残差 ✗✗）。"""
    h, w = img.shape[:2]
    if not dx and not dy:
        return img
    out = np.full_like(img, float(img.mean()) if img.size else 0.0)
    xs0, xs1 = max(0, dx), min(w, w + dx)
    xd0, xd1 = max(0, -dx), min(w, w - dx)
    ys0, ys1 = max(0, dy), min(h, h + dy)
    yd0, yd1 = max(0, -dy), min(h, h - dy)
    if xs1 <= xs0 or ys1 <= ys0:
        return img
    out[yd0:yd1, xd0:xd1] = img[ys0:ys1, xs0:xs1]
    return out


class LieTracker:
    """状态机：init（找白色目标）→ track（运动残差跟随）→ lost（如实报丢）。"""

    def __init__(self, path_ms=None, merge_iou=None, merge_iou_out=None, sep_ratio=None,
                 ring_cov_sep=None, brick_iou_sep=None, ring_cov_fuse=None,
                 brick_iou_fuse=None, inherit_dist=None,
                 allow_back_ratio=None, edge_max=None, sep_vel_max_ratio=None, noise_tol=None,
                 board_s=None, board_overlap=None, iou_brick=None,
                 select_step_ratio=None, clamp_step_ratio=None, show_kf=None,
                 select_vel_ratio=None, kf_pos=None):
        # ⭐⭐ **轨迹预测的观察窗**可配（用户 2026-10-01 ✓ 演示窗那一行「轨迹预测窗口时间」
        #   就是它 ✓）：`None` ⇒ 用模块默认 `_PATH_MS`（500ms ✓ 老行为一字不变 ✓）。
        self.path_ms = float(path_ms) if path_ms else float(_PATH_MS)
        # ⭐⭐⭐ **「融合框判定 IoU」**（用户 2026-10-03 ✓ 原话："把『融合框判定阈值』换成
        #   『**融合框判定 IoU**』：**小于这个 IoU 才行**，之前配的 1.2 改成 **0.5**" ✓
        #   —— 取代原来那个**面积比**阈值 ✓ 见 `_MERGE_IOU` ✓）：
        #   候选框与"它压着的那块砖"的 **IoU < 它** ⇒ 才算**融合框**（真并集 ✓）；
        #   对称地 `IoU ≥ 它` ⇒ 两者基本同一格 ⇒ 那是"**砖自己那一格**" ✗ 不标红 ✓。
        #   ⚠ **0 是合法值**（= 不靠这条判融合 ⇒ 只剩规则② ✓）⇒ 判 `None` 不能判真值 ✗；
        #     夹进 `[0, 1]` ✓（与 `iou_brick` / `board_overlap` 同款 ✓）。
        self.merge_iou = (float(_MERGE_IOU) if merge_iou is None
                          else max(0.0, min(1.0, float(merge_iou))))
        # ⭐⭐⭐ **「融合框判定 IoU · 退出」= 迟滞下半段**（用户 2026-10-03 ✓ 第 1 步 ✓ 见
        #   `_MERGE_IOU_OUT` ✓）：**已在融合保持期**时用这个更宽的阈值判"还算不算并集" ✓。
        #   ⚠⚠ **2026-10-03 当天再改：`merge_iou_out` 已废弃** ✗（用户原话："**『退出 IoU』不需要了，
        #     用第一行的同检出 IoU**，满足条件时用『检出框与圆外接矩形 IoU > ___ 时，与内砖 IoU
        #     < ___ 判定为融合』" ✓）⇒ 迟滞改由**第 2/3 行那两档"内砖 IoU"**实现 ✓（见下 ✓）；
        #     ⚠ 上面引述里那句的**前半**当天又**二次修订**成了「**圆外接矩形与检出框相交的
        #       比例 >**」✓（分母从"并集"换成"**圆矩形面积**" ✓ 见 `_ring_cov` ✓）—— 引述保持
        #       原话不动 ✗（那是当时的口径 ✓），现行口径以 `_ring_cov` / `_RING_COV_*` 为准 ✓。
        #     本字段**保留只为兼容旧调用**（不再参与任何判定 ✓ 界面已不再暴露 ✓）。
        self.merge_iou_out = (float(_MERGE_IOU_OUT) if merge_iou_out is None
                              else max(0.0, min(1.0, float(merge_iou_out))))
        # ⭐⭐⭐ **参数分档（用户 2026-10-03 ✓ 第 2/3 行）**：每档一对 —— "圆外接矩形相交比例 >" 与
        #   "框↔内砖 IoU <" ✓ 两条**同时**满足才算"融合" ✓（分离期=进入 ✓ 融合期=保持 ✓）。
        #   ⚠ **默认值里的"进严守松"就是迟滞** ✓：分离期 `0.5`（严 ⇒ 不容易进 ✓）、融合期 `0.7`
        #     （松 ⇒ 不容易掉 ✓）⇒ 边界不再进进出出横跳 ✓（治"太松放大错误 / 太严没指导值" ✓）。
        self.ring_cov_sep = (float(_RING_COV_SEP) if ring_cov_sep is None
                             else max(0.0, min(1.0, float(ring_cov_sep))))
        self.ring_cov_fuse = (float(_RING_COV_FUSE) if ring_cov_fuse is None
                              else max(0.0, min(1.0, float(ring_cov_fuse))))
        self.brick_iou_sep = (float(_BRICK_IOU_SEP) if brick_iou_sep is None
                              else max(0.0, min(1.0, float(brick_iou_sep))))
        self.brick_iou_fuse = (float(_BRICK_IOU_FUSE) if brick_iou_fuse is None
                               else max(0.0, min(1.0, float(brick_iou_fuse))))
        # ⭐⭐⭐ **分离判定阈值**（用户 2026-10-02 ✓ 原话："**融合期间融合框的最大面积 >= 融合
        #   期间融合框的最小面积 * x**，这个 x 做成配置参数『**分离判定阈值**』加在『融合框判定
        #   阈值』**右边**" ✓）：分离信号第三条的 x ✓ —— 融合期**最大框面积 ÷ 最小框面积 ≥ x**
        #   才允许判分离 ✓（= 框确实"从并集缩回砖"过 ✓）。`None` ⇒ 模块默认 `_SEP_RATIO` ✓。
        #   ⚠ 与 `merge_iou` 不同，这里**没有"0/假值"的合法语义**（x < 1 无意义 ✓）
        #     ⇒ 照旧写法（`if sep_ratio else 默认` ✓ 不做 `is None` 判断 ✓）。
        self.sep_ratio = float(sep_ratio) if sep_ratio else float(_SEP_RATIO)
        # ⭐⭐⭐ **融合框继承距离限制**（用户 2026-10-02 ✓ 口径修订 ✓ 原话："『S = 框∩绿圈外接
        #   矩形 ÷ 绿圈外接矩形 > 「融合框继承面积限制」』改为『**绿圈圆心到框最近一条边的垂直
        #   距离(绿圆半径比例) > 「融合框继承距离限制」**』" ✓）：融合框候选的**第一条** ——
        #   `圆心到框最近边的有符号垂距 ÷ 绿圈半径` **> 它** ⇒ 才算融合候选 ✓。
        #   ⚠ **只收非负值**（用户 2026-10-02 ✓ 原话："这个距离**正数判定才有意义**啊，都是负数
        #     都在里面了肯定融合" ✓）—— 距离的定义是"**圆心在框内时**到最近那条边的垂距 ÷ 半径"
        #     ✓；圆心在框外 ⇒ 这个量**为负** ⇒ **一律不过** ✗（不存在"负阈值放宽"那种语义 ✗）
        #     ⇒ 入参 `max(0.0, ...)` 夹紧 ✓ 越界值夹进 `[0, 3]` ✓
        #     （默认 0 ⇒ 圆心落在框内即可 ✓ 与"负值 = 出框也算"那种口子彻底断开 ✓）。
        self.inherit_dist = (float(_INHERIT_DIST) if inherit_dist is None
                             else max(0.0, min(3.0, float(inherit_dist))))
        # ⭐⭐⭐ **砖最多拥有融合框边数量**（用户 2026-10-02 ✓ 原话："增加参数：『**砖最多拥有
        #   融合框边数量**』(1~4)，注意在多条边选取最近的**前 x 条**" ✓）：`_edge_ownership`
        #   里归砖的边**只留距离最近的这么条** ✓（更远的改判"真目标提供的边" ✓）。
        #   ⚠ 整数、夹进 `[1, 4]` ✓（默认 **4** = 不截断 ⇒ 老行为一字不变 ✓）。
        self.edge_max = int(_EDGE_MAX if edge_max is None else max(1, min(4, int(edge_max))))
        # ⭐⭐⭐ **真目标预测最大速度倍率**（用户 2026-10-03 ✓ 原话："将**分离期（淡粉色框时期）**
        #   的**最大相对假目标群速度（白箭头）** = a × **假目标群体的标准速度**" ✓）：
        #   分离期白箭头模长上限 = `a × 当拍群体速度模长` ✓ 见 `_sep_vel_cap` ✓。
        #   ⚠ **0 是合法值**（= 分离期白箭头模长压到 0 ⇒ 圆不再预测前进 ✓ 极端但合法 ✓）
        #     ⇒ 判 `None` 不能判真值 ✗（与 `noise_tol` 同款 ✓）；越界值夹进 `[0, 5]` ✓。
        self.sep_vel_max_ratio = (float(_SEP_VEL_MAX) if sep_vel_max_ratio is None
                                  else max(0.0, min(5.0, float(sep_vel_max_ratio))))
        # ⭐⭐⭐ **融合框挑选允许倒退距离(绿圆半径比例)**（用户 2026-10-02 ✓ 原话："『融合框挑选
        #   允许倒退距离(px)』改为『**融合框挑选允许倒退距离(绿圆半径比例)**』" ✓）：
        #   第二条闸的**容差** ✓ 见 `_merge_fix_safe` ✓。
        #   ⚠ **0 是合法值**（= 一点也不许倒退 ✓ 上一版的布尔判据 ✓）⇒ 判 `None` 不能判真值 ✗
        #     （与 `noise_tol` / `inherit_dist` 同款 ✓）；负数无意义 ⇒ 夹到 ≥ 0 ✓。
        self.allow_back_ratio = (float(_ALLOW_BACK_RATIO) if allow_back_ratio is None
                                 else max(0.0, float(allow_back_ratio)))
        # ⭐⭐ **噪声容差(px)**（用户 2026-10-02 ✓ 界面「噪声容差(px)」✓）：规则① 判的是
        #   "**圆心 ± 它** 的范围与框相交" ✓（`_pos_range_hits` ✓ 用户 2026-10-02 口径 ✓）。
        #   ⚠ **0 是合法值**（= 范围退化成点 ⇒ 严格"圆心在框内" ✓）⇒ 判 `None`
        #   不能判真值 ✗（跟上面两个不同 ✓）。
        self.noise_tol = float(_NOISE_TOL) if noise_tol is None else max(0.0, float(noise_tol))
        # ⭐⭐⭐ **「缩成砖判定 · 最小 IoU」**（用户 2026-10-03 ✓ 原话："我才学到 IoU 这个算法，我认为
        #   我们很多判定都可以换成这个算法（例如『噪声容差』改成『**噪声最小 IoU**』）" ✓）：
        #   给"框缩回砖大小/位置"（`_box_is_brick_det` ✓）补一把**尺度无关**的尺 ✓
        #   —— 与"四条边都在噪声容差(px) 内"**并列 OR** ✓。见 `_IOU_BRICK` 与 `geom` 模块头 ✓。
        #   ⚠ **0 是合法值**（= 关 ⇒ 老行为一字不变 ✓）⇒ 判 `None` 不能判真值 ✗；夹进 `[0, 1]` ✓。
        self.iou_brick = (float(_IOU_BRICK) if iou_brick is None
                          else max(0.0, min(1.0, float(iou_brick))))
        # ⭐⭐⭐ **「选框距离门（步数）」**（用户 2026-10-03 ✓ 原话："动手" ✓ 见 `_SELECT_STEP_RATIO` ✓）：
        #   非融合红框候选必须满足"框心到**预测落点**的距离 ≤ 本值 × **本拍该走多远**" ✓ ——
        #   **B 型（步数比例）** ⇒ 帧率 / 播放倍速无关 ✓（用户："② 选框距离门会因为视频播放
        #   速度而改变结果吧？" ✓ 见 `_step_len_px` 与 `_select_dist_px` ✓）。治"分离后挑到
        #   远处的框 ⇒ 硬夹一步拽过去 ⇒ 白线剧裂折角"（帧 48 跳 97.8px ✓）。**0 = 关** ✓。
        self.select_step_ratio = (float(_SELECT_STEP_RATIO) if select_step_ratio is None
                                  else max(0.0, float(select_step_ratio)))
        # ⭐⭐⭐ **「夹取限速（步数）」**（用户 2026-10-03 ✓ 原话："动手" ✓ 见 `_CLAMP_STEP_RATIO` ✓）：
        #   出口那次"夹进红框内接安全区"每拍最多挪 `本值 × 本拍该走多远`（B 型 ⇒ 帧率无关 ✓）
        #   —— **0 = 关**（回"硬夹" = 老行为 ✓ 一字不变 ✓）。
        self.clamp_step_ratio = (float(_CLAMP_STEP_RATIO) if clamp_step_ratio is None
                                 else max(0.0, float(clamp_step_ratio)))
        # ⭐⭐⭐ **「显示 KF 预测」开关**（用户 2026-10-03 ✓ 原话："**1. 移除「位置估计」参数**（非
        #   可视化的配置用户界面不需要），新增「**显示 KF 预测**」的开关" ✓）：
        #   ⚠ 它**不是"位置估计算法分支"** ✗（那名字会让人以为会改位置 ✗）—— 它是**可视化开关** ✓：
        #   · `False`（默认 ✓）= **不跑 KF、画面不画** ⇒ **零开销、零污染** ✓；
        #   · `True` = 跑 KF（`perception/kf.py` ✓ 把经典链条每拍算出的位置当**观测** ✓）
        #     ＋ 演示窗画**青线/青点/青箭头** ✓ —— **只记录** ✗ **绝不动 `out["pos"]`** ✓✓。
        #   它的产出：① "KF 比现状好在哪"有数据可答 ✓；② **新息统计直接给出观测噪声 σ 该取多大** ✓。
        self.show_kf = bool(show_kf)
        # ⭐⭐⭐ **「KF 位置驱动」（`kf_pos`）**（用户 2026-10-03 ✓ 原话："因为**预测结果不同，实际
        #   走向也会不同**，所以在**实时演算上叠加 KF 显示意义不大**。能不能：当『KF预测』开启时，
        #   将**窗口分为两列视图**，左边跑经典右边跑 **KF**，这样对照才有意义" ✓）：
        #   · `False`（默认 ✓）= 老行为（KF 顶多是影子 ✓ 位置一律走经典 ✓ 逐位不变 ✓）；
        #   · `True` = **真用 KF 的位置当"我们认为目标在哪"** ✓ —— 观测仍是"经典链条这一拍
        #     算出来的位置" ✓（同影子 ✓），但算完**覆盖** `out["pos"]` 并把内部状态一起认 ✓
        #     （`self.pos` / `_raw` / `_pos_prev` ✓ 与「甲：落位点 ⇒ 内部状态一起认」同一手法 ✓
        #     见 `_adopt_merge_fix` ✓）⇒ **白线历史、下一拍的预测起点 / 选框参考 / 速度推算
        #     全部从 KF 位置走** ✓ ⇒ "右边这一列就是 KF 在跑" ✓（两列各跑一份 `LieTracker` ✓
        #     状态隔离 ✓ 见演示窗 ✓）。
        #   ⚠⚠ 与"只记录不动位置"的影子是**两种用法** ✓：`kf_pos=True` 时 `out["kf"]` 照给 ✓
        #     （诊断/画速度箭头还要用 ✓）；⚠ 它**会改变轨迹**（这正是要对照的东西 ✓ 用户原话
        #     "预测结果不同，实际走向也会不同" ✓）。
        self.kf_pos = bool(kf_pos)
        # ⭐⭐⭐ **上一拍的"圆心 / 白箭头"**（用户 2026-10-03 ✓ 原话澄清："『对比**上一拍的白箭头
        #   预测位置**』意思是**假设本拍按上拍预测走了之后**" ✓）：给落位闸（`_merge_fix_safe` ✓）
        #   算"**假设本拍走到了上拍预测位置**"当基准用 ✓（见该函数 ✓）。
        self._vel_rel_prev = None    # 上一拍**结束时**的白箭头（每拍末尾存 ✓ 见 `process()` ✓）
        #: ⭐⭐⭐ **上一拍到底有没有红框**（`True` / `False` ✓ 用户 2026-10-03 ✓）：给「选框速度门」
        #:   （`_select_vel_ok` ✓）划作用域用 ✓ —— ⚠ 不能用 `_prev_tbox` / `_tbox_last` 代替 ✗
        #:   （那俩在丢框期**留着旧框** ✗ ⇒ 判出来永远为真 ✗ 实测踩过 ✓ 见 `process()` ✓）。
        self._had_tbox_prev = False
        #: ⭐ **「漂移纠正」待应用**（用户 2026-10-03 ✓ 原话："把**「漂移纠正」挪到闸判定之后**" ✓）：
        #:   这一支原来**当场**改写 `_vel_rel` ✗ ⇒ 而落位闸读的就是"本拍白箭头" ⇒ **自己批准自己**
        #:   ✗✗（实测 `10月2日.mp4` 帧 37 ✓）⇒ 现在先**暂存** ✓、等闸判完再应用 ✓ 见 `process()` ✓。
        self._pend_drift = None
        self._kf = None              # 惰性建（勾了「显示 KF 预测」⇒ 第一拍才建 ✓）
        self._kf_ts = None           # 上一拍时间戳（算 dt ⇒ **帧率/倍速无关** ✓）
        self._kf_acc = []            # 逐拍对照累积 (与经典差, 新息模长, NIS) ✓ 供 `kf_summary` 汇总 ✓
        # ⭐⭐ **上板时长（秒 ✓ 用户 2026-10-02 ✓）**：登记条目自出生要走满这么久才许上板 ✓
        #   （`None`/`0` ⇒ 一帧就上板 = 老行为 ✓）。放登记表那边判 ✓（`ShapeRegistry.board_s` ✓）。
        self._board_s = 0.0 if board_s is None else max(0.0, float(board_s))
        # ⭐⭐ **上板防抖重叠率**（用户 2026-10-02 ✓ 原话："如果**新砖与旧砖重叠率 >= 0.5**，
        #   判定为**同一登记砖**……这个 0.5 做成参数配置『**上板防抖重叠率**』" ✓）：
        #   `None` ⇒ 用登记表那边的同一处默认值 `_BOARD_OVERLAP_DEF`（0.5 ✓）；`0` = 关 ✓。
        #   判据/落点全在登记表里（`ShapeRegistry._dedup_board_overlap` ✓）⇒ 这里只透传 ✓。
        self._board_overlap = (float(_BOARD_OVERLAP_DEF) if board_overlap is None
                               else max(0.0, min(1.0, float(board_overlap))))
        self._reg = ShapeRegistry(board_s=self._board_s,
                                  board_overlap=self._board_overlap)   # ⭐ 透传给登记表 ✓
        # ⭐ 本拍红框**是不是融合框**（面积 ≥ 阈值 × 标准面积 ✓）：丢框期**保持上一拍**的
        #   判定 ✓（融合到一半框丢了 ⇒ 仍然"在融合" ✓）。
        self._tbox_merged = False
        # ⭐⭐⭐ **融合期间融合框面积**（用户 2026-10-02 ✓ **二次定稿** ✓ 原话："融合期间融合框
        #   **出现最小面积后出现的最大面积** >= 融合期间融合框的最小面积 * x" ✓）：分离信号的
        #   **第三条**靠它 ✓ 见 `_merge_area_span_ok` ✓。
        #   · 记账窗口 = **一次融合会话**（从"进门（`_is_merged_box` 命中）"到"分离" ✓）——
        #     进门那拍**重置**成该框面积 ✓，之后**每拍**用当选的那个融合框面积**追加** ✓；
        #   · `_merge_area_series` = **按拍序**的面积序列 ✓（必须有时序 ✗ —— "出现最小面积
        #     **之后**"用"全域 max/min"表达不出来 ✓ 见 `_merge_area_note` 的说明 ✓）；
        #     `_merge_area_max/_min` = 全域极值（**只给日志/诊断**用 ✓ 不再参与判据 ✓）；
        #   · 空序列 = 还没有记录（没进过融合 / 刚复位 ✓）⇒ 第三条**不成立** ⇒ 不判分离 ✓
        #     （保守：宁可继续跟，也不凭空记录判分离 ✗）。
        self._merge_area_series = []
        self._merge_area_max = None
        self._merge_area_min = None
        # ⭐⭐ **融合判定的诊断留档**（用户 2026-10-02 ✓："当融合框生成时添加日志，显示相关的砖
        #   以及解释判定为融合框的计算数据" ✓）：`_merge_why` = `_is_merged_box` 最近一次算过
        #   的那些量 ✓（每次调用都覆盖 ✓）；`_merge_why_snap` = **判 `merged` 那一刻的快照** ✓
        #   （`_target_box_state` 里存 ✓ —— 之后别的调用不会把它改掉 ✓）。
        self._merge_why = None
        self._merge_why_snap = None
        # ⭐⭐ **本拍是不是"刚分离"**（上一拍是融合框、这一拍不是 ✓ = S2 ✓）：分离 ⇒ 速度
        #   **平滑接管**（`_SEP_TAKE_N` ✓ 见 `process()` 末尾 ✓）。
        self._merge_split = False
        #: ⭐⭐ **本拍判出了「分离信号」**（= 融合框塌缩成"砖 ± 噪声容差" ✓ 用户 2026-10-02 ✓
        #:   原话："若出现『分离』信号（融合检出框缩小后，判定 **4 条边都归属砖**）**也按预测**" ✓）。
        #:   · 置真点 = `_target_box_state` 里 `_box_is_brick_det` 命中的那一支 ✓（那一拍它返回
        #:     `None` ⇒ `_step_track` 走的是"丢框那一支"✗ ⇒ 放别处都读不到 ✗ 实测踩过 ✓）；
        #:   · 每拍在 `_target_box_state` **之前**清零 ✓；
        #:   · 用处 = `process()` 的位置滑行分支（`_tbox_merged or _split_now` ✓）—— 分离那一拍
        #:     也**按预测/白箭头滑行一步** ✓（不然落回观测路径 ⇒ 圆往预测反方向跑 ✗✗）。
        #:   ⚠ 与 `_merge_split` **不是一回事** ✗：后者在"融合到一半丢框"时也为真 ✓（那条只给
        #:     速度接管用 ✓ 见 `_sep_takeover` ✓）。
        self._split_now = False
        #: ⭐⭐ **本拍"融合框消失（分离）"的诊断留档**（用户 2026-10-02 ✓ 原话："把融合框消失
        #:   （分离）的日志**也依据融合的格式**打印出来" ✓）—— 与 `_merge_why` 同一格式 ✓：
        #:   `_target_box_state` 判出分离的那一支用 `_split_diag` 记现场 ✓、`_build_split_log`
        #:   组一句中文 ✓、`_out()` 在 `_merge_split` 那一拍带出 `split_log` ✓。
        #:   ⚠ 每拍在 `_target_box_state` **之前**清零 ✓（与 `_split_now` 同处 ✓ 免得旧值残留 ✗）。
        self._split_why = None
        #: ⭐⭐⭐ **本拍"非融合红框"的判定留档**（用户 2026-10-03 ✓ 原话："在日志加一下**非融合
        #:   红框选择**的判定信息吧" ✓）：决策链上"**目标自己那格**"（`_circle_hits` ✓）选中红框
        #:   时填现场 ✓、`_build_pick_log` 组一句中文 ✓、`_out()` 带出 `pick_log` ✓。
        #:   ⚠ 每拍在 `_target_box_state` **之前**清零 ✓（与 `_split_why` 同处 ✓）。
        self._pick_why = None
        self._vel_rel_prev = None               # ⭐ 上一拍的白箭头（新一局作废 ✓ 见 `__init__` ✓）
        self._pend_drift = None                 # ⭐ 「漂移纠正」待应用（同上 ✓）
        #: ⭐ KF 影子（勾了「显示 KF 预测」= `show_kf` ✓ 用户 2026-10-03 ✓）：新一局一起作废 ✓
        #:   （卡尔曼的状态与那一局的轨迹绑死 ✗ 留着会拿旧轨迹当先验 ⇒ 污染对照 ✓）。
        self._kf = None
        self._kf_ts = None
        self._kf_acc = []
        self._sep_n = None          # 接管进行到第几拍（None = 没在接管 ✓）
        self._sep_vel0 = None       # 接管期的**起点速度** = 分离前那个冻结值 ✓
        self._corner_prev = None    # ⭐ 上一拍的"对角修正点"（算"修正进白箭头"的位移 ✓）
        self._corner_prev_ts = None
        self.state = "init"
        self.pos = None                 # 当前目标质心（全分辨率像素 ✓）
        self._report_prev = None        # ⭐ 上一帧**最终报告位置**（分离那一拍"按白箭头走"的起点 ✓）
        # ⭐⭐ **白线 = 刻在背景板上的轨迹**（用户 2026-10-01 ✓ **最新定稿** 原话："白色轨迹线
        #   应该是需要是**刻在背景板上**的线，也就是说是会**跟假目标群相对静止、随着他们移动**的"
        #   ✓ —— **推翻**同日早先"每拍圆心连起来、没有任何其他逻辑"的口径 ✓）：
        #   · `_hist_pos` 仍记**屏幕系**报告位置（兼容/诊断 ✓）；
        #   · `_hist_grp` 记**群体系**（= 报告位置 − 该拍累计群体平移 ✓ 半域×2 换算 ✓）——
        #     画线时再加回**当前**累计平移 ⇒ 整条线骑在背景板上、跟着砖群一起走 ✓。
        self._hist_pos = []
        self._hist_grp = []
        self.area = 0.0                 # 当前残差块面积（回放评分算"目标半径"用 ✓）
        self.lost_n = 0                 # 连续没找到候选的步数
        self.init_t = None              # 认出目标的时刻（回放报告用 ✓）
        self._cands = []                # 建档候选：[{"pos","area","first","n"}]
        self._buf = []                  # v2：半分辨率帧缓冲（双窗均值差分 ✓）
        self._vel = (0.0, 0.0)          # 目标**屏幕**速度（小图域 px/s，对外/前馈/超前补偿用 ✓）
        # ⭐⭐⭐ **自身速度 = 相对"假目标群体"的速度**（用户 2026-10-01 定稿 ✓ 原话："真目标轨迹
        #   预测……我认为应该**相对于假目标群体**进行预测" ✓）。
        #   为什么必须拆开 ✗：屏幕速度 = **群体分量**（背景/相机在滚 ⇒ 每拍实测得到、可靠 ✓）
        #   ＋ **自身分量**（目标相对群体的运动 ⇒ 小、稳、可 EMA ✓）。
        #   原来只有"屏幕速度"一个量 ✗ ⇒ EMA 里**混着每拍都在变的背景滚动** ✗ ⇒ 一旦切到
        #   "没有观测"的拍子就该按旧值滑行，而那个旧值**把背景的旧速度也一起冻住了** ✗✗。
        #   ⇒ 拆开后：**群体分量永远取"当拍实测"** ✓（`T` / `avg_vel` ✓ 不滞回 ✓），
        #   **自身分量沿用 EMA** ✓ —— 这正是"轨迹预测"该有的样子 ✓。
        #   ⚠ 两者同域：小图域 px/s ✓（实测 `_vel` 与帧间真位移 /dt 完全吻合 ✓，
        #     `avg_vel`（px/帧）÷ dt 即同域 ✓）⇒ 相加/相减都是**直接运算** ✓ 不用换算 ✓。
        self._vel_rel = (0.0, 0.0)      # 目标**自身**速度（相对群体 ✓ 小图域 px/s ✓）
        self._gv_now = None             # 诊断：本拍实测到的群体速度（px/s ✓）
        # ⭐⭐⭐ **上一拍"夹取完"的位置**（用户 2026-10-01 定稿 ✓ 原话："**先听预测，后夹取，
        #   夹取完再计算本帧与上一帧的预测**" ✓）—— 速度要用"**这一拍实际落在哪**"来算 ✓，
        #   而不是用裸观测 ✗（裸观测没经过预测与夹取 ⇒ 箭头会说一套、圆圈走另一套 ✗）。
        self._raw_prev = None
        self._vel_realized = None       # 诊断：本拍由"实际位移"量出来的自身速度 ✓
        self._tbox_prev = None          # ⭐ 上一拍的**红框**（用来直接量"红框相对群体的位移" ✓）
        # ⭐⭐⭐ **缺口记账**（用户 2026-10-01："第17帧红框再次出现 ⇒ 用**丢失红框的12帧→17帧的
        #   首尾位置/时间**来预测真目标的轨迹" ✓）：`_tbox_last`/`_ts_last` = 缺口前的**首点** ✓，
        #   `_gapT` = 缺口期间**累计的群体平移** ✓，`_gap_n` = 缺口帧数 ✓，`_dt_gap` = 缺口真实耗时 ✓。
        self._tbox_last = None
        self._ts_last = 0.0
        self._gapT = [0.0, 0.0]
        self._gap_n = 0
        self._dt_gap = 0.0
        self._gap_hold = 0              # 缺口补上后还剩几帧"先信首尾值" ✓
        self._vel_src = None            # 诊断：本拍自身速度的来源（"box"=红框相对群体 ✓）
        self._raw = None                # ⭐ **原始检测质心**（半分辨率）—— 与报告位置
                                        #   分开算：lead 只加在报告上，**不许**混进速度 ✗
        self._prev_ts = None
        self._dt_last = None
        self._cur_box = None            # 上一拍"离报告位置最近的那个框"（面积变化用 ✓）
        self._area_nudge = None         # 面积方向补偿 [dx, dy, 剩余秒, 幅度px] ✓
        self._area_fresh = False        # 面积刚变 ⇒ 这一拍要"立即修正"报告位置 ✓
        self._box_hist = []
        self._box_ok = None             # 跨度**锚**：上一格"正常大小"的当前框 ✓
        self._anchor_n = 0              # 锚已连续用了多少帧（满 _AREA_SPAN 就滚动 ✓）
        self._typ_area = 0.0            # 这一拍的"标准面积"（所有目标面积基本相等 ✓）
        self._group = GroupMotion()     # ⭐ A 层：群体平移 `T` + 群体一致性（重构 ✓）
        # ⭐ A 层-2：**假目标登记表**（上面已按 `board_s` 建好 ✓ 这里不重复建 ✗）
        self._t_hist = []               # 逐帧 `T` 历史（**背景对齐**用 ✓ 见 `_diff` ✓）
        self._clamped = False           # ⭐ 本拍发生过**信念夹取** ⇒ 轨迹样本不入窗（见 `_clamp_into_tbox` ✓）
        self._obs_lag = True            # 本拍观测有没有**滞后**（残差=有 ✓ 白块/检测=无 ✓）
        self._white_cur = None          # 本帧白块观测（白块阶段 ✓ 见 `_white_obs` ✓）
        self._gray_full = None          # 本帧**全分辨率**灰度（A 层用 ✓）
        self._tbox = None               # 后端认定的**真目标所属框**（给演示窗画红框 ✓）
        self._tbox_role = ""            # ⭐ 本拍红框候选的**身份**（`""` / `"fake"` / `"merged"` ✓ 见
                                        #   `_box_identity` ✓）：`"fake"` 一律**不出红框** ✓
        self._tbox_now = None           # 后端**这一拍**给没给框（`None` = 没给 = 漂移期 ✓）
        self._pos_prev = None           # 上一拍的报告位置（融合期"按白箭头走"的起点 ✓）
        # ⭐⭐⭐ **大红框（融合框）出现的"第一拍"**（用户 2026-10-01 ✓ 原话："大红框出现的融合期
        #   的第一拍：① **先夹取**（例如第 17 帧会与红框上边相切）② 计算「飘移纠正速度」=
        #   （淡粉色框的「飘移期」到…融合期的第一拍的 圆圈与假目标群的 相对位移 / 时间），
        #   以「飘移纠正速度」作为白色箭头指导预测圆圈的位移" ✓）：
        #   · `_merge_first` = **本拍是不是那一拍**（只在那一拍为真 ✓ 用来放行"夹取" ✓）；
        #   · `_drift_rel0/_drift_ts0` = 漂移期（= 淡粉框那段 ✓）**起点**的"群体系坐标 + 时刻"
        #     （与白/黄箭头**同一口径** ✓）⇒ 融合第一拍拿它算漂移纠正速度 ✓。
        self._merge_first = False
        self._drift_pos0 = None
        self._drift_gt = (0.0, 0.0)
        self._drift_ts0 = None
        self._drift_last_ts = None
        # （`_merge_peak` / `_peak_age` / `_edge_own` 已随「边归属相切」整套删除 ✓ 2026-10-01）
        self._prev_tbox = None          # 上一拍的框（判"面积明显变大" ✓ 引
        self._vel_from_box = False      # 本拍速度是否已按"框自身位移 + T"更新 ✓（防重复叠 ✓）
        self._rad = None                # ⭐ 目标**实际半径**（白块学 ✓ 相切/可视化都用它 ✓）
        self._rad_locked = False        # ⭐ 半径已按"首次红框内接"确定过（用户 2026-10-02 ✓）
        self._rad_samples = []
        self._rad_frozen = False
        self._rad_seen = None
        self._rad_t0 = None
        self._was_merged = False        # 上一拍目标框是不是**并集块**（S1→S2 转移 ✓）
        # ⭐⭐⭐ **融合保持态**（用户 2026-10-02 ✓ 原话："融合框判定阈值、规则①②只是在
        #   『未融合时判定进入融合』才使用的，在进入融合之后不再生效，要持续跟踪更新融合框
        #   的变化，直到分离信号出现" ✓）：进门（规则①② ✓）后**规则不再逐帧生效** ✓，
        #   融合框变小也**继续算融合** ✓，直到"可以通过噪声容差判定为砖检出框"（分离信号 ✓）
        #   或框不再包住参照砖 ✓。`_merge_hold_bid` = 保持期参照砖（身份 ✓）。
        self._merge_hold = False
        self._merge_hold_bid = None
        self._recap = []                # M2b：预测态太久后的重新捕获候选 [(pos 全分辨率)] ✓
        self._wh = None                 # 画面 (W, H)（钳制用 ✓ process 时记 ✓）
        # ⭐⭐ 运动向量自我纠错的状态（用户 2026-09-30 要求 ① ✓ 见 `_update_tracks`）
        self._tracks = []               # [{id, p, v, a, age, miss}] 所有检测框的轨迹
        self._next_tid = 1
        self._target_id = None          # 当前认定的目标轨迹 id（滞回 ✓）
        self._sway_n = 0                # "该换目标"连续帧数（满 `_SWITCH_N` 才换 ✓）
        self._prev_target_id = None     # 换目标前的那个（**回归复核**要退回去用 ✓ 用户 ④ ✓）
        self._back_n = 0                # "新目标不再异常"连续帧数（满 `_SWITCH_N` 才回退 ✓）
        self._dev = 0.0                 # 当前目标速度与中位速度的偏差（px/s ✓ 诊断用）
        # 可视化快照（演示窗画"每个候选的运动向量"用 ✓ 纯读 ✓ 不影响任何判定 ✓）
        self._viz = {"tracks": [], "median": (0.0, 0.0), "dev": 0.0,
                     "tid": None, "followed": None}

    def _clamp_into_tbox(self, box):
        """把内部位置 `_raw`（半分辨率）**夹进后端认定的目标框**（用户 2026-09-30 信念口径 ✓）。

        "红框代表**我们认为真目标在它里面**" ✓ —— 只要**还没出现"分离"信号**（后端仍给出这格
        框 ✓），报告位置就不许跑到框外 ✗。框**缩小**时，这层夹取会把位置**拉**向留下的那一侧 ✓
        （用户原话："第 18 帧红框面积缩小了，那么它应该'拉着'追踪器的绿圈往左移动" ✓）。
        夹的是 `_raw`（预测与报告的**源** ✓）⇒ 报告位置照旧过 `_report_pos` 的限速 ✓
        ⇒ 是"**拉**"不是"瞬移" ✓。`box=None` ⇒ 不夹（后端没答案 ✓）。
        """
        if box is None or self._raw is None:
            return
        if float(box[2]) <= 0 or float(box[3]) <= 0:
            return
        # ⚠ 边界一律走 `_tbox_inner`（**内接安全区** ✓ = 框内缩一个半径 ✓）—— 与
        #   `_pos_in_tbox` 同一套口径 ✓，否则"夹 `_raw` 时不留余量、夹报告位置时才留" ⇒
        #   两侧打架 ⇒ 圆圈照样探出 ✗（用户 2026-09-30 问的第 15 帧现象 ✓）。
        x0, y0, x1, y1 = self._tbox_inner(box)
        nx = min(max(self._raw[0], x0 * _SCALE), x1 * _SCALE)
        ny = min(max(self._raw[1], y0 * _SCALE), y1 * _SCALE)
        # ⭐⭐⭐ **夹取限速（第三处硬夹 ✓ 用户 2026-10-03 ✓ 原话："动手" ✓）**：这一处夹的是 `_raw`
        #   （预测与报告的**源** ✓）—— 它一步到位 ⇒ **下一拍** `_report_pos`（`_raw` + 限速 ✓）也
        #   跟着跳 ✗（实测：只改前两处时白线折角仍有 76.5px ✗ 因为源头这一跳没管 ✓）。
        #   ⇒ 同一把尺限速（`_clamp_step_px()` ✓ B 型步数比例 ✓ 帧率无关 ✓）—— ⚠ 在半域里算
        #   （`_raw` 是半分辨率 ✓）⇒ 上限也要 × `_SCALE` ✓；圆已在安全区 ⇒ 一动不动 ✓。
        _lim = self._clamp_step_px()
        if _lim is not None:
            _dx, _dy = float(nx) - float(self._raw[0]), float(ny) - float(self._raw[1])
            _d = math.hypot(_dx, _dy)
            _cap = float(_lim) * float(_SCALE)
            if _d > _cap > 0.0:
                _k = _cap / _d
                nx, ny = self._raw[0] + _dx * _k, self._raw[1] + _dy * _k
        if nx != self._raw[0] or ny != self._raw[1]:
            _dm = abs(nx - self._raw[0]) + abs(ny - self._raw[1])
            self._raw = (nx, ny)
            # ⭐ **这一拍发生过夹取** ⇒ raw 的移动混着"被框拉回"的量、不是目标运动 ✗
            #    ⇒ 轨迹样本入样要跳过这一拍（用户口径"夹取只改本帧位置，绝不影响
            #    白箭头（预测）" ✓ —— 路径样本喂的就是预测 ✗ 见 `_path_pred` ✓）。
            # ⭐⭐ 但**内接的微调**（每帧往退化安全区中心挪一两个 px ✓）不算"污染" ✗ ——
            #   它会把路径样本**全滤空**（实测 `_path` 只剩首帧 1 个样本 ⇒ 白线/切向全废 ✗✗）
            #   ⇒ 只有**明显的夹取**（外推/咬错那种几十 px ✓）才置 `_clamped` 跳过样本 ✓。
            if _dm > _CLAMP_SKIP_MIN:
                self._clamped = True

    def _learn_rad(self, wa, ts):
        """学"**目标实际半径**"（用户 2026-09-30 口径 ✓）：白块还在时用 `sqrt(面积/π)` ✓ 取中位
        （与倒计时数字并块的少数帧被压掉 ✓）；白块消失够久 / 学满窗口 ⇒ **永久冻结** ✓。
        """
        if wa and not self._rad_frozen:
            self._rad_samples.append((float(wa) / 3.141592653589793) ** 0.5)
            if len(self._rad_samples) > 240:
                self._rad_samples.pop(0)
            self._rad = sorted(self._rad_samples)[len(self._rad_samples) // 2]
            self._rad_seen = ts
            if self._rad_t0 is None:
                self._rad_t0 = ts
            if ts - self._rad_t0 > _RAD_LEARN_S:
                self._rad_frozen = True
        elif wa:
            self._rad_seen = ts
        elif self._rad_seen is not None and ts - self._rad_seen > _RAD_FREEZE_S:
            self._rad_frozen = True

    # ⚠⚠ **「边归属相切」整套已移除**（用户 2026-10-01 ✓ 原话："移除边归属相切逻辑" ✓）：
    #   原来 `_update_edge_own` 记"红框哪几条边属于真目标"（圆穿过哪条边 ✓）+ 融合块缩小时
    #   把圆拉到那几条边**相切** ✗ —— 现在改成**一条简单判据**：`检出框面积 ≥ 登记假目标
    #   面积 × 「融合框判定阈值」` ⇒ 判红框**融合**（大框 = 目标 + 假目标的并集 ✓）
    #   ⇒ 此时**不做信念夹取**、绿圈**继续按白箭头（预测）走** ✓。
    #   `_prev_tbox`（"上一拍的框"）仍要维护 ✓ —— `_target_box_state` 的"同一格框 + 变大"
    #   判据用它 ✓ ⇒ 搬到调用点直接赋 ✓。
    def _drift_fix_vel(self, ts, at=None):
        """**漂移纠正速度**（用户 2026-10-01 ✓ 两轮口径合一）：

        `（圆圈**报告位置**的位移 − 同期**群体平移**）/ 时间` —— 也就是"圆圈与假目标群的
        **相对位移 / 时间**" ✓（第二轮的公式："（第 17 帧位置 − 第 12 帧位置）/ 时间" ✓ 分子里
        的"位置"= 圆圈报告位置 ✓，扣掉群体后才是"相对位移" ✓）。

        ⭐⭐ `at`（可选）= **终点位置**（加工域 ✓ 默认 `self.pos` ✓）：用户 2026-10-01 要求
        "对绿圈的**修正**要考虑到白箭头轨迹预测里" ✓ —— 融合第一拍把圆修正到对角了，终点就该用
        **修正后的位置**（= 传 `at=修正点` ✓）⇒ 白箭头才会跟着**朝修正的方向**偏 ✓。

        ⚠⚠ **必须用与白/黄箭头同一套群体口径**（`_group_vel` = 登记表 `avg_vel` / `_t_hist` ✓）✗✗
        —— 第一版用 `_path_cumT`（**路径样本坐标系**的累计群体平移 ✗）⇒ 两套群体测量 5 帧能差
        ~200px ⇒ 算出来的方向**整个反了**（实测 (-2,+18)px/帧 vs 实际 (+10,-9)px/帧 ✗✗
        用户当场问"第 17 帧的白箭头速度向量怎么算出来的" ✓）。

        → `(vx, vy)`（**加工域 px/s** ✓ 与 `_vel_rel` 同域 ✓ ⇒ 直接写给它 ✓）
        ｜ `None`（没有起点 / 时间太短 ⇒ 不猜 ✗ 调用方沿用旧速度 ✓）。
        """
        _p = at if at is not None else self.pos
        if (self._drift_pos0 is None or self._drift_ts0 is None
                or _p is None or not ts):
            return None
        _dt = float(ts) - float(self._drift_ts0)
        if _dt <= 1e-3:
            return None
        _dx = float(_p[0]) - self._drift_pos0[0] - self._drift_gt[0]
        _dy = float(_p[1]) - self._drift_pos0[1] - self._drift_gt[1]
        return (_dx / _dt, _dy / _dt)

    def _is_merged_box(self, box):
        """这个检出框是不是「**融合框**」= **真并集**（用户 2026-10-01 ✓ 最新定稿 ✓）。

        判据（一条 ✓）：这格框**包围**某块**已上板**的假目标（覆盖率 ≥ `_FAKE_COV_MIN` ✓ **或**
        至少把那块假框的**中心**吞在框里 ✓ —— "并集 = 目标 + 砖 叠出来的样子"就是这个样 ✓）
        **且** `IoU(检出框, 那块假目标的登记框) < self.merge_iou` ✓（用户 2026-10-03 ✓ 原话：
        "把『融合框判定阈值』换成『**融合框判定 IoU**』：**小于这个 IoU 才行**，之前配的 1.2
        改成 **0.5**" ✓ —— **取代**原来那条"面积比 ≥ 阈值" ✗ 见 `_MERGE_IOU` ✓）。

        ⭐⭐ **两条路都通向融合**（用户 2026-10-02 定稿 ✓ 原话："规则②：如果框住了砖并且
          整圈在框内 → 必定标红；但是，如果框住了砖但并不是整圈框内 → **不一定不标红**！
          规则②是**充分条件**，不是必要条件" ✓）：
          · **规则②（充分 ✓）**：框包住砖 + **整圈绿圈在框内**（`_circle_inside` ✓）
            + 面积比 ≤ `_OVERLAP_RATIO` ⇒ 融合 ✓（"面积与砖相等也算"那一档 ✓ ⚠ 规则② **不看 IoU** ✓）；
          · **规则①**：**`IoU(检出框, 那块砖的登记框) < 配置值`**（用户 2026-10-03 ✓ 原话
            "**小于这个 IoU 才行**" ✓ 见 `_MERGE_IOU` ✓）**且「圆心 ± 噪声容差」范围与框相交**
            （`_pos_range_hits` ✓ 用户 2026-10-02 三次定稿 ✓）⇒ 融合 ✓
            —— 帧 17 的形状（条目锁着、圆心在框里、框比砖大得多 ✓）。
        ⚠⚠ **分母 = 登记表里那块假目标的面积**（`self._reg.confirmed_boxes()` ✓）——**不是**当拍
          检出的中位 `_typ_area` ✗✗（那个逐帧抖 1.7 倍 ⇒ **同一格框面积一点没变也会"过线"**
          ⇒ 假融合 ✗：实测 `9月30日(1).mp4` 帧 9 面积 17040 与上一拍**完全相同**，只因 `_typ_area`
          从 14768 掉到 12117 就被判融合 ✗✗ = 用户报的"没有任何融合信号的红框"✓）。
        ⚠ 框里**没有**任何已上板假目标 ⇒ **不是融合**（没有"并集"可言 ✓ 保守 ⇒ 走非融合的老路 ✓）。
        ⚠⚠ **不做"白块免判"** ✗✗（`_observed_in` ✓ 那是**身份判定** `_box_identity` 的闸 ✓ 不是这条的 ✗）：
          真并集那一拍目标白块**照样在框里**（并集 = 目标 + 砖 ✓）⇒ 拿白块免判会把**真并集漏掉** ✗✗
          （实测合成台：漏掉后 8~11 帧"并集当目标框"夹取 ⇒ 位置误差中位 **5.0 → 19.4px** ✗）。
        **融合 ⇒ 全套"并集待遇"**（不夹取 + 速度冻结 + 半径冻结 + 就近内接修正 ✓ = 用户 Q6/Q7 ✓
          —— 能走到这里的只剩真并集 ✓ "规则②照常"那档已被 `_brick_owned` 拦下 ✓）。
        """
        if box is None:
            self._merge_why = {"rule": "", "why": "没框"}
            return False
        _ref, _cov = self._fake_ref(box)
        if _ref is None:
            self._merge_why = {"rule": "", "why": "框里没有已上板的砖 ⇒ 不是并集"}
            return False
        _bx0 = float(box[0]) - float(box[2]) / 2.0
        _by0 = float(box[1]) - float(box[3]) / 2.0
        _bx1 = float(box[0]) + float(box[2]) / 2.0
        _by1 = float(box[1]) + float(box[3]) / 2.0
        _covers = bool(_cov >= _FAKE_COV_MIN
                       or (_bx0 <= float(_ref.x) <= _bx1 and _by0 <= float(_ref.y) <= _by1))
        if not _covers:
            self._merge_why = {"rule": "", "cov": float(_cov), "covers": False,
                               "ref_bid": tuple(_ref.bid),
                               "why": "没包住砖（覆盖率 < %.2f 且砖心不在框内）" % _FAKE_COV_MIN}
            return False
        _a = float(box[2]) * float(box[3])
        _fa = float(_ref.w) * float(_ref.h)
        _ratio = (_a / _fa) if _fa > 0.0 else 0.0
        # ⭐⭐⭐ **规则① 的判据 = `IoU(检出框, 该砖的登记框)`**（用户 2026-10-03 ✓ 原话："把
        #   『融合框判定阈值』换成『**融合框判定 IoU**』：**小于这个 IoU 才行**" ✓ 见
        #   `_MERGE_IOU` ✓）—— **取代**原来那条"面积比 ≥ 阈值"✗（它在"框远大于砖"时分不出
        #   "并集"与"框只是大"✗；IoU 尺度无关 ✓）。
        _iou_b = geom.iou(box, (float(_ref.x), float(_ref.y), float(_ref.w), float(_ref.h)))
        # ⚠⚠ **2026-10-03 教训：迟滞不要做在这里** ✗✗ —— 第一版把"保持期用退出阈值"加在
        #   本函数上 ⇒ 更多框被当**融合候选** ⇒ **选框那步更爱换框** ⇒ 会话更碎 ✗（对照台实测：
        #   10月2日 融合 23 → **1** 帧 ✗✗）。⇒ **进入判据一律用严的那个** ✓（`merge_iou` ✓）；
        #   "守"挪到保持侧 ✓ 见 `_iou_below_out` 与 `_target_box_state` 的保持分支 ✓。
        # ⭐⭐⭐ **参数分档（用户 2026-10-03 ✓）**：本拍"框↔内砖 IoU"的上界 = `_brick_iou_thr()`
        #   （分离期严 ✓ / 融合期松 ✓ = **迟滞** ✓）；另加**第①条前置** = `（圆外接矩形 ∩ 框）÷
        #   圆外接矩形面积` 要 `> ring_cov_xxx` ✓（**取代**原来那条"圆心±噪声容差与框相交" ✗
        #   用户明确："替换" ✓；⚠ 分母 = **圆矩形面积** ✗ **不是并集** ✓ 2026-10-03 二次修订 ✓）。
        _thr_b = self._brick_iou_thr()
        _ring = self._ring_cov(box)
        _ring_thr = self._ring_cov_thr()
        _ring_ok = bool(_ring > _ring_thr)
        # ⭐⭐ **「为什么判成融合」的诊断留档**（用户 2026-10-02 ✓ 原话："当融合框生成时添加日志，
        #   显示**相关的砖**以及**解释判定为融合框的计算数据**" ✓）⇒ 把这条判据里**算过的每一个
        #   量**记下来 ✓（`_target_box_state` 判 `merged` 时快照、`_build_merge_log` 组一句中文 ✓）。
        #   ⚠ 只**记录**、不改判据 ✗（`_circ`/`_pin` 就是原来那两次调用 ✓ 行为逐位不变 ✓）。
        _circ = bool(self._circle_inside(box))
        # ⭐ 规则① 的这一条 = **「圆心 ± 噪声容差」范围与框相交**（用户 2026-10-02 ✓ 原话：
        #   "圆心在框内改成『圆心±噪声容差范围与框相交』" ✓ 见 `_pos_range_hits` ✓）。
        # ⚠⚠ **这条已被"圆外接矩形与检出框相交的比例"替代** ✗（用户 2026-10-03 ✓ 先说"**替换**"
        #   ✓ 当天再改分母 ✓ 原话："……**相交的比例**" ✓）——
        #   保留**只作诊断**（`pos_in` / `pos_gap` 仍写进 `_diag` ✓ 便于对照"两种尺差多少" ✓），
        #   **不再参与判定** ✗（`_r1` 只看 `_ring_ok` ✓）。
        _pin = bool(self._pos_range_hits(box, tol=float(getattr(self, "noise_tol", 0.0) or 0.0)))
        _diag = {"covers": True, "cov": float(_cov), "ratio": float(_ratio),
                 # ⭐ **IoU 口径**（用户 2026-10-03 ✓）：`iou` = 本判据实际用的那个量 ✓
                 #   `thr` = 现在的阈值（**含义已从"面积比"变成"IoU"** ✓ 日志/自检读它 ✓）
                 "iou": float(_iou_b),
                 # ⭐ **分档口径（用户 2026-10-03 ✓）**：`ring` = **圆矩形∩框 ÷ 圆矩形面积** ✓、
                 #   `ring_thr` = 本档下界（分离期/融合期各一 ✓）、`brick_thr` = 本档内砖上界 ✓
                 "ring": float(_ring), "ring_thr": float(_ring_thr),
                 "ring_ok": bool(_ring_ok), "brick_thr": float(_thr_b),
                 # ⚠ `pos_in` 保留键名（自检 / 日志都在读 ✓）—— 语义已按用户口径更新：
                 #   True = **圆心±容差的范围与框相交** ✓（`tol=0` 时才是"圆心严格在框内"✓）。
                 "circle": _circ, "pos_in": _pin,
                 # ⭐ 诊断：圆心范围离框还有多远（px ✓ 0 = 相交 ✓）—— "为什么这格不算融合"
                 #   一眼能看到"只差 0.4px"这类量 ✓（只记录、不改判据 ✗）
                 "pos_gap": self._pos_gap_to_box(
                     box, tol=float(getattr(self, "noise_tol", 0.0) or 0.0)),
                 "thr": float(self.merge_iou), "ov_max": float(_OVERLAP_RATIO),
                 "rad": float(getattr(self, "_rad", 0.0) or 0.0),
                 "ntol": float(getattr(self, "noise_tol", 0.0) or 0.0),
                 "box": (float(box[0]), float(box[1]), float(box[2]), float(box[3])),
                 "ref_bid": tuple(_ref.bid),
                 "ref_box": (float(_ref.x), float(_ref.y), float(_ref.w), float(_ref.h)),
                 "ref_pending": bool(getattr(_ref, "_shape_pending", False))}
        # ⭐⭐⭐ **规则 ②（用户 2026-10-02 ✓ 明确："规则②没有让你删过，恢复" ✓）**：框把绿圈
        #   **整圈**包住了、且"面积与砖相等"（≤ `_OVERLAP_RATIO` ✓）⇒ **算融合** ✓
        #   （用户原话：②"如果小检出框**即包住了砖，又包住了绿圈**，那么**即使它的面积与砖相等
        #   也属于融合红框**" ✓；"包住绿圈" = **整个圆圈完全在检出框内部** ✓ `_circle_inside` ✓）。
        #   覆盖"**真目标和假目标正好完全重叠**"（面积一样 ⇒ 光比面积永远认不出来 ✗）✓。
        if _circ and _ratio <= _OVERLAP_RATIO:
            self._merge_why = dict(_diag, rule="②",
                                   why="整圈绿圈在框内 且 面积比 ≤ %.2f" % _OVERLAP_RATIO)
            return True
        # ⭐⭐⭐ **规则 ①（用户 2026-10-02 三次定稿 ✓ 原话：**
        #   **"圆心在框内改成『圆心±噪声容差范围与框相交』"** ✓**）**：
        #   面积比 ≥ 配置阈值 **且「圆心 ± 噪声容差」范围与检出框相交**（`_pos_range_hits` ✓）⇒ 融合 ✓
        #   —— 帧 17（比 1.604、圆心 (359.7,254.8) 在框里 ✓）走这条 ✓；帧 16 圆心只出框
        #     0.7px ✗ 严格判会漏 ⇒ 「噪声容差」兜住 ✓。
        #   ⚠⚠ 口径三次演进（都是用户定的 ✓ 数值上"相交"这一版 = 上一版"点落在扩过的框里" ✓
        #     逐条等价 ⇒ 行为不变 ✓，名字与写法按用户口径显式化 ✓）：
        #     ① 首版"与绿圈**外接圆**相交"（`_circle_hits` ✗ 被半径放大 ✗ 帧 22：圆心在框外
        #        25px 也算"相交" ✗✗ = 用户点名 ✓）⇒ ② 收紧为"**圆心在框内**（外扩「噪声容差」）"✓
        #        ⇒ ③ 本次显式写成"**圆心±噪声容差范围与框相交**"✓（同一把尺、同一个数 ✓）。
        #   ⚠ 容差是**有限**的 ⇒ 不是万能兜底 ✗：帧 70 那一格圆心出框 25.4px、容差 25px
        #     ⇒ 范围与框仍差 **0.4px** ⇒ 不融合 ✓（要它融合得把容差调到 ≥ 25.4 ✓）。
        #   ⚠ 圆心不在框里的大框交由 `_target_box_state` 选框的"**未登记框优先**"那条路管 ✓
        #     （用户帧 22 第二条 ✓）。
        # ⭐⭐⭐ **规则①（2026-10-03 换成 IoU ✓）**：`IoU(框, 砖) < 配置值` **且** `圆心±容差与框
        #   相交` ⇒ 融合 ✓（用户原话："**小于这个 IoU 才行**" ✓）。⚠ 原来那条"面积比 ≥ 阈值"
        #   **已撤** ✗（同一句口径 ✓ 见 `_MERGE_IOU` ✓）。
        # ⭐⭐⭐ **规则①（2026-10-03 参数分档 ✓）** = **两条同时满足** ✓：
        #   ① `（圆外接矩形 ∩ 检出框）÷ 圆外接矩形面积 > ring_cov_本档` ✓（用户那句话的前半
        #     ✓ —— ⚠ 分母是**圆矩形面积** ✗ **不是并集** ✓ 2026-10-03 二次修订 ✓）；
        #   ② `IoU(检出框, 该砖) < brick_iou_本档` ✓（后半 ✓ 分离期 0.5 / 融合期 0.7 ✓ = 迟滞 ✓）。
        _r1 = bool(_ring_ok and _iou_b < _thr_b)
        self._merge_why = dict(_diag, thr=float(_thr_b), rule=("①" if _r1 else ""),
                               why=("圆矩形∩框 ÷ 圆矩形 %.2f > %.2f ✓ 且 框↔内砖 IoU %.2f < %.2f ✓"
                                    % (_ring, _ring_thr, float(_iou_b), _thr_b) if _r1
                                    else "两条规则都不成立"))
        return _r1

    def _hold_ref(self):
        """融合保持期的**参照砖**（按 bid 在登记表里找 ✓ 找不到 ⇒ None ⇒ 保持态作废 ✓）。"""
        bid = getattr(self, "_merge_hold_bid", None)
        if bid is None:
            return None
        _reg = getattr(self, "_reg", None)
        if _reg is None:
            return None
        for _e in _reg.entries:
            if tuple(_e.bid) == tuple(bid):
                return _e
        return None

    def _box_covers_entry(self, box, e):
        """框还包住那块砖吗（交集 ≥ 0.5×砖面积 **或** 砖心在框内 ✓）—— 融合保持的底线 ✓：
        框连砖都不包了 = 目标已经走了 ⇒ 保持态作废（也算分离 ✓）。"""
        if box is None or e is None:
            return False
        _bx0 = float(box[0]) - float(box[2]) / 2.0
        _by0 = float(box[1]) - float(box[3]) / 2.0
        _bx1 = float(box[0]) + float(box[2]) / 2.0
        _by1 = float(box[1]) + float(box[3]) / 2.0
        _ex0 = float(e.x) - float(e.w) / 2.0
        _ex1 = float(e.x) + float(e.w) / 2.0
        _ey0 = float(e.y) - float(e.h) / 2.0
        _ey1 = float(e.y) + float(e.h) / 2.0
        _ix = max(0.0, min(_bx1, _ex1) - max(_bx0, _ex0))
        _iy = max(0.0, min(_by1, _ey1) - max(_by0, _ey0))
        _ea = float(e.w) * float(e.h)
        _swallow = (_bx0 <= float(e.x) <= _bx1 and _by0 <= float(e.y) <= _by1)
        return bool((_ea > 0.0 and _ix * _iy >= 0.5 * _ea) or _swallow)

    def _box_is_brick_det(self, box, e):
        """**分离信号**（用户 2026-10-02 ✓ **最新定稿 = 三条同时成立** ✓ 原话："**框缩成砖 &&
        框中心在轨迹预测方向的反方向 && 融合期间融合框的最大面积 >= 融合期间融合框的最小
        面积 \* x**" ✓、x = 「分离判定阈值」`self.sep_ratio` ✓）：
        **① 框缩成砖** 且 **② 框中心在预测方向的反方向** 且 **③ 融合期框面积真的缩过**
        ⇒ 才算"融合结束（分离）" ✓。

        **① 框缩成砖**（2026-10-02 二次定稿 ✓ 原话："检出框缩小到**比砖大『噪声容差(px)』
        以内**即可判分离" ✓）：框的每条边都**不超出**砖对应边外扩噪声容差的范围
        （框 ⊆ 砖矩形 ⊕ 容差 ✓；**框可以比砖小** ✗ 那只是残框/被真目标压住的砖的一部分 ✓
        旧判据要求四边 |差| 都 ≤ 容差 ✗ = 框比砖小也算"没缩到位" ✗ 帧 25 抓到 ✓）。

        **② 框中心在预测方向的反方向**（2026-10-02 ✓ 用户本轮新增 ✓）：判据 = `(框中心 −
        圆心) · 白箭头方向 < 0` ✓ —— 就是 `_box_ahead_of_pred` 的**取反** ✓（**同一把尺** ✓
        白箭头 = `_vel_rel` ✓ 用户 2026-10-02 选 "白箭头方向、以圆心为基准" ✓）。
        为什么要有这条：只有 ① 时，"缩成砖"的框可能是**目标自己那一格**（或它正要去的那格 ✗
        —— 目标走进属砖的格子时，那格检出框也正好 == 砖本身 ✓）⇒ 会**误判分离**、把跟踪白
        丢一拍 ✗。真目标正沿白箭头方向走 ⇒ 它**身后**那块砖缩回原尺寸，才会留下"就是砖自己"
        的框 ⇒ **框心落在预测反方向**才说明"这是被落下的砖" ✓。

        ⚠ 白箭头速度 ≈ 0 / 拿不到方向（还没学出来 ✓）⇒ `_box_ahead_of_pred` 回 `True`（判不出
          ⇒ 保守放行 ✓ 不猜 ✗）⇒ 本条**取反后为假** ⇒ **不判分离** ✓（宁可按融合继续跟、
          也不凭空丢一次跟踪 ✓；下一拍方向一出来就照常判 ✓）。

        **③ 融合期框面积真的缩过**（2026-10-02 ✓ 用户本轮新增 ✓；⭐⭐ **2026-10-03 口径修订** ✓
        用户原话："把 ③ 改成「**本拍之前的最大 ≥ 本拍面积 × 分离判定阈值**」" ✓）：
        `_merge_area_span_ok` ✓ —— **本拍之前的最大框面积 ≥ 本拍框面积 × `sep_ratio`** ✓
        （记账见 `_merge_area_note` ✓；旧式"最小 → 其后最大"已废 ✗ 见该函数 docstring ✓）。
        为什么要有这条：①② 只说明"这一拍的框已经等于砖、且在预测反方向"，但**并集框从
        大缩到小**才是"砖从目标身上分离出来"的物理过程 ✗ —— 若整个融合期框面积几乎没变，
        那"等于砖"更可能是**一开始就量错了**（框本来就是砖大小 ✓ 当初压根不该判融合 ✗）
        ⇒ 不判分离 ✓、保持继续 ✓。
        """
        if box is None or e is None:
            return False
        _tol = float(getattr(self, "noise_tol", 0.0) or 0.0)
        _bx, _by = float(box[0]), float(box[1])
        _bw, _bh = float(box[2]), float(box[3])
        _bl, _br = _bx - _bw / 2.0, _bx + _bw / 2.0
        _bt, _bb = _by - _bh / 2.0, _by + _bh / 2.0
        _el = float(e.x) - float(e.w) / 2.0
        _er = float(e.x) + float(e.w) / 2.0
        _et = float(e.y) - float(e.h) / 2.0
        _eb = float(e.y) + float(e.h) / 2.0
        _shrink = bool(_bl >= _el - _tol and _br <= _er + _tol
                       and _bt >= _et - _tol and _bb <= _eb + _tol)
        if not _shrink:
            # ⭐⭐⭐ **另一把尺：「框 ⇄ 砖 的 IoU ≥ 阈值」也算"缩成砖"**（用户 2026-10-03 ✓
            #   原话："我认为我们很多判定都可以换成这个算法（例如『噪声容差』改成『**噪声最小
            #   IoU**』）" ✓ 见 `_IOU_BRICK` ✓）：上面那条是**绝对像素**（同一 25px 对大砖松、
            #   对小砖紧 ✗），这条是**尺度无关**（"两框是不是同一块"✓ = IoU 的天然场景 ✓）。
            #   ⚠ 两条**并列 OR** ✓：任一满足即算"缩成砖" ✓；`iou_brick = 0`（默认）⇒ 不参与 ✓
            #   （老行为一字不变 ✓）。
            _ib = float(getattr(self, "iou_brick", 0.0) or 0.0)
            if _ib <= 0.0:
                return False
            if geom.iou(box, (float(e.x), float(e.y), float(e.w), float(e.h))) < _ib:
                return False
        # ⭐ **② 框中心在轨迹预测方向的"反方向"**（用户 2026-10-02 ✓）—— 取 `_box_ahead_of_pred`
        #   的反 ⇒ 速度拿不到方向时它回 True ⇒ 这里 False ⇒ **不判分离** ✓（见 docstring ✓）。
        if self._box_ahead_of_pred(box):
            return False
        # ⭐⭐⭐ **③ 融合期框面积要真的缩过**（用户 2026-10-02 ✓ 2026-10-03 口径修订 ✓ 见
        #   `_merge_area_span_ok` ✓）—— 新式 = "**本拍之前的最大面积 ≥ 本拍面积 × 阈值**" ✓
        #   ⇒ 把**本拍框面积**传进去（不传就判不出 ⇒ 不成立 ✓ 不猜 ✗）。
        return self._merge_area_span_ok(
            (float(box[2]) * float(box[3])) if box is not None else None)

    def _merge_area_note(self, box):
        """把这一拍的**融合框面积**记进**时序序列**（用户 2026-10-02 ✓ 分离信号第三条的记账 ✓）。

        ⭐⭐ **为什么存整条序列而不是两个极值**（用户 2026-10-02 二次定稿 ✓）：第三条要的是
        "**融合期间融合框出现最小面积后出现的最大面积** ≥ 最小面积 × x" ✓ —— "**出现最小
        面积之后**"是个**时序**条件 ✗，用"全域 max / min"表达不出来（那个分不清"先大后小"
        与"先小后大" ✗）。所以按拍序把面积都留着 ✓（融合段通常只有几拍，代价可忽略 ✓）。

        只该在"这一拍该框仍是融合框（还包着参照砖 ✓）"时调 ✓ —— 见 `_target_box_state` 的
        保持分支 ✓（框已不包砖的那一拍算"出融合"，面积不具代表性 ✗ 不计 ✓）。
        """
        if box is None:
            return
        _a = float(box[2]) * float(box[3])
        if _a <= 0.0:
            return
        _s = getattr(self, "_merge_area_series", None)
        if _s is None:
            _s = self._merge_area_series = []
        _s.append(_a)
        _mx, _mn = self._merge_area_max, self._merge_area_min
        self._merge_area_max = _a if _mx is None else max(float(_mx), _a)
        self._merge_area_min = _a if _mn is None else min(float(_mn), _a)

    def _merge_area_span_ok(self, area=None):
        """⭐ **分离判定（用户 2026-10-03 ✓ 流程图那条「分离判定阈值」✓）**：

        **「历史最小面积（不含本拍）出现之后的历史最大面积」÷ 本拍面积 > 「分离判定阈值」** ✓
        （用户原话确认 ✓："『分离判定阈值』的判定项是『**历史最小面积（不含本拍）出现之后的
        历史最大面积 / 本拍面积**』" ✓）。

        判据（一句话：**"已缩到过最小之后的**最大**" ≥ 本拍面积 × 阈值** ✓ —— 纯**时序**版）：
          · `历史最小` = 本会话序列（**不含本拍** ✓）里的最小值 ⇒ 取它**首次**出现的下标 ✓；
          · 分子 = 那个下标**之后**的**最大**面积 ✓（用户 2026-10-03 原话："**取已缩到过最小后的
            最大**" ✓ —— 取"最大"而非"当前那拍" ⇒ "张开过又回落"也成立 ✓）；⚠⚠ **`_after` 为空
            （一路缩 ⇒ 最小在末位）⇒ 退用整体历史最大** ✓（否则"一路缩到砖"这个最典型的形态
            永远判不出来 ✗✗ 实测帧 62/63/64 全 False ✓ 见下 ✓）；
          · 分母 = **本拍框面积** ✓；`>` 阈值（`sep_ratio` ✓）。
        `area` = **本拍框面积**（调用方传 ✓；不传 ⇒ 判不出 ⇒ **不成立** ✓ 不猜 ✗）。

        ⚠⚠ 为什么换掉旧式（"最小面积 → **其后**最大面积 ≥ 最小 × x" ✗）：那把尺要求
          "先缩到最小、**后来又涨回来**" ⇒ 而"**一路缩到砖**"（分离最典型的形态 ✓ 框从并集
          连续缩到砖大小 ✓）根本没有"涨回来"这一步 ⇒ 旧式**几乎永远不成立**（实测两段素材、
          在"①②已成立"的 156 次判定里只成立 **3 次 ≈ 2%** ✗✗）⇒ 「框已缩成砖」这条分离
          来路事实上被关掉 ✗（`10月1日.mp4` 帧 15 就是：框已 ≈ 砖、框心也在预测反方向，
          只因第三条不成立 ⇒ 判不了分离 ⇒ 圆被"包着砖的框"夹过去 89px ✗ = 用户点名 ✓）。
          新式用**绝对值**（历史最大 vs 本拍 ✓）⇒ 不依赖"其后涨回" ✓、也不依赖"本拍算不算"
          （同一批 156 次里成立 **152 次 ≈ 97%** ✓ 与"①②成立 ⇒ 确实缩过"的直觉一致 ✓）。
        ⚠ 记账仍沿用"**本拍不算**" ✓（`_merge_area_note` 在**判定之后**才追加本拍 ✓ 见
          `_target_box_state` 保持分支 ✓）—— 于是这里读到的序列**正好就是"本拍之前"** ✓
          不需要任何额外剔除 ✓（用户 2026-10-03 确认："本拍不算"指的就是判分离的那一拍 ✓）。
        """
        _s = [float(v) for v in (getattr(self, "_merge_area_series", None) or [])]
        if not _s or area is None:
            return False
        _mn = min(_s)
        _i = _s.index(_mn)                   # 最小值**首次**出现的位置 ✓
        _after = _s[_i + 1:]                 # 它**之后**的那些拍 ✓
        # ⭐⭐⭐ **分子 = "已缩到过最小之后的**最大**"**（用户 2026-10-03 ✓ 原话："不是必须已缩到过
        #   最小、且当前又张开，而是**取已缩到过最小后的最大**" ✓）—— `_after` 里取的正是
        #   **最大值**（不是"当前那拍" ✗），所以"张开过又回落"也照样成立 ✓。
        #   ⚠⚠ **`_after` 为空时必须回退** ✗✗（否则"**一路缩到砖**"这种最典型的分离形态
        #     **永远判不出来** ✗×）：一路缩 ⇒ 最小值**永远落在末位** ⇒ `_after` 恒空 ✗ ⇒
        #     旧实现直接 `return False` ✗ ⇒ 实测 `10月1日.mp4` 帧 62/63/64 面积
        #     **32130 → 25539 → 21351**（一路在缩 ✓ 正是"缩回砖"✓）却**三拍全是 False** ✗✗
        #     （用户直接问："**缩框了，为何没分离？**" ✓）。⇒ 空时退用**整体历史最大** ✓
        #     （= 注释里那句"新式用绝对值：历史最大 vs 本拍"✓ 与 `_merge_area_span_info` 同口径 ✓）。
        _mx_after = max(_after) if _after else max(_s)
        if _mx_after <= 0.0:
            return False
        return bool(_mx_after >= float(area) * float(self.sep_ratio))

    def _merge_area_span_info(self, area=None):
        """⭐ 分离判定的诊断量 ⇒ `(最小之后的最大面积, 它出现在第几拍, 本拍面积, 比值)`
        （用户 2026-10-03 ✓ 口径 = **历史最小（不含本拍）之后**的最大 ✓ 见 `_merge_area_span_ok` ✓）。"""
        _s = [float(v) for v in (getattr(self, "_merge_area_series", None) or [])]
        if not _s or area is None:
            return (None, None, None, None)
        _mn = min(_s)
        _i = _s.index(_mn)
        _after = _s[_i + 1:]
        if not _after:
            return (None, int(_i), float(area), None)
        _mx = max(_after)
        return (float(_mx), int(_i + 1 + _after.index(_mx)), float(area),
                (float(_mx) / float(area)) if float(area) > 0 else None)

    def _split_diag(self, box, ref, how):
        """⭐ **融合框消失（分离）那一拍的诊断载荷**（用户 2026-10-02 ✓ 原话："把融合框消失
        （分离）的日志**也依据融合的格式**打印出来" ✓）—— 与 `_merge_why` **同一格式**：把
        这条判据里**算过的每一个量**都记下来 ✓（`_build_split_log` 组一句中文 ✓）。

        `how` = 是哪条判据判出去的 ✓（⭐ **2026-10-03 简化后只剩两条主路** ✓ 见 `_target_box_state`）：
          · `"落点倒退超限"`（⭐ 用户流程图 ✓：融合第 2 拍起，落点相对**本拍白箭头**落在后方
            180° 扇形内、且长度 > 「允许倒退距离」× 半径 ✓ 见 `_merge_fix_safe` ✓）
          · `"面积跨度超阈值"`（⭐ 用户流程图新增 ✓：**本拍之前的最大框面积 ≥ 本拍面积 ×
            「分离判定阈值」** ✓ 见 `_merge_area_span_ok` ✓ —— 与上一条**并列 OR** ✓）
          · `"门内没有能挑的格"`（门里有框但**全都不够格**当红框 ✓ 用户 2026-10-03 明确保留 ✓；
            含"内砖与参照砖不同"那类被筛掉的情形 ✓ 见 `_same_inner_brick` ✓；⚠ 这一档会把
            **被筛的框**交给本函数（`box` 不为 None ✓）⇒ 覆盖率/四边差照常写出来 ✓）
          · `"检出框丢了"`（这一帧没有可用检测框 ✓ 第二条主路 ✓）

        ⚠ 只**记录**、不改判据 ✗（那些量就是判据里本来要算的 ✓ 行为逐字不变 ✓）。
        """
        _tol = float(getattr(self, "noise_tol", 0.0) or 0.0)
        # ⭐ 第三条的诊断（用户 2026-10-02 ✓ 2026-10-03 口径修订 ✓）：与 `box` 无关 ⇒ 放在基础
        #   字段里 ✓ —— 这样"门内没有能挑的格"那类分离（没有框 ✓）也能把融合期面积写进日志 ✓。
        #   新口径要**本拍框面积**（"本拍之前的最大 ≥ 本拍 × 阈值" ✓）⇒ 从 box 算出来传进去 ✓。
        _amn, _ami, _amx, _arr = self._merge_area_span_info(
            (float(box[2]) * float(box[3])) if box is not None else None)
        _d = {"how": how, "ntol": _tol, "thr": float(self.merge_iou),
              "rad": float(getattr(self, "_rad", 0.0) or 0.0),
              "pos": (None if self.pos is None
                      else (float(self.pos[0]), float(self.pos[1]))),
              "box": (None if box is None else tuple(float(v) for v in box)),
              "ref_bid": (None if ref is None else tuple(ref.bid)),
              "ref_box": (None if ref is None
                          else (float(ref.x), float(ref.y), float(ref.w), float(ref.h))),
              "sep_ratio": float(self.sep_ratio),
              "area_n": len(getattr(self, "_merge_area_series", None) or []),
              "area_prev_max": _amn, "prev_max_idx": _ami, "area_self": _amx,
              "area_ratio": _arr}
        if box is None or ref is None:
            return _d
        _b = tuple(float(v) for v in box)
        _bl, _br = _b[0] - _b[2] / 2.0, _b[0] + _b[2] / 2.0
        _bt, _bb = _b[1] - _b[3] / 2.0, _b[1] + _b[3] / 2.0
        _el, _er = float(ref.x) - float(ref.w) / 2.0, float(ref.x) + float(ref.w) / 2.0
        _et, _eb = float(ref.y) - float(ref.h) / 2.0, float(ref.y) + float(ref.h) / 2.0
        _ix = max(0.0, min(_br, _er) - max(_bl, _el))
        _iy = max(0.0, min(_bb, _eb) - max(_bt, _et))
        _ea = float(ref.w) * float(ref.h)
        _d.update({
            # 覆盖率（"包住砖"那条用的就是它 ✓）与砖心在不在框里 ✓
            "ref_cov": round((_ix * _iy / _ea) if _ea > 0 else 0.0, 3),
            "ref_center_in": bool(_bl <= float(ref.x) <= _br
                                  and _bt <= float(ref.y) <= _bb),
            # 面积比（融合阈值那条用的 ✓）—— 分离时它必然 < 阈值 ✓
            "ratio": round((_b[2] * _b[3] / _ea) if _ea > 0 else 0.0, 3),
            # 四边差（`_box_is_brick_det` 的四条不等式 ✓：框每条边相对于砖对应边外扩容差的位置 ✓）
            "edges": (round(_bl - _el, 1), round(_br - _er, 1),
                      round(_bt - _et, 1), round(_bb - _eb, 1)),
            "covers": bool(self._box_covers_entry(_b, ref)),
            "brick_det": bool(self._box_is_brick_det(_b, ref)),
            "hold_ok": bool(self._hold_active(_b)),
            # ⭐ 分离信号的**第二条**（用户 2026-10-02 ✓）：框中心在不在预测方向的反方向 ✓
            #   —— 记下点积（>0 = 前方、<0 = 反方向 ✓）与布尔，便于事后核对"为什么没判分离" ✓。
            "ahead": bool(self._box_ahead_of_pred(_b)),
            "dot": round(self._pred_dot(_b), 1),
            # ⚠ 第三条那几项（`area_min` / `min_idx` / `area_max_after` / `area_ratio` /
            #   `sep_ratio`）在**基础字段**里 ✓（与 box 无关 ✓ 见上 ✓）⇒ 这里不重复 ✗。
            "area_max": (None if getattr(self, "_merge_area_max", None) is None
                         else round(float(self._merge_area_max), 1)),
        })
        return _d

    def _pred_dot(self, box):
        """`(框中心 − 圆心) · 白箭头速度`（px²/s ✓）—— 诊断用 ✓ 符号就是方向：
        `> 0` 前方 / `< 0` **反方向**（分离信号第二条看的正是它 ✓ 用户 2026-10-02 ✓）。"""
        if box is None or self.pos is None:
            return 0.0
        _vr = getattr(self, "_vel_rel", (0.0, 0.0)) or (0.0, 0.0)
        return float((float(box[0]) - float(self.pos[0])) * float(_vr[0])
                     + (float(box[1]) - float(self.pos[1])) * float(_vr[1]))

    def _hold_active(self, box):
        """**融合保持**对本拍这格框是否生效（用户 2026-10-02 ✓ 原话："融合框判定阈值、
        规则①②只是在『未融合时判定进入融合』才使用的，在进入融合之后不再生效，要持续
        跟踪更新融合框的变化，直到分离信号出现" ✓）＝ 保持中 + 还包住参照砖 +
        **不是**砖检出框（分离信号 ✗）✓。

        ⚠ "分离信号"现在是**两条同时成立**（用户 2026-10-02 最新定稿 ✓）：框缩成砖 **且**
          框中心在轨迹预测方向的**反方向** ⇒ 见 `_box_is_brick_det` ✓ —— 所以"缩成砖的框
          落在预测前方"（更可能是目标自己那格）**不再**作废保持 ✓ 会继续跟 ✓。"""
        if not getattr(self, "_merge_hold", False) or box is None:
            return False
        _href = self._hold_ref()
        if _href is None or not self._box_covers_entry(box, _href):
            return False
        return not self._box_is_brick_det(box, _href)

    def _sep_takeover(self):
        """⭐⭐ **分离后的速度"平滑接管"**（用户 2026-10-01 ✓ 原话："分离那一拍速度从冻结值
        **硬切**到实测值，改成**平滑接管**" ✓）—— 每拍调一次（在 `process()` 末尾 ✓ 实测更新
        之后 ✓），接管期内把"冻结值 → 实测值"按 `w=(n+1)/N` **摊开** ✓。

        为什么需要它 ✗（实测 ✓ `9月30日(1).mp4` 显示帧 22）：融合期速度是**冻结**的
        （事实 6 ✓ "不用更新轨迹预测"）⇒ 分离那一拍突然又信实测 ⇒ `vel_rel` **一帧断崖**
        `(65.3,137.0) → (2.3,36.4)` ⇒ 白箭头 **33px → 8px** ✗✗（用户看到的就是"箭头丢了" ✓）。

        ⚠⚠ **只接管"自身分量"** ✓：`_vel` = 自身 + 群体 ⇒ 把**差值**补进 `_vel` 即可 ✗
          别动群体那一份（它永远取**当拍实测** ✓ 不滞回 ✓）。
        ⚠ 不在接管期（`_sep_n is None` ✓）⇒ 一个字都不动 ✓（行为与改动前完全一致 ✓）。
        """
        if getattr(self, "_sep_n", None) is None:
            return
        _N = max(1, int(_SEP_TAKE_N))
        if self._sep_n >= _N:
            return
        _w = float(self._sep_n + 1) / float(_N)
        _v0 = tuple(self._sep_vel0 or (0.0, 0.0))
        _old = tuple(self._vel_rel)
        _new = (_v0[0] * (1.0 - _w) + _old[0] * _w,
                _v0[1] * (1.0 - _w) + _old[1] * _w)
        self._vel_rel = _new
        self._set_vel(self._vel[0] - _old[0] + _new[0],
                      self._vel[1] - _old[1] + _new[1])
        self._sep_n += 1
        if self._sep_n >= _N:
            self._sep_n = None                     # 接管完成 ⇒ 之后完全信实测 ✓
            self._sep_vel0 = None

    def _sep_vel_cap(self):
        """⭐⭐⭐ **分离期的白箭头模长上限**（用户 2026-10-03 ✓ 原话："将**分离期（淡粉色框时期）**
        的**最大相对假目标群速度（白箭头）** = a × **假目标群体的标准速度**，a 为新配置
        『**真目标预测最大速度倍率**』默认 1.0" ✓）。

        · **分离期** = **红框丢失**那一段（`self._tbox is None` ✓ —— 演示窗里画"淡粉接力框"
          的正是这段预测期 ✓ 见 `lie_demo` 的绘制注释 ✓）；有红框（含融合框）时**一个字不动** ✗；
        · "**假目标群体的标准速度**" = **当拍实测的群体速度模长** ✓（`_group_vel` ✓ **小图域
          px/s** ✓ —— 与 `vel_rel` **同域** ✓ 见它的 docstring ✓）；
        · 判据：`|vel_rel| > a × |群体速度|` ⇒ **只压模长**（方向不动 ✓）压回上限 ✓ 并同步
          `_vel = 压后自身 + 群体` ✓（`_set_vel` 收口 ✓）；
        · ⚠ 群体速度判不出（没观测 ⇒ `_group_vel` 回 `None` ✓）⇒ **不夹** ✓（不猜 ✗）。
        """
        if self._tbox is not None:
            return                                  # 有红框 ⇒ 不是"淡粉框时期" ⇒ 不管 ✓
        _dt = float(self._dt_last) if self._dt_last else 0.0
        if _dt <= 0.0:
            return
        _gv = self._group_vel(_dt)
        if _gv is None:
            return
        _gs = math.hypot(float(_gv[0]), float(_gv[1]))
        if _gs <= 1e-6:
            return
        _lim = float(self.sep_vel_max_ratio) * _gs
        _vx, _vy = float(self._vel_rel[0]), float(self._vel_rel[1])
        _vs = math.hypot(_vx, _vy)
        if _vs <= _lim or _vs <= 1e-9:
            return                                  # 没超上限 ⇒ 不动 ✓（**只压不抬** ✓）
        _k = _lim / _vs
        self._vel_rel = self._rel_cap((_vx * _k, _vy * _k))   # ⭐ 白箭头限幅（用户 ✓）
        self._set_vel(self._vel_rel[0] + float(_gv[0]), self._vel_rel[1] + float(_gv[1]))

    def _anti_group_vel(self):
        """⭐⭐ **试验型：把自身速度旋转到「群体速度的反向」**（用户 2026-10-01 ✓ 原话："最终的
        白色轨迹预测箭头旋转至<假目标群体速度向量>方向的反向" + 更正："我并没有说只改箭头方向，
        一定要 **白箭头 = 圆圈真的会走多少**" ✓）。

        ⚠⚠ 这不是"只改显示箭头" ✗ 是**改后端速度** ✓：把 `_vel_rel`（自身分量 ✓ 白箭头读的就是
        它 ✓）旋转到 `-群体速度` 方向（**长度不变** ✓ 旋转保模 ✓），再重算 `_vel = _vel_rel' + 群体`
        ⇒ **圆圈真的朝那个方向走** ✓、白箭头（= `out["vel_rel"]`）自然也指那个方向 ✓ ——
        两者永远同拍同一支速度 ✓（正是用户要的"白箭头 = 圆圈真的会走多少" ✓）。

        群体速度 = **`_group_vel(dt)`（权威口径 ✓）**——登记表里"已上板假目标"的平均速度 ✓ =
        用户定义的"假目标群体速度" ✓。拿不到（表里条目不够 ✓）⇒ 退回 `_vel - _vel_rel`。
        ⚠⚠ **为什么不能用 `_vel - _vel_rel` 当第一选择** ✗✗（用户 2026-10-02 ✓ 帧 36 点名"已经
          差的很远了" ✓）：`_vel` 被 `_set_vel` **限幅 600** ✓ 而 `_vel_rel` **不限** ✓（曲线预测
          一旦给出 798 px/s 的大速度 ✗）⇒ 差值 = 被污染的"群体" ✗ ⇒ 旋转对齐到错方向 ✗✗
          （实测帧 36 偏 46°、帧 40 偏 104° ✗✗）。
        ⚠ 群体≈0 / 自身≈0 ⇒ **不旋转**（没有"上游"可指 ✗ 维持原样 ✓）。
        ⚠ 放在 `process()` **末尾**（`_sep_takeover` 之后、速度回写 `out` 之前 ✓）⇒ 它作用于
           "本拍最终生效值" ✓，且回写出来的就是旋转后的那一支 ✓。
        """
        if not _ANTI_GROUP_VEL:
            return
        _gv0 = self._group_vel(float(getattr(self, "_dt_last", 0.0) or 0.0))
        gv = _gv0 if _gv0 is not None else (
            self._vel[0] - self._vel_rel[0], self._vel[1] - self._vel_rel[1])
        gsp = (gv[0] * gv[0] + gv[1] * gv[1]) ** 0.5
        rsp = (self._vel_rel[0] * self._vel_rel[0] + self._vel_rel[1] * self._vel_rel[1]) ** 0.5
        if gsp <= 1e-6 or rsp <= 1e-6:
            return
        _nr = (-gv[0] / gsp * rsp, -gv[1] / gsp * rsp)   # 自身速度旋转到 -群体 方向（保模 ✓）
        self._vel_rel = _nr
        self._set_vel(_nr[0] + gv[0], _nr[1] + gv[1])     # 绝对速度 = 新自身 + 群体 ✓

    def _box_is_registered_fake(self, box):
        """这格红框是不是**已经塌缩成"某个在册假目标自己那一格"**（用户 2026-10-01 ✓ 原话：
        "第27帧→第28帧大红框变成与登记框重叠的检出框，这是分离的信号" ✓）。

        判据（两条同时成立 ✓）：
        ① 框中心落在某在册假框中心的门内（`_BOX_SELF_GATE` ✓ = "**与登记框重叠**" ✓）；
        ② 框面积**不比那假框大**（`≤ 1.0×` ✓）—— ⚠⚠ 这是关键 ✗：真并集 = 目标 + 假目标 ⇒
           **一定比单块假框大** ✓；若框 ≤ 假框（甚至更小 ✓ 实测第 27~29 帧：`149.6×145.6` 等
           vs 登记假框 `162.7×166.4` ✓）⇒ 说明红框里**没有目标**了 ✗ 只是假目标自己的那一格 ✓。

        → `True` = 分离（真目标走了 ✓ 圆该按预测滑行 ✗ 别再把圆钉到假框的角上 ✗）。
        """
        if box is None:
            return False
        _a = float(box[2]) * float(box[3])
        for _b in self._reg.confirmed_boxes():
            ex, ey, ew, eh = (float(_b[0]), float(_b[1]), float(_b[2]), float(_b[3]))
            if math.hypot(float(box[0]) - ex, float(box[1]) - ey) <= _BOX_SELF_GATE:
                if _a <= ew * eh:
                    return True
        return False

    def _observed_in(self, box):
        """这一拍**有没有"目标的直接观测"落在这格框里**（白块 ✓ 用户 2026-09-30 口径 ✓）。

        ⚠ 它是 `_box_identity` 的**免判闸** ✗：白块在框里 ⇒ 目标**就在这格**（哪怕它正站在
          某块在册假框上 ✓）⇒ 不许判"这只是块假目标" ✗（实测开局帧 5~10：白块 `(374,251)`
          落在 129×128 的框里、那框又恰好是一块**已上板**的砖 ⇒ 判假目标会把开局的
          **红框整个抹掉** ✗✗ —— 那是目标自己 ✓）。
        """
        w = getattr(self, "_white_cur", None)
        if not w or box is None:
            return False
        x, y = float(w[0]), float(w[1])
        return (float(box[0]) - float(box[2]) / 2 <= x <= float(box[0]) + float(box[2]) / 2
                and float(box[1]) - float(box[3]) / 2 <= y <= float(box[1]) + float(box[3]) / 2)

    def _pos_range_hits(self, box, tol=0.0):
        """**「圆心 ± 噪声容差」这个范围，与检出框相交吗？**（用户 2026-10-02 ✓ 原话：
        "圆心在框内改成『**圆心±噪声容差范围与框相交**』" ✓）—— 给"**目标还在那格吗**"用
        （融合规则① ✓ ／ 分离判据 ✓）。

        范围 = 以圆心为中心的**轴对齐方块** `[px−tol, px+tol] × [py−tol, py+tol]` ✓
          （"±噪声容差" = 圆心在这 Npx 内**都可能**是真目标 ✓ ⇒ 这个不确定性方块只要**碰到**
           检出框，就认"目标还在这一格里" ✓）。
        判据 = 轴对齐矩形**相交**（两条轴都要重叠 ✓）：

            px + tol ≥ 框左   且   px − tol ≤ 框右
            py + tol ≥ 框上   且   py − tol ≤ 框下

        ⚠⚠ **与上一版写法逐条等价**（上一版："框四边各外扩 tol ⇒ 圆心点是否落在里面" ✓）：
          `框左 − tol ≤ px` ⇔ `px + tol ≥ 框左` ✓，其余三条同理 ⇒ **行为逐字不变** ✓ ——
          这次只是把口径从"点落在扩过的框里"改写成用户要的"**范围与框相交**" ✓。
          `tol=0` ⇒ 范围退化成点 ⇒ "相交" = "点在框内" ✓ 老行为一字不变 ✓。

        ⚠ 与"包住绿圈"**不是**一回事 ✗✗（用户 2026-10-01 ✓ 明确纠正："『包住』指**整个圆圈完全在
          检出框内部**，而 29 帧按照预测到 30 帧的位置不可能被包住" ✓）：
          · 本函数 = **圆心（±容差）这个范围**与框的关系（关心"目标大概还在不在这一格"✓）；
          · `_circle_inside` = **整圈**在框内（关心"这一格完完整整地套住了目标"✓ 融合规则② ✓）。

        谁用 ✓：
          · 融合**规则①**（`_is_merged_box` ✓ 传「噪声容差」✓ 吸收检出框边缘的亚像素噪声 ✓
            帧 16 圆心只出框 0.7px ✓）；⚠ 容差是**有限**的 ⇒ 帧 70 那一格圆心出框 25.4px、
            容差 25px ⇒ 范围与框**仍差 0.4px** ⇒ 不融合 ✓（想要它融合得调容差 ≥ 25.4 ✓）；
          · `_circle_inside` 半径还没学到的退回档（`tol=0` ✓ 保守放行 ✓）；
          · 分离判据（`tol=0` ✓ **不许跟着松** ✗ —— 分离那把尺必须严格 ✓）。
        """
        if box is None or self.pos is None:
            return False
        _t = max(0.0, float(tol or 0.0))
        _px = float(self.pos[0])
        _py = float(self.pos[1])
        _x0 = float(box[0]) - float(box[2]) / 2.0
        _x1 = float(box[0]) + float(box[2]) / 2.0
        _y0 = float(box[1]) - float(box[3]) / 2.0
        _y1 = float(box[1]) + float(box[3]) / 2.0
        return bool(_px + _t >= _x0 and _px - _t <= _x1
                    and _py + _t >= _y0 and _py - _t <= _y1)

    def _pos_gap_to_box(self, box, tol=0.0):
        """**「圆心 ± 噪声容差」范围离检出框还有多远**（px ✓ 0 = 已经相交 ✓）—— 纯诊断
        （只进 `_merge_why` ✓ 不改任何判据 ✗）：让"这一格为什么不算融合"一眼能看到"只差 0.4px"
        这类量 ✓（用户 2026-10-02 ✓ 帧 70 正是靠它定位的 ✓）。

        逐轴取"范围到框"的间隙（轴对齐 ✓ 与 `_pos_range_hits` 同一把尺 ✓），返回**两轴的最大值**
        （切比雪夫口径 ⇒ 它 `== 0` 与 `_pos_range_hits` 为真**等价** ✓）。`box`/`pos` 缺失 ⇒ None ✓。
        """
        if box is None or self.pos is None:
            return None
        _t = max(0.0, float(tol or 0.0))
        _px = float(self.pos[0])
        _py = float(self.pos[1])
        _x0 = float(box[0]) - float(box[2]) / 2.0
        _x1 = float(box[0]) + float(box[2]) / 2.0
        _y0 = float(box[1]) - float(box[3]) / 2.0
        _y1 = float(box[1]) + float(box[3]) / 2.0
        _gx = max(_x0 - (_px + _t), (_px - _t) - _x1, 0.0)
        _gy = max(_y0 - (_py + _t), (_py - _t) - _y1, 0.0)
        return round(max(_gx, _gy), 1)

    def _circle_inside(self, box):
        """**★ 整个圆圈是否完全在检出框内部**（用户 2026-10-01 ✓ 口径原文："『包住』指**整个圆圈
        完全在检出框内部**" ✓）—— 融合规则② 的判据就是这个 ✓。

        判据（两个维度都要满足 ✓）：`框尺寸 ≥ 2×半径` **且** 圆心落在"四边各让开一个半径"的区间里 ✓
        ⇒ 圈**整圈**在框里 ✓（缺一不可 ✗：某一维比直径还窄 ⇒ 那一维**永远**装不下 ✗ 直接 False ✓）。
        · 半径 = **演示窗画的那个绿圈的半径**（`_rad` ✓ 白块学到的"目标实际半径" ✓ `out["rad"]` ✓）——
          ⚠⚠ **不能用 `_tbox_rad`（红框内切半径）** ✗✗（用户 2026-10-02 ✓ 帧 24 点名 ✓）：那把尺
          是"红框的内切圆"✗ **滞后且可巨大**（实测帧 20 起冻在 **78.7** ✗ 而画的绿圈半径只有 18 ✗）
          ⇒ 规则② 的"整圈装不装得下"被放大 4 倍的尺测 ⇒ **几乎永远判 False** ✗✗ = 用户看到的
          "整圈都包住了却不标融合" ✓）。"包住绿圈"包的就是**画面上那个绿圈** ✓ 同一把尺 ✓。
        · 与 `_tbox_inner` 的**区别**（⚠ 关键 ✗）：`_tbox_inner` 在"框比直径窄"时**退回原边**
          （宁可让圈探出也不让位置抽风 ✓）；本函数在那种情形**直接判 False** ✓（圈就是装不进去 ✓）。
        **实测**（`9月30日(1).mp4` ✓ 用户点名）：帧 30 红框 `154×137`、半径 66 ⇒ 圆心必须落在
        离框中心 **±11px（横）±2.5px（纵）** 之内；实际圆心在框中心左边 **21px** ⇒ **装不进去** ✓
        ⇒ 规则② **不成立** ✓（= 用户口径："29 帧按预测到 30 帧的位置不可能被包住" ✓）。
        """
        if box is None or self.pos is None:
            return False
        _w = float(box[2])
        _h = float(box[3])
        _r = float(getattr(self, "_rad", 0.0) or 0.0)
        if _r <= 0.0:
            return self._pos_range_hits(box)          # 半径还没学到 ⇒ 退回"圆心在内"✓（保守放行 ✓）
        if _w < 2.0 * _r - 1e-9 or _h < 2.0 * _r - 1e-9:
            return False                              # 某一维比直径还窄 ⇒ 整圈根本装不下 ✗
        _px = float(self.pos[0])
        _py = float(self.pos[1])
        _x0 = float(box[0]) - _w / 2.0 + _r
        _x1 = float(box[0]) + _w / 2.0 - _r
        _y0 = float(box[1]) - _h / 2.0 + _r
        _y1 = float(box[1]) + _h / 2.0 - _r
        return bool(_x0 <= _px <= _x1 and _y0 <= _py <= _y1)

    def _cover_ratio(self, box, e):
        """**这格框盖住了那块砖多少**（交集 ÷ **砖面积** ✓）—— `_fake_ref` 与 `_covered_ref`
        **共用同一把尺** ✓（原来是 `_fake_ref` 里内联算的 ✓ 抽出来免两处走样 ✗）。
        `box` / `e` 缺失、砖面积 ≤ 0 ⇒ `0.0` ✓。"""
        if box is None or e is None:
            return 0.0
        # ⭐ 算法在 `perception/geom.py`（`cover_ratio` = **单向**：交集 ÷ 砖面积 ✓ —— 框多大
        #   不进分母 ✓ 所以**不能**用 IoU 代替 ✗ 见该模块头 ✓）。
        return geom.cover_ratio(box, (float(e.x), float(e.y), float(e.w), float(e.h)))

    def _covered_ref(self, box):
        """**这格框里最该认的那一块内砖**（用户 2026-10-03 ✓ 原话："我们应该**只允许融合框认一个
        内砖，就是覆盖率最大的那个**" ✓）⇒ `(条目, 覆盖率)`（一块都没包住 ⇒ `(None, 0.0)`）。

        范围 = **被这格框包住**的条目（`_box_covers_entry` ✓ —— **含候选**未上板 ✓ 与边归属 /
        `_brick_owned` 同一把尺 ✓："包住" = 交集 ≥ 0.5×砖面积 **或** 砖心在框内 ✓）；
        从里面**只取一块**：覆盖率（= 交集 ÷ 砖面积 ✓ 见 `_cover_ratio` ✓）**最大**者 ✓。

        ⚠ 与 `_fake_ref` 的分工（两个都在用 ✓ 别混 ✗）：
          · `_fake_ref` = **只认已上板**的砖里覆盖率最大那块 ✓（"**有记录的**假目标" ✓
            融合进门判据 / 参照砖用它 ✓）；
          · `_covered_ref` = **含候选**的砖里覆盖率最大那块 ✓（"框里那块砖**是谁**" ✓
            边归属 `_edge_ownership` 用它 ✓）。
        """
        if box is None:
            return (None, 0.0)
        _best, _bv = None, 0.0
        for e in (getattr(self, "_reg", None).entries
                  if getattr(self, "_reg", None) else []):
            if not self._box_covers_entry(box, e):
                continue
            _cov = self._cover_ratio(box, e)
            if _best is None or _cov > _bv:
                _best, _bv = e, _cov
        return (_best, _bv)

    def _same_inner_brick(self, box):
        """**保持期内**：这格框认的**内砖**（覆盖率最大的那块 ✓ 见 `_covered_ref` ✓）是不是**就是**
        这次融合会话那块参照砖（`_merge_hold_bid` ✓）？

        用户 2026-10-03 ✓ 原话："**分离前（包括分离当拍）不允许将内砖不同的检出框当做融合框**" ✓
        —— 即**一次融合会话只认同一块砖** ✓（"换对象"= 把这格框标成**别的砖**的并集 ✗）。

        · **不在保持期**（还没进门 / 已经分离 ✓）⇒ `True`（放行 ✓ 新会话本来就该自由挑 ✓）；
        · 保持期却没参照砖（表里找不到 / 没记 ✓）⇒ `True`（判不出 ⇒ 不猜 ✗ 与其它判据同一取舍 ✓）；
        · 框里**一块被包住的砖都没有** ⇒ `False`（它不可能是"这块砖的并集" ✗）；
        · 内砖 `bid` ≠ 参照砖 `bid` ⇒ `False` ✓。
        """
        if not getattr(self, "_merge_hold", False):
            return True
        _bid = getattr(self, "_merge_hold_bid", None)
        if _bid is None:
            return True
        _e, _ = self._covered_ref(box)
        if _e is None:
            return False
        return tuple(_e.bid) == tuple(_bid)

    def _fake_ref(self, box):
        """**这格框最贴合的那块"已上板"假目标** ⇒ `(条目, 覆盖率)`（一块都没贴上 ⇒ `(None, 0.0)`）。

        覆盖率 = 交集 / 假框面积 ✓（= "这格检出框盖住了那块砖多少" ✓ 与 `_box_identity` 同一把尺 ✓）。
        只认 `self._reg.confirmed_boxes()`（**已上板** ✓ 用户 2026-10-01 口径："已上板的假目标
        记录的面积" ✓）—— 候选（没上板）不算"有记录" ✗ 它连尺寸都还在矫正中 ✓。
        ⚠ 返回**条目对象**（不是框元组 ✓ 2026-10-02 ✓）：`_brick_owned` 要看它的
        `_shape_pending`（形状待定中 ⇒ 登记尺寸不可信 ✓ 帧 23 ✓）。
        """
        if box is None:
            return (None, 0.0)
        _best, _bv = None, 0.0
        for _b in getattr(self._reg, "entries", None) or []:
            if not getattr(_b, "confirmed", False):
                continue                      # 只认"已做实"的条目（= 原 confirmed_boxes ✓）
            _cov = self._cover_ratio(box, _b)  # ⚠ 同一把尺（交集 ÷ 砖面积 ✓）见 `_cover_ratio` ✓
            if _cov > _bv:
                _best, _bv = _b, _cov
        return (_best, _bv)

    def _brick_owned(self, box):
        """**这格检出框是不是"某块砖自己那一格"**（用户 2026-10-01 ✓ 最新定稿 ✓ 原话："该检出框
        是否判定为**属于砖条目**的？如果是就**不应该标**，而是应该遵循上一帧的预测" ✓）。

        判据（与 `_box_identity` 的 `"fake"` 同一把尺 ✓，但**两处关键不同** ✓）：
        · 参照 = 登记表里**全部条目**（已上板 + **候选** ✓ —— 候选也是"正在跟踪的砖" ✓）；
        · **不做"白块免判"** ✗（`_observed_in` ✗）：目标踩上砖的那几拍，白块**必然**在框里 ✓，
          拿白块免判会把"属于砖"这个事实丢掉 ⇒ 框被误当目标 ⇒ 误标红 ✗✗（实测帧 12：框与
          登记条目完全重合 d=0、尺寸相同，就因白块免判判成 `""` ⇒ 标红 ✗✗ = 用户点名 ✓）。
        · 几何（两条同时 ✓）：
          覆盖率 ≥ `_BRICK_OWN_COV`（0.65 ✓ 比身份判定的 0.75 略松 ✓ —— "框把砖盖住六成半以上"
          基本就是砖自己/目标深踩在砖上 ✓；实测帧 66：砖滑出画面右缘的**残框** 97×166，覆盖率
          0.754 卡线 ✗ 决策时差一点没过门 ⇒ 误标红 ✗ 用 0.65 兜住 ✓）；
          **且** 面积倍率 **< 配置的融合阈值**（`self.merge_ratio` ✓ 不另设常数 ✓）。
        · ⚠⚠ **上界为什么是阈值本身** ✗（两个方向都实测踩过 ✓）：
          用身份判定的 1.7 ⇒ 帧 17 的真并集（208.7×165.9 完全包住砖 160.6×134.4，面积比 **1.60**、
          框比砖多出 ~48px）被误判"属于砖" ⇒ **真并集不标红** ✗✗（用户点名 ✓）；
          用 1.10 又会把 1.10~阈值 之间的框漏出去 ⇒ 被"相交"误标红 ✗。
          ⇒ 分界线就是用户自己配的阈值：帧 12（1.007）不红 ✓、帧 17（1.60）红 ✓、
          帧 31/42（<阈值）不红 ✓ —— 三条口径一次对齐 ✓。
        ⇒ **属于砖 ⇒ 永远不给红框** ✗（红框只属于"真并集"和"目标自己那格" ✓）。
        """
        if box is None:
            return False
        # ⚠ 2026-10-03：判据已换成 IoU ⇒ **不再需要框面积** ✗（`_a` 已删 ✓ 免 pyflakes 报未用 ✓）
        _bx0 = float(box[0]) - float(box[2]) / 2.0
        _by0 = float(box[1]) - float(box[3]) / 2.0
        _bx1 = float(box[0]) + float(box[2]) / 2.0
        _by1 = float(box[1]) + float(box[3]) / 2.0
        for _e in getattr(self._reg, "entries", None) or []:
            _ew, _eh = float(_e.w), float(_e.h)
            _fa = _ew * _eh
            if _fa <= 0.0:
                continue
            _ix = max(0.0, min(_bx1, float(_e.x) + _ew / 2) - max(_bx0, float(_e.x) - _ew / 2))
            _iy = max(0.0, min(_by1, float(_e.y) + _eh / 2) - max(_by0, float(_e.y) - _eh / 2))
            if _ix * _iy / _fa < _BRICK_OWN_COV:
                continue
            # ⭐⭐⭐ **判据换成 IoU**（用户 2026-10-03 ✓ 与融合门**同一把尺、方向相反** ✓ 对称 ✓）：
            #   `IoU(检出框, 这条目的框) < 配置值` ⇒ 两者**不是同一格** ⇒ **不算"属于砖"** ✗
            #   （那正是"真并集"⇒ 交给规则① 判融合 ✓）；`IoU ≥ 配置值` ⇒ 基本同一格 ⇒
            #   **属于砖**（不标红 ✓）。⚠ 原来那条"面积比 > 阈值"**已撤** ✗（同一句口径 ✓）。
            if geom.iou(box, (float(_e.x), float(_e.y), float(_ew), float(_eh))) < float(self.merge_iou):
                # ⭐⭐⭐ **例外（用户 2026-10-02 ✓ 帧 23）**：那条目此刻**"形状待定"**
                #   （登记表 `_shape_pending` ✓ = 它正与绿圈外接矩形相交 ✗ 登记尺寸**不可信** ✓ ——
                #   实测帧 23：条目 145.9×**109.5**（高度是残的 ✗）与检出框 158.4×148.7 重合，
                #   面积比 1.47 ≥ 1.2 ⇒ 被误判"真并集"标红 ✗✗ = 用户点名 ✓）。
                #   条目尺寸不可信 ⇒ **面积比根本证明不了"并集"** ✗ ⇒ 大半盖住它（cov ✓）就算
                #   "**属于登记砖**"（不红 ✓ 预测态 ✓）。
                #   ⚠ **不再加中心重合门** ✗（实测踩过 ✓）：判定发生在 `_reg.step` **之前**，条目
                #     还停在**上一拍**坐标（未做本拍群体平移 ✓）⇒ 中心天然差一个 T（帧 23 实测
                #     23.5px ✗）⇒ 任何中心门都会漏 ✗。而"待定中"本身就是充分理由 ✓。
                #   ⚠ 帧 17 不受影响 ✓：那格条目**不在待定中**（并集框中心偏出紧门 ⇒ 没配上 ✗
                #     `_shape_pending=False` ✓）⇒ 真并集照常红 ✓。
                #   ⚠⚠ 覆盖两种"尺寸不可信"状态（用户 2026-10-02 ✓）：**形状待定**（初次登记
                #     被绿圈压着 ✓）与**锁尺寸**（钉死的砖被绿圈压着 ✓）✓。
                if not (getattr(_e, "_shape_pending", False)
                        or getattr(_e, "_size_locked", False)):
                    continue
            return True
        return False

    def _box_identity(self, box):
        """**这格检出框是谁**（用户 2026-10-01 ✓ 原话："每个检出框我们都需要它是谁" ✓）。

        参照 = **上板登记的假目标**（`self._reg.confirmed_boxes()` ✓ 就是用户说的"上板登记" ✓）。
        先算**覆盖率**（= 交集 / 假框面积 ✓）取最贴合的那一块：
        · 覆盖率 < `_FAKE_COV_MIN` ⇒ `("", 那块)`（说不清 ⇒ 照老行为 ✓）；
        · 覆盖率过线后看**面积倍率**（框面积 / 假框面积 ✓）：
            - 倍率 **> `_FAKE_SIZE_MAX`** ⇒ `("merged", 那块)` = **② 大检出框直接包住了假目标** ✓
              ⇒ 融合信号（用户原话 ✓）；
            - 倍率 **≤ `_FAKE_SIZE_MAX`** 且中心也贴合（≤ `_BOX_SELF_GATE` ✓ = "**高度重合**" ✓）
              ⇒ `("fake", 那块)` = **① 检出框又检出了假目标** ⇒ **不能锁红** ✗（用户原话 ✓）；
            - 倍率够小但中心不贴（差半格）⇒ 那是**另一块**砖 ✓ ⇒ `("", 那块)` 不判 ✓。

        回值 `(role, entry)`：`role` ∈ `"fake"`（假目标）/ `"merged"`（融合信号）/ `""`（说不清）。
        """
        if box is None:
            return ("", None)
        if self._observed_in(box):
            return ("", None)                     # ⚠ 有目标的直接观测 ⇒ 免判（见 `_observed_in` ✓）
        _a = float(box[2]) * float(box[3])
        _best, _bv = self._fake_ref(box)          # ⭐ 参照假框 + 覆盖率（与 `_is_merged_box` 共用 ✓）
        if _best is None or _bv < _FAKE_COV_MIN:
            return ("", _best)
        if _a > _FAKE_SIZE_MAX * (float(_best.w) * float(_best.h)):
            return ("merged", _best)
        if math.hypot(float(box[0]) - float(_best.x),
                      float(box[1]) - float(_best.y)) <= _BOX_SELF_GATE:
            return ("fake", _best)
        return ("", _best)

    def _merge_edge_own(self, box, at=None):
        """⭐⭐⭐ **融合态圆落位 =「边归属」**（用户 2026-10-02 ✓ 定稿 ✓ 五档 a~e ✓）。

        · **边归属**（`_edge_ownership` ✓）：融合框的某边 与 **任意已登记砖**的某边 距离
          ≤「噪声容差」⇒ 这条边"归属于假目标"（= 框的这条边是砖**提供**的 ✓ 不是目标 ✓）；
        · 五档落位（`n` = 归属假目标的边数 ✓ —— ⚠ 已按「**砖最多拥有融合框边数量**」
          （`edge_max` ✓ 用户 2026-10-02 ✓）截断：只数**距离最近的前 `edge_max` 条** ✓
          见 `_edge_ownership` ✓）：
          a. `n=0` ⇒ 圆 = **框中心** ✓（框全是目标自己的 ✓）；
          b. `n=1` ⇒ 圆贴这条边**对面**的框边（**只改一个坐标** ✓ 另一轴照旧预测 ✓）；
          c. `n=2` ⇒ 另两条边归属真目标 ⇒ 圆 = 这两条真边的**对角内接**（两坐标都定 ✓）；
          d. `n=3` ⇒ 圆贴"中间那条边"（= 它的对面边**不是**假边的那条 ✓ 三假边里唯一 ✓）
             对面的框边（**只改一个坐标** ✓）；
          e. `n=4` ⇒ 圆 = **框中心** ✓。
        · ⚠ **c 的退化情形**：两条假边**对面**（L+R 或 T+B，= 框左右/上下都是砖 ✗）⇒
          "真边对角"不存在 ⇒ **`None`**（不落位、按预测 ✓）。
        · ⭐⭐ **2026-10-02 修订**（用户："预测优先，只有边归属明确时才落位；出现『分离』信号
          （框缩小后判定 4 条边都归砖）也按预测" ✓）：原来 `n=0`/`n=4` 一律返回**框中心** ✗
          ⇒ 现在是 **`None`**（"中心"不带信息、还会把圆从角上一跳 48px 钉到中间 ✗）。
          生成那一拍另有"就近内接"分支（`_merge_first` ✓ 见上）✓ —— 顺序上它**先**判 ✓。
        · ⚠ **取代旧两段式**（「就近相接」仅第一拍 + 「顶边贴边」基线推距 ✓）—— 新机制
          **每拍独立成立** ✓ 不需要基线、不需要第一拍特判 ✓（用户本条即最新裁决 ✓）。
        · ⭐⭐⭐ **甲方案（用户 2026-10-02 ✓ 最新裁决 ✓）**：落位点 ⇒ **内部状态一起认** ✗✓
          （`process()` 出口调 `_adopt_merge_fix` ✓ 见它 ✓）—— 这是对原纪律「落位**只**改
          报告位置、内部信念不动」的**受控修订** ✓，用户原话："**我期望绿圆就是我们认为的真
          目标所处的位置**" ✓（分叉的代价：实测显示帧 43 绿圆与内部差 **53.1px** ⇒ 下一拍从
          "心里那个未修正的点"起滑 ⇒ 圆**回跳** ✗✗）。
        · 非并集 / 没框 ⇒ `None` ⇒ 照旧"按预测滑行 + 内接夹取" ✓。
        """
        if box is None or not (self._is_merged_box(box) or self._hold_active(box)):
            return None                              # 非并集且不在融合保持 ⇒ 不修正 ✓
        own = self._edge_ownership(box)              # (L, R, T, B) 归属假目标? ✓
        _cx, _cy = float(box[0]), float(box[1])      # 框中心（处理域 ✓）
        # ⭐⭐⭐ **融合框「生成」那一拍 ⇒ 「就近内接」**（用户 2026-10-02 ✓ 原话一字不改：
        #   "**融合框生成时→就近内接**；融合框生成后的拍直到分离前→按轨迹预测、或按边归属内接" ✓）：
        #   · 参考点 = **融合前那一刻的圆心**（`_pos_prev` ✓ —— `process()` 每拍把它更新成"本拍
        #     未修正的位置" ✓ ⇒ 生成这一拍它正是**上一拍**的位置 ✓）；
        #   · 看它在**框中心的哪个象限** ⇒ 取**那个角**的内接点 ✓（安全区角 ✓ 与 `_pos_in_tbox`
        #     同一把尺 ⇒ 整圈恒在框内 ✓、且与"就近"的直觉一致 ✓）；
        #   · `_pos_prev` 拿不到 ⇒ **退回下面的边归属** ✓（不猜 ✗）。
        #   ⚠⚠ **这条修订了 2026-10-02 那句"边归属每拍独立成立、不需要第一拍特判"** ✗ ——
        #     用户当天实测 `9月30日(1).mp4` 第 17 帧（融合第一拍）指出：融合前圆心在框中心的
        #     **右上** ⇒ 期望落 **右上角** ✓；而边归属当时给的是 `L=True,T=True` ⇒ 真边对角 =
        #     **右下角** ✗（实测 (331.0,316.1) vs 期望 (331.0,279.3)，差 **36.8px** ✓）。
        # ⭐⭐⭐ **「就近内接」已屏蔽**（用户 2026-10-03 ✓ 原话："先屏蔽『就近内接』逻辑，**都按边
        #   归属算**" ✓）：`_MERGE_FIRST_NEAREST = False` ⇒ 生成那一拍**不再**按"融合前圆心在
        #   框心的哪个象限"取角 ✗，而是照下面的**边归属五档**走（真边对角 ✓）。要回退把常量设
        #   `True` 即可 ✓（代码原样保留 ✓）。
        if _MERGE_FIRST_NEAREST and getattr(self, "_merge_first", False):
            _pp = getattr(self, "_pos_prev", None)
            if _pp is None:
                _pp = at if at is not None else self.pos
            if _pp is not None:
                _ax0, _ay0, _ax1, _ay1 = self._tbox_inner(box)
                return (_ax1 if float(_pp[0]) > _cx else _ax0,
                        _ay0 if float(_pp[1]) < _cy else _ay1)
        _n = sum(own)
        # ⭐⭐⭐ **只有「边归属明确」时才落位；否则按预测**（用户 2026-10-02 ✓ 原话："**预测优先，
        #   只有边归属明确时才落位**，若出现『分离』信号（融合检出框缩小后，判定 **4 条边都归属
        #   砖**）**也按预测**" ✓）：
        #   · **不明确** ⇒ 一律 `None`（调用方见 `None` ⇒ 圆继续按预测走 ✓ = "预测优先" ✓）：
        #     `n=0`（四条边都不归砖 ⇒ 框全是目标自己的、"框中心"不带任何信息 ✗）、
        #     `n=4`（四条边都归砖 ⇒ **正是用户点名的那个「分离」形态** ⇒ 目标已经走了 ⇒ 按预测 ✓）、
        #     **c 的退化**（两条假边正对面 ⇒ 没有"真边对角"可落 ✓）；
        #   · **明确** ⇒ `n=1/2/3` 且能算出确定的对面边/对角 ⇒ 照旧落位 ✓（见下面 b/c/d ✓）。
        #   ⚠ 这条**修订**了 2026-10-02 早先那句"a/e ⇒ 圆 = 框中心" ✗（"中心"= 把圆钉在并集
        #     中心不动 ⇒ 实测帧 18 从右上角 (331.0,279.3) 一跳 48px 到中心 ✗✗）。
        if _n in (0, 4):
            return None
        if _n == 2 and own[0] == own[1]:
            return None
        # ⭐⭐⭐ **与「真边」相切**（用户 2026-10-03 ✓ 原话："这种情况的**正确做法是保证归属（真目标）
        #   的边与圆相切**" ✓）：坐标**直接从「框边 ± 半径」算** ✓ —— **不再用 `_tbox_inner` 的边界** ✗。
        #   病根（实测 `10月2日.mp4` 帧 18）：框 266×**132**、半径 75.7 ⇒ **框高装不下直径** ⇒
        #   `_tbox_inner` 在那一维**整维不缩**（退回框的原边界 ✗）⇒ 圆心被放到**框的上边**
        #   （y = 195.6 ✗）⇒ 圆从上方**探出 75.7px**、上边**并没有与圆相切** ✗✗（正是用户点出的）。
        #   ⇒ 现在：**哪条边归真目标 ⇒ 圆心离它正好一个半径** ✓（= 相切 ✓），**与"装不装得下"无关** ✓；
        #     归**砖**的边**不设限** ✓（圆该探出就探出 ✓ —— 那条边是砖提供的、目标可以被它裁 ✓）。
        _rad = (float(getattr(self, "_tbox_rad", 0.0) or 0.0)
                or float(getattr(self, "_rad", 0.0) or 0.0))
        _bl = float(box[0]) - float(box[2]) / 2.0    # 框左
        _br = float(box[0]) + float(box[2]) / 2.0    # 框右
        _bt = float(box[1]) - float(box[3]) / 2.0    # 框上
        _bb = float(box[1]) + float(box[3]) / 2.0    # 框下
        x0, y0, x1, y1 = self._tbox_inner(box)       # ⚠ 只留给"**另一轴**"夹取用（见下 ✓）
        _px, _py = None, None
        if own[0] != own[1]:                         # x 轴恰一条假边 ✓（b 的那条 / d 的"中间" ✓）
            _px = (_br - _rad) if own[0] else (_bl + _rad)   # 与**真边**（对面那条）**相切** ✓
        if own[2] != own[3]:                         # y 轴恰一条假边 ✓（c 时两轴同时命中 = 对角 ✓）
            _py = (_bb - _rad) if own[2] else (_bt + _rad)
        # 另一轴照旧预测（用户："仅修改 x、y 坐标中的一个" ✓），夹进内接安全区 ✓
        _p = at if at is not None else self.pos
        _bx = float(_p[0]) if _p is not None else _cx
        _by = float(_p[1]) if _p is not None else _cy
        if _px is None:
            _px = min(max(_bx, x0), x1)
        if _py is None:
            _py = min(max(_by, y0), y1)
        return (_px, _py)

    def _adopt_merge_fix(self, out):
        """⭐⭐⭐ **「落位点 = 我们认定的真目标位置」⇒ 内部状态一起认**（用户 2026-10-02 ✓
        原话："**我期望绿圆就是我们认为的真目标所处的位置**" + "**改成甲试试 ——『落位点就是
        我们认定的真目标位置』⇒ 内部也该认它**" ✓）。

        ⚠ 这是对既有纪律「落位**只**改报告位置、内部信念不动」的**受控修订** ✗✓ —— 那条纪律
          的原委见 `process()` 出口那段长注释（当年是为了"别让修正经选框反过来改红框" ✓
          代价 = **绿圆与内部位置分叉**：实测显示帧 43 差 **53.1px** ⇒ 下一拍从"心里那个未修正
          的点"起滑 ⇒ 圆**回跳** ✗✗）。用户现在明确：落位点**就是**"我们认为真目标在的地方"
          ⇒ 内部没理由不认它 ✓（轨迹因此可能与旧版分岔 —— 这是用户明确要试的 ✓）。

        一把尺写三处（同一拍同一帧 ✓）：
          · `self.pos` = 落位点 ✓ —— 下一拍的**预测起点**、**选框**参考（`_target_box_state`
            的"目标踩着的那格框" ✓）、速度推算全从这儿走 ⇒ **绿圆 ≡ 内部信念** ✓；
          · `self._raw` = 落位点（半域 ✓）+ 同步刷 `out["raw_pos"]` ✓（演示窗那颗**绿点**
            = 内部真实位置 ⇒ 这一拍它与绿圆圆心**重合**、小红点不再出现 ✓）；
          · `self._clamped = True` ✓ —— 这一跳是**信念几何推断**、不是目标自己走的 ✗ ⇒
            轨迹样本照样不许入窗（与统一出口/夹取同一把尺 ✓ 见 `_CLAMP_SKIP_MIN` ✓）。

        ⚠ `_pos_prev` **不在**这里写 ✗：它由调用处按"有没有真落位"决定 ✓（见 `process()` ✓）。
        返回落位点（`out["pos"]` 抓不到 ⇒ `None` ⇒ 调用方照旧走老路 ✓ 不猜 ✗）。
        """
        _p = out.get("pos")
        if _p is None:
            return None
        _p = (float(_p[0]), float(_p[1]))
        self.pos = _p
        self._raw = (_p[0] * _SCALE, _p[1] * _SCALE)
        if "raw_pos" in out:
            out["raw_pos"] = _p                 # 绿点（内部真实位置）同步 ⇒ 与圆心重合 ✓
        self._clamped = True                    # 这一跳不是"目标自己走的" ⇒ 样本不入窗 ✓
        return _p

    def _edge_ownership(self, box, detail=False):
        """**融合框四边的「边归属」**（用户 2026-10-02 ✓ 原话："每条边都需要能定义『这条边是
        由谁提供的』，当融合框的某边距离**已登记的砖**的某边 ≤『噪声容差(px)』时认为这条边
        『归属于假目标』" ✓）。→ `(L, R, T, B)` bool ✓（`detail=True` ⇒ 再带上四条边各自的
        **最近距离** ✓ 给自检/日志用 ✓）。

        · 距离 = **线段对线段**（垂直间距 ⊕ 段间空隙 的合距 ✓）—— 框边与砖边**错开一段**时
          （远处的砖 ✓）不会被同侧坐标误判 ✓；
        · ⭐⭐ **只对"被这格框包住的砖"判归属**（用户 2026-10-02 ✓ 原话："融合框的归属**只能
          根据其包含的砖**去判，例如**帧 27 只看砖 (144,96)**" ✓）—— "包住"用
          `_box_covers_entry` ✓（交集 ≥ 0.5×砖面积 **或** 砖心在框内 ✓ 与融合保持那条同一把尺 ✓）；
          ⚠ 与本次并集**无关**的砖**不参与** ✓ —— 它的边可能只是从框边"擦过去"（实测帧 27：
          砖 `(349,51)` 的左边距框左边 23.8px ≤ 容差 25 ⇒ 旧口径把它算成"提供左边" ✗✗ 用户点名 ✓）；
        · ⭐⭐⭐ **只认一块内砖 = 覆盖率最大的那块**（用户 2026-10-03 ✓ 原话："我们应该**只允许
          融合框认一个内砖，就是覆盖率最大的那个**" ✓）：范围 = 被包住的那些条目（含**候选** ✓
          与 `_brick_owned` 同一口径 ✓），但**只取一块**（`_covered_ref` ✓ 覆盖率 = 交集 ÷ 砖面积
          ✓）⇒ **四条边全部只看它** ✓（**取代** 2026-10-02 那版"每边各自取最近那块砖的边距" ✗
          —— 那时"一框两块砖"会两块各供各的边 ✗ 实测 `9月30日(1)` 帧 38／46 ✓）；
        · ⭐⭐ **「砖最多拥有融合框边数量」**（用户 2026-10-02 ✓ 新参数 ✓ 1~4 ✓）：归砖的四条边里
          **只留距离最近的 `edge_max` 条** ✓ —— 多出来的（更远的那些）重新算作"真目标提供的
          边" ✓（用户原话："**注意在多条边选取最近的前 x 条**" ✓）。
          默认 **4** = 不截断（老行为一字不变 ✓）；设 1~3 ⇒ "一块砖最多只能占住这么多条边" ✓
          （⇒ `_merge_edge_own` 五档里 `n=4` ⇒ 不落位那一档，只有 `edge_max=4` 时才可能走到 ✓）。
        """
        _bx, _by = float(box[0]), float(box[1])
        _bw, _bh = float(box[2]), float(box[3])
        _bl, _br = _bx - _bw / 2.0, _bx + _bw / 2.0
        _bt, _bb = _by - _bh / 2.0, _by + _bh / 2.0
        _tol = float(getattr(self, "noise_tol", 0.0) or 0.0)
        _d = [None, None, None, None]
        # ⭐⭐⭐ **只认「一块」内砖 = 覆盖率最大的那块**（用户 2026-10-03 ✓ 原话："我们应该**只允许
        #   融合框认一个内砖，就是覆盖率最大的那个**" ✓ 见 `_covered_ref` ✓）：
        #   四条边**全部只看同一块砖** ✓ —— 它取代了 2026-10-02 那版"**每边各自取最近那块砖的
        #   边距**" ✗：那时一个框里躺着两块砖会**两块各供各的边**（实测 `9月30日(1)` 帧 38／46
        #   就是"一框两块砖" ⇒ 左上两条边来自 A、右下两条来自 B ✗✗）⇒ 落位角变成"两块砖拼出来的
        #   角"、与"并集里那块假目标"不是一回事 ✗；现在四边只看"框里那块砖"（覆盖率最大 ✓ 与
        #   参照砖同一把尺 ✓）。
        #   ⚠ 范围照旧 = **被这格框包住**的条目（`_box_covers_entry` ✓ 含候选 ✓；与本次并集无关、
        #     只是从框边擦过去的砖**一律不参与** ✓ 见 `_covered_ref` 与帧 27 实测 ✓）。
        _ref, _ = self._covered_ref((_bx, _by, _bw, _bh))
        if _ref is not None:
            _el = float(_ref.x) - float(_ref.w) / 2.0
            _er = float(_ref.x) + float(_ref.w) / 2.0
            _et = float(_ref.y) - float(_ref.h) / 2.0
            _eb = float(_ref.y) + float(_ref.h) / 2.0
            _d = [_edge_seg_dist(_bl, _bt, _bb, _el, _et, _eb),        # 左 ↔ 砖左
                  _edge_seg_dist(_br, _bt, _bb, _er, _et, _eb),        # 右 ↔ 砖右
                  _edge_seg_dist(_bt, _bl, _br, _et, _el, _er),        # 上 ↔ 砖上
                  _edge_seg_dist(_bb, _bl, _br, _eb, _el, _er)]        # 下 ↔ 砖下
        own = [(_d[_i] is not None and _d[_i] <= _tol) for _i in range(4)]
        # ⭐⭐ **「砖最多拥有融合框边数量」**（用户 2026-10-02 ✓ 原话："注意在多条边选取最近的
        #   前 x 条" ✓）：归砖的边按距离**从小到大**排 ⇒ 只留前 `edge_max` 条 ✓ 其余的改判
        #   "真目标提供的边" ✓（⇔ 把它们的距离当成超出容差 ✓ 语义一致 ✓）。
        _mx = int(getattr(self, "edge_max", _EDGE_MAX) or _EDGE_MAX)
        if _mx < 4:
            _owned = sorted((_i for _i in range(4) if own[_i]), key=lambda _i: _d[_i])
            for _i in _owned[_mx:]:
                own[_i] = False
        return (own, _d) if detail else own

    def _ease_pos(self, cur, want, dt):
        """**拟人平滑**地朝 `want` 挪一步（用户 2026-09-30 口径 ✓ 原话："不要瞬间调整追踪器去
        一帧追到圆圈，做一下拟人的平滑" ✓）。

        · 每拍只走"剩余距离的 `_SMOOTH_K`" ✓（像人拖鼠标那样渐进 ✓）；
        · 并且**不超过这一拍的限速**（`_STEP_SPEED × dt` ✓）⇒ 无论"相切落位"还是"夹进红框"
          都不会瞬移 ✓；
        · 目标就是目标（`want` ✓）：几拍之内自然贴上 ✓，而不是一帧生硬对齐 ✗。
        """
        if cur is None or want is None:
            return want
        step = float(dt) if (dt and 0.0 < float(dt) <= 1.0) else _STEP_DT_DEF
        lim = _STEP_SPEED * step
        dx = (float(want[0]) - float(cur[0])) * _SMOOTH_K
        dy = (float(want[1]) - float(cur[1])) * _SMOOTH_K
        m = (dx * dx + dy * dy) ** 0.5
        if m > lim and m > 1e-9:
            dx, dy = dx * lim / m, dy * lim / m
        return self._clamp_full((float(cur[0]) + dx, float(cur[1]) + dy))

    def _tbox_inner(self, box):
        """红框的**内接安全区**（全分辨率 `(x0, y0, x1, y1)` ✓）—— 圆心夹取的真正边界。

        ⭐⭐⭐ **为什么要留一个半径的余量**（用户 2026-09-30 认知 #1 ✓ 原话："红框代表我们认为
        真目标**被包含在里面**" ✓）：绿圈半径 `rad` = **目标的实际半径**（恒定 ✓ 用户定稿 ✓）
        ⇒ 只夹**圆心**是不够的 ✗：圆心离边不足 `rad` 时**圆圈照样探出框外** ✗✗。
        **实测**（`9月30日(1).mp4` ✓）：第 17 帧圆心到上边只有 **35px < r=56** ⇒ 圈从上面
        探出 **22px** ✗；第 24 帧探出 **29px** ✗；第 4/11/18/25 帧分别 10/3/6/19px ✗
        —— 用户问的"既然都有红框了，为什么绿圈不在红框里"就是它 ✓。
        ⇒ 圆心夹到 `[x0+r, x1-r] × [y0+r, y1-r]` ⇒ **整圈恒在红框内** ✓。
        ⚠ 框比 `2r` 还窄/还矮时（融合块被切窄 ✗ / 半径还没学好 ✓）那一维**退回原边** ✓
          （否则夹出空区间 ⇒ 位置乱跳 ✗）—— 宁可圈探出，也不让位置抽风 ✗。

        ⭐⭐⭐ **两把尺必须同一把（用户 2026-10-01："红框检出 ⇒ 绿圈需要与其内接" ✓）**：
        画圆的半径 = `tbox_rad`（红框内切半径 min(w,h)/2 ✓ 丢框后冻结 ✓ —— 界面上圆
        画多大就是它 ✓），夹取就必须按**同一个数**算安全区 ✗ —— 原来用 `_rad`（学到的
        目标实际半径，更小 ✗）⇒ 按 56 夹、按 82 画 ⇒ 圈恒探出（实测第 17 帧探出上 18px
        ／右 23px ✗✗ —— 用户截图圈出来的就是它 ✓）。
        ⚠⚠ 且 `tbox_rad = min(w,h)/2` ⇒ **min 维上 `2r == 框宽` 恒成立** ⇒ 内缩条件必须
          **含等号**（原来 `> 2r` 严格大于 ⇒ min 维永远走"退回原边"⇒ 永不夹 ⇒ 恒探出 ✗✗
          —— 这正是"原则没贯彻"的机制 ✓）。等号 ⇒ 安全区在该维**退化为中点** ⇒ 圆心被
          夹到框中心 ⇒ 圆与 min 维两条边**相切** = **内接** ✓（用户要的就是这个 ✓）。
        """
        bx, by, bw, bh = (float(box[0]), float(box[1]), float(box[2]), float(box[3]))
        # ⭐ 半径 = **画圆那把尺**：`tbox_rad`（红框内切半径 ✓ 与显示一致 ✓）；
        #   从没见过红框（建档期）⇒ 退回 `_rad` ✓。
        r = float(getattr(self, "_tbox_rad", 0.0) or 0.0) or float(getattr(self, "_rad", 0.0) or 0.0)
        x0, x1 = bx - bw / 2.0, bx + bw / 2.0
        y0, y1 = by - bh / 2.0, by + bh / 2.0
        if r > 0.0:
            # ⚠ **含等号**（见上）：`2r == 维宽` ⇒ 区间退化为中点 = 内切 ✓ 不是空区间 ✓
            if bw >= 2.0 * r - 1e-6:
                x0, x1 = x0 + r, x1 - r
            if bh >= 2.0 * r - 1e-6:
                y0, y1 = y0 + r, y1 - r
        return x0, y0, x1, y1

    def _pos_in_tbox(self, xy, box):
        """把**全分辨率**坐标夹进目标框的**内接安全区**（信念约束 ✓ 与 `_clamp_into_tbox`
        同一套口径 ✓ —— 都走 `_tbox_inner` ✓）。

        ⚠ 为什么连**报告位置**也要夹 ✗：报告位置 = `_raw` + **超前补偿**（最多 2 帧的前馈 ✓）
        ⇒ 只夹 `_raw` 仍会让绿圈**跑到框外**（实测第 19 帧：raw 夹住了、报告位置却出去 12.9px ✗）。
        用户要的是"**绿圈**被红框拉着走" ✓ ⇒ 最终出口也得夹 ✓。
        """
        if box is None or xy is None:
            return xy
        bw, bh = float(box[2]), float(box[3])
        if bw <= 0 or bh <= 0:
            return xy
        x0, y0, x1, y1 = self._tbox_inner(box)
        return (min(max(float(xy[0]), x0), x1), min(max(float(xy[1]), y0), y1))

    def _speed_of_vel(self):
        """当前速度大小（px/s ✓）。"""
        return (self._vel[0] ** 2 + self._vel[1] ** 2) ** 0.5

    def _clamp(self, xy_half):
        """半分辨率坐标**钳回画面**（目标不会出画面 ✓；飞出 = 坏观测 ✗ 实测 00046 ✓）。

        ⭐ **钳制即归零该方向速度**（2026-09-30 闭环实测 ✓）：位置贴在边界、速度还
        指着画面外 ⇒ 目标点（pos + 前馈）落在屏外 ⇒ 光标常驻边界外 **20px** ✗
        —— 一个系统性偏差就吃掉整个 ±10% 判据（实测 ✓）。
        """
        if self._wh is None or xy_half is None:
            return xy_half
        w, h = self._wh[0] * _SCALE - 1.0, self._wh[1] * _SCALE - 1.0
        x = min(max(xy_half[0], 0.0), w)
        y = min(max(xy_half[1], 0.0), h)
        if x != xy_half[0]:
            self._vel = (0.0, self._vel[1])
        if y != xy_half[1]:
            self._vel = (self._vel[0], 0.0)
        return (x, y)

    def _box_self_resid(self, ev, dets, tbox):
        """**"红框那一格"的自身残差** = 该框**相对假目标群体**的位移（px/帧 ✓）——
        用户 2026-10-01 口径的原点 ✓ 原话："**我们对真目标的轨迹预测应该是相对于假目标群的运动**……
        例如第10帧→第11帧**红框相对假目标群向下运动**，那么这个运动在12帧丢失红框后需要延续" ✓。

        来源 = A 层 `GroupMotion` 的**逐框模板匹配** `self_resid` ✓（`matchTemplate` ✓ 比框中心
        差分稳得多 ✗）⇒ 这就是用户要的那个量的**直接测量** ✓，不用任何反推 ✓。
        返回 `(dx, dy)`（px/帧 ✓）或 `None`（没框 / 没配上 / 没有 A 层数据 ✓）。
        """
        if tbox is None or not dets or ev is None:
            return None
        _j, _bd = None, None
        for _i, _b in enumerate(dets):
            _cx = float(_b[1]) if len(_b) > 4 else float(_b[0])
            _cy = float(_b[2]) if len(_b) > 4 else float(_b[1])
            _d = math.hypot(_cx - float(tbox[0]), _cy - float(tbox[1]))
            if _d <= _BOX_SELF_GATE and (_bd is None or _d < _bd):
                _j, _bd = _i, _d
        if _j is None:
            return None
        _sr = (ev.get("self_resid") or {}).get(_j)
        return None if _sr is None else (float(_sr[0]), float(_sr[1]))

    def _group_vel(self, dt):
        """**当拍实测的"群体速度"**（小图域 px/s ✓）—— 用户 2026-10-01 口径 ✓：
        "相对于假目标群体进行预测" ✓。

        优先级：① **登记表里"已上板的假目标"的位移中位** `avg_vel` ✓（最稳 ✓ 用户原话：
        "**实时计算所有登记假目标群的平均速度向量**" ✓，且只在 `avg_vel_n ≥ 3` 时采信 ✗ ——
        一两条算出来的"平均"没意义 ✓）；② 退到 A 层的**群体平移** `T` ✓（也够用 ✓ 只是
        容易被"真目标自己那一格"带偏一点点 ✓）；③ 都没有 ⇒ `None`（没观测就**别猜** ✓）。
        """
        if not dt or dt <= 0.0:
            return None
        _n = int(getattr(self._reg, "avg_vel_n", 0))
        _av = getattr(self._reg, "avg_vel", None)
        if _av is not None and _n >= 3:
            self._gv_now = (float(_av[0]) / float(dt), float(_av[1]) / float(dt))
            return self._gv_now
        if self._t_hist:
            _t = self._t_hist[-1]
            self._gv_now = (float(_t[0]) / float(dt), float(_t[1]) / float(dt))
            return self._gv_now
        return None

    def _box_flags(self, tbox):
        """⇒ `(并集块?, 碎片框?)` —— 「这格框的**框心**能不能当目标运动的测量」的**同一把尺** ✓
        （2026-10-01 合成台 trace 实锤 ✓）：

        · **并集块**（面积 ≥ `_FAKE_SIZE_MAX` × 标准 ✓ ⚠ **2026-10-03 起不用可配阈值** ✗ ——
          用户把那个配置换成 **IoU** 了 ✓ 此处没有"砖框"可算 IoU ⇒ 退回**固定面积倍率** ✓）：
          框心跟着**群体**走
          （两个成员都只随群体平移 ✓）⇒ 单帧差分只会学出 0 ✗；
        · **碎片框**：面积 < 0.82× 标准（= 登记表「完整尺寸」下限 `_SIZE_LO` 同一语义 ✓，
          被屏幕切一半 ✗）**或框贴画面边**（面积法挡不住"还够大但已被切"的框 ✗ trace：
          94×76/102×59/108×44 面积比 1.25/1.06/0.83 全过面积门 ✓ 框心却被边缘偏置拖着走 ✗）
          ⇒ 框心 ≠ 图形中心 ✗。
        """
        typ = float(self._typ_area or 0.0)
        if typ <= 0 or tbox is None:
            return (False, False)                 # 没有标准面积可判 ⇒ 不拦（保守 ✓）
        a = float(tbox[2]) * float(tbox[3])
        # ⚠ 这里**没有"砖框"可算 IoU**（比的是"本拍框面积 vs 典型面积"✓）⇒ 仍用**面积倍率**
        #   常量 `_FAKE_SIZE_MAX`（1.7 ✓ 与"身份判定"同一处 ✓）；⚠ 用户 2026-10-03 已把**可配的
        #   那个阈值**换成 IoU ✓ ⇒ 本处**不再读配置**（免得"0.5 当面积倍率"把一切都判成并集 ✗✗）。
        uni = bool(a >= _FAKE_SIZE_MAX * typ)
        frag = bool(a < 0.82 * typ)
        wh = getattr(self, "_wh", None) or (0, 0)
        if wh[0] > 0 and (float(tbox[0]) - float(tbox[2]) / 2.0 <= 2.0
                          or float(tbox[1]) - float(tbox[3]) / 2.0 <= 2.0
                          or float(tbox[0]) + float(tbox[2]) / 2.0 >= float(wh[0]) - 2.0
                          or float(tbox[1]) + float(tbox[3]) / 2.0 >= float(wh[1]) - 2.0):
            frag = True
        return (uni, frag)

    def _path_pred(self, dt):
        """**轨迹预测（用户 2026-10-01 重定义 + 曲率升级 ✓）**：下一帧位置 =
        `当前位置 + 切向直线步 + 曲率修正` ✓ —— 其中"切向"取自**目标在过去 `self.path_ms`
        毫秒内运动的曲线** ✓（默认 = 模块常量 `_PATH_MS` ✓ 演示窗可配 ✓）。

        用户原话："**下一帧的位置 = 目标在过去 xms 内运动的曲线的切向方向延伸
        <目标在过去 xms 内运动的曲线的切向速度> × 帧时长** 的位置。这个 x 是多少你来定
        一个合适的" ✓。
        用户 2026-10-01 再升级："**我们不能用纯切向来预测轨迹，轨迹实际是有曲率的**" ✓
        ⇒ 二次拟合的**二次项系数 `a` 也要用**（沿曲线外推一小段 = `b·dt + a·dt²` ✓ 不是只走
        切向直线 `b·dt` ✗）。

        · **x = 500ms**（我定的 ✓ 理由）：素材 10fps ⇒ 正好 **5 个采样** ✓ —— 少于 3 个点
          拟合不出曲率 ✗、多于 ~7 个点会把"转弯前的旧方向"也带进来 ✗（目标相对群体每帧
          走 ~10px ✓、500ms 内约 50px ✓ 恰好是一个可辨的弧段 ✓）；
        · **拟合在群体坐标系**（2026-10-01 ✓ 见 `_path` 样本说明）：每个样本扣掉它自己的
          **累计群体平移** ⇒ 曲线里只剩**目标自己的运动** ✓ —— 原来在屏幕系拟合 ✗：
          **背景一变速，二次拟合就被群体运动拖着走** ✗✗（合成台 p90 70.8 → 190.3 的主因 ✓）；
        · **切向方向** = 对窗口内的相对 `x(t)/y(t)` 各做**二次拟合**、取**末端导数** `b` ✓（有
          曲率时它自动偏向"正在转过去"的方向 ✓）；
        · **曲率修正** = 同一个二次拟合的**二次系数 `a`** ✓ ⇒ `a·dt²` 是沿弧走一小段的"弯" ✓
          （`x(t)=a·t²+b·t+c` ⇒ `x(dt)−x(0)=a·dt²+b·dt` ✓）—— ⚠ 加噪声防护：`a·dt²` 的模
          不许超过切向步长 `sp·dt`（5 点拟合的 `a` 会被单帧抖动放大 ✗ 超过 = 拟合噪声 ✗）；
        · **切向速度** = 窗口内**逐段相对速度的中位** ✓（与拟合同坐标系 ✓；屏幕系逐段速度
          会被 ~12px/帧 的群体运动淹没 ✗）；
        · 返回**半域**预测点 ✓（与 `fx/fy`、`_raw` 同域 ⇒ **域统一 ✓**：全文件换算只发生在
          最后加回群体位移的那一处 `_SCALE` ✓）。

        ⚠ 与老做法的区别（用户要改的就是它 ✓）：老是 `位置 + 速度向量×dt` ✗ —— 目标在
        **转弯**时，速度向量外推会**沿旧方向冲出去** ✗；切向+曲率法只走"弧上的下一小段" ✓。
        """
        _hist = list(getattr(self, "_path", None) or [])   # 惰性初始化 ✓（首拍还没有样本 ✓）
        if not dt or float(dt) <= 0.0 or len(_hist) < 3:
            return None
        _t1 = _hist[-1][0]
        # ⚠ 读**实例**的观察窗（`self.path_ms` ✓ 演示窗那一行配的就是它 ✓），不是模块常量 ✗
        #   （用常量 ⇒ 界面上的「应用」永远不生效 ✗）。
        _w = [p for p in _hist if _t1 - p[0] <= float(self.path_ms) / 1000.0]
        if len(_w) < 3 or self._raw is None:
            return None
        try:
            import warnings as _warnings
            import numpy as _np
            _ts = _np.array([p[0] - _t1 for p in _w], dtype=float)   # 末端为 0 ✓
            # ⭐⭐ **群体坐标系**：样本元组 = `(ts, x, y, cumTx, cumTy)`（后两项 = 该样本
            #   时刻的**累计群体平移**（半域 ✓ 见入样处 ✓）⇒ 扣掉它，拟合的只剩目标自己 ✓。
            _xs = _np.array([p[1] - p[3] for p in _w], dtype=float)
            _ys = _np.array([p[2] - p[4] for p in _w], dtype=float)
            # ⭐ 退化窗（样本全等/时间重合 ⇒ 秩亏 ✗）**按拟合失败处理** ✓：把 RankWarning
            #   升级成异常 ⇒ 走统一的 `except` ⇒ 退回"速度×dt"外推 ✓（不刷屏 ✗）。
            with _warnings.catch_warnings():
                _warnings.simplefilter("error")
                _ax, _bx, _ = _np.polyfit(_ts, _xs, 2)
                _ay, _by, _ = _np.polyfit(_ts, _ys, 2)
            # 末端导数（t=0）：x' = bx ✓、y' = by ✓
            _tx, _ty = float(_bx), float(_by)
            # ⭐⭐ **曲率项（二次系数 a ✓）**（用户 2026-10-01 ✓ 原话："我们不能用纯切向来预测
            #   轨迹，轨迹实际是有曲率的" ✓）：`x(t) = a·t² + b·t + c` ⇒ 沿曲线外推一小段，位移
            #   = `b·dt + a·dt²` ✓ —— 老实现只取 `b·dt`（切向直线 ✗），把 `a·dt²`（弯 ✗）丢了 ✓。
            _cx, _cy = float(_ax), float(_ay)
        except Exception:
            return None
        _m = (_tx * _tx + _ty * _ty) ** 0.5
        if _m < 1e-6:
            return None
        # 切向速度 = 逐段**相对群体**速度中位 ✓（稳 ✓ 且不被背景滚动淹没 ✓）
        _segs = []
        for _a2, _b2 in zip(_w, _w[1:]):
            _d2 = float(_b2[0] - _a2[0])
            if _d2 > 1e-6:
                _rx = (_b2[1] - _b2[3]) - (_a2[1] - _a2[3])
                _ry = (_b2[2] - _b2[4]) - (_a2[2] - _a2[4])
                _segs.append(((_rx * _rx + _ry * _ry) ** 0.5) / _d2)
        if not _segs:
            return None
        _segs.sort()
        _sp = _segs[len(_segs) // 2]
        # 起点 = 当前内部位置（半域 ✓ —— 比最后一个样本新：上一拍样本可能被突变过滤跳掉 ✓）
        _px, _py = float(self._raw[0]), float(self._raw[1])
        # 相对步长 = **切向直线**（`(_tx,_ty)/m × sp × dt` ✓）+ **曲率修正**（`(_cx,_cy) × dt²` ✓）
        #   —— 目标在转弯时，直线切向会沿旧方向冲出去 ✗；曲率项把它"掰回弧上" ✓（用户 2026-10-01 ✓）。
        #   ⚠ 曲率项加一个**噪声防护**：5 点二次拟合的 `a` 会被单帧抖动放大 ✗ ⇒ 曲率修正的模
        #   不许超过切向步长（= 一帧内方向最多掰 ~90° ✓ 再大就是拟合噪声 ✗）。
        # 当拍群体位移（半域 ✓ —— **全文件唯一一处** `_SCALE` 换算 ✓ 域统一 ✓）。
        _gv1 = self._group_vel(float(dt)) or (0.0, 0.0)
        _dt2 = float(dt) * float(dt)
        _step = _sp * float(dt)                       # 切向步长（直线 ✓ 半域 px）
        _cx0, _cy0 = _cx * _dt2, _cy * _dt2           # 曲率修正（半域 px ✓）
        _cm = (_cx0 * _cx0 + _cy0 * _cy0) ** 0.5
        if _cm > _step and _step > 1e-6:
            _k = _step / _cm                          # ⭐ 曲率修正 ≤ 切向步长（防噪声 ✗）
            _cx0, _cy0 = _cx0 * _k, _cy0 * _k
        return (_px + (_tx / _m) * _step + _cx0 + float(_gv1[0]) * float(dt) * _SCALE,
                _py + (_ty / _m) * _step + _cy0 + float(_gv1[1]) * float(dt) * _SCALE)

    def _path_vel(self, dt):
        """**白箭头（= 圆心自己的曲线预测速度，相对假目标群 ✓）**（用户 2026-10-01 定稿 ✓ 原话：
        "**箭头不能来自框，它来自圆心的曲线预测**" ✓）。

        做法：拿 `_path_pred(dt)`（切向 + 曲率那一小步 ✓ 见它的长注释）**减去当前位置与当拍
        群体位移** ⇒ 就是"这一拍**相对假目标群**该走的那一小步" ✓ ⇒ ÷dt、`÷_SCALE` 换算到
        **加工域 px/s** ✓（`_path_pred` 回的是半域屏幕点 ✓，两者同源 ⇒ 域自洽 ✓）。

        ⚠ 返回 `None` = 样本不够 / 拟合失败 / 没有 `_raw` ⇒ **调用方保持原值**（不猜 ✗）。
        ⚠ 反向旋转（`_anti_group_vel` ✓ 用户 2026-10-01 设计要求）**不在这里**做 ✗ ——
          它作用在"本拍最终生效值"上（放在调用点之后 ✓）。
        """
        if not dt or float(dt) <= 0.0 or self._raw is None:
            return None
        _pred = self._path_pred(dt)
        if _pred is None:
            return None
        _dt = float(dt)
        _gv = self._group_vel(_dt) or (0.0, 0.0)
        _sx = _pred[0] - float(self._raw[0]) - float(_gv[0]) * _dt * _SCALE
        _sy = _pred[1] - float(self._raw[1]) - float(_gv[1]) * _dt * _SCALE
        return (_sx / _SCALE / _dt, _sy / _SCALE / _dt)

    def _path_viz(self):
        """**白线 = 刻在背景板上的轨迹**（用户 2026-10-01 ✓ **最新定稿** 原话："白色轨迹线应该是
        需要是**刻在背景板上**的线，也就是说是会**跟假目标群相对静止、随着他们移动**的" ✓ ——
        **推翻**同日早先"每拍圆心连起来、没有任何其他逻辑"的口径 ✓）。

        做法：每拍存**群体系**坐标（报告位置 − 该拍累计群体平移 ✓ 见 `_hist_grp` ✓），
        画线时统一加回**当前**累计群体平移 ⇒ 整条线**骑在背景板上**：砖群往左滚，线也整体往左
        平移 ✓ —— 线上每个点相对砖是**钉死**的 ✓（"刻在板上" ✓）。演示窗读的就是它 ✓。

        ⚠ 预测（白箭头）用的样本是另一份（`self._path` ✓ 群体系 + 过滤 ✓）—— 两者互不影响 ✓。
        ⚠ 跳帧/拖动后不清空 ✓（用户 Q9 ✓ 白线会跨过那一段 ✓）。
        """
        _pcum = getattr(self, "_path_cumT", None) or (0.0, 0.0)
        _tx, _ty = 2.0 * float(_pcum[0]), 2.0 * float(_pcum[1])
        return [(float(g[0]) + _tx, float(g[1]) + _ty)
                for g in (getattr(self, "_hist_grp", None) or [])]

    def _rel_cap(self, v):
        """**白箭头（自身速度 `_vel_rel`）限幅**（用户 2026-10-03 ✓ 原话："**a. 给白箭头加限幅
        （治本）**" ✓）。

        上限 = **`_REL_V_MAX` = 400 px/s**（项目**既有**的尺 ✓ 原话口径："自身分量只该是目标相对
        群体的运动（**小量**）" ✓ 超过它只可能是"这一拍没拆干净" ✗）。

        ⚠ **为什么必须治本**（实测 `10月2日.mp4` 帧 37）：白箭头爆到 **(1037,−204) ≈ 1057 px/s** ✗
        ⇒ 两重恶果：① 融合落位**顺着这个假方向** ⇒ 圆心**一拍走 140.9px** ✗（用户："看起来是
        **后退太多了**" ✓）；② **B 型闸的尺子被污染** ✗ —— 允许量 = 比值 × **步长**（= |白箭头|×dt）
        ⇒ 步长被放大到 141px ⇒ 允许量 42px ⇒ 56px 的落位位移被判成"**顺向未超限**" ⇒ 放行 ✗✗。
        ⇒ 限幅后这条链从**源头**掐断 ✓。

        ⚠ **只压模长、不改方向** ✓（与 `_sep_vel_cap` 同一手法 ✓）；⚠ 纯函数（**只返回值、不赋值** ✓）
        —— 调用处照旧自己写 `self._vel_rel` 与 `_set_vel`（保住"绝对 = 自身 + 群体" ✓ 行为最小改动 ✓）。
        """
        _m = math.hypot(float(v[0]), float(v[1]))
        if _m <= float(_REL_V_MAX) or _m <= 1e-9:
            return (float(v[0]), float(v[1]))
        _k = float(_REL_V_MAX) / _m
        return (float(v[0]) * _k, float(v[1]) * _k)

    def _set_vel(self, vx, vy):
        """速度统一入口（**限幅** ✓）：所有赋值都必须走它 —— 微小 dt 的除法/咬错观测
        会把速度炸到几千 px/s（实测 -10886 ✓），而 `pos` 带 vel×_LEAD_S 的超前补偿
        ⇒ 输出瞬移几千 px ✗（离线口径还给瞬移记命中 = 假命中 ✗ 实测 ✓）。"""
        m = max(abs(vx), abs(vy))
        if m > _V_MAX:
            k = _V_MAX / m
            vx, vy = vx * k, vy * k
        self._vel = (float(vx), float(vy))

    def _rate_limit(self, raw_half, dt=None):
        """输出**速率限制**（半分辨率 ✓ 这一拍最多走 `_STEP_SPEED × dt` px）：一帧跳 100px+
        只能是错检/身份切换 ✗ —— 限速让输出成为**可被真鼠标跟随**的平滑曲线
        （离线口径的"合成鼠标"会瞬移、真实鼠标不会 ⇒ 不限速就白丢 ✗ 实测 M2c ✓）。

        ⭐ 2026-09-30 改成**按速度**（`_STEP_SPEED` px/s × dt ✓ 帧率无关 ✓）——
        用户第③问："第14帧真目标消失，但十字标位置突变太远了" ✓ 实测帧13→14→15 是
        (339,274)→(333,318)→(290,398)（跳 45 再跳 85px ✗✗）⇒ 老写法"每帧固定 45px"
        在慢素材上太松 ✗、在快素材上又毫无意义 ✗。
        """
        if self._raw is None:
            return raw_half
        dx = raw_half[0] - self._raw[0]
        dy = raw_half[1] - self._raw[1]
        d = (dx * dx + dy * dy) ** 0.5
        step = float(dt) if (dt and 0.0 < float(dt) <= 1.0) else _STEP_DT_DEF
        cap = _STEP_SPEED * step * _SCALE
        if d > cap > 0:
            k = cap / d
            return (self._raw[0] + dx * k, self._raw[1] + dy * k)
        return raw_half

    def _report_pos(self, dt=None):
        """`_raw` + 超前补偿 ⇒ **报告位置（十字标）**，并且**也限速**（用户第③问 ✓）。

        ⚠ **只限 `_raw` 远远不够**（实测：仍然出现 84px/帧的突跳 ✗✗）：超前补偿是
        `vel × 2 帧` 的**前馈偏移**（封顶 `_LEAD_MAX`=60px ✓），速度一抖，它就带着报告
        位置一起跳 ✗ —— 而用户一眼看的是**十字标**（第③问原话："十字标位置突变太远了，
        我们是否需要限制一下跟踪器的最大速度？" ✓）⇒ **报告位置本身**也要按
        `_STEP_SPEED × dt` 限速 ✓（实测这一道加上去之后逐帧位移才真的守住上限 ✓）。
        """
        tgt = self._clamp_full(self._lead_pos(self._raw))
        if tgt is None:
            return None
        if self.pos is None:
            return tgt
        step = float(dt) if (dt and 0.0 < float(dt) <= 1.0) else _STEP_DT_DEF
        cap = _STEP_SPEED * step
        dx, dy = tgt[0] - self.pos[0], tgt[1] - self.pos[1]
        d = (dx * dx + dy * dy) ** 0.5
        if d > cap > 0:
            k = cap / d
            return (self.pos[0] + dx * k, self.pos[1] + dy * k)
        return tgt

    def _set_raw(self, xy_half, dt=None):
        """⭐ `self._raw` 的**唯一出口**：钳进画面 + **速率限制**（用户第③问 ✓）。

        为什么非要收口：原来只有"有观测"那条路调 `_rate_limit` ✗，而**滑行 / 预测 /
        探测接管 / 复活**四条路是直接赋值的 ⇒ 真目标一消失，十字标就能一帧跳 85px ✗✗
        （实测 ✓）。现在全部走这里 ⇒ 无论哪条路都不会瞬移 ✓。
        """
        if xy_half is None:
            return
        self._raw = self._rate_limit(self._clamp(xy_half), dt)

    def _lead_pos(self, raw_half):
        """`raw`（半分辨率）+ 超前补偿 ⇒ 报告位置（全分辨率）。

        ⭐ **补偿时长封顶为一帧**（用户 2026-09-30 口径 ✓ 原话："我们的轨迹追踪最小精度
        应该是图片帧长，更小只会预测错乱"）：补偿量 = `vel × min(_LEAD_S, 本帧间隔)` ——
        素材是 **10fps**（录像 60fps 去重后 ✓）⇒ 原 `_LEAD_S = 0.28s` = **2.8 帧的预测**
        ✗✗（超出"一帧"这个最小精度单位 ⇒ 报出的位置会比真实领先近 3 帧的位移 ✗）。
        再叠加 `_LEAD_MAX` 的绝对封顶（防 vel 爆掉 ⇒ pos 瞬移 ✗ 实测 ✓）。
        """
        # ⚠⚠ **滑行时不加超前补偿**（2026-09-30 重构实测踩到 ✗）：超前补偿是给**残差观测**
        #   补"半个窗的滞后"用的 ✓；连丢几拍时位置本身就是按速度外推的 ✗ ⇒ 再加 2 帧超前 =
        #   **纯过剩**（实测：漂到 172px ✗✗）。⇒ 只在**上一拍有观测**（`lost_n == 0` ✓）时补 ✓。
        if self.lost_n > 0:
            return (raw_half[0] / _SCALE, raw_half[1] / _SCALE)
        # ⭐⭐⭐ **无滞后的观测不许前馈**（2026-09-30 实测大坑 ✓✓ 用户第 2 条"拟人平滑"的近亲 ✓）：
        #   超前补偿的**唯一用途**是补**残差观测**的滞后（残差质心 ≈ 半个窗之前 ✓ ⇒ 要按速度
        #   补回去 ✓）；而**白块观测本来就在当前帧**（实测与真值只差 0.2~0.8px ✓✓）⇒ 再补
        #   `vel × 2 帧` 就是**多补** ✗✗ —— 实测它表现为**恒定 (+13,+6) 的偏置**（合成台 15px
        #   误差**全部**来自这里 ✓：`vel≈(38,16)px/s × 0.36s = (13.6,5.8)` ✓ 一模一样 ✓）。
        if not self._obs_lag:
            return (raw_half[0] / _SCALE, raw_half[1] / _SCALE)
        # ⭐⭐⭐ **超前补偿：按用户要求"关掉"** ✗✗（2026-10-01 ✓ 原话："**超前补偿关掉**" ✓）。
        #   为什么该关 ✓（实测铁证 ✓）：它**唯一的用途**是给"**滞后的残差观测**"补半个窗 ✓；
        #   而现在 —— 位置已经改成 **① 预测滑行 + ② 夹取** 决定 ✓、**残差候选不再当位置观测**
        #   （已删 ✓）、速度还按"**夹取完的实际位移**"反算（`realized` ✓）—— 超前补偿就变成
        #   **重复计一次** ✗✗。实测（`9月30日(1).mp4`）：帧 12~15 的报告位置比内部 `_raw`
        #   **超前 (+3.8,−0.8) → (+44.7,−6.8) → (+53.7,−4.8) px** ✗✓，而超前项
        #   `vel×2帧 = (−52,−8)` ✓ 与之一模一样 ✓ ⇒ **绿圈凭空跳到前面** ✗、且它在第 12 帧
        #   （白块消失、`_obs_lag` 由假变真那一拍）**突然打开** ⇒ 用户看到"圆圈没走出箭头
        #   指示的位移 / 箭头第 12 帧突然转向" ✓ 全是它造成的 ✓。
        #   ⇒ 现在 `_lead_pos` = **原样返回 `_raw`** ✓（绿圈 = 预测 + 夹取 ✓、箭头 = 圆圈真的
        #   走多少 ✓、第 12 帧不再跳 ✓）。要恢复：把下面这行 `return` 删掉、走原路径 ✓。
        return (raw_half[0] / _SCALE, raw_half[1] / _SCALE)
        # （以下为原实现，保留以便回退 ✓）
        ts_lead = _LEAD_FRAMES * (self._dt_last or _LEAD_S / _LEAD_FRAMES)
        lx = self._vel[0] * ts_lead
        ly = self._vel[1] * ts_lead
        m = max(abs(lx), abs(ly))
        if m > _LEAD_MAX:
            k = _LEAD_MAX / m
            lx, ly = lx * k, ly * k
        return ((raw_half[0] + lx) / _SCALE, (raw_half[1] + ly) / _SCALE)

    def _clamp_full(self, xy, kill_vel=True):
        """全分辨率坐标钳回画面（`pos` 是报告给鼠标的 ⇒ 更不能出画面 ✓）；同 `_clamp` ✓。

        ⚠⚠ `kill_vel`：**只有"目标自己贴到画面边"才清零速度**（= 它顶到边界 ⇒ 那个方向确实没
        法再走 ✓ 默认 True ✓）。**别的地方借用它时必须传 `False`** ✗ —— 否则会莫名其妙把
        **目标速度**清掉（实测：画箭头用的"检测轨迹滑行"滑出边缘 ⇒ 速度被清零 ⇒ 目标冻结
        6 帧 ✗✗ 用户素材第 10~11 帧 ✓）。
        """
        if self._wh is None or xy is None:
            return xy
        x = min(max(xy[0], 0.0), self._wh[0] - 1.0)
        y = min(max(xy[1], 0.0), self._wh[1] - 1.0)
        if x != xy[0] and kill_vel:
            self._vel = (0.0, self._vel[1])
        if y != xy[1] and kill_vel:
            self._vel = (self._vel[0], 0.0)
        return (x, y)

    # ---- 检测轨迹的公共小工具（滑行 / 记忆 / 可视化 ✓ 2026-09-30）----
    def _speed_of(self, t):
        """轨迹速度模长（px/s ✓）。"""
        vx, vy = t.get("v") or (0.0, 0.0)
        return (vx * vx + vy * vy) ** 0.5

    def _age_tracks(self, tracks, dt, matched):
        """没配上的轨迹：**按速度滑行 + 记记忆时间**，超时才删 ⇒ 返回新表。

        ⭐ 这就是用户 ③ 要的"防抖"（原话："让每个检测出来的目标按照当前速度的方向跟着
        预测做点防抖，下次检测出来了再刷新防抖时间？这样即使 yolo 短暂的没识别出来也不会
        永久丢失其速度记录" ✓✓）：短暂漏检时轨迹**不删**、速度**不丢**，位置按速度外推
        （= 预测位置 ⇒ 供重新捕获与"可疑真目标"判定用 ✓ 用户 ② ✓）。
        """
        out = []
        for t in tracks:
            if id(t) in matched:
                out.append(t)
                continue
            t["miss"] += 1
            lost = (t.get("lost_s") or 0.0) + (dt or 0.0)
            t["lost_s"] = lost
            vx, vy = t.get("v") or (0.0, 0.0)
            if dt:
                # ⚠⚠⚠ **必须用"纯钳制"**（`kill_vel=False` ✓）：`_clamp_full` 钳到画面边缘时会
                #   **顺手把追踪器的 `_vel` 分量清零** ✗ —— 那是给"**目标自己**贴到画面边"准备的
                #   语义 ✓；这里是**检测轨迹**（画箭头用 ✓）滑出画面 ✗ ⇒ 拿它钳一次就会把
                #   **目标速度**清掉 ✗✗。实测（用户素材第 10~11 帧）：轨迹滑出边缘 ⇒ 速度
                #   (-120,+16) 被清零 ⇒ 目标冻结 6 帧 ✗✗（用户："第10帧→第11帧不是有速度吗" ✓）。
                t["p"] = self._clamp_full((t["p"][0] + vx * dt, t["p"][1] + vy * dt),
                                          kill_vel=False)
            if lost > _TRK_MEM_S or t["miss"] > _TRK_MISS_CAP:
                continue                      # 记忆到期 ⇒ 删（速度记录也就此作废 ✓）
            out.append(t)
        return out

    def _mark_size_suspects(self, dt):
        """⭐ 「重叠 / 分离」怀疑链（用户 2026-09-30 ①②③ ✓ 口径见常量区注释）。

        **只记账、不裁决**（用户 ④："以上只是<可能>，仅记录怀疑" ✓ —— 裁决留给"不合群
        速度持续够久"那条 ✓ 见 `dev_s`）：
          · 面积**突然变大** ⇒ `merge_s`：怀疑与别的图形**重叠**（合并块中心 = 两者中点 ✗）
            ⇒ 跟踪器该按**轨迹预测**走 ✓；
          · 面积**突然变小** + 附近有**这一拍新出的框** ⇒ `split_s` + 给新框打
            `must_check`（= 用户②"**严查新多出来的边**" ✓）；
          · 面积**突然变小** + 没有新框 ⇒ `hidden_s`：真目标"很可能就在**面积消失的地方**，
            只是 yolo 没检出来"（用户③ ✓）⇒ 位置**锚在原地**靠预测撑 ✓。
        所有计时按 `dt` 递减、过期自动失效 ✓（怀疑有时效 ✓）。
        """
        step = max(0.0, float(dt or 0.0))
        fresh = [t for t in self._tracks if t.get("new")]
        for t in self._tracks:
            for k in ("merge_s", "split_s", "hidden_s", "area_s"):
                if t.get(k, 0.0) > 0.0:
                    t[k] = max(0.0, t[k] - step)
            if t.get("must_check", 0) > 0:
                t["must_check"] = max(0, int(t["must_check"]) - 1)
            if t.get("must_check", 0) == 0 and t.get("sus_kind") == "split":
                t["sus_kind"] = ""                 # 严查期过了 ⇒ 旗子落下 ✓
            a_prev = float(t.get("a_prev") or 0.0)
            a_now = float(t.get("a") or 0.0)
            if t.get("miss") or a_prev <= 0.0 or a_now <= 0.0:
                continue                           # 这拍没检出 / 无历史 ⇒ 判不了大小变化 ✓
            if a_now >= a_prev * _MERGE_GROW:
                t["merge_s"] = _SUSPECT_HOLD_S
                t["sus_kind"] = "merge"
            elif a_now <= a_prev * _SPLIT_SHRINK:
                near = [f for f in fresh
                        if f is not t
                        and ((f["p"][0] - t["p"][0]) ** 2
                             + (f["p"][1] - t["p"][1]) ** 2) ** 0.5 <= _SPLIT_GATE]
                if near:
                    t["split_s"] = _SUSPECT_HOLD_S
                    t["sus_kind"] = "split"
                    hold = int(max(1.0, _SUSPECT_HOLD_S / max(step, 0.05))) + 2
                    for f in near:                 # ⭐ ②"严查新多出来的边" ✓
                        f["must_check"] = max(int(f.get("must_check", 0)), hold)
                else:
                    t["hidden_s"] = _SUSPECT_HOLD_S
                    t["sus_kind"] = "hidden"
        for t in self._tracks:                     # `new` 只在**建它的那一拍**有效 ✓
            t["new"] = False

    def _sus_of(self, t):
        """当前**最需要提醒**的怀疑（"" / "merge" / "split" / "hidden" ✓ 给可视化用 ✓）。"""
        if t.get("merge_s", 0.0) > 0.0:
            return "merge"
        if t.get("split_s", 0.0) > 0.0:
            return "split"
        if t.get("hidden_s", 0.0) > 0.0:
            return "hidden"
        return ""

    def _target_sus(self):
        """当前认定目标轨迹的怀疑类型（"" / "merge" / "split" / "hidden" ✓ 没有 ⇒ ""）✓。"""
        for t in self._tracks:
            if t["id"] == self._target_id:
                return self._sus_of(t), t
        return "", None

    def _box_merged(self, cx, cy):
        """这个检测框落在一个**疑似合并**的轨迹上吗（用户 ① ✓）—— 是的话**别拿它的中心
        当观测**（合并块中心 ≈ 真目标与假目标的中点 ✗）⇒ 该按**轨迹预测**走 ✓。"""
        for t in self._tracks:
            if t.get("merge_s", 0.0) <= 0.0:
                continue
            if ((t["p"][0] - cx) ** 2 + (t["p"][1] - cy) ** 2) ** 0.5 <= _TRK_GATE:
                return True
        return False

    def _group_median(self, tracks):
        """一组轨迹的**中位速度**（只有"自己算得出速度"的参战 ✓ 少于 2 条 ⇒ None ✓）。"""
        vs = [t["v"] for t in tracks if t.get("v_ok") and t.get("miss", 0) == 0]
        if len(vs) < 2:
            return None
        vxs = sorted(v[0] for v in vs)
        vys = sorted(v[1] for v in vs)
        return (vxs[len(vxs) // 2], vys[len(vys) // 2])

    def _borrow_vel(self, med):
        """给自己算不出速度的轨迹**借群体中位速度**（用户 2026-09-30 第③问 ✓）。

        ⚠ 只借给**这一拍真检出**（`miss==0`）的轨迹 ✓ —— 滑行中的用**记忆里的速度** ✓
        （那是它自己的、更可信 ✓）。借来的速度 = 中位速度 ⇒ `dev`≈0 ⇒ 赢不了判据 ✓ 安全 ✓。
        """
        if med is None or not _GROUP_BORROW:
            return
        for t in self._tracks:
            if t.get("v_ok") or t.get("miss", 0) > 0:
                continue
            t["v"] = med
            t["borrowed"] = True

    def _typical_area(self, dets):
        """**所有目标的面积基本相等**（用户 2026-09-30 第 2 条 ✓ 原话："所有目标的面积
        （无论真假）都是基本相等的" ✓）⇒ 取这一拍检测框面积的**中位**当"标准面积" ✓。

        用途：① 面积**明显偏离**标准（≈2× ⇒ 两个图形**并成一块** ✗、≈0.5× ⇒ 被切掉 ✗）
        的框 ⇒ 说明它**不是"一个完整的目标"** ⇒ 判断"离报告位置最近的那个框"时要打个折 ✓；
        ② 演示窗**选红框**也用得上（要选"像单个目标"的那个 ✓ 见 `lie_demo._pick_target_box`）。
        """
        aa = sorted(w * h for _cx, _cy, w, h in dets if w > 0 and h > 0)
        return aa[len(aa) // 2] if aa else 0.0

    def _white_obs(self, bgr):
        """**白块观测**（白块阶段最可信 ✓ 那时目标 = 画面里唯一的大白块 ✓ 用户 2026-09-30：
        "第 6 帧……真目标都没有变透明还是白的" ✓ ⇒ 这种帧根本不该靠"猜" ✓）。

        ⚠ 只在**离预测位置不远**（`_DET_GATE × 2` ✓）时采用：透明阶段亮背景碎块/招牌也会被
        `V≥185 & 低饱和` 的掩码抓进来 ✗（实测有 15285px² 的亮背景块 ✗）—— 但它们不会正好
        长在目标旁边 ✓。⇒ 返回 `(cx, cy)`（全分辨率）或 None ✓。
        """
        try:
            hsv = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)
            bw = cv2.inRange(hsv, (0, 0, _WHITE_V), (180, _WHITE_SAT, 255))
            bw = cv2.morphologyEx(bw, cv2.MORPH_CLOSE,
                                  np.ones((5, 5), np.uint8), iterations=2)
            bs = _white_blobs(bw, _INIT_AREA, 0.0)
        except cv2.error:
            return None
        if not bs:
            return None
        if self.pos is None:
            return (bs[0][0], bs[0][1], bs[0][2])
        # ⚠⚠⚠ **面积也要像目标**（2026-09-30 实测踩到 ✗，比"门"更隐蔽）：透明阶段**亮背景碎块**
        #   会正好落在预测位置旁边 ⇒ 过了 40px 门 ✗ ⇒ 被当成白块观测 ⇒ 观测≈当前位置 ⇒
        #   `nv≈0` ⇒ **速度被 EMA 压到 0** ⇒ 位置**冻住 5 帧**（实测 `9月30日(1).mp4` 第 11~15 帧
        #   ✗✗）⇒ 后面所有几何（红框/相切）全建在一个不动的点上 ✗。
        #   ⇒ 要求它的**等价半径 ≥ 0.6× 学到的目标实际半径** ✓（真目标 ≈ 1.0× ✓ 碎块远小于 ✓）。
        if self._rad:
            bs = [b for b in bs if (b[2] / 3.141592653589793) ** 0.5 >= 0.6 * float(self._rad)]
            if not bs:
                return None
        c = min(bs, key=lambda b: math.hypot(b[0] - self.pos[0], b[1] - self.pos[1]))
        if math.hypot(c[0] - self.pos[0], c[1] - self.pos[1]) <= _WHITE_GATE:
            # ⇒ `(cx, cy, 面积)`：面积给上层量"**目标实际半径**"用 ✓（`sqrt(A/π)` ✓ 用户口径 ✓）
            return (c[0], c[1], c[2])
        return None

    def _circle_hits(self, box):
        """**绿圈（圆）与这格检出框是否相交**（圆心到矩形的最近距离 ≤ 半径 ✓）。

        · 半径 = **画圆那把尺**（`_tbox_rad` ✓ 丢框后冻结 ✓；还没学到 ⇒ 退回 `_rad` ✓）。
        · 用户 2026-10-01 ✓ 定稿原话："判定：如果**与绿圈外接圆相交，那么它就是红框**；
          其他情况 pass" ✓ —— 这是"真目标框"的判据 ✓（相交 = 目标就在这一格上 ✓）。
        """
        if box is None or self.pos is None:
            return False
        _r = float(getattr(self, "_tbox_rad", 0.0) or 0.0) or float(getattr(self, "_rad", 0.0) or 0.0)
        _px, _py = float(self.pos[0]), float(self.pos[1])
        _dx = max(float(box[0]) - float(box[2]) / 2.0 - _px, 0.0, _px - (float(box[0]) + float(box[2]) / 2.0))
        _dy = max(float(box[1]) - float(box[3]) / 2.0 - _py, 0.0, _py - (float(box[1]) + float(box[3]) / 2.0))
        return bool(math.hypot(_dx, _dy) <= _r)

    def _circle_rect(self, box):
        """检出框与**绿圈外接矩形**是否相交（用户 2026-10-02 ✓ 原话："只能往轨迹预测方向的前方挑
        **与绿圆圈外接矩形相交**的格子" ✓）。

        · 半径 = **与 `_circle_hits` 同一把尺**（`_tbox_rad` 优先、丢框后冻结 ✓ 退回 `_rad` ✓）；
        · "外接矩形" = `圆心 ± 半径` 那个**方形** ✓（比"圆"宽松 ✓ 用户点名的就是它 ✓）。
        ⚠ 它与 `_circle_hits`（圆 ↔ 矩形最近距 ✓）**不是同一判据** ✗ —— 两条并存、各用各处 ✓。
        """
        if box is None or self.pos is None:
            return False
        _r = (float(getattr(self, "_tbox_rad", 0.0) or 0.0)
              or float(getattr(self, "_rad", 0.0) or 0.0))
        if _r <= 0.0:
            return True          # 半径还没学到 ⇒ **判不出 ⇒ 保守放行** ✓（与 `_box_ahead_of_pred`
            #   同一取舍 ✓ 不猜 ✗；否则合成用例里"还没有半径"的那些帧会被整片否掉 ✗）
        _px, _py = float(self.pos[0]), float(self.pos[1])
        return not (float(box[0]) + float(box[2]) / 2.0 < _px - _r
                    or float(box[0]) - float(box[2]) / 2.0 > _px + _r
                    or float(box[1]) + float(box[3]) / 2.0 < _py - _r
                    or float(box[1]) - float(box[3]) / 2.0 > _py + _r)

    def _box_ahead_of_pred(self, box):
        """框中心是不是在「**轨迹预测方向的前方**」？（用户 2026-10-02 ✓ 原话："只能往轨迹预测
        方向的**前方**挑……" ✓）

        判据 = `(框中心 − 圆心) · 白箭头方向 ≥ 0` ✓（方向 = `_vel_rel` ✓ 用户 2026-10-02 选 ✓
        "白箭头方向、以圆心为基准" ✓ —— 与 `_merge_edge_own` 里那条"白箭头前方 180°"筛选
        **同一把尺** ✓）。
        ⚠ 速度≈0（还没学出方向 ✓）⇒ `True`（判不出 ⇒ 保守放行 ✓ 不猜 ✗）；圆心不比自己更前 ✓。
        """
        if box is None or self.pos is None:
            return True
        _vr = getattr(self, "_vel_rel", (0.0, 0.0)) or (0.0, 0.0)
        if abs(float(_vr[0])) + abs(float(_vr[1])) < 1e-6:
            return True
        _dx = float(box[0]) - float(self.pos[0])
        _dy = float(box[1]) - float(self.pos[1])
        return bool(_dx * float(_vr[0]) + _dy * float(_vr[1]) >= 0.0)

    def _circle_rect_area(self):
        """绿圈**外接矩形**的面积（`S` 的**分母** ✓ 用户 2026-10-02 ✓）—— 半径用**画圆那把尺** ✓
        （`_tbox_rad` ✓ 丢框后冻结 ✓；还没学到 ⇒ 退回 `_rad` ✓ 与 `_circle_hits` 同一处口径 ✓）。"""
        _r = float(getattr(self, "_tbox_rad", None) or getattr(self, "_rad", 0.0) or 0.0)
        return (2.0 * _r) ** 2

    def _box_iou(self, a, b):
        """两框的 **IoU = 交集 ÷ 并集**（用户 2026-10-03 ✓ 原话："**改成 IoU（交集 ÷ 并集）**" ✓）
        —— 给融合**续任判定**用（判"这一拍的这格，是不是上一拍那个融合框的**同一格**" ✓）。

        ⚠⚠ 为什么不用"交集 ÷ **较小面积**"（`_box_overlap_min` ✗ 实测踩过 ✓）：那个口径下
          **小框被大框整个包住 ⇒ 恒≈1** ✗ ⇒ "上一拍的大框缩下来的那一小块"永远赢 ✗
          （实测 `10月1日.mp4` 帧 23：conf 0.80 的小框重叠 0.901 赢了 0.897 ✗，而它与上一拍
          红框的 **IoU 只有 0.503**、而 conf 0.94 那格（≈ 上一拍红框本体）IoU 是 **0.790** ✓）
          ⇒ 换成 IoU ⇒ "谁跟上一拍那格**更像同一格**"一目了然 ✓（几何中立 ✓）。
        """
        if a is None or b is None:
            return 0.0
        # ⭐ 算法统一放在 `perception/geom.py`（用户 2026-10-03 ✓ 原话："我认为我们很多判定都可以
        #   换成这个算法" ✓）⇒ 这里只**委托** ✓（实现一份 ✓ 不再各自写 ✗）。
        return geom.iou(a, b)

    def _box_overlap_min(self, a, b):
        """两框的**重叠率 = 交集 ÷ 较小面积**（与登记表判"同一块砖"同一把尺 ✓）。

        ⚠ 融合**续任判定**已改用 `_box_iou`（用户 2026-10-03 ✓ 见它 ✓ —— "较小面积"口径会让
          "被大框包住的小框"虚高 ✗）；本函数**保留**（登记表那条链仍用同一把尺 ✓ 别动 ✗）。
        """
        if a is None or b is None:
            return 0.0
        # ⭐ 同上：算法在 `perception/geom.py` ✓（登记表那份也走同一个 ✓ 口径一处 ✓）。
        return geom.overlap_min(a, b)

    def _inner_edge_dist_ratio(self, box):
        """**「绿圈圆心到框最近一条边的垂直距离」÷ 绿圈半径**（用户 2026-10-02 ✓ 新口径 ✓
        原话："『S = 框∩绿圈外接矩形 ÷ 绿圈外接矩形 > 「融合框继承面积限制」』改为『**绿圈圆心
        到框最近一条边的垂直距离(绿圆半径比例) > 「融合框继承距离限制」**』" ✓）—— 融合框候选
        **第一条闸**的新判据 ✓（取代 `_circle_rect_overlap_ratio` 的 S ✗ 那个函数保留 ✓ 别处在用 ✓）。

        定义（**有符号** ✓ 关键 ✗✗）：
          `d = min( px − 框左 , 框右 − px , py − 框上 , 框下 − py )` ／ 再 ÷ **绿圈半径** ✓
          · 圆心在框内 ⇒ 四个量全正 ⇒ `d > 0` ✓（**越靠框中心越大**）；
          · 圆心出框 ⇒ 至少一个量为负 ⇒ `d < 0` ✓（负多少 = "出框多少 px" ✓）。

        ⚠⚠ **必须带符号** ✗：若取绝对值/非负（"点到矩形的最短距离"那种 ✓），圆心**跑得越远
          反而越大** ⇒ `> 阈值` 会把"离框十万八千里"的框判成合格 ✗✗（本判据的单调性会整个反掉 ✓）。

        阈值语义（`self.inherit_dist` ✓ 用户 2026-10-02 ✓ 原话："**圆心在框外 才判定，圆心在
        框内直接允许融合**" ✓）：
          · 圆心在框内（`d ≥ 0`）⇒ **直接通过** ✓（不看阈值 ✗ —— 这才是"正数才有意义" ✓）；
          · 圆心在框外（`d < 0`）⇒ 才看阈值：**出框量 ≤ 阈值 × 半径** ⇒ 通过 ✓
            （等价于 `d ≥ −阈值` ✓ 见 `_inherit_dist_ok` ✓）；
          · 阈值只收**非负** ✓（`0`（默认）= 一点也不许出框 ⇒ 圆心必须落在框内 ✓）。

        ⚠ 半径还没学到（`_rad ≤ 0` ✓ 开头那几帧）⇒ 回 **`None`**（判不出 ⇒ 调用处**放行** ✓
          与 `_circle_rect_overlap_ratio` 回 1.0 同一取舍 ✓ 不猜 ✗）。
        """
        if box is None or self.pos is None:
            return None
        _r = float(getattr(self, "_rad", 0.0) or 0.0)
        if _r <= 1e-6:
            return None
        _px, _py = float(self.pos[0]), float(self.pos[1])
        _x0 = float(box[0]) - float(box[2]) / 2.0
        _x1 = float(box[0]) + float(box[2]) / 2.0
        _y0 = float(box[1]) - float(box[3]) / 2.0
        _y1 = float(box[1]) + float(box[3]) / 2.0
        _d = min(_px - _x0, _x1 - _px, _py - _y0, _y1 - _py)
        return float(_d) / _r

    def _inherit_dist_ok(self, box):
        """融合框候选**第一条闸**（用户 2026-10-02 ✓ 定稿口径 ✓）：**圆心在框内 ⇒ 直接允许** ✓；
        **圆心在框外** ⇒ 才判"出框量 ≤ 「融合框继承距离限制」× 半径" ✓（见实现 ✓）。

        ⚠⚠⭐ **2026-10-03 起已屏蔽**（用户原话："**有了这个逻辑，就不需要『融合框继承距离限制』
          了，先屏蔽相关逻辑**" ✓ 见 `_INHERIT_DIST_ON` ✓）：默认**恒放行** ✓ —— 候选框改由
          「**内砖同一性**」（`_same_inner_brick` ✓ 分离前不许换内砖 ✓）+「**允许倒退距离**」
          （`_merge_fix_safe` ✓）两道把关 ✓。开关拨回 `True` ⇒ 恢复本判据（= 老行为 ✓）。

        ⚠ 距离比判不出来（半径未学到 ✓）⇒ **放行**（保守 ✓ 与老 S 回 1.0 同款 ✓ 不猜 ✗）。
        """
        if not _INHERIT_DIST_ON:
            return True                      # ⭐ 已屏蔽（用户 2026-10-03 ✓ 见 `_INHERIT_DIST_ON` ✓）
        _dr = self._inner_edge_dist_ratio(box)
        if _dr is None:
            return True                      # 半径还没学到 ⇒ 判不出 ⇒ 放行（不猜 ✓）
        # ⭐⭐ **圆心在框内 ⇒ 直接允许**（用户 2026-10-02 ✓ 原话："**圆心在框外 才判定，圆心在
        #   框内直接允许融合**" ✓）；**圆心在框外**才看阈值：**出框量 ≤ 阈值 × 半径** ⇒ 允许 ✓
        #   （`_dr ≥ 0` ⇒ `_dr ≥ −阈值` 恒真 ⇒ 框内不再受阈值约束 ✓）。
        #   ⚠⚠ 与上一版 `_dr > 阈值` **方向完全不同** ✗✗：那一版要求"圆心离最近那条边还得 ≥
        #     阈值 × 半径"（框内也受限 ✗ ⇒ 实测 9月30日 帧 38 那格圆心明明在框里，只因离下边
        #     只有 0.563 半径就被挡在融合候选之外 ✗ = 用户点名的毛病 ✓）；本版是"**最多允许
        #     出框这么多**"⇒ 阈值语义 = **允许圆心出框的倍数半径** ✓（0 = 一点也不许出框 ✓）。
        return bool(_dr >= -float(self.inherit_dist))

    def _step_len_px(self):
        """**「本拍通常该走多远」= B 型归一化基准**（用户 2026-10-03 ✓ 原话："② 选框距离门的话
        会因为**视频播放速度**而改变结果吧？" ✓ ⇒ 所有"距离类"闸的容差都按**它的倍数**给 ✓）。

        ⭐ **为什么这样就和帧率 / 播放倍速无关** ✓：倍速播放时"每拍位移"与"框的偏差"**同比例**
          变 ⇒ 比值 `偏差 ÷ 本拍位移` 恒定 ✓；而"绿圆半径比例"那样给 ✗ ⇒ 倍速一开，偏差被放大
          而半径不动 ⇒ 判定漂 ✗（用户点出来的正是这个 ✓）。B 型 ⇒ **判定逐帧稳定** ✓。

        取法（依次退让 ✓ 拿不到 ⇒ `None` ⇒ 调用方**放行** ✓ 不猜 ✗）：
          ① `|白箭头| × dt`（**相对群体**的预测速度 ✓ 与预测本身同源 ✓ 首选 ✓）；
          ② `|绝对速度| × dt`（`_vel` ✓ 兜底 ✓）；
          ③ `None`（速度还没学出来 ✓）。
        ⚠ `dt` 取不到（第 0 拍 ✓）⇒ 用模块默认帧长 `_STEP_DT_DEF` ✓（与 `_report_pos` 同款 ✓）。
        """
        _dt = float(self._dt_last) if self._dt_last else float(_STEP_DT_DEF)
        if _dt <= 0.0:
            return None
        _n = math.hypot(float(self._vel_rel[0]), float(self._vel_rel[1]))
        if _n <= 1e-6:
            _n = math.hypot(float(self._vel[0]), float(self._vel[1]))
        if _n <= 1e-6:
            return None
        return float(_n) * _dt

    def _clamp_step_px(self):
        """**「夹取限速」的每拍上限（px）**（用户 2026-10-03 ✓ 原话："动手" ✓）：**B 型（步数比例）**
        = `clamp_step_ratio × 本拍该走多远`（帧率 / 播放倍速无关 ✓ 见 `_step_len_px` ✓）；
        基准拿不到（速度≈0 ✓）⇒ 回 `_CLAMP_STEP_FLOOR_PX`（固定 px ✓）；
        `clamp_step_ratio ≤ 0` ⇒ **`None`**（调用方据此走**硬夹** = 老行为 ✓）。
        """
        if float(getattr(self, "clamp_step_ratio", 0.0) or 0.0) <= 0.0:
            return None
        _st = self._step_len_px()
        if _st is None:
            return float(_CLAMP_STEP_FLOOR_PX)
        return max(float(_CLAMP_STEP_FLOOR_PX),
                   float(self.clamp_step_ratio) * float(_st))

    def _clamp_step(self, xy, box, dt=None):
        """**限速版夹取**（用户 2026-10-03 ✓ 原话："动手" ✓）：把 `xy` 朝框的**内接安全区**挪一步
        —— 每拍最多 `_clamp_step_px()` ✓（B 型 ⇒ 帧率无关 ✓）。

        · **已经在安全区里** ⇒ `_pos_in_tbox` 回它自己 ⇒ 位移 0 ⇒ **原样返回** ✓（平时就是这条 ✓
          所以对正常跟随**零影响** ✓）；
        · 一步够得着（≤ 上限 ✓）⇒ **直接到位** ✓（不引入多余滞后 ✓）；
        · 够不着 ⇒ 只走上限那一段 ✓（**渐进贴上** ✓ 不再一步 96px ✗）；
        · `_clamp_step_px()` 回 `None`（= 关 ✓）⇒ 走**硬夹**（`_pos_in_tbox` ✓ **老行为一字不变** ✓）。
        """
        if box is None or xy is None:
            return xy
        _want = self._pos_in_tbox(xy, box)
        _lim = self._clamp_step_px()
        if _lim is None:
            return _want                       # 关 ⇒ 硬夹（老行为 ✓）
        _dx, _dy = float(_want[0]) - float(xy[0]), float(_want[1]) - float(xy[1])
        _d = math.hypot(_dx, _dy)
        if _d <= _lim or _d <= 1e-9:
            return _want
        _k = float(_lim) / _d
        return (float(xy[0]) + _dx * _k, float(xy[1]) + _dy * _k)

    def _select_dist_px(self):
        """**「选框距离门」的容差（px）**（用户 2026-10-03 ✓ 原话："动手" ✓；上一轮定下的口径：
        门限按 **B 型（步数比例）** 给 ⇒ **帧率 / 播放倍速无关** ✓ 见 `_step_len_px` ✓）。

        = `max(_SELECT_FLOOR_PX, select_step_ratio × 本拍该走多远)` ✓；
        · 基准拿不到（速度≈0 那几拍 ✓）⇒ 回 `_SELECT_FLOOR_PX`（固定 px ✓ 不会把静止段全拦 ✗）；
        · `select_step_ratio ≤ 0` ⇒ **关** ⇒ 回 `None`（调用方据此**不设门** ✓ = 老行为 ✓）。
        """
        if float(getattr(self, "select_step_ratio", 0.0) or 0.0) <= 0.0:
            return None
        _st = self._step_len_px()
        if _st is None:
            return float(_SELECT_FLOOR_PX)
        return max(float(_SELECT_FLOOR_PX),
                   float(self.select_step_ratio) * float(_st))

    def _select_vel_px(self):
        """**「选框速度门」的每拍位移上限（px）**（用户 2026-10-03 ✓ 原话："选这个融合框后明显会
        超过白箭头限速，不应该选，判断了吗？没有的话应该加上" ✓）。

        ⭐⭐⭐ **尺子复用既有的「真目标预测最大速度倍率」（`sep_vel_max_ratio` ✓ 用户 2026-10-03
          提醒 ✓）** ⇒ = **`sep_vel_max_ratio × 当拍群体速度模长 × dt`** ✓ —— 就是**分离期白箭头
        模长上限**（`_sep_vel_cap` 同一把尺 ✓："分离期白箭头的模长 ≤ a × 假目标群体的标准速度" ✓
        用户原话 ✓）**换算成位移** ✓ 好与预演的位移直接比 ✓。

        · 为什么必须复用 ✗ 不能用 `_REL_V_MAX`（400 px/s）那个常量 ✗：那是"**自身分量**"的兜底
          防灾限幅 ✓（口径是"超过它就说明这一拍没拆干净" ✓）；而"**分离后重新认框**"这一档，
          项目**已定**的尺子就是 `sep_vel_max_ratio × 群体速度` ✓（同一档素材、同一期状态 ✓）
          ⇒ 两者混用等于**同一条判据两把尺** ✗✗（实测帧 64：400 那把尺算出上限 53.3px、群体的
          那把算出 **24.1px** ✓ 差一倍 ⇒ 判定跟着差一档 ✓）。
        · 它是**速度**（px/s ✓）换算来的 ⇒ **帧率 / 播放倍速无关** ✓✓（倍速 ⇒ dt 与位移同为
          同比变小 ⇒ 判定一字不变 ✓ —— 用户上一轮点出"② 会因为视频播放速度改变结果吧？"✓）。
        · `dt` 拿不到 / 非法（第一拍 ✓）／**群体速度≈0**（拆不出来 ✓）⇒ `None`（不设门 ✓ 不猜 ✗）；
        · **要放宽/收紧就调 `sep_vel_max_ratio`** ✓（调大 ⇒ 门更松 ✓）—— 不另设参数 ✗。
        """
        _dt = float(getattr(self, "_dt_last", 0.0) or 0.0)
        if not (0.0 < _dt <= 1.0):
            return None
        _gv = self._group_vel(_dt)
        _gs = 0.0 if _gv is None else math.hypot(float(_gv[0]), float(_gv[1]))
        # ⭐⭐⭐ **上限 = min(两把既有尺) × dt**（用户 2026-10-03 ✓ 提醒"注意我们有参数『真目标预测
        #   最大速度倍率』" ✓）—— 这两把都是项目**已经定下**的"白箭头限速"✓ 一次也没新造 ✗：
        #     · `sep_vel_max_ratio × 群体速度模长`（= **分离期**白箭头上限 ✓"a × 假目标群体的
        #       标准速度"用户原话 ✓ 见 `_sep_vel_cap` ✓）；
        #     · `_REL_V_MAX`（400 px/s ✓ = **自身分量**的兜底限幅 ✓"超过它就说明这一拍没拆干净"
        #       ✓ 见 `_rel_cap` ✓）。
        #   ⚠ 为什么**取较小值**（实测：只用群体那把 ⇒ `10月3日.mp4` 帧 64 上限算到 634 px/s ✗
        #     ⇒ **拦不住** ⇒ 白线照旧 86.5px 折角 ✗；只用 400 那把 ⇒ 上限恒 53.3px ✓ 拦得住 ✓
        #     但"群体很慢、圆却在跳"那几拍就管不到 ✗）⇒ 取 min ⇒ **两条口径都不丢** ✓。
        #   ⚠⚠ **群体速度拿不到时只退化、不许整条失效** ✗✗（实测：`_group_vel` 在"选框那一刻"
        #     常常还没算出来 ⇒ 若因此回 `None` ⇒ **门形同不存在** ⇒ 帧 64 照旧放行 ✗✗）⇒ 那几拍
        #     只用 `_REL_V_MAX` 那一把 ✓。
        _lim_v = float(_REL_V_MAX)
        if _gs > 1e-6:
            _lim_v = min(float(self.sep_vel_max_ratio) * _gs, float(_REL_V_MAX))
        return _lim_v * _dt

    def _select_vel_ok(self, box):
        """**认了这一格 ⇒ 圆这一步要挪多远**（把 `_report_pos` 夹进它的内接安全区 ✓）÷ dt ⇒
        与「选框速度门」比 ✓（用户 2026-10-03 ✓ 原话见 `_select_vel_px` ✓）。

        ⚠ 为什么**必须预演"夹进框"**而不是看"落位点" ✗：实测 `10月3日.mp4` 帧 64 —— 那格融合框
          的**落位位移是 0** ✓（落位点恰好就是圆心 ✓）⇒ 用落位点判**完全拦不住** ✗；真正的位移
          来自"**认了它 ⇒ 把圆夹进它的内接安全区**"（`_pos_in_tbox` ✓）⇒ **96.5px** ✗
          （口径上是"圆要一步走 726 px/s" ✓ 远超白箭头限速 400 ✓）。
        返回 `True` = 放行（门关着 / 算不出 / 没超限 ✓）；`False` = **不认这格** ✓。
        """
        if not _SELECT_VEL_GATE:
            return True                    # 默认关 ✓（实测：开着会把融合会话整段掐掉 ✗ 见该常量 ✓）
        _lim = self._select_vel_px()
        if _lim is None:
            return True
        # ⚠⚠ **只在"上一拍还没有红框"这一档生效** ✗✗（用户 2026-10-03 ✓ 实测定界 ✓）：同一把尺若
        #   一律生效 ⇒ 会**误伤**"框一直在"的那些正常融合 ✓ —— 实测 `9月30日(1).mp4` 帧 17~20
        #   位移 60~88px（那是"**框在移动、圆跟着微调**"✓ 正常 ✓）一旦拦掉 ⇒ 整个会话崩掉
        #   （融合 **25 → 3** 帧 ✗✗；`10月2日.mp4` 同样 18 → 6 ✗）；而 `10月3日.mp4` 帧 64
        #   （84px ✓）是"**上一拍没有红框**（分离态 ⇒ 圆在**纯预测**）⇒ 忽然认一个融合框 ⇒ 圆
        #   **一步跳进框** ✗✗"（白线 85px 折角 ✓ = 用户点名的那一下 ✓）。⇒ 判据只判"**重新认框**"
        #   这一档 ✓（框一直在 ⇒ 直接放行 ✓ 行为与老口径一字不差 ✓）。
        if getattr(self, "_prev_tbox", None) is not None:
            return True
        _rp = self._report_pos(self._dt_last)
        if _rp is None:
            return True
        _cp = self._pos_in_tbox(_rp, box)
        if _cp is None:
            return True
        return bool(math.hypot(float(_cp[0]) - float(_rp[0]),
                               float(_cp[1]) - float(_rp[1])) <= _lim)

    def _allow_back_px(self):
        """第二条闸的容差换算成 **px**：**`「允许倒退距离(步数比例)」× 本拍该走多远`** ✓ ——
        ⭐⭐ **2026-10-03 已从"绿圆半径比例"改成 B 型（位移比例）**（用户原话："顺便把
        「允许倒退距离(绿圆半径比例)」也**改成 B**" ✓ 见 `_step_len_px` 的解释 ✓）：
        帧率 / 播放倍速不再影响判定 ✓（旧写法下倍速一开就漂 ✗ 用户点出 ✓）。

        ⚠ 基准拿不到（速度还没学出来 / dt 无效 ✓）⇒ 回 **`_BACK_FLOOR_PX`**（小下限 ✓ ——
          否则"基准 0 ⇒ 一点也不许退"会把静止段的候选全拦 ✗）；下限是**固定 px** ✓
          （不随帧率变 ✓ 只在"速度≈0"那几拍兜底 ✓）。
        """
        _st = self._step_len_px()
        if _st is None:
            return float(_BACK_FLOOR_PX)
        return max(float(_BACK_FLOOR_PX), float(self.allow_back_ratio) * float(_st))

    def _circle_rect_overlap_ratio(self, box):
        """`S` = 框 ∩ 绿圈外接矩形的**相交面积** ÷ **绿圈外接矩形面积**（用户 2026-10-02 ✓
        原话："**S = 相交的面积 / 绿圈外接矩形面积**" ✓）。

        ⚠ 分母是**绿圈外接矩形**（**不是**框面积 ✗ 用户点名 ✓）⇒ `S` 大 = "圆圈现在占的那块
          地方"被这格盖得实 ✓（阈值取 0 ⇒ 只要沾到就算 ✓）。
        ⚠ 半径还没学到（外接矩形面积 ≤ 0 ✓）⇒ 回 **1.0**（视为"盖满"⇒ 放行 ✓ —— 与
          `_circle_rect` / `_box_ahead_of_pred` 那两处"判不出就保守放行 ✓ 不猜 ✗"同一取舍 ✓）。
        """
        if box is None or self.pos is None:
            return 1.0
        _a = self._circle_rect_area()
        if _a <= 0.0:
            return 1.0
        _r = math.sqrt(_a) / 2.0
        _px, _py = float(self.pos[0]), float(self.pos[1])
        _bl = float(box[0]) - float(box[2]) / 2.0
        _br = float(box[0]) + float(box[2]) / 2.0
        _bt = float(box[1]) - float(box[3]) / 2.0
        _bb = float(box[1]) + float(box[3]) / 2.0
        _ix = max(0.0, min(_br, _px + _r) - max(_bl, _px - _r))
        _iy = max(0.0, min(_bb, _py + _r) - max(_bt, _py - _r))
        return float(_ix * _iy) / float(_a)

    def _hit_distance(self, box):
        """沿**白箭头**从圆心走到**进入**这格框的距离（≤0 = 圆心已在框内 / 已越过 ✓）。

        = 矩形在方向轴上的**支撑函数**（精确 ✓）：`t = (框心 − 圆心)·d̂ − (|w/2·d̂x| + |h/2·d̂y|)`；
        方向拿不到 ⇒ `None`（判不出 ⇒ 调用处不排序 / 全放行 ✓ 不猜 ✗）。
        """
        if box is None or self.pos is None:
            return None
        _vr = getattr(self, "_vel_rel", (0.0, 0.0)) or (0.0, 0.0)
        _n = math.hypot(float(_vr[0]), float(_vr[1]))
        if _n < 1e-6:
            return None
        _ux, _uy = float(_vr[0]) / _n, float(_vr[1]) / _n
        return float((float(box[0]) - float(self.pos[0])) * _ux
                     + (float(box[1]) - float(self.pos[1])) * _uy
                     - (abs(float(box[2]) / 2.0 * _ux) + abs(float(box[3]) / 2.0 * _uy)))

    def _hit_sorted(self, boxes):
        """把候选按"**沿白箭头依次接触**"的顺序排好（用户 2026-10-02 ✓ 原话："模拟将绿圆圈沿着
        白箭头的方向推进**依次接触**……" ✓）—— 判不出方向 ⇒ **保持原顺序** ✓（不猜 ✗）。

        ⚠ 排序键是**进入距离**（`_hit_distance` ✓），**只在"尚未越过"（t ≥ 0）的框之间**用它排 ✗
          —— 已越过的框（t < 0）排在**最后**（它们不可能是"沿方向推进先撞上的" ✓ 见
          `_first_hit_box` 里那次实测：负值会让"身后的框"反而排到最前 ✗✗）。
        """
        _lst = list(boxes or [])
        if not _lst:
            return []
        _ts = [self._hit_distance(b) for b in _lst]
        if all(_t is None for _t in _ts):
            return _lst
        _keys = []
        for _b, _t in zip(_lst, _ts):
            # ⚠ 三种情形分开 ✗（都踩过/想清楚了才写）：
            #   · **圆心已经在这框内** ⇒ 这就是"绿圈一推进就在其中"⇒ **最先接触** ✓ key = 0
            #     （不能按 `t`（负数）排 ✗ 那会把它垫到最后 ✓ 语义正好相反 ✗）；
            #   · 还没越过（`t ≥ 0`）⇒ 按 `t` 从小到大 ✓；
            #   · 其余（框整体在圆心**后方**、圆心又不在其中 ⇒ `t < 0`）⇒ **垫底** ✓
            #     （它不是"沿方向先撞上的" ✓ 见 `_first_hit_box` 那次实测 ✓）。
            _inside = bool(self.pos is not None
                           and float(_b[0]) - float(_b[2]) / 2.0 <= float(self.pos[0])
                           <= float(_b[0]) + float(_b[2]) / 2.0
                           and float(_b[1]) - float(_b[3]) / 2.0 <= float(self.pos[1])
                           <= float(_b[1]) + float(_b[3]) / 2.0)
            if _inside:
                _keys.append(0.0)
            elif _t is not None and _t >= 0.0:
                _keys.append(float(_t))
            else:
                _keys.append(1e18)
        return [b for _k, b in sorted(zip(_keys, _lst), key=lambda p: p[0])]

    def _iou_below_out(self, box, ref=None):
        """**迟滞·守**：本拍这格框与"它压着的那块砖"的 IoU 是否仍 **< 退出阈值**（松 ✓）？

        ⚠⚠ **当前【未接入】** ✗（2026-10-03 ✓ 保留为下一步的零件 ✓）：试过两处落点都不成 ——
        · 做在**进入判据**（`_is_merged_box`）：会话**更碎** ✗✗（10月2日 融合 23 → **1** 帧 ✗）；
        · 做在**保持分支**（"框不再包住砖"那一支 ✓）：**参数无效** ✗（`out` 取 0.5 与 0.75 结果
          逐项相同 ⇒ 那一支几乎不被走到 ✓）。
        ⇒ 真要做迟滞，得改"**保持期每拍凭什么继续**"（`_box_covers_entry` 那条尺 ✓）或"**选框那步
          凭什么换框**"✓ —— 属重新设计 ✓。函数留着（口径已写好 ✓ 方便接）。
        `ref` = 那块砖（保持期传 `_hold_ref()` ✓）；判不出 ⇒ `False`（保守 ✓ 不猜 ✗）。
        """
        if box is None:
            return False
        _ref = ref
        if _ref is None:
            _ref, _ = self._fake_ref(box)
        if _ref is None:
            return False
        return bool(geom.iou(box, (float(_ref.x), float(_ref.y), float(_ref.w), float(_ref.h)))
                    < float(getattr(self, "merge_iou_out", _MERGE_IOU_OUT)))

    def _ring_cov(self, box):
        """**「圆外接矩形与检出框相交的比例」**（用户 2026-10-03 ✓ 口径修订 ✓ 原话："将所有的
        『**检出框与圆外接矩形 IoU > ___ 时，与内砖 IoU < ___ 判定为融合**』改为『**圆外接矩形
        与检出框相交的比例 > ___ 时，检出框与内砖 IoU < ___ 判定为融合**』" ✓）。

        = **交集 ÷ 圆外接矩形面积**（**单向** ✓ = "**绿圈那一块地方有多少落在框里**" ✓
        见 `geom.cover_ratio` ✓）—— ⚠ **不是 IoU** ✗（旧口径的分母是**并集** ⇒ 框一变大就被摊薄
        ⇒ 天生偏小 ✗ 实测同一局面只有 `4r²/框面积 ≈ 0.35~0.5` ✗；**换分母后同一局面直接 1.0** ✓）。

        圆外接矩形 = **圆心 ± 半径**（`2r × 2r` 正方形 ✓ 与"融合判定③"当年用的那个框同一把 ✓）；
        半径拿不到（开局那几拍 ✓ `_rad = 0`）⇒ **放行**（回 `1.0` ⇒ 该条不拦 ✓ 保守 ✓ 不猜 ✗）。
        ⚠ **量级不同了**（务必知悉 ✗）：可用区从 0.3~0.4 抬到 **0.7~0.95** ✓（"绿圈那块地方七八
          成以上落在框里" ✓）—— 旧值 0.35 拿到新口径来配，等于"只要 35% 的绿圈落在框里"⇒
          **形同虚设** ✗ 见 `_RING_COV_SEP` ✓。
        """
        if box is None or self.pos is None:
            return 1.0
        _r = float(getattr(self, "_rad", 0.0) or 0.0)
        if _r <= 0.0:
            return 1.0
        # ⭐ **分母 = 圆的那个方块** ⇒ `cover_ratio(框, 圆矩形)` = 交 ÷ **圆矩形面积** ✓（单向 ✓）
        return float(geom.cover_ratio(box, (float(self.pos[0]), float(self.pos[1]),
                                           2.0 * _r, 2.0 * _r)))

    def _brick_iou_thr(self):
        """本拍"框↔内砖 IoU"的**上界阈值**（用户 2026-10-03 ✓ 参数分档 ✓）：

        · **分离期**（不在融合保持里）⇒ `brick_iou_sep`（**严** ✓ 不容易进融合 ✓）；
        · **融合期**（已在保持里）⇒ `brick_iou_fuse`（**松** ✓ 不容易掉出 ✓）。

        ⇒ 两者之差 = **迟滞** ✓（"进严守松" ✓ 治"参数太松放大错误 / 太严没指导值" ✓）。
        ⚠ 第 1 行那个「同检出 IoU」（`self.merge_iou`）**仍管别的用途** ✓（"这格是不是砖自己那一格"
        ⇒ `_brick_owned` ✓ 以及下面的兜底 ✓）—— 两者**不冲突** ✓（一个管"进不进的来"、一个管
        "是不是同一格" ✓）。
        """
        if bool(getattr(self, "_merge_hold", False)):
            return float(getattr(self, "brick_iou_fuse", _BRICK_IOU_FUSE))
        return float(getattr(self, "brick_iou_sep", _BRICK_IOU_SEP))

    def _ring_cov_thr(self):
        """本拍"圆外接矩形与检出框相交的比例"的**下界阈值**（用户 2026-10-03 ✓ 参数分档第 2/3 行 ✓）：
        分离期用 `ring_cov_sep` ✓、融合期用 `ring_cov_fuse` ✓（默认同值 ⇒ 行为一致 ✓）。"""
        if bool(getattr(self, "_merge_hold", False)):
            return float(getattr(self, "ring_cov_fuse", _RING_COV_FUSE))
        return float(getattr(self, "ring_cov_sep", _RING_COV_SEP))

    def _brick_iou_now(self, box, ref=None):
        """`IoU(检出框, 它压着的那块砖)`（保持期传 `ref` 省一次查找 ✓）；判不出 ⇒ `0.0` ✓。"""
        if box is None:
            return 0.0
        _ref = ref
        if _ref is None:
            _ref, _ = self._fake_ref(box)
        if _ref is None:
            return 0.0
        return float(geom.iou(box, (float(_ref.x), float(_ref.y),
                                    float(_ref.w), float(_ref.h))))

    def _merge_should_exit(self, box):
        """**融合期退出判据**（用户 2026-10-03 ✓ 第 3 行 ✓ 原话："……**否则就算分离**" ✓）。

        = `（圆外接矩形 ∩ 框）÷ 圆外接矩形面积 > ring_cov_fuse` **且** `IoU(框, 内砖) < brick_iou_fuse`
        ⇒ **继续融合**（回 `False` ✓）；否则 ⇒ **该分离**（回 `True` ✓）。

        ⚠⚠ 与"融合期**进入/保持**"用的是**同一句口径、同一对参数** ✓（用户第 3 行就一句话 ✓）——
          这正是**迟滞的正确落点** ✓：`brick_iou_sep = 0.5`（进严 ✓）、`brick_iou_fuse = 0.7`
          （守松 ✓）。
        ⚠ **想临时关掉这条** ⇒ 把 `brick_iou_fuse` 设成 **1.0**（`IoU < 1.0` 几乎恒成立 ⇒
          永不退出 ✓ = 回到"靠框还包住砖维持"的老行为 ✓）✓ 不需要改代码 ✓。
        """
        if box is None:
            return False
        _ring_ok = bool(self._ring_cov(box) > float(getattr(self, "ring_cov_fuse",
                                                            _RING_COV_FUSE)))
        _brick_ok = bool(self._brick_iou_now(box, self._hold_ref())
                         < float(getattr(self, "brick_iou_fuse", _BRICK_IOU_FUSE)))
        return not (_ring_ok and _brick_ok)

    def _is_tangent_fix(self, box):
        """本拍的落位点是不是**「相切点」**（= 归**真目标**的那条边与圆**相切** ✓）？

        ⭐⭐⭐ 用户 2026-10-03 ✓ 原话："**做①**" ✓ —— 选项① = "**相切豁免闸**：归真目标的边
        与圆相切 ⇒ 不参与『融合框挑选允许倒退距离』闸" ✓。

        判据与 `_merge_edge_own` **同一处** ✓（那里是 `if own[0] != own[1]` / `if own[2] !=
        own[3]` ⇒ "某轴恰有一条真边 ⇒ 该轴按相切定坐标" ✓）：`own[i] = True` ⇒ 第 i 条边
        **归砖**（L,R,T,B ✓ 见 `_edge_ownership` ✓）⇒ 只要**某一轴恰有一条真边** ⇒ 就是相切落位 ✓。
        ⚠ 自动排除掉那些**不是相切**的档 ✓：`n=0`/`n=4`（全真/全砖 ⇒ 两轴都相等 ✓）与
        "两条假边**正对面**"（L+R 或 T+B ⇒ 该轴两条都 True ✓）—— 那几种 `_merge_edge_own`
        本来就返回 `None`（不落位 ✓）⇒ 这里回 `False` 正合适 ✓。
        """
        if box is None:
            return False
        try:
            _own = self._edge_ownership(tuple(float(v) for v in box[:4]))
        except Exception:
            return False
        if _own is None:
            return False
        return bool(_own[0] != _own[1] or _own[2] != _own[3])

    def _merge_fix_safe(self, box, allow_tangent=True):
        """⭐⭐⭐ **这个框当融合框时，圆心**不会**往白箭头反方向走吗**（用户 2026-10-02 ✓ 原话：
        "……依次接触，**第一个在融合后绿圈圆心不会往白箭头反方向行进的框**" ✓）—— 融合框候选
        第二条闸的**安全性判据** ✓（方案 B ✓ 见汇报：只模拟**落位**那一支 ✓ 零复刻 ✓）。

        理由（融合期位置只有这几条来路 ✓）：**预测滑行天然顺向** ✓；**夹取在融合期不做** ✓
        （除首拍 `_merge_first` ✓）；所以唯一会**把圆拽向反方向**的就是**落位**
        （`_merge_edge_own` 把圆挪到框的某个角/中心 ✗）⇒ 只用它判就够 ✓。

        判据：
          · 不落位（`_merge_edge_own` 回 `None` ✓）⇒ 位置按预测滑行走 ⇒ **安全** ✓；
          · 落位 ⇒ **先看方向**：落位位移与白箭头夹角 ≤ 90°（= 前方半球 ✓）⇒ **不限制** ✓；
            **落在后方 180° 扇形内**（夹角 > 90° ✓ 即 `_proj < 0` ✓）⇒ 再看**长度**：
            `|落位位移| ≤ 「允许倒退距离(步数比例)」× **「本拍该走多远」**` 才放行 ✓
            ⚠⚠ 那把尺是 **`_step_len_px` = `|白箭头| × dt`** ✗✗ —— **不是绿圈半径** ✓
            （用户 2026-10-03 ✓ 原话："**顺便把「允许倒退距离(绿圆半径比例)」也改成 B**" ✓
            理由：半径比例那种写法会**随播放倍速漂** ✗ 而 B 型"偏差 ÷ 本拍位移"恒定 ✓）——
            实测（`10月1日.mp4` 显示 22 帧）：基准 **21.1px**、要挡的位移 **34.0px**
            ⇒ **本项要到 `1.61` 才过** ✓（用户设 1.0 时"以为够了却还是过不了"✓ 差的就是它 ✓）。
            （用户 2026-10-03 ✓ 原话："……改成 **后方 180 度扇形内的任意方向都限制**
            （而**不只是向后的分量**）" ✓ —— 旧版只比沿白箭头的**分量**✗ ⇒ 侧向的逆动不设限 ✗）；
            默认 0 = 一点也不许倒退 ✓ 见 `allow_back_ratio` + `_allow_back_px` ✓；
          · 白箭头 ≈ 0 / 圆心拿不到 ⇒ **安全**（判不出 ⇒ 放行 ✓ 不猜 ✗ 与其它判据同一取舍 ✓）。

        ⚠ `_merge_edge_own` 是**纯读**的（只看 `box` / `_pos_prev` / `_merge_first` / 登记表 ✓
          不写任何状态 ✓）⇒ 在这里当"模拟"用是安全的 ✓。
        """
        if box is None or self.pos is None:
            return True
        # ⭐⭐⭐ **「相切落位」豁免这道闸**（用户 2026-10-03 ✓ 原话："**做①**" ✓ —— 选项① =
        #   "**相切豁免闸**：归真目标的边与圆相切 ⇒ 不参与倒退闸" ✓）：
        #   · **为什么该豁免**（两条口径的**动机不同** ✓）：这道闸要治的是"**圆被融合框 / 并集
        #     中心拽着逆着白箭头跑**"✗（那种落位点 = "框的几何中心"之类、**不带『目标在哪』的
        #     信息** ✓）；而"**归真目标的边与圆相切**"是**信念几何的正确位置**（用户原话："这种
        #     情况的正确做法是保证归属（真目标）的边与圆**相切**" ✓）⇒ 它本来**就该在那** ✓
        #     不是被拽 ✗；
        #   · 实测（`10月2日.mp4` 帧 43 ✓ 用户问的那一拍）：框 (200.7,164.1) 251×173、边归属
        #     `[左砖, 右真, 上砖, 下砖]` ⇒ 相切点 = **(251.3,175.6)** ✓；可白箭头 (29,−154) ⇒
        #     位移 (69.3,+20.6) 落进**后方 180° 扇形**（分量 −7.4）⇒ 按长度 72.3 > 允许 8.0
        #     ⇒ **被否** ✗ ⇒ 圆心停在 (178.1,175.6)、**离该贴的那条边差 73.3px** ✗（= 用户问的 ✓）；
        #   · ⚠ **代价**（用户已知并要 ✓）：这一拍圆会**向右挪 ~69px** ⇒ 白线一个折角 ✗ ——
        #     与"宁可圆不贴边、白线平滑"正相反 ✓ 这是"相切口径优先"的必然结果 ✓。
        #   ⇒ 相切落位**直接放行** ✓；其余落位照旧按老口径判 ✓（一个字不改 ✓）。
        #   ⭐⭐⭐ **但"相切豁免"只管"落位采纳"这一个用途** ✗✗（用户 2026-10-03 ✓ 原话：
        #     "**A. 恢复 `_hover`：相切豁免只用于『落位采纳』，倒退判据仍按老口径算**" ✓）：
        #     · `allow_tangent=True`（**默认** ✓ 调用点 = `process()` 出口"要不要落位" ✓）
        #       ⇒ 相切落位**照旧豁免** ✓（"这种落位本来就该在那" ✓）；
        #     · `allow_tangent=False`（调用点 = **分离判定的 `_hover`** ✓）⇒ **按老口径算** ✓
        #       （相切落位照样比"后方扇形 + 位移长度 vs 允许量"✓）—— 否则 `_merge_edge_own`
        #       五档里"能给出落位点的全是相切"⇒ `_hover` **恒 False** ✗✗ ⇒ "落点倒退超限 ⇒
        #       判分离"这条**整个失效** ✗（实测 `10月1日.mp4` 帧 62 就是：缩框 + 落点倒退，
        #       却因为豁免而判不出 ✓ 用户问"缩框了，为何没分离" ✓）。
        if allow_tangent and self._is_tangent_fix(box):
            return True
        # ⭐⭐⭐ **基准 = 「上拍圆心 + 上拍白箭头 × dt」**（用户 2026-10-03 ✓ 原话澄清："我的流程图里
        #   写的原话是『**对比上一拍的白箭头预测位置**』意思是**假设本拍按上拍预测走了之后**的本拍
        #   白箭头（因为不一定按上一拍预测走，所以是『假设』拿来判定用的）" ✓）：
        #   · 原来用的是"**当刻** `self.pos`" ✗ —— 那个点已经被这一拍的各种更新（观测 / 夹取 /
        #     滑行 / 落位 ✓）挪过了 ⇒ 量出来的位移**不是**用户口径要的那个 ✗：实测 `10月2日.mp4`
        #     帧 37，当刻圆心 (250.9,226.2) ⇒ 位移只 **56.2px** ✗；而按"上拍预测位置"
        #     (145.8,246.7) ⇒ **162.5px** ✓ —— 后者才是"这一步到底偏了多少"的全貌 ✓；
        #   · 拿不到上拍圆心 / 上拍白箭头 / dt（第 0 拍 ✓）⇒ 退回 `self.pos` ✓（不猜 ✗）。
        _base = (float(self.pos[0]), float(self.pos[1]))
        _rp = getattr(self, "_report_prev", None)
        _vp = getattr(self, "_vel_rel_prev", None)
        _dtb = float(getattr(self, "_dt_last", 0.0) or 0.0)
        if _rp is not None and _vp is not None and _dtb > 0.0:
            _base = (float(_rp[0]) + float(_vp[0]) * _dtb,
                     float(_rp[1]) + float(_vp[1]) * _dtb)
        _vr = getattr(self, "_vel_rel", (0.0, 0.0)) or (0.0, 0.0)
        _n = math.hypot(float(_vr[0]), float(_vr[1]))
        if _n < 1e-6:
            return True
        _p = self._merge_edge_own(tuple(float(v) for v in box[:4]), at=_base)
        if _p is None:
            # ⭐⭐⭐ **拿不到落位点 ⇒ 放行**（用户 2026-10-03 ✓ 原话："**拿不到点按白箭头预测走
            #   下一步『倒退距离』的判断**" ✓ = 这一拍不落位、圆按白箭头预测走、**下一拍再判** ✓）：
            #   · 什么时候拿不到（"五档退化" ✓ 见 `_merge_edge_own`）：0 条边归砖 ✓／两条砖边
            #     **正对面**（左+右 或 上+下 ✓）／四条边全归砖 ✓；
            #   · ⚠ 同日早先那版"没有落位点就改判『当选后被信念夹取会拽到哪』"**已撤** ✗
            #     （用户明说：拿不到点 ⇒ 按预测走、下一步再判 ✓ 不拿它判分离 ✓）。
            return True
        # ⚠⚠⚠ **位移必须用同一个基准 `_base`** ✗✗（2026-10-03 ✓ 查实的漏洞 ✓）：原来这里写的是
        #   `_p − self.pos`（**当刻圆心** ✗）⇒ 而落位点 `_p` 是按 `_base`（上拍预测位置 ✓）算的
        #   ⇒ **同一个函数里混用两个基准** ✗✗ ⇒ 判据量出来的"位移"根本不是用户口径要的那个 ✓
        #   （实测 `10月1日.mp4` 帧 37：按 `_base` 算是 **117.8px、逆向分量 −91** ✗ 该拦 ✓；
        #    按 `self.pos` 算却很小 ⇒ **放行** ✗ = 用户问"这一步为什么没被倒退限制拦住" ✓）。
        _dx = float(_p[0]) - float(_base[0])
        _dy = float(_p[1]) - float(_base[1])
        # ⭐ 判据 = 落位位移**在白箭头方向上的分量**（px ✓ 点积除以 |v| ✓）≥ **−允许倒退距离**
        #   （用户 2026-10-02 ✓ 原话："做个配置吧『融合框挑选允许倒退距离(px)』" ✓；
        #   ⭐ 同日口径修订 ✓："『融合框挑选允许倒退距离(px)』改为『**融合框挑选允许倒退距离
        #   (绿圆半径比例)**』" ✓ ⇒ 容差 = 比例 × **绿圈半径** ✓ 见 `_allow_back_px` ✓）：
        #   · 0（默认）⇒ 等价于上一版的 `点积 ≥ 0`（一点不许倒退 ✓ 行为不变 ✓）；
        #   · 调大 ⇒ 允许落位把圆往反方向拽"这么多倍半径"以内 ✓ ⇒ 候选变多 ✓。
        _proj = (_dx * float(_vr[0]) + _dy * float(_vr[1])) / _n
        if _proj >= 0.0:
            return True                      # 前方半球（含正侧向）⇒ 不限制 ✓
        # ⭐⭐⭐ **后方 180° 扇形内 ⇒ 按"位移长度"限制**（用户 2026-10-03 ✓ 原话："『融合框挑选
        #   允许倒退距离』的具体逻辑改成 **后方 180 度扇形内的任意方向都限制**（而不只是向后的
        #   分量）" ✓）：
        #   · 判据分两段：**方向**决定"算不算往后"（与白箭头夹角 > 90° ⇒ 后方扇形 ✓ 就是
        #     `_proj < 0` ✓）；**长度**决定"超没超限"（`|位移|` vs 允许量 ✓）；
        #   · ⚠ 旧版只拿**沿白箭头的分量**比（`_proj ≥ −允许量` ✓）⇒ 侧向的逆动完全不设限 ✗
        #     （例：白箭头朝右、落位往"左上 45°"退 30px ⇒ 分量只有 −21，旧版会放行 ✓ 但它
        #      实际退了 42px ✗）；新版按长度 ⇒ 该例 42 > 30 ⇒ **拦下** ✓（更保守 ✓）。
        return bool(math.hypot(_dx, _dy) <= self._allow_back_px())

    def _first_hit_box(self, boxes):
        """沿**白箭头方向**推进绿圈 ⇒ **第一个接触到的框**（用户 2026-10-02 ✓ 原话："模拟将绿
        圆圈沿着白箭头的方向**推进第一个接触的框**" ✓）⇒ 返回它的 `(cx, cy)`（判不出 ⇒ `None`）。

        算法 = 矩形在方向轴上的**支撑函数**（精确 ✓ 一次遍历 ✓）：
            `t = (框心 − 圆心)·d̂ − (|w/2 · d̂x| + |h/2 · d̂y|)`
        `t` = 从圆心沿 `d̂` 要走多远才**进入**该框（≤ 0 = 圆心已经在该框内 / 已越过 ✓）；
        取 `t` **最小**者 = "第一个接触的框" ✓（并列 ⇒ 先遍历到的那个 ✓）。

        ⚠ 白箭头速度 ≈ 0（还没学出方向 ✓）⇒ `None` ⇒ 调用处**放行全部融合候选** ✓
          （判不出 ⇒ 不猜 ✗，与 `_box_ahead_of_pred` 同一取舍 ✓）。
        """
        if not boxes or self.pos is None:
            return None
        _vr = getattr(self, "_vel_rel", (0.0, 0.0)) or (0.0, 0.0)
        _n = math.hypot(float(_vr[0]), float(_vr[1]))
        if _n < 1e-6:
            return None
        # ⚠ 全部按"进入距离"排序后取第一个（**还没越过的**排在前 ✓ 已越过的垫底 ✓ —— 实测踩过：
        #   后方框的投影是负数，直接取最小会把"身后的框"当成第一个撞上的 ✗✗；这条口径统一在
        #   `_hit_sorted` 里 ✓ 不在这里再写一遍 ✗）。
        _order = self._hit_sorted(boxes)
        return None if not _order else (float(_order[0][0]), float(_order[0][1]))

    def _box_like_target(self, box):
        """这格框的面积像不像"**一个目标**"（`0.8 ~ 1.3 × 当拍检出中位` ✓ 用户 2026-10-01 Q8 ✓）。

        给**半径学习**当门 ✓：邻砖的框、并集刚回缩的框（面积明显偏离单个目标 ✓）**不许**拿来
        更新绿圈半径 ✗（否则半径虚大 ⇒ 圆装不进框 ✗ 实测 70 → 87.3 ✗✗）。与演示窗量半径的
        门同一套数值 ✓。中位还没量到 ⇒ `False`（不学 ✓ 保守 ✓）。
        """
        _tp = float(self._typ_area or 0.0)
        if _tp <= 0.0 or box is None:
            return False
        _a = float(box[2]) * float(box[3])
        return bool(0.8 * _tp <= _a <= 1.3 * _tp)

    def _target_box_state(self, dets, ev):
        """目标"踩着"的那格框 ⇒ `(状态, 框)` —— **S0~S3 的判据**（用户事实 4~7 ✓）。

        · `"ok"`     面积 ≈ 标准 ⇒ 目标独自占一格 ✓（事实 1 ✓）；
        · `"merged"` 面积 > 标准 × `_MERGE_RATIO` ⇒ **并集块**（事实 5 ✓）⇒ 位置照残差走、
                     **速度冻结**（事实 6："不用更新轨迹预测" ✓ 别把并集中点当观测 ✗）；
        · `"gone"`   门内没有框 ⇒ ① 上一拍是 merged ⇒ **S2 刚分离**（事实 7 ✓ ⇒ 用**新框的
                     边界**夹住滑行位置 ✓）；② 否则 ⇒ **S3 yolo 漏检**（事实 4 ✓）⇒ 按上一次
                     速度滑行、**不重置速度** ✓。
        选框：**包含报告位置优先** ✓、否则门内最近 ✓（并集块也照选 ⇒ 状态才判得出来 ✓）。
        """
        self._tbox_role = ""                    # ⭐ 本拍选中那格的身份（按**最终判定**给值 ✓ 先复位 ✓）
        # ⭐⭐⭐ **本拍开始时"上一拍是不是已在融合"**（用户 2026-10-03 ✓ 流程图："**融合第二拍**
        #   开始每拍判定" ✓）：进门那一拍它还是 `False`（保持态是**这一拍**才置上的 ✓）⇒ 用它实现
        #   "**首拍不判倒退**" ✓。⚠ 必须先在开头存一份 ✗ —— `_merge_hold` 在本函数里会被改 ✓
        #   （静默出融合 / 判分离都会 `= False` ✓）。
        _hold0 = bool(getattr(self, "_merge_hold", False))
        if not dets or self.pos is None:
            # ⭐ **融合框消失（分离）日志**（用户 2026-10-02 ✓）：这一帧压根没有可用检测框
            #   ⇒ 只在"上一拍还在融合 / 保持中"时算分离 ✓（建档 / 从没框 ⇒ 不冒充分离 ✗）。
            if bool(getattr(self, "_was_merged", False)) or self._merge_hold:
                self._split_why = self._split_diag(None, self._hold_ref(), "检出框丢了")
            return ("gone", None)
        px, py = self.pos
        # ⭐⭐⭐ 这一拍"**沿白箭头推进第一个接触到的框**"（用户 2026-10-02 ✓ 闸的第二条 ✓）——
        #   循环里要拿每一格跟它比对 ⇒ 在**循环之前**算一次 ✓（判不出方向 ⇒ `None` ⇒ 全部放行 ✓）。
        #   ⚠⚠ **只在"融合框候选"之间比** ✗✗：用户的口径是"**融合框候选** = S > 阈值 **且**
        #     （推进第一个接触的框）" ✓ —— "第一个接触"是用来**在融合框里挑最靠前那个**的 ✓，
        #     不是"全场所有检出框里最先撞上的那一个" ✗（A/B 实测踩过：目标前方常有一格**自己
        #     那格的小框**✓ 它必然比身后的并集框"更先被撞到" ✗ ⇒ 并集框全被挤掉 ⇒ `9月30日(1)`
        #     整段**融合生成 0 次** ✗✗ 与预期完全相反 ✓）。
        # ⭐⭐⭐ **融合会话的「续任优先」**（用户 2026-10-03 ✓ 方案 ② ✓ 原话："融合框被替换了检出
        #   框，有什么方法能够判定并屏蔽掉这种现象吗" ✓）—— 融合**保持期内**，先找"上一拍那个
        #   融合框在这一拍的**延续格**"（= 与上一拍红框重叠最大的门内格 ✓ 见 `_box_overlap_min` ✓）：
        #   · 延续格**命中分离信号**（框缩成砖 / 不再包住参照砖 ✓）⇒ **这一拍判分离** ✓
        #     ⇒ `gone`（按上一拍预测滑 ✓）+ 保持作废 ✓ ⇒ **绝不接任"另一块砖"的融合框** ✗✗；
        #   · 延续格仍够格 ⇒ **这一拍只许用它**（下面把别的格全过滤掉 ✓）⇒ 不会被抢走 ✗
        #     （"续任"而不是"重挑" ⇒ 融合段不会被一次检测抖动打断 ✓）。
        #   ⚠ 只在**保持期内**做（`_merge_hold` ✓）⇒ 会话结束后照旧自由挑 ✓（不阻新会话 ✓）。
        #   ⚠⚠ 实测为什么需要它 ✗（`9月30日(1).mp4` 帧 44→45）：帧 44 的红框 `(240.8,157.0)`
        #     延续到帧 45 就是格 `(219.6,155.1)`（重叠 **0.86** ✓ 贴的还是同一块砖 `(327,104)` ✓），
        #     但它这一拍**已缩成砖**（`_box_is_brick_det` ✓ = 分离信号 ✓）⇒ 旧代码里它走不到
        #     "保持分支"（`_mg` 由 `_is_merged_box` 规则① 给 ⇒ 走"进门"分支 ✗）；而同一拍另一格
        #     `(289.3,248.7)`（贴**另一块砖** `(560,81)`、与帧 44 红框只重叠 0.31）因为
        #     `_hit_sorted` 里两格的**排序键并列**（两格圆心都在框内 ⇒ 键都是 0.0 ✓ ⇒ 由**检测框
        #     先后顺序**定胜负 ✓）抢到了 `_first_ok` ⇒ 融合框换对象、参照砖跟着换 ✗✗ = 用户点名 ✓。
        _succ = None
        if self._merge_hold and self._prev_tbox is not None:
            _pb = tuple(float(v) for v in self._prev_tbox[:4])
            _sov, _sbox = 0.0, None
            for b in dets:
                _b4 = tuple(float(v) for v in b[:4])
                if math.hypot(_b4[0] - px, _b4[1] - py) > _DET_GATE:
                    continue                       # 门外的格不算"延续" ✓
                _o = self._box_iou(_b4, _pb)      # ⭐ IoU（用户 2026-10-03 ✓ 见 `_box_iou` ✓）
                if _o > _sov:
                    _sov, _sbox = _o, _b4
            if _sbox is not None and _sov >= _SWAP_OV:
                # ⚠⚠ **这里原来会判分离**（延续格"缩成砖 / 不再包住参照砖"⇒ 置 `_split_now` ✗）——
                #   **已删**（用户 2026-10-03 ✓ 原话："**只留『框丢了』，其余删**" ✓）：延续格照旧
                #   用 ✓、不再因它判分离 ✓（"框不再包住参照砖"改到下面保持分支里**静默出融合** ✓
                #   不报分离 ✓）。⇒ 分离现在只剩两条路：**框丢了** ✓ ／ **落点倒退超限** ✓。
                _succ = _sbox
        _mg_cand = [b for b in dets
                    if self._is_merged_box(tuple(float(v) for v in b[:4]))
                    or self._hold_active(tuple(float(v) for v in b[:4]))]
        # ⭐ 续任期内：融合候选**只留延续格** ✗✗（否则 `_first_ok` 可能被别的格抢走 ⇒ 换对象 ✗）
        if _succ is not None:
            _mg_cand = [b for b in _mg_cand
                        if abs(float(b[0]) - _succ[0]) < 1e-6
                        and abs(float(b[1]) - _succ[1]) < 1e-6]
        # ⭐⭐⭐ **依次接触 + 取第一个"安全"的**（用户 2026-10-02 ✓ **三次定稿** ✓ 原话：
        #   "……（模拟将绿圆圈沿着白箭头的方向推进**依次接触**，第一个**在融合后绿圈圆心
        #   不会往白箭头反方向行进**的框）" ✓；判据 = 方案 B ✓ 见 `_merge_fix_safe` ✓）：
        #   · 顺序 = 沿白箭头的**进入距离**从小到大（`_hit_sorted` ✓ 判不出方向 ⇒ 原顺序 ✓）；
        #   · 逐个试：**距离闸过**（`_inherit_dist_ok` ✓ 用户 2026-10-02 新口径 ✓）✓ 且
        #     **落位不会把圆拽向反方向**（`_merge_fix_safe` ✓）✓ ⇒ 取**第一个**两者都过的 ✓；
        #   · 候选非空、却**一个都不安全** ⇒ `_first_ok` 留 `None` ⇒ 下面那道闸会把**所有**
        #     融合候选挡掉 ⇒ 落到「门内没有能挑的格」⇒ 判分离 ✓（= "宁可不融合"的取舍 ✓）。
        #   ⚠ 首拍（`_merge_first`）**不做特殊处理**（同一判据 ✓）；那一拍落位走"就近内接"
        #     分支 ⇒ `_merge_edge_own` 照样会给点、同一把尺照样判 ✓ 若将来要单独照顾首拍的
        #     "漂移纠正速度"再在这里加一条 ✓。
        _first_ok = None
        _skip_why = None                             # ⭐ 记"第一个被筛掉的原因"（给分离日志用 ✓）
        _skip_box = None                             # ⭐ 被筛掉的那个框（内砖不同那条 ✓）
        for _b in self._hit_sorted(_mg_cand):
            _b4 = tuple(float(v) for v in _b[:4])
            # ⭐⭐⭐ **「分离前（含分离当拍）不许把内砖不同的框当融合框」**（用户 2026-10-03 ✓ 原话：
            #   "是否有这样的规则：『**分离前（包括分离当拍）不允许将内砖不同的检出框当做融合框**』，
            #   如果没有就加上" ✓）：保持期内**一次会话只认同一块砖** ✓ —— 这格框认的内砖
            #   （覆盖率最大的那块 ✓ `_covered_ref` ✓）必须 = 本次会话的参照砖（`_merge_hold_bid` ✓）
            #   ⇒ 否则**不许当选** ✓（全部候选都因此被筛 ⇒ 落到「门内没有能挑的格」⇒ **判分离** ✓
            #   = "那块砖的合体结束了" ✓）。⚠ 非保持期一律放行 ✓（新会话自由挑 ✓）见 `_same_inner_brick` ✓。
            #   （几何上的"续任优先" `_succ` 仍在上面 ✓ —— 这条补的是"没找到延续格"时的漏洞 ✗：
            #    那时保持期能自由挑 ⇒ 可能标到**另一块砖**的并集上 ✗✗。）
            if not self._same_inner_brick(_b4):
                _skip_why = "内砖与参照砖不同"
                if _skip_box is None:
                    _skip_box = _b4               # ⭐ 记下被筛的框（分离日志用它算覆盖率 ✓）
                continue
            # ⭐⭐⭐ **「融合框挑选允许倒退距离」= 框能否当红框的「前置条件」**（用户 2026-10-03 ✓
            #   原话："**有点本末倒置了，那个框被判为红框的前置条件就应该有这个判断**" ✓）：
            #   ⇒ 在这里做"**候选框过不了就整个淘汰**" ✓（恢复 2026-10-02 那版的位置 ✓；同日
            #   早先把它挪到"落位那一刻"是**本末倒置** ✗ = 用户点名 ✓）。
            #   · `_merge_fix_safe` 现在**不管有没有落位点都判** ✓（用户同日："不管有没有
            #     落位点都要判啊" ✓ 见它 ✓：无落位点 ⇒ 判"当选后**信念夹取**会把圆拽到哪" ✓）；
            #   · 逐个试的**顺序**照旧 = 沿白箭头"依次接触"（`_hit_sorted` ✓）⇒ 取第一个
            #     两条闸都过的 ✓；**候选非空却一个都不过** ⇒ `_first_ok` 留 `None` ⇒ 下面
            #     那道重合闸把**所有**融合候选挡掉 ⇒ 落到「门内没有能挑的格」⇒ **判分离** ✓
            #     ⚠ 代价（用户已明确要）：唯一的融合框也可能被淘汰 ⇒ 红框消失走预测态 ✓
            #     （实测 `10月1日.mp4` 帧 54 就是这种形态 ✓ —— 之前正因此把它挪到落位处，
            #      本日按用户口径挪回来 ✓："**宁可没有红框，也不许圆被框拽着倒退**" ✓）。
            # ⚠⚠ **「允许倒退距离」已从这里撤掉**（用户 2026-10-03 ✓ 原话："照着我的逻辑**简化
            #   分离判定**" ✓ 流程图里候选框**不过**这条闸 ⇒ "倒退"改到**融合期每拍**判 ✓
            #   见下面保持分支里那一段 ✓）：选框只留「内砖同一性」（用户："留着，只当选框门槛" ✓
            #   在循环开头已判 ✓）＋「继承距离」（照旧被 `_INHERIT_DIST_ON` 屏蔽 ✓ 留着便于回退 ✓）。
            # ⭐⭐⭐ **「选框速度门」**（用户 2026-10-03 ✓ 原话："选这个融合框后**明显会超过白箭头
            #   限速，不应该选，判断了吗？没有的话应该加上**" ✓ 见 `_select_vel_px` /
            #   `_select_vel_ok` ✓）：上面那些管的是"**框合不合规**" ✓，本条管"**认了它，圆这一步
            #   走不走得到**" ✗ —— 实测 `10月3日.mp4` 帧 64：那格融合框覆盖率 89% ✓ 面积比 1.227 ✓
            #   （都过 ✓）按老口径就当融合框 ✓，但认了它 ⇒ 圆要**一步挪 96.5px**（= **726 px/s** ✗
            #   白箭头限速只有 400 ✓）⇒ 白线一个 **85px** 的折角 ✗✗（用户看图点出 ✓）。
            #   ⇒ 超限 ⇒ **这格不算"安全框"** ✓（`_first_ok` 不给它 ⇒ 下面那道"必须与安全框
            #     重合"的闸自然把它挡掉 ✓ = 用户口径"**不应该选**" ✓）；候选全被挡 ⇒ 落到
            #     「门内没有能挑的格」⇒ 判分离 ✓（= "宁可没有红框，也不许圆被框拽着走" ✓）。
            #   ⚠ 这是**补位**：既有的「选框距离门」只作用在"**非融合**红框"那一档 ✗ ⇒ 融合框
            #     那档原来**没有距离 / 速度门** ✗（用户问的正是它 ✓）；门限由**速度**（px/s ✓）
            #     换算 ⇒ **帧率 / 播放倍速无关** ✓。
            if not self._select_vel_ok(_b4):
                _skip_why = "认它需要的速度超过白箭头限速（选框速度门）"
                if _skip_box is None:
                    _skip_box = _b4
                continue
            if self._inherit_dist_ok(_b4):
                _first_ok = (float(_b[0]), float(_b[1]))
                break
        best, bs = None, None
        for b in dets:
            cx, cy, w, h = (float(b[0]), float(b[1]), float(b[2]), float(b[3]))
            # ⭐ **续任期内只许用延续格**（用户 2026-10-03 ✓ 方案 ② ✓ 见上面那段注释 ✓）
            if (_succ is not None
                    and not (abs(cx - _succ[0]) < 1e-6 and abs(cy - _succ[1]) < 1e-6)):
                continue
            d = math.hypot(cx - px, cy - py)
            if d > _DET_GATE:
                continue
            inside = (cx - w / 2 <= px <= cx + w / 2 and cy - h / 2 <= py <= cy + h / 2)
            _mg = self._is_merged_box((cx, cy, w, h))
            _hit = self._circle_hits((cx, cy, w, h))
            # ⭐ **预测方向上的"近"**（用户 2026-10-02 ✓ 帧 22 定稿 ✓："当有多个**未登记检出框**
            #   与绿圈相交时，**优先选择预测方向上更近的**" ✓）：分数 = 框中心到**预测落点**
            #   （pos + 白箭头速度 × dt ✓）的距离 —— 速度给不出（`_dt_last` 没有就是 0 ✓）时
            #   预测点 = pos ⇒ 退化为老的"离圆心近" ✓ 同一把尺 ✓。
            _dt6 = float(getattr(self, "_dt_last", 0.0) or 0.0)
            _pxp = px + float(self._vel_rel[0]) * _dt6
            _pyp = py + float(self._vel_rel[1]) * _dt6
            d_pred = math.hypot(cx - _pxp, cy - _pyp)
            _own = self._brick_owned((cx, cy, w, h))
            # ⭐ **融合保持也算"融合框"**（用户 2026-10-02 ✓）：保持期框在变小、规则①②
            #   已不再生效 ✗ ⇒ 选框优先级也要认它 ✓（否则缩小的融合框被 `_brick_owned`
            #   压到"基本不选"档 ✗ 融合跟踪就断了 ✗）。
            _mg = bool(_mg or self._hold_active((cx, cy, w, h)))
            # ⭐⭐⭐ **融合框（含融合保持）的两条筛选闸 —— 2026-10-02 三次定稿**（用户原话：
            #   首版："**融合框候选 = 与绿圈外接矩形相交面积比例 > S 且（模拟将绿圆圈沿着白
            #   箭头的方向推进第一个接触的框）**" ✓、"**S = 相交的面积 / 绿圈外接矩形面积**" ✓；
            #   ⭐ 同日口径修订 ✓："『S = 框∩绿圈外接矩形 ÷ 绿圈外接矩形 >「融合框继承面积
            #   限制」』改为『**绿圈圆心到框最近一条边的垂直距离(绿圆半径比例) > 「融合框继承
            #   距离限制」**』" ✓）：
            #   ① **距离闸**（`_inherit_dist_ok` ✓）：`圆心到框最近边的有符号垂距 ÷ 绿圈半径
            #      > inherit_dist` —— 要求圆心落在框内（阈值 0 ✓）且离最近那条边足够远 ✓
            #      （**取代**老那条面积比 S ✗：S 是"面积"口径、与框的尺寸耦合 ✗；距离比只问
            #       "圆心离边多远"、用**绿圈半径**归一 ⇒ 半径变（实测 56~61px）判别不变 ✓）；
            #   ② 是"**沿白箭头推进第一个接触到的框**" ✓（`_first_hit_box` ✓ **取代**老那条
            #      "框心在圆心前方" ✗：框心只是一个点、会被并集里被压住的砖拖偏 ✗ —— 实测
            #      帧 19 那格**盖住了预测落点**、却因框心偏后 16px 被判"不在前方"✗✗ 正是
            #      用户这次点出来的毛病 ✓）。
            #   ⚠ 适用范围照旧 = **只作用于融合框 / 融合保持** ✓（"目标自己那格"与"未登记
            #     相交优先"两档不动 ✓）；不过 ⇒ `continue`（这格留给登记表当砖 ✓ 用户口径 ✓）。
            #   ⚠ 判不出时两条都**放行**（方向拿不到 ⇒ `_first` 为 None ✓；半径还没学到 ⇒
            #     `_inherit_dist_ok` 回真 ✓）⇒ 退化成"融合框一律可挑"✓ 不猜 ✗。
            if _mg:
                _d_ok = self._inherit_dist_ok((cx, cy, w, h))
                # ⭐ 必须与"依次试出来的那个安全框"**重合**才许过（用户 2026-10-02 ✓ 三次定稿 ✓）；
                #   `_first_ok is None`（没有安全的）⇒ 这一格也过不了 ⇒ **全部挡掉** ✓。
                _is_ok = (_first_ok is not None
                          and abs(float(cx) - _first_ok[0]) < 1e-6
                          and abs(float(cy) - _first_ok[1]) < 1e-6)
                if not (_d_ok and _is_ok):
                    continue
            if _hit and not _mg and not _own:
                # ⭐⭐⭐ **未登记检出框 + 绿圈（上一拍预测过来的）压着 ⇒ 最优先**（用户 2026-10-02 ✓
                #   帧 22 定稿原话："与上一帧预测的圆相交的位置有**未登记的检出框**，这种情况
                #   **优先标红**，融合优先级应该更低" ✓）—— 目标就在这格上（先验 B：不在册
                #   ⇒ 是真目标 ✓），并集框只是它身后被压住的砖 ✗ 让位 ✓。
                #   ⭐⭐⭐ **「选框距离门」**（用户 2026-10-03 ✓ 原话："动手" ✓ 见 `_select_dist_px` ✓）：
                #     这格虽然与绿圈相交，但可能**离预测落点很远**（= 分离后"擦边"够上来的远处
                #     框 ✓ 实测 `9月30日(1).mp4` 帧 48 偏差 119px、帧 50 偏差 ~81px ✓）—— 认了
                #     它，出口的信念夹取就会把圆**一步拽过去** ⇒ 白线出现剧烈折角 ✗✗。
                #     ⇒ 超限就**不认**（`continue` ✓ 这一拍继续按预测走 ✓ 等它走近了再认 ✓）。
                #     ⚠ 只作用在"**非融合**红框"这一档 ✗（融合候选有自己那套闸 ✓ 见上 ✓）；
                #       门限是 **B 型（步数比例）** ⇒ 帧率 / 播放倍速无关 ✓（用户点出 ✓）。
                _dmax = self._select_dist_px()
                if _dmax is not None and d_pred > _dmax:
                    _skip_why = "离预测落点太远（选框距离门）"
                    if _skip_box is None:
                        _skip_box = (cx, cy, w, h)
                    continue
                score = d_pred
            elif _mg:
                # 融合框：**次优先** ✓（上面那类在场就必须让 ✓）；多个融合框里按**预测落点距离**
                # 排近的 ✓（与未登记档同一把尺 ✓）。
                score = 1e4 + d_pred
            elif _hit:
                # ⭐ **与绿圈相交但属于砖条目**（`_brick_owned` ✓ 与最终判定同一把尺 ✓ 含候选 ✓
                #   不做白块免判 ✓）—— score 抬高 = 基本不选 ✓。
                #   分数 = **到预测落点的距离**（用户 2026-10-02 ✓ 帧 22 ✓ "预测方向上更近的"
                #   优先 ✓；多个相交框里，圆心按白箭头**正在走过去**的那格排最前 ✓）。
                score = d_pred + 1e5
            elif inside:
                score = d                                  # 含报告位置但不相交？不可能 ✓ 保守 ✓
            else:
                score = d + 1e6                            # 既不融合、也不与绿圈相交 ⇒ 基本不选 ✓
            if bs is None or score < bs:
                best, bs = (cx, cy, w, h), score
        if best is None:
            # ⭐⭐⭐ **没有能挑的格 ⇒ 判「分离信号」**（用户 2026-10-02 ✓ 原话："如果没有能挑的
            #   就判定为分离信号（接入淡粉色框按轨迹预测走那一套）" ✓）：
            #   · 只在**上一拍还在融合**（`_was_merged` / 融合保持 ✓）时才算"分离"✓ —— 建档 /
            #     从来没框的情况照旧走老 `gone`（预测态 ✓），不冒充分离 ✗；
            #   · 置 `_split_now` ⇒ `process()` 那套现成的分离处置全部生效 ✓：**红框消失**
            #     （`_split_skip` ⇒ 不对外报框 ✓）+ **淡粉接力框**（演示窗按"红框丢 + 有宽高
            #     快照"画 ✓）+ **圆按上一拍预测走**（`_report_prev + vel×dt` ✓）✓。
            if (bool(getattr(self, "_was_merged", False))
                    or bool(getattr(self, "_merge_hold", False))):
                self._split_now = True
                self._merge_hold = False
                self._tbox_role = "fake"
                # ⭐ **融合框消失（分离）日志**（用户 2026-10-02 ✓）：门内**一个能挑的都没有**
                #   （全在门外 / 全被融合那几条闸筛掉 ✓）⇒ 记下这一刻的现场 ✓。
                #   ⭐ 2026-10-03：`_skip_why` 有值 ⇒ 用它（"**内砖与参照砖不同**" ✓）—— 否则
                #     日志只会笼统说"门内没有能挑的格" ✗、看不出是**换对象**被拦下的 ✓。
                self._split_why = self._split_diag(_skip_box, self._hold_ref(),
                                                   (_skip_why or "门内没有能挑的格"))
            return ("gone", None)
        # ⭐⭐⭐ **红框的判定顺序**（用户 2026-10-02 ✓ 规则②恢复后重排 ✓）：
        #   ① **融合**（规则②：包住砖 + **整圈绿圈在内** + 面积≈砖 ✓；规则①：包住砖 + 面积比
        #      ≥ 阈值 ✓ —— 都在 `_is_merged_box` 里 ✓）⇒ `merged` ✓（全套并集待遇 ✓）。
        #      ⚠ **必须先于"属于砖"** ✗✗：规则② 的框**天生盖住砖** ✓ ⇒ 让 `_brick_owned` 排在
        #        前面 = 规则② 永远被拦 ✗✗（恢复了个寂寞 ✗）。
        #   ② **属于砖条目 ⇒ 不红**（帧 12/23 口径 ✓ `_brick_owned` ✓ 含候选 ✓ 不做白块免判 ✓）
        #      —— 到得了这里的都是"没包住整圈绿圈、面积比也不够"的框 ✓ = 砖自己/残框 ✓。
        #   ③ **与绿圈相交、又不是砖**（Q4.1 ✓）⇒ `ok` ✓ = **目标自己那格框** ✓ 照常夹取 ✓。
        #   都不是 ⇒ `gone` ✓ 预测态 ✓。
        # ⭐⭐ **身份标签 = 最终判定本身**（2026-10-02 ✓）：原来这行取 `_box_identity`（旧尺：
        #   0.75 覆盖 + `_FAKE_SIZE_MAX` 1.7 倍 + 中心贴 ✓）—— 它与**决策链**（`_brick_owned`
        #   新尺：0.65 + 比 < 阈值 + 锁尺寸例外 ✓ 用户后来定稿 ✓）在**边际带**会打架 ✗
        #   （实测 9月30日 帧 52~54：比 1.42 卡在 1.4 边缘 ⇒ 旧标签 "fake"、决策 "ok" ✗✗
        #   = 生长把砖长到全尺寸后翻出来的 ✓）。⇒ 标签跟着**最终判定**走 ✓
        #   （"判定成假目标的那一拍不出红框"（帧 31 ✓）里的**判定**就是这条决策链 ✓）。
        # ⭐⭐⭐ **融合第 2 拍起：每拍判一次「落点倒退」**（用户 2026-10-03 ✓ 流程图 ✓ 原话：
        #   "假设上拍走了白箭头的指示到了本拍，对比**本拍的白箭头**和**本拍圆心指向融合框
        #   计算出的落点的位置的向量**" ✓ —— 同一把尺 = `_merge_fix_safe` ✓）：
        #   · **首拍不判** ✓（`_hold0` 为 False ⇒ 进门那一拍 ✓ 图里"融合**第二拍**开始" ✓）；
        #   · **拿不到落点 ⇒ 不判** ✓（用户同日："**拿不到点按白箭头预测走下一步『倒退距离』
        #     的判断**" ✓ = 这一拍不落位、圆按白箭头走、下一拍再判 ✓ 见 `_merge_fix_safe` ✓）；
        #   · 逆着白箭头（**后方 180° 扇形**）+ 长度 > 允许量 ⇒ **判分离** ✓（红框消失 +
        #     淡粉接力框 + 圆按上一拍预测走 ✓）。
        #   ⚠⚠ **位置必须在"进门 / 保持"两支之前** ✗✗：保持期的框多半**仍满足 `_is_merged_box`**
        #     （包住砖 ✓ 面积比 ≥ 阈值 ✓）⇒ 放后面会被"进门分支"抢走 ⇒ **永不执行** ✗（实测踩过 ✓）。
        # ⭐⭐⭐ **进门条件里那条 `_hold_active` 是"锁死的门"**（用户 2026-10-03 ✓ 原话："**把门打开**"
        #   ✓）：`_hold_active` 的定义 = "包住砖 **且没缩成砖**" ✓ ⇒ 而 ①「**框缩成砖**」一旦成立
        #   （它正是分离三条件之一 ✓），`_hold_active` **必然为假** ✗ ⇒ 与 `_is_merged_box`
        #   （"变小了"也多半为假 ✗）合起来 ⇒ **整段被跳过** ⇒ `_hover` / `_span` **压根没被求值**
        #   ✗✗ —— 实测 `9月30日(1).mp4` **帧 47**：三条齐（缩成砖 ✓ 反方向点积 −24420 ✓
        #   面积跨度 32599/21788 = **1.50 ≥ 1.15** ✓）却继续当融合框 ✓ 就是被这道门挡住 ✓
        #   （用户："**报警响了，但值班室的门锁着 —— 而锁门的就是报警本身**" ✓）。
        #   ⇒ 现在门改成"**还在保持会话里 + 框还包着那块参照砖**"就能进 ✓（`_box_covers_entry` ✓
        #     与下面"融合保持"支**同一把尺** ✓ = 2990 行那条 ✓）—— "缩成砖"不再把自己锁在门外 ✓。
        #   ⚠ 只加"还能找到参照砖且框仍包住它"这一条 ✗ 不再要求"没缩成砖"✓；`_hold_ref()` 为
        #     `None`（本该在保持却没记参照砖 ✓）⇒ `_box_covers_entry` 回 False ⇒ 照老样跳过 ✓ 不崩 ✓。
        #   ⭐⭐⭐ **2026-10-03 再改：进门那一拍也判**（用户 ✓ 原话："矛盾查实，然后**按进门拍也判**"
        #     ✓）：原来这里是 `_hold0 and …` ✗ ⇒ **融合第一拍（进门）整段不执行** ✗ ⇒ 而那一拍
        #     恰恰是**位移最大**的一拍（`10月1日.mp4` 帧 37：圆被挪 **117.8px**、方向与白箭头相反 ✓
        #     = 白线折角的来源之一 ✓）⇒ 现在去掉 `_hold0` 这个前提 ✓ —— 只要"这一格
        #     **有可能成为融合框**"（= `_is_merged_box` ✓ 或保持中 ✓ 或"还在包着参照砖" ✓
        #     三者取或 ✓ 与下面"进门分支"**同一条件** ✓）就**先判一次落点倒退** ✓。
        #   ⚠⚠ **"进门那一拍也判"试过、已撤** ✗（2026-10-03 ✓ 用户要求过 ✓ 对照台实测 ✓）：
        #     去掉 `_hold0` 前提之后 ⇒ 融合体系**基本停摆** ✗✗（`10月2日/9月30日(1)` 融合
        #     23/22 → **0/0** 帧 ✗）—— 因为"**认框的第一拍本来就需要一次超过允许量的位移**"
        #     （圆要从**预测位置挪进框** ✓）⇒ 拿"倒退闸"去拦它 = **融合起不来** ✗
        #     （与当年"选框速度门"同一个坑 ✓ 见 `_SELECT_VEL_GATE` ✓）。
        #   ⇒ 恢复 `_hold0` 前提 ✓（= 图里"融合**第二拍**起才判" ✓）；要管"进门那一下"，得用
        #     **别的尺**（例如"落位只许贴着进入侧那条边" ✓），不能用这条倒退闸 ✗。
        if (_hold0 and best is not None
                and (self._is_merged_box(best) or self._hold_active(best)
                     or self._box_covers_entry(best, self._hold_ref()))):
            # ⭐⭐⭐ **`allow_tangent=False`**（用户 2026-10-03 ✓ 原话："**A. 恢复 `_hover`：
            #   相切豁免只用于『落位采纳』，倒退判据仍按老口径算**" ✓）—— 这条判据**不能**吃
            #   相切豁免 ✗（吃的话它恒为 False ⇒ "落点倒退超限 ⇒ 判分离"整个失效 ✗ 实测帧 62 ✓）。
            _hover = not self._merge_fix_safe(best, allow_tangent=False)   # ① 落点倒退超限？✓
            _a_now = float(best[2]) * float(best[3])
            # ② **「分离判定阈值」那条**（用户 2026-10-03 ✓ 流程图新增 ✓ 原话："融合框期间
            #   最大面积/最小面积 >「分离判定阈值」？" ✓）：`_merge_area_span_ok` = **本拍之前
            #   融合期出现过的最大框面积 ≥ 本拍面积 × 阈值** ✓（记账 = 本会话的时序序列 ✓
            #   "本拍不算" ✓ 见它 ✓）。⚠ 这条与①是**并列（OR）** ✓ —— 图里①"否"⇒ 直接分离 ✓、
            #   ①"是"⇒ 再判② ✓ ⇒ 等价于"两条任一成立就分离" ✓。
            _span = self._merge_area_span_ok(_a_now)
            if _hover or _span:
                _href0 = self._hold_ref()
                self._merge_hold = False
                self._tbox_role = "fake"
                self._split_why = self._split_diag(
                    best, _href0, ("落点倒退超限" if _hover else "面积跨度超阈值"))
                self._split_now = True
                return ("gone", None)
        if self._is_merged_box(best):
            # ⭐⭐ **进门**（规则①②只在这里用 ✓）⇒ 进入融合保持、记下参照砖 ✓
            # ⭐⭐⭐ **融合期的面积记账从这一拍开始**（用户 2026-10-02 ✓ 分离信号第三条 ✓）：
            #   新一次融合会话 ⇒ 序列**重置**成"只有这个并集框的面积" ✓（之后每拍
            #   `_merge_area_note` 追加 ✓）—— 于是第三条那条"出现最小面积**之后**的最大面积"
            #   才有正确的时序可用 ✓。
            # ⚠⚠ **只在"真正的进门那一拍"重置序列** ✗✗（`_hold0=False` ✓）—— 保持期的框
            #   **多半仍满足 `_is_merged_box`** ⇒ 也会走到这一支 ✗ ⇒ 若每拍都重置，序列永远只有
            #   1 个元素 ⇒ **「分离判定阈值」那条判据永远不成立** ✗（实测踩过 ✓）。保持期 ⇒
            #   **追加**本拍面积 ✓（判定已经在上面做过了 ⇒ "本拍不算"成立 ✓）。
            if not _hold0:
                _a0 = float(best[2]) * float(best[3])
                self._merge_area_series = [_a0]
                self._merge_area_max = _a0
                self._merge_area_min = _a0
            else:
                self._merge_area_note(best)
            _r0, _ = self._fake_ref(best)
            if _r0 is not None:
                self._merge_hold = True
                self._merge_hold_bid = tuple(_r0.bid)
            # ⭐⭐ **把"为什么判成融合"那一份诊断快照下来**（用户 2026-10-02 ✓）—— 后面还有
            #   别的调用会覆盖 `_merge_why` ✗ ⇒ 进门这拍必须先存 ✓（`_build_merge_log` 用它 ✓）。
            self._merge_why_snap = dict(getattr(self, "_merge_why", None) or {})
            self._tbox_role = "merged"            # 并集块 ✓
            return ("merged", best)
        if self._merge_hold:
            _href = self._hold_ref()
            if _href is None or not self._box_covers_entry(best, _href):
                # ⚠⚠ **「迟滞·守」试过、已撤** ✗（2026-10-03 ✓ 对照台实测 ✓）：一度在这里加
                #   "框不再包住砖、但 `IoU < merge_iou_out` ⇒ 继续融合" ✓ 想治"融合段太碎"✓；
                #   实测**效果与参数无关**（`out=0.5` 与 `out=0.75` 结果逐项相同 ✗）⇒ 说明
                #   这条支路**几乎不被走到**（保持期绝大多数拍 `_box_covers_entry` 为真 ✓ ⇒
                #   走上面的 else ✓）⇒ 结论：**"会话碎不碎"的主因不在这一支** ✗。
                #   ⚠ 与迟滞相关的**两条实测教训**都留着（免得后人重踩 ✗）：
                #     · 迟滞做在**进入判据**（`_is_merged_box`）上 ⇒ 会话**更碎** ✗✗
                #       （10月2日 融合 23 → **1** 帧 ✗："更容易判融合"≠"融合更持久" ✓）；
                #     · 做在**这一支**上 ⇒ 参数无效 ✗（因为很少走到 ✓）。
                #   ⇒ 迟滞要真正生效，得改"**保持期每拍凭什么继续**"本身（= `_box_covers_entry`
                #     那条尺 ✓ 或"选框那步凭什么换框"✓）—— 属**重新设计**，见 `_iou_below_out` ✓。
                # ⚠ **静默出融合**（用户 2026-10-03 ✓ "其余删" ⇒ 这里**不再判分离** ✗）：框不再
                #   包住那块砖 = 目标已离开那块砖 ⇒ 会话结束 ✓ 但**不置** `_split_now` ✓、不写
                #   分离日志 ✓（那一拍照下面的常规链判定 ✓ 多半是 `fake`/`gone` ⇒ 预测态 ✓）。
                self._merge_hold = False
            elif self._merge_should_exit(best):
                # ⭐⭐⭐ **融合期退出（用户 2026-10-03 ✓ 第 3 行 "**否则就算分离**" ✓）**：框虽然还
                #   包着那块砖 ✓ 但用**融合期那一对阈值**复核 ⇒ 已经"不像并集"了
                #   （圆矩形的相交比例掉下来 ✗ 或 与内砖太同格 ✗）⇒ **判分离** ✓（红框消失 +
                #   淡粉预测态 + 圆按上一拍预测走 ✓）——⚠ 这是**新增行为** ✓ 用对照台评估过 ✓。
                #   ⚠ 想关掉：把 `brick_iou_fuse` 设 **1.0** ✓（见 `_merge_should_exit` ✓）。
                self._merge_hold = False
                self._split_why = self._split_diag(best, self._hold_ref(),
                                                   "融合期阈值不满足")
                self._split_now = True
                return ("gone", None)
            else:
                # ⭐⭐⭐ **判定在前、记账在后** —— **本拍不算**（用户 2026-10-02 ✓ 原话：
                #   "注意一下，**本拍不算**" ✓）：第三条（`_merge_area_span_ok`）看的是
                #   "本拍**之前**的融合期面积" ✓。
                #   ⚠ 为什么必须这样 ✗✗：若把本拍也记进去，那么"**缩到最小的那一拍**"永远
                #     满足不了（最小 = 本拍 ⇒ 之后最大 = 本拍自己 ⇒ 比 1.00 ✗）⇒ 该分手的
                #     那一拍反而**不分手** ✗（实测 `10月1日.mp4` 帧 25 正是这个病 ✓：
                #     本拍框 149×123 = 18354 是全程最小 ⇒ 含本拍 ⇒ 比 1.00 ⇒ 不分离 ✗；
                #     不含本拍 ⇒ 历史最小 28608（第 1 拍）→ 之后最大 35093 ⇒ 比 1.23 ≥ 1.15
                #     ⇒ ①②③ 齐 ⇒ 判分离 ✓）。
                # ⚠ **「落点倒退」那条判据已上移到本函数决策链最前**（见 `best` 判出来之后那段 ✓
                #   —— 因为它对"仍满足 `_is_merged_box` 的保持框"也要生效 ✓ 放这里会被进门分支抢走 ✗）。
                # ⚠⚠ **"框已缩成砖 ⇒ 判分离"已删**（用户 2026-10-03 ✓ 原话："只留『框丢了』，
                #   其余删" ✓）：缩成砖**不再直接分手** ✗ ⇒ 这一拍照旧算融合 ✓（下一拍它多半被
                #   判成"砖自己那一格"⇒ 门内全不够格 ⇒ 才分手 ✓ 见 `best is None` 那条 ✓）。
                # ⭐ 面积记账**保留**（诊断/日志与"本拍不算"那条口径都要它 ✓）。
                self._merge_area_note(best)
                # ⭐⭐ **融合保持**（用户 2026-10-02 ✓ 原话："在进入融合之后不再生效，要持续
                #   跟踪更新融合框的变化，直到分离信号出现" ✓）：哪怕比掉下阈值、圈不再整圈
                #   在内 ⇒ 继续算融合、持续跟踪融合框的变化 ✓。
                self._tbox_role = "merged"
                return ("merged", best)
        _owned = bool(self._brick_owned(best))     # ⭐ 记下结果（只记录 ✗ 判据一字不动 ✓）
        if _owned:
            self._tbox_role = "fake"              # 判定成"属于砖" ⇒ 不出红框 ✓（帧 31 ✓）
            return ("gone", None)
        if self._circle_hits(best):
            # ⭐⭐⭐ **非融合红框**（用户 2026-10-03 ✓ 原话："在日志加一下**非融合红框选择**的
            #   判定信息吧" ✓）—— 把"为什么最后判成红框"的那条链**按判定顺序**记下来 ✓
            #   （演示窗日志区显示 ✓ 与融合 / 分离 / 边归属并列 ✓ 四条互补 ✓）：
            #     · 走到这一行 ⇒ 上面"融合（含保持）"与"属于砖"两支**都没走** ✓ ⇒ 这两条
            #       布尔必然是假 ✓（直接写 False ✓ 不必再算一遍 ✗ 免得覆盖 `_merge_why` ✗）；
            #     · 本条的判据 = `_circle_hits` ✓（"框与绿圈相交" ✓）⇒ 记它的**尺**：
            #       圆心到框最近边的**有符号垂距 ÷ 半径**（`_inner_edge_dist_ratio` ✓ 纯算 ✓）。
            #   ⚠ 只**记录**、不改判据 ✗（下面两支与原来逐位一致 ✓）。
            _inner = self._inner_edge_dist_ratio(best)
            self._pick_why = {
                "n_cand": int(len(dets or [])),
                "box": tuple(float(v) for v in best[:4]),
                "merged": False,              # 已过"融合"那两支 ⇒ 假 ✓
                "owned": False,               # 已过"属于砖"那一支 ⇒ 假 ✓
                "hit": True,                  # 本条判据 ✓
                # ⚠ 保留 `None`（= **算不出垂距** ✓ 半径还没学到那几拍 ✓）—— 别写 0.0 ✗
                #   否则日志里"半径 0.0、垂距比 0.00"看着像真值 ✗（用户要看的就是这个数 ✓）。
                "inner": (None if _inner is None else float(_inner)),
                "d_center": (((float(best[0]) - float(self.pos[0])) ** 2
                              + (float(best[1]) - float(self.pos[1])) ** 2) ** 0.5
                             if self.pos is not None else 0.0),
                "rad": float(getattr(self, "_rad", 0.0) or 0.0),
                "ntol": float(getattr(self, "noise_tol", 0.0) or 0.0),
            }
            self._tbox_role = ""                  # 目标自己那格 ✓
            return ("ok", best)
        self._tbox_role = ""                      # 预测态 ✓
        return ("gone", None)

    def _viz_of(self, t):
        """轨迹 ⇒ 可视化条目（多带 `miss/stable/spread/sus/dev_s` ⇒ 演示窗能看出"哪条在
        滑行 / 不稳 / 被怀疑重叠或分离 / 不合群多久了" ✓ 用户复核要看的就是这些 ✓）。"""
        return {"p": t["p"], "v": t["v"], "dev": 0.0, "tid": t["id"],
                "age": t["age"], "miss": t.get("miss", 0),
                "stable": bool(t.get("stable")), "spread": t.get("spread", 0.0),
                "sus": self._sus_of(t), "dev_s": float(t.get("dev_s", 0.0)),
                "must": int(t.get("must_check", 0)),
                "borrowed": bool(t.get("borrowed")),
                "area_s": float(t.get("area_s", 0.0))}

    # ---- ⭐⭐ 运动向量自我纠错（用户 2026-09-30 要求 ①）----
    def _update_tracks(self, dets, dt, ts=None):
        """维护所有检测框的运动轨迹 ⇒ 返回 `(pos, area, dev, tid)` 或 None。

        `dev` = 该候选速度与**全体中位速度**的距离（px/s ✓）—— 目标与背景/干扰"运动
        不同"，所以 dev 最大的就是目标 ✓；**连续 `_SWITCH_N` 帧**出现"明显更大"的
        新候选就换过去（自我纠错 ✓ 目标被压住/短暂重叠后能认回来 ✓）。
        """
        self._typ_area = self._typical_area(dets or [])   # ⭐ 标准面积（用户第2条 ✓）
        if not dets:
            # ⭐ 一帧检测都没有：所有轨迹照旧**滑行 + 记记忆时间**（别当场删 ✗ 用户 ③ ✓）
            self._tracks = self._age_tracks(self._tracks, dt, matched=set())
            self._viz = {"tracks": [self._viz_of(t) for t in self._tracks],
                         "median": (0.0, 0.0), "dev": 0.0,
                         "tid": self._target_id, "followed": None}
            return None
        # 贪心最近邻关联（每个轨迹只能被用一次 ✗ 别循环里抢同一个 ✓）
        # ⭐ **关联门随"丢了多久"放大**（用户 ② 原话："如果有轨迹预测的话，它其实是符合
        #   预测范围内要求的" ✓）：轨迹滑行期间位置已经按速度外推 ⇒ 天然就在预测点上 ✓；
        #   门再补上"这段丢失时间里它走了多远" ⇒ 短暂消失后重出的框能**接回原轨迹** ✓
        #   （而不是建一条从零开始的 ✗ 那样速度记录就永久没了 ✗）。
        pairs = []
        for di, (_cx, _cy, _w, _h) in enumerate(dets):
            for t in self._tracks:
                gap = (t.get("lost_s", 0.0) or 0.0) + (dt or 0.0)
                gate = _TRK_GATE + self._speed_of(t) * gap * 1.2
                d = ((t["p"][0] - _cx) ** 2 + (t["p"][1] - _cy) ** 2) ** 0.5
                if d <= gate:
                    pairs.append((d, di, t))
        pairs.sort(key=lambda r: r[0])
        used_d, used_t = set(), set()
        for d, di, t in pairs:
            if di in used_d or id(t) in used_t:
                continue
            used_d.add(di)
            used_t.add(id(t))
            cx, cy, w, h = dets[di]
            t["a_prev"] = t["a"]                    # ⭐ 上一拍面积（判"突然变大/变小"用 ✓）
            t["p"] = (cx, cy)
            t["a"] = float(w) * float(h)
            t["age"] += 1
            t["miss"] = 0
            t["lost_s"] = 0.0                 # ⭐ 重新检出 ⇒ **刷新防抖计时**（用户 ③ ✓）
            t["ts"] = ts
            t["hist"].append((ts, cx, cy, float(w), float(h)))   # ⭐ 带 w/h ⇒ 面积变化可判 ✓
            if len(t["hist"]) > _TRK_HIST:
                t["hist"].pop(0)
        # ⭐ 速度 = **逐步差的中位数**（每步 Δp/Δt 取中位 ✓）—— 比"整窗端点差"抗**误关联**
        #   得多：一步配错（跳 ~40px ⇒ 单步速度 ~2000px/s ✗）只是中位数里的一票 ✓
        #   （端点差会被这一步直接带飞 ✗ 实测：现场噪声 ~400px/s ⇒ 挑中噪声 ✗）。
        for t in self._tracks:
            h_ = [s for s in t["hist"] if s[0] is not None]
            t["v_ok"] = False                  # 自己的速度够不够格（不够 ⇒ 借群体的 ✓）
            # ⚠⚠ **"有速度"和"够格参赛"是两件事**（2026-09-30 修 ✓）：原来整个速度计算被
            #   `_TRK_MIN_AGE`(=6) 卡住 ✗ ⇒ 年轻轨迹**永远没有速度** ⇒ ① 借群体也借不到
            #   （群体里一个 `v_ok` 都没有 ✗）② 建档期（第 6-12 帧）箭头全是 0 长 = 用户看到的
            #   "速度向量消失" ✗✗。现在：**2 段干净样本**就算"有速度"（`v_ok` ✓ 可以当群体
            #   成员 ✓ 也能画箭头 ✓）；"够格参赛"仍旧要 `_TRK_MIN_AGE` 帧 + 稳定 ✓（不放松 ✓）。
            if len(h_) < 2:
                t["stable"] = False
                continue
            vxs, vys, segs = [], [], []
            for a, b in zip(h_, h_[1:]):
                dt_ = b[0] - a[0]
                if not (0.0 < dt_ <= 1.0):
                    continue
                # ⭐⭐ **面积变过的那一段不算速度**（用户 2026-09-30 第④问 ✓）：合并/分离
                #   那一拍的质心位移**主要是"形状变了"**、不是运动 ✗ —— 实测第 23 帧目标框
                #   190×189 → 149×139，质心跳 (-30.5,-9.9)px ⇒ 采信它就把速度带飞 ✗✗
                #   （第 24 帧红箭头朝上就是这么来的 ✓）。跳过这一段 ⇒ 速度**保持上一次
                #   可信值**（既不清零、也不采信 ✗）。
                if len(a) > 4 and len(b) > 4:
                    aa = float(a[3]) * float(a[4])
                    ab = float(b[3]) * float(b[4])
                    if aa > 0 and ab > 0 and \
                            max(aa, ab) / min(aa, ab) >= _AREA_SEG_SKIP:
                        continue
                sx, sy = (b[1] - a[1]) / dt_, (b[2] - a[2]) / dt_
                vxs.append(sx)
                vys.append(sy)
                segs.append((sx, sy))
            if len(vxs) < 2:
                t["stable"] = False
                # ⚠ 干净段不够 ⇒ **速度不清零**（保留上一次可信值 ✓ 用户②"程序后台需要
                #   认为其还存在"✓）
                continue
            vxs.sort()
            vys.sort()
            vx, vy = vxs[len(vxs) // 2], vys[len(vys) // 2]
            t["v"] = (0.0, 0.0) if abs(vx) + abs(vy) > _TRK_VMAX else (vx, vy)
            t["v_ok"] = True
            # ⭐ **稳定度**（用户 ④⑤ ✓）：每段速度与"中位速度"的距离取**中位** ——
            #   抗单段误配（一票带不飞 ✓）、又能抓住"方向忽东忽西/时快时慢"的假目标 ✓
            devs = sorted(((sx - t["v"][0]) ** 2 + (sy - t["v"][1]) ** 2) ** 0.5
                          for sx, sy in segs)
            t["spread"] = devs[len(devs) // 2]
            # ⚠ 参赛资格（`stable`）**照旧严格**：够 6 帧（`_TRK_MIN_AGE` ✓ 见 hist 长度）+
            #   4 段以上 + 速度稳 ✓ —— "有速度"（`v_ok`）只是能画箭头/当群体成员 ✓ 两会事 ✓
            t["stable"] = (t["age"] >= _TRK_MIN_AGE
                           and len(vxs) >= _TRK_STABLE_N
                           and t["spread"] <= _TRK_V_SPREAD)
            # ⚠⚠ 重构（2026-09-30 ✓）：这里原来还有一段"按**面积方向**重定向轨迹速度"的
            #   启发式（`_area_dir()` ✓）—— 已**整族删除** ✗✗。实测（`tools/eval_lie.py`）：
            #   把**框的几何变化**当运动指示会不断把位置拽到"随群体平移的背景"上
            #   （位置误差中位 147.7px ✗ 而物理判据的局部偏离只有 0.6px ✗）；面积变化现在
            #   只用来判**事件**（融合/分离 ⇒ S1/S2 ✓ 用户事实 5~7 ✓），不再改速度 ✓。
        for di, (cx, cy, w, h) in enumerate(dets):        # 新出现的框 ⇒ 建新轨迹 ✓
            if di in used_d:
                continue
            _nt = {"id": self._next_tid, "p": (cx, cy),
                                 "v": (0.0, 0.0), "a": float(w) * float(h),
                                 "a_prev": 0.0, "age": 1, "miss": 0,
                                 "lost_s": 0.0, "ts": ts,
                                 "stable": False, "spread": 0.0,
                                 # ⭐ 怀疑链状态（用户 ④ 条口径 ✓ 见常量区注释）
                                 "dev_s": 0.0, "merge_s": 0.0, "split_s": 0.0,
                                 "area_s": 0.0, "v_ok": False,
                                 "hidden_s": 0.0, "must_check": 0, "new": True,
                                 "hist": [(ts, cx, cy, float(w), float(h))]}
            self._tracks.append(_nt)
            # ⚠⚠ **新建的轨迹必须记进 `used_t`**（2026-09-30 修 ✓ 实测踩到）：不记的话
            #   `_age_tracks` 会把它当"这拍没配上"⇒ 出生第一帧就 `miss=1` ✗✗ ⇒
            #   ① 看着像"滑行中"（可视化画成粘滞 ✗）；② **借不到群体速度**（只借给
            #   `miss==0` ✓）⇒ 新框的箭头依旧是 0 长 ✗ = 用户第②问的"向量消失" ✓。
            used_t.add(id(_nt))
            self._next_tid += 1
        # ⭐⭐ **重叠 / 分离怀疑链**（用户 2026-09-30 ④ 条 ✓）—— 一律**只记账**，
        #   真正的裁决留给"不合群速度持续够久"（判据④ ✓ 见下面的 `dev_s`）✓。
        self._mark_size_suspects(dt)
        # ⚠ 没配上的轨迹：**滑行 + 记记忆时间**（不立刻删 ✗ 用户 ③ ✓）
        self._tracks = self._age_tracks(self._tracks, dt, used_t)
        # ⭐ 判据只吃**成熟且速度稳定**的轨迹（2026-09-30 ✓）：现场那批 age=3 的静止噪声
        #   （dev 232 抢判据 ✗）与 77 帧那种"一次性的方向突变假目标"都进不来 ✓
        mature = [t for t in self._tracks
                  if t["age"] >= _TRK_MIN_AGE and t.get("stable")]
        # ⚠⚠ **滑行中的轨迹不许参赛**（2026-09-30 ✓ 实测教训）：记忆本来是为了"保住速度
        #   记录、等重新检出接回"（用户 ③ ✓），但滑行轨迹的 `p` 是**外推的预测点**（还会
        #   撞到画面边缘被钳住）⇒ 让它继续当冠军 = 拿鬼影当目标 ✗✗（实测：判据被
        #   `miss=7~16` 的鬼影连任 ✓ 真目标反而没人看 ✓）。
        #   ⇒ **只有这一帧真检出的（miss==0）才参加"谁最异常"的比赛** ✓；
        #     已确认的目标轨迹即便是滑行状态，**身份照旧保留**（走 `_target_id` 那条 ✓
        #     这正是用户 ② 要的"可疑的真目标" ✓），只是不许它去抢新王冠 ✓。
        contend = [t for t in mature if t.get("miss", 0) == 0]
        # ⭐ **"严查"的框放进来考**（用户 ②："严查新多出来的边" ✓）：成熟门槛放宽到
        #   `_MUSTCHECK_AGE`（不然刚分离出来的新框要等 6 帧才有人看它 ✗），但它要
        #   **更久**的不合群证据（`_MUSTCHECK_DEV_HOLD` ✓ 见换目标那处）⇒ 只放"值得查的"
        #   进来、不放噪声 ✗。
        _ids = {id(t) for t in contend}
        contend = contend + [t for t in self._tracks
                             if t.get("miss", 0) == 0 and id(t) not in _ids
                             and t.get("must_check", 0) > 0
                             and t["age"] >= _MUSTCHECK_AGE]
        if len(contend) < _TRK_MIN_N:
            # 这一帧够格的轨迹太少（没有"多数"可言 ✗）—— 判据返回 None ✓（不猜 ✓），
            # 但**照样**：① 给可视化（看箭头长起来 ✓）；② **借群体速度**（用户第③问 ✓
            # 建档期/刚开局就是这个情形 ⇒ 有了兜底中位，箭头立刻有方向 ✓ 不会"消失" ✓）。
            self._borrow_vel(self._group_median(self._tracks))
            self._viz = {"tracks": [self._viz_of(t) for t in self._tracks
                                    if t["age"] >= 2],
                         "median": (0.0, 0.0), "dev": 0.0,
                         "tid": self._target_id, "followed": None}
            return None
        mature = contend                                   # 以下全用"这一帧真检出的" ✓
        vxs = sorted(t["v"][0] for t in mature)
        vys = sorted(t["v"][1] for t in mature)
        mvx, mvy = vxs[len(vxs) // 2], vys[len(vys) // 2]   # 中位速度 = 背景/干扰的"共同漂移"
        # ⭐⭐ **假目标群体的速度互相修正**（用户 2026-09-30 第③问 ✓ 原话："有一件确定的事：
        #   假目标群体的速度向量几乎一致，可以互相修正" ✓）—— 自己算不出速度的轨迹
        #   （新出现 / 刚接回原轨迹 / 干净段不足 ✓ `v_ok=False`）**先借群体中位速度**：
        #     · 用户第②问的"它就应该跟着轨迹预测显示" ✓ ⇒ 一漏检就能画出**合理方向**的
        #       粘滞箭头（否则箭头是 0 长 ⇒ 看着像"消失了" ✗）；
        #     · "程序后台需要认为其还存在（只是暂时没被检测出来）" ✓ ⇒ 速度非 0 ⇒ 预测
        #       会继续走 ✓。
        #   ⚠ 安全：借来的速度**等于**中位速度 ⇒ 它的 `dev`≈0 ⇒ **永远赢不了判据** ✓
        #     （不会把噪声抬成目标 ✓），而且 `stable` 保持 False ⇒ 不进中位/不参赛 ✓。
        if _GROUP_BORROW:
            self._borrow_vel((mvx, mvy))
        best, best_dev = None, -1.0
        for t in mature:
            dev = (((t["v"][0] - mvx) ** 2 + (t["v"][1] - mvy) ** 2) ** 0.5)
            # ⭐⭐ **判据④：累计"不合群"的秒数**（用户 2026-09-30 原话："当不合群的速度
            #   向量**持续够久**（你可以根据移动速度拍一个值），那此框是真目标的可能性
            #   最大" ✓）—— 满 `_DEV_HOLD_S`（0.6s ≈ 8 帧@13fps）才敢换过去 ✓；
            #   ⚠ 期间只要有一拍不再"不合群"⇒ 归零（"持续"才有意义 ✓ 断断续续 = 噪声 ✗）。
            if dev >= _DEV_MIN:
                t["dev_s"] = float(t.get("dev_s", 0.0)) + max(0.0, float(dt or 0.0))
            else:
                t["dev_s"] = 0.0
            if dev > best_dev:
                best, best_dev = t, dev
        second_dev = 0.0
        for t in mature:
            if t is best:
                continue
            d2 = (((t["v"][0] - mvx) ** 2 + (t["v"][1] - mvy) ** 2) ** 0.5)
            if d2 > second_dev:
                second_dev = d2
        # ⭐ 可视化快照**在置信闸之前就写好**（演示窗要能看见"为什么没用运动判据" ✓）
        vis = []
        for t in mature:
            e = self._viz_of(t)
            e["dev"] = (((t["v"][0] - mvx) ** 2 + (t["v"][1] - mvy) ** 2) ** 0.5)
            vis.append(e)
        # ⭐⭐ **滑行中的轨迹也要给可视化**（用户 2026-09-30 第④问 ✓ 原话："当检测目标
        #   消失时，其速度向量的绘制**不要消失**，并且根据轨迹预测移动并绘制" ✓）——
        #   它们的 `dev` 不在场内（不参与判据 ✓），`miss>0` ⇒ 演示窗画成**白空心箭头**
        #   = "预测中（粘滞）" ✓，跟"这帧真检出"的实心箭头一眼分得开 ✓。
        for t in self._tracks:
            if t.get("miss", 0) > 0:
                e = self._viz_of(t)
                e["dev"] = 0.0
                e["sticky"] = True
                vis.append(e)
        self._viz = {"tracks": vis, "median": (mvx, mvy), "dev": best_dev,
                     "tid": self._target_id, "followed": None}
        # ⭐ **置信判据**：冠军要**明显甩开**亚军才敢用 —— 一群候选偏差都差不多时，
        #   说明是**噪声在打架**（检测框抖动 ⇒ 逐帧差分算出的速度纯噪声 ✗），
        #   这时**退回残差路线** ✓ 比"硬选一个"安全得多 ✓（实测：不加这道闸会把
        #   红点甩到画面另一头 ✗✗）。
        if best is None or best_dev < _DEV_MIN:
            return None                                    # 没人"运动明显不同" ⇒ 不猜 ✗
        if best_dev < second_dev * _DEV_LEAD:
            return None                                    # 分不清冠军 ⇒ 不用运动判据 ✓
        # ---- 自我纠错：当前目标被别的候选"更异常"地压过 ⇒ 连续 N 帧才换 ✓ ----
        cur = None
        for t in self._tracks:              # ⚠ 含**滑行中**的（目标短暂漏检时身份不断 ✓）
            if t["id"] == self._target_id:
                cur = t
                break
        cur_dev = 0.0
        if cur is not None:
            cur_dev = (((cur["v"][0] - mvx) ** 2
                        + (cur["v"][1] - mvy) ** 2) ** 0.5)
        if cur is not None and best["id"] != cur["id"]:
            if best_dev >= cur_dev * _DEV_MARGIN:
                self._sway_n += 1
                # ⭐ **换目标要过两道**（判据④ ✓）：连续 `_SWITCH_N` 帧都该换 **且**
                #   它的"不合群"已经**持续够久**（`_DEV_HOLD_S` 秒 ✓；被②判"严查"的新框
                #   要更久 `_MUSTCHECK_DEV_HOLD` ✓）—— 这样"一闪而过的假目标"（用户④里
                #   第 77 帧那种）根本来不及被换上去 ✓。
                need_s = (_MUSTCHECK_DEV_HOLD if best.get("must_check")
                          else _DEV_HOLD_S)
                if (self._sway_n >= _SWITCH_N
                        and float(best.get("dev_s", 0.0)) >= need_s):
                    self._prev_target_id = cur["id"]    # ⭐ 记下"换之前是谁"（回归复核用 ✓）
                    self._target_id = best["id"]        # ⭐ 换目标（纠正 ✓）
                    self._sway_n = 0
            else:
                self._sway_n = 0
        else:
            self._sway_n = 0
        # ⭐⭐ **回归复核 / 假目标回退**（用户 2026-09-30 复核 ④ 原话："第77帧有个因为检测
        #   误差出来的指向左上的假目标，可以通过后第78、79帧的速度**回归群体**确认其为
        #   假目标" ✓✓）：换过目标之后，若**新目标不再"与群体不同"**（dev 掉回门限下 =
        #   它的速度回归群体 ⇒ 当初那次"不同"是噪声 ✗），而**旧目标还在且仍然异常** ⇒
        #   连续 `_SWITCH_N` 帧就**退回去** ✓（比"锁死在新目标上"稳 ✓）。
        if self._target_id is not None and cur_dev < _DEV_MIN \
                and self._prev_target_id is not None:
            self._back_n = getattr(self, "_back_n", 0) + 1
            if self._back_n >= _SWITCH_N:
                for t in self._tracks:
                    if t["id"] == self._prev_target_id:
                        self._target_id = self._prev_target_id
                        self._prev_target_id = None
                        best, best_dev = t, (((t["v"][0] - mvx) ** 2
                                              + (t["v"][1] - mvy) ** 2) ** 0.5)
                        break
                self._back_n = 0
        else:
            self._back_n = 0
        if self._target_id is None or cur is None:
            self._target_id = best["id"]                # 还没锁定/当前目标没了 ⇒ 认它 ✓
        if self._target_id != best["id"]:
            # 保留原目标（滞回 ✓）—— ⚠ **在全部轨迹里找**（含**滑行中**的 ✓）：目标这一帧
            #   没被检出时，它的**预测位置**照样能继续报（用户 ②："应该记录其为可疑的真实
            #   目标……它其实是符合预测范围内的" ✓✓）。
            for t in self._tracks:
                if t["id"] == self._target_id:
                    best, best_dev = t, (((t["v"][0] - mvx) ** 2
                                          + (t["v"][1] - mvy) ** 2) ** 0.5)
                    break
        self._dev = best_dev
        # ---- 可视化快照：**每个候选**的位置/速度/偏差 + 中位速度（演示窗画箭头用 ✓）----
        vis = []
        for t in mature:
            e = self._viz_of(t)
            e["dev"] = (((t["v"][0] - mvx) ** 2 + (t["v"][1] - mvy) ** 2) ** 0.5)
            vis.append(e)
        self._viz = {"tracks": vis, "median": (mvx, mvy), "dev": best_dev,
                     "tid": self._target_id, "followed": None}
        return (best["p"][0], best["p"][1], best_dev, best["id"], best["a"])

    def motion_viz(self, followed_pos=None):
        """给演示窗的**运动向量快照**（纯读 ✓）：每个候选的 `p/v/dev/tid` + 中位速度 +
        当前"运动最异常"的那个 + **实际跟随的是哪一个**（用报告位置就近认 ✓ 用于对比
        "机制想跟的" vs "真的跟的" ✓）。`followed_pos` = 报告位置（全分辨率 ✓）。"""
        v = dict(self._viz)
        v["typ_area"] = float(self._typ_area)   # ⭐ 标准面积（所有目标面积基本相等 ✓）
        if followed_pos is not None and v.get("tracks"):
            bi, bd = None, None
            for i, t in enumerate(v["tracks"]):
                d = ((t["p"][0] - followed_pos[0]) ** 2
                     + (t["p"][1] - followed_pos[1]) ** 2) ** 0.5
                if bd is None or d < bd:
                    bi, bd = i, d
            if bi is not None and bd is not None and bd <= 40.0:
                v["followed"] = v["tracks"][bi]["tid"]
        return v

    def reseek(self, ts=None):
        """**跳帧（拖动进度条）后复位**：清掉帧缓冲与上一拍时间戳，**保留**目标身份
        （`state/pos/_vel/_raw` ✓）—— 缓冲要 ~0.5s 重填，这期间走滑行分支 ✓ 不会瞎 ✗；
        若还在 init/lost 阶段，连建档候选一起清（重新认一次白色目标 ✓）。"""
        self._buf = []
        self._prev_ts = ts
        self._tracks = []               # 跳帧后位置记忆全失效 ⇒ 清轨迹（会自愈重建 ✓）
        self._target_id = None
        self._sway_n = 0
        self._prev_target_id = None
        self._back_n = 0
        self._cur_box = None
        self._area_nudge = None
        self._area_fresh = False
        self._box_hist = []
        self._box_ok = None
        self._anchor_n = 0
        self._typ_area = 0.0
        self._group.reset()
        self._reg = ShapeRegistry(board_s=getattr(self, "_board_s", 0.0),
                                  board_overlap=getattr(self, "_board_overlap",
                                                        _BOARD_OVERLAP_DEF))
        self._gray_full = None
        self._was_merged = False
        self._merge_hold = False               # ⭐ 融合保持态作废（新一局 ✓）
        self._merge_hold_bid = None
        self._tbox = None
        self._tbox_now = None
        self._pos_prev = None
        self._report_prev = None        # ⭐ 跳帧后位置记忆全失效（否则分离那一拍会用旧起点 ✗）
        self._tbox_merged = False
        self._merge_first = False
        self._merge_split = False
        self._split_now = False
        self._merge_why = None                  # ⭐ 融合诊断（新一局作废 ✓）
        self._merge_why_snap = None
        self._split_why = None                  # ⭐ 分离诊断（同上 ✓ 新一局作废 ✓）
        self._merge_area_series = []            # ⭐ 融合期框面积**时序序列**（新一局作废 ✓）
        self._merge_area_max = None
        self._merge_area_min = None
        self._sep_n = None
        self._sep_vel0 = None
        self._corner_prev = None
        self._corner_prev_ts = None
        self._drift_pos0 = None
        self._drift_gt = (0.0, 0.0)
        self._drift_ts0 = None
        self._drift_last_ts = None
        self._prev_tbox = None
        self._vel_from_box = False
        self._rad = None
        self._rad_samples = []
        self._rad_frozen = False
        self._rad_seen = None
        self._rad_t0 = None
        self._t_hist = []
        self._path = []                 # ⭐ 拖动/跳帧后旧轨迹样本作废 ✓（时间线断了，旧样本
        self._path_cumT = None          #   会以"负时长"混进 500ms 窗 ⇒ 切向拟合被污染 ✗）
        self._grp_prev = None           # ⭐ 上一帧的**群体系位置**（过滤锚点 ✓ 见入样处 ✓）
        self._clamped = False
        self._white_cur = None
        self._obs_lag = True
        if self.state != "track":
            self._cands = []
            self._recap = []
            self._raw = None

    # ---- 对外主入口 ----
    def process(self, bgr, ts=None, dets=None):
        """`dets`（M2b ✓）：本帧检测框 `[[cx, cy, w, h]]`（**全分辨率像素、中心点** ✓）。
        不传 = 纯残差路线（行为与 v2 完全一致 ✓ 合成自检就是这么钉的 ✓）。"""
        g = cv2.cvtColor(bgr, cv2.COLOR_BGR2GRAY)
        small = cv2.resize(g, None, fx=_SCALE, fy=_SCALE)
        self._gray_full = g                        # ⭐ A 层在全分辨率上工作（与检测框同空间 ✓）
        # ⭐ **白块观测**（只跟踪期算 ✓ 白块阶段目标=唯一大白块 ⇒ 直接观测 ✓）
        self._white_cur = self._white_obs(bgr) if self.state == "track" else None
        self._wh = (bgr.shape[1], bgr.shape[0])   # 画面尺寸（钳制用 ✓ 目标不出画面 ✓）
        out = {"state": self.state, "pos": self.pos, "area": self.area,
               "lost_n": self.lost_n, "init": self.init_t}
        # ⭐ **本拍"分离 ⇒ 圆按预测走、跑到框外"** 的标记（每拍复位 ✓ 见 `_step_track` 的分离
        #   分支 ✓）：置上 ⇒ 这一拍**不对外报红框** ✓（否则"绿圈内接红框"必破 ✗ 见 `_out`）。
        self._split_skip = False
        # ⭐ 本拍报告位置**是不是被"边归属落位"挪过**（`_merge_edge_own` ✓）—— 每拍复位 ✓
        #   （诊断/自检用 ✓：这些拍的位置**不是**"按白箭头走"来的 ⇒ 白箭头契约不适用 ✓）。
        #   ⚠ **甲之后**（用户 2026-10-02 ✓）置真的那些拍：内部状态（`self.pos` / `self._raw` /
        #     `_pos_prev`）也**一起**被落位点接管 ✓ ⇒ `pos == raw_pos == _pos_prev` ✓
        #     （见 `_adopt_merge_fix` ✓ 自检里就按这条钉 ✓）。
        self._corner_used = False
        self._tbox_role = ""            # ⭐ 本拍红框候选的身份（`_target_box_state` 会写 ✓）
        if self.state == "init":
            out = self._step_init(bgr, g, small, ts, dets)
        elif self.state == "track":
            out = self._step_track(small, ts, dets)
        # ⭐⭐⭐ **`lost` 已废除**（用户 2026-10-01 ✓ 原话："我们应该只有 融合态、锁定态、预测态" ✓）：
        #   红框丢了 = **预测态**（`track` 内 ✓ 绿圈照画、淡粉框照画），重新捕获 = `_step_track`
        #   内部的后台尝试 `_try_recapture` ✓ —— 不再有会掐掉绿圈的独立 `lost` 状态 ✗。
        #   ⚠⚠ **复活已停用**（用户 2026-10-02 ✓ "停用这个逻辑" ✓）⇒ 丢框期就是**纯预测滑行
        #     + 夹取** ✓（见 `_step_track` 里那处被注释掉的调用与它的归因说明 ✓）。
        # ⭐⭐⭐ **信念约束的统一出口**（用户 2026-09-30 定稿 ✓ 原话："红框代表我们认为真目标在
        #   它里面，这个认知要保持到'分离'信号的出现" ✓）：只要后端还持有那格框（`self._tbox`
        #   ✓ 由 `_step_track` 维护、**丢了也继续持有**直到分离 ✓），**报告位置就必须在框内** ✓。
        #   ⚠⚠ 必须在**所有路径**上生效 ✗：原来只在 `_step_track` 里夹 ⇒ **复活路径
        #   （后台 `_try_recapture` ✓）漏了** ⇒ 实测第 19 帧绿圈跑到框外 12.9px ✗✗
        #   （⚠ 复活已于 2026-10-02 停用 ✓ 这段是历史留档 ✗ 别删）。
        #   `_tbox` 陈旧也没关系 ✓ —— 用户口径就是"**这个认知要保持到分离**" ✓（框给的是**边界
        #   信息** ✓ 比继续按速度滑更可信 ✓）。
        #   ⚠⚠ **拟人平滑**（用户 2026-09-30："不要瞬间调整追踪器去一帧追到圆圈，做一下拟人的
        #   平滑" ✓）：原来是**直接赋值**等于"一帧夹进框" ✗ ⇒ 现在走 `_ease_pos`（每拍走剩余
        #   距离的 `_SMOOTH_K` + 限速封顶 ✓）⇒ 几拍之内自然贴上去 ✓ 不生硬 ✗。
        #   ⭐⭐ **融合红框除外**（用户 2026-10-01 ✓ 原话："融合大红框后，绿圈继续按白箭头的
        #     指示行动" ✓）：融合框是并集、框不住目标一个人 ⇒ **不夹**（位置全由预测决定 ✓）。
        # ⭐⭐⭐ **分离那一拍（已按预测放行 ✓）统一出口也不夹**（用户 2026-10-01 ✓ 原话："任何情况下，
        #   都不允许将绿圈往预测方向的反方向跑" ✓）：否则这条统一出口又把圆拽回 `_tbox`（实测帧 39→40
        #   向左跳 91px、白箭头却指右下 ✗✗）。⚠ 判据用 `_split_skip`（= 分离那一拍 ✓ 由 `_step_track`
        #   置上 ✓），而不是 `_merge_split` ✗ —— 后者在丢框期（无框 ⇒ 不夹）也会为真 ✓，但那时
        #   `_tbox` 已经是 None ⇒ 这条本来就进不来 ✓，用 `_split_skip` 语义更准 ✓。
        if self._tbox is not None and (not self._tbox_merged or self._merge_first) \
                and not getattr(self, "_split_skip", False) \
                and out.get("pos") is not None:
            _raw_before = self._raw
            # ⚠ 这里**不含**"融合并集 ⇒ 边归属落位"那条认知 ✗ —— 它在 `process()` 的**最后一步**
            #   做 ✓（⚠⚠ **甲方案之后**那一步**会**写回 `self.pos` / `self._raw` / `_pos_prev` ✗
            #   —— 用户 2026-10-02 明确要的就是"**绿圆就是我们认为的真目标所处的位置**" ✓ 代价
            #   （经"包含报告位置优先"的**选框**反哺 ⇒ 轨迹可能与旧版分岔 ✗）他已接受 ✓ 见
            #   `_adopt_merge_fix` ✓）。
            _want = self._pos_in_tbox(out["pos"], self._tbox)
            out["pos"] = self._ease_pos(out["pos"], _want, self._dt_last)
            # ⭐⭐ **平滑的硬下限 = 整圆不许出框（内接 ✓ 用户 2026-10-01 定稿）**：
            #   `_ease_pos` 每拍只走 45% ⇒ 当**进入这一拍时位置就在框外**（复活路径
            #   `_try_recapture` 上报的检出位置 ✗ 不经 `_step_track` 的夹取 ✓ ⚠ 复活已停用
            #   2026-10-02 ✓ 但"平滑的硬下限"照旧要留 ✓），渐进期间
            #   圆仍在框外 ✗（实测 GIF 帧 42 ✗）。⇒ 渐进照旧 ✓、结果**夹回内接安全区**
            #   ✓（= `_pos_in_tbox` ✓ 同一把尺 ✓）—— "绿圈与红框内接"没有过渡期 ✗。
            #   ⚠ 原来只夹回**整框**（圆心不出框 ✗）⇒ 圆照样探出（半径那一份没管 ✗）。
            # ⭐⭐⭐ **夹取限速**（用户 2026-10-03 ✓ 原话："动手" ✓ 见 `_clamp_step` ✓）：原来这一行是
            #   **硬夹**（`_pos_in_tbox` ✓ = 一步就把圆塞进内接安全区 ✓ 注释原文"绿圈与红框内接
            #   **没有过渡期**" ✗）⇒ 认的框一远（分离后重新认框 ✓ 帧 48 差 96px ✓）圆就**一步被
            #   拽过去** ⇒ 白线剧裂折角 ✗✗。⇒ 换成**限速版**：每拍最多挪 `本拍该走多远 ×
            #   「夹取限速(步数)」`（B 型 ⇒ 帧率 / 倍速无关 ✓）；**圆已在安全区里 ⇒ 一动不动** ✓
            #   （所以正常跟随**零影响** ✓）。⚠ 代价（用户已知并要）：重新认框那几拍圆可能**短暂
            #   探出框**（渐进贴上 ✓）；`clamp_step_ratio = 0` ⇒ 回硬夹（老行为 ✓）。
            out["pos"] = self._clamp_step(out["pos"], self._tbox, self._dt_last)
            self.pos = out["pos"]
            self._raw = (out["pos"][0] * _SCALE, out["pos"][1] * _SCALE)
            # ⭐ 统一出口**挪过 raw**（信念夹取/拟人平滑 ✓）⇒ 这一拍的样本同样不入曲线
            #    （"夹取只改本帧位置，绝不影响预测" ✓ 见 `_clamp_into_tbox` ✓）。
            if _raw_before is not None and (
                    abs(self._raw[0] - _raw_before[0])
                    + abs(self._raw[1] - _raw_before[1])) > _CLAMP_SKIP_MIN:
                self._clamped = True
        # ⚠⚠ **「融合块缩小 ⇒ 边归属相切」整段已移除**（用户 2026-10-01 ✓ 原话："移除边归属
        #   相切逻辑" ✓）：原来靠"融合峰值 + 圆穿过哪几条边"把圆拉到那几条边相切 ✗ ——
        #   现在只有一条判据（`_tbox_merged` = 面积 ≥ 阈值 × 标准面积 ✓）：融合 ⇒ **不夹**
        #   （位置按预测/白箭头走 ✓）；非融合 ⇒ 照旧内接 ✓。见上面那个统一出口 ✓。
        # ⭐⭐⭐ **漂移期记账 / 漂移纠正速度**（用户 2026-10-01 ✓ 原话："① 先夹取（例如第 17 帧
        #   会与红框上边相切）② 计算「**飘移纠正速度**」=（淡粉色框的「飘移期」到**大红框出现
        #   的融合期的第一拍**的 圆圈与假目标群的 相对位移 / 时间），以「飘移纠正速度」作为
        #   **白色箭头**指导预测圆圈的位移" ✓）。
        #   ⚠⚠ 必须放在**统一出口之后**（= 用"夹取完以后圆圈真正落在哪"的那一拍位置 ✓
        #     —— 用户第二次给的公式就是"（第 17 帧位置 − 第 12 帧位置）/ 时间" ✓ 而"第 17 帧
        #     位置"正是**夹取进红框之后**的位置 ✓；放在 `_step_track` 里会用到夹取前的旧位置 ✗）。
        #   · **漂移期**（红框不在 = 画淡粉色"预测接力框"那段 ✓）：起点记 `pos` + 时刻，
        #     并且**从下一拍起**逐拍累计"与箭头同口径的群体平移"（`_group_vel × dt` ✓ 加工域 ✓）；
        #   · **融合第一拍**（`_merge_first` ✓ 上面已夹过 ✓）⇒
        #     `(pos_now − pos0 − 群体累计) / Δt` = **漂移纠正速度**（加工域 px/s ✓ 与 `_vel_rel`
        #     同域 ⇒ 直接写 ✓）⇒ 白箭头/预测都按它走 ✓。
        #   ⚠ 只算一次（算完消费掉起点 ✓）；没起点 / `Δt` 太短 ⇒ 不动速度（沿用旧值 ✓ 不猜 ✗）。
        # ⭐⭐⭐ **「分离」那一拍 ⇒ 位置 = 上一拍真正画出来的圆 + 本拍速度 × dt**（用户 2026-10-02 ✓
        #   原话："查第 40 帧分离后，为何绿圆没有按照 39 帧的预测位置行进" ✓）。
        #   ⚠⚠ **必须放在下面那个"漂移记账" `if` 之前** ✗✗：分离那一拍 `_tbox_now` 正好是
        #     `None`（红框已经没了 ✓）⇒ 会命中"漂移记账"⇒ 而"融合期滑行"是挂在**同一条
        #     `elif` 链**上的 ⇒ **永远轮不到它** ✗（实测：`_split_now` 明明是 True、位置却
        #     一动不动 ✓ 就是卡在这里 ✓）。
        #   · 起点 = `_report_prev`（= **上一拍最终画出来的那个圆心** ✓ 用户说的"39 帧的位置" ✓）
        #     —— 不能用 `_pos_prev` ✗（**甲之前**它是"未修正"的内部位置 ✓ 实测帧 39 的落位
        #     修正把圆从 x≈150 挪到 **224**、差 **73.7px** ✗ ⇒ 从那儿起滑会跟眼前的圆完全脱节
        #     ✗✗；⚠ **甲之后** `_pos_prev` 已含落位修正 ⇒ 两者基本就是同一个圆 ✓，这里仍写
        #     `_report_prev` 是因为它**直白**：就是"上一拍真正画出来的那个点" ✓）；
        #   · 速度用**本拍**的 `_vel`（分离接管的渐变值 ✓ 既有设计 ✓）；
        #   · 内部状态（`self.pos` / `_raw`）跟着一起走 ✓ 免得下一拍又从头观测拉回来 ✗。
        if (self._split_now and not self._merge_first
                and out.get("pos") is not None and self._pos_prev is not None):
            _d7 = float(self._dt_last) if (self._dt_last and 0 < self._dt_last <= 1.0) else 0.0
            _rp7 = getattr(self, "_report_prev", None)
            _p7 = ((float(_rp7[0]), float(_rp7[1])) if _rp7 is not None
                   else (self._pos_prev[0], self._pos_prev[1]))
            if _d7 > 0:
                out["pos"] = (_p7[0] + self._vel[0] * _d7, _p7[1] + self._vel[1] * _d7)
            self.pos = out["pos"]
            self._raw = (out["pos"][0] * _SCALE, out["pos"][1] * _SCALE)
        if getattr(self, "_tbox_now", None) is None and out.get("pos") is not None:
            # ⚠ 判据必须是 `_tbox_now`（**后端这一拍给没给框** ✓）而不是 `_tbox` ✗ ——
            #   `_tbox` 丢了也继续持有（"保持到分离" ✓）⇒ 拿它判 ⇒ 漂移期永远进不来 ✗
            #   （实测：漂移起点一直没记、白箭头还是老值 ✗）。
            if self._drift_pos0 is None:
                self._drift_pos0 = (float(out["pos"][0]), float(out["pos"][1]))
                self._drift_gt = (0.0, 0.0)
                self._drift_ts0 = ts
                self._drift_last_ts = ts
            else:
                # ⚠ 间隔自己算（`ts − 上一拍 ts` ✓）：`_dt_last` 在有些路径上是 0 / None ✗ ⇒
                #   拿它当间隔会**永远不累加**（实测：群体累计恒 (0,0) ✗）。
                _d5 = (float(ts) - float(self._drift_last_ts)
                       if (ts and getattr(self, "_drift_last_ts", None) is not None) else 0.0)
                if 0.0 < _d5 <= 1.0:
                    _g5 = self._group_vel(_d5)
                    if _g5 is not None:
                        self._drift_gt = (self._drift_gt[0] + float(_g5[0]) * _d5,
                                          self._drift_gt[1] + float(_g5[1]) * _d5)
                self._drift_last_ts = ts
        elif getattr(self, "_merge_first", False):
            # ⭐⭐ **修正要进白箭头**（用户 2026-10-01 ✓ 原话："对绿圈的修正要考虑到白箭头轨迹
            #   预测里（理应白箭头更多朝左）" ✓）：这一拍（融合第一拍 ✓）如果有"边归属落位"，
            #   漂移纠正速度的**终点**就该用**修正后的那个点** ✓（而不是
            #   `self.pos` ✗ —— 那还是修正前的信念位置 ✗）⇒ 白箭头才会跟着朝**修正方向**偏 ✓。
            _fc0 = (self._merge_edge_own(self._tbox, at=self.pos)
                    if self._tbox is not None else None)
            _dfv = self._drift_fix_vel(ts, at=_fc0)
            # ⭐⭐⭐ **先算、不落地**（用户 2026-10-03 ✓ 原话："**把「漂移纠正」挪到闸判定之后**" ✓）：
            #   `_dfv` 原来**当场**就写进 `_vel_rel` ✗ ⇒ 而"落位闸"（`_merge_fix_safe` ✓）读的正是
            #   "**本拍白箭头**" ✗ ⇒ 于是变成**自己批准自己** —— 这一支把箭头改成"**指向落位点**"
            #   （它的终点 `_fc0` 就是那个落位点 ✓）⇒ 闸必判"顺向"⇒ 放行 ✗✗（实测 `10月2日.mp4`
            #   帧 37：白箭头 (−172,−51) 被翻成 (392,−77)、落位位移 56.2px 判"顺向" ⇒ 圆心
            #   一拍走 138px ✗）。⇒ 现在只**暂存** `_pend_drift` ✓、等闸判完再应用 ✓（见下面
            #   "落地"那一段 ✓）—— 闸看到的就还是"**目标真实走向**" ✓（用户口径"对比**本拍**的
            #   白箭头"**一个字都不用改** ✓）。
            self._pend_drift = _dfv
            self._drift_pos0 = None           # 消费掉（只算一次 ✓）
            self._drift_gt = (0.0, 0.0)
            self._drift_ts0 = None
        # ⭐⭐⭐ **融合期（第一拍之后）：圆圈按白箭头运动**（用户 2026-10-01 ✓ 原话："已经夹取
        #   进红框了就让他以白箭头的指示运动，**除非运动到另一边再夹取**" ✓）：
        #   · 位置 = **上一拍位置 + 速度 × dt**（`_vel` = 白箭头 + 群体 ✓ 屏幕上看就是它 ✓）
        #     —— ⚠ 不再用"这一拍的观测位置" ✗（融合框是并集、它的中心会把圆**按在并集中心**
        #     不动 ✗ 实测帧 16~18 圆圈钉在 (305.6,283.3) 三拍不动 ✓ 正是这个病 ✓）；
        #   · **越过边界 ⇒ 再夹一次**（`_pos_in_tbox` 内接安全区 ✓）—— 这就是用户说的
        #     "除非运动到另一边再夹取" ✓。
        #   ⚠⚠ **分离那一拍也要走这里** ✗✗（用户 2026-10-02 ✓ 原话："查第 40 帧分离后，为何
        #     绿圆没有按照 39 帧的预测位置行进" ✓ —— 实测：帧 39 白箭头 ⇒ 预测位移 (+18.5,−25.7)，
        #     而帧 40 实际走了 (−65.1,−30.5)、**x 方向整个反过来** ✗）：
        #     病根 = 这条分支原来要求 `self._tbox_merged` ✓，而**分离那一拍它恰好是 False** ✗
        #     （`_tbox_merged = (tstate == "merged")` ✓ 分离时 tstate="gone" ✓）⇒ 滑行分支进不去
        #     ⇒ 位置**落回观测路径**、被这一拍的观测拽走 ✗✗（上方注释却写着"分离那一拍照走滑行
        #     分支"—— 注释与实现不一致 ✓ 这次对齐 ✓）。
        #   ⚠ 判据用 `_split_now`（**有框但塌缩** ✓）而**不是** `_merge_split` ✗ —— 后者在丢框期
        #     也为真 ✓，那会把"丢框期"的行为一起改掉（不是这次要动的 ✓ 见 `__init__` 的说明）。
        elif (self._tbox is not None and self._tbox_merged and not self._merge_first
              and out.get("pos") is not None and self._pos_prev is not None):
            # ⚠ **分离那一拍不走这里** ✗ —— 它已在上面单独处理（那条必须在"漂移记账"之前 ✓）。
            _d6 = float(self._dt_last) if (self._dt_last and 0 < self._dt_last <= 1.0) else 0.0
            # ⭐⭐ **滑行起点**（用户 2026-10-02 ✓ 原话："查第 40 帧分离后，为何绿圆没有按照
            #   39 帧的预测位置行进" ✓）：
            #   · 融合期（保持）⇒ `_pos_prev`（⚠ **甲之后**它就是上一拍**落位后的那个圆** ✓
            #     见 `_adopt_merge_fix` ✓ —— 老口径"未修正的位置 / 不让修正渗进内部状态"已被
            #     用户 2026-10-02 明确修订 ✓）；
            #   · **分离那一拍** ⇒ 改用 `_report_prev`（= **上一拍真正画出来的那个圆** ✓）✗✗
            #     —— 实测帧 39 的落位修正把圆从 x≈150 挪到 **224**（差 **73.7px** ✓），
            #     而从"未修正位置"起滑 ⇒ 帧 40 圆跟用户眼前那个圆**完全脱节** ✗✗
            #     （实测位移 (−65.1,−30.5)、而 39 帧白箭头指着 (+18.5,−25.7) ✗）。
            if _d6 > 0:
                out["pos"] = (self._pos_prev[0] + self._vel[0] * _d6,
                              self._pos_prev[1] + self._vel[1] * _d6)
            _cl6 = self._pos_in_tbox(out["pos"], self._tbox)
            if _cl6 != tuple(out["pos"]):
                out["pos"] = _cl6
                self._clamped = True               # 夹过 ⇒ 这一拍的位置不算"目标自己走的" ✓
            self.pos = out["pos"]
            self._raw = (out["pos"][0] * _SCALE, out["pos"][1] * _SCALE)
        # ⭐⭐⭐ **`_pos_int` = 本拍"落位修正之前"的报告位置**（= 滑行 / 夹取后的最优估计 ✓）。
        #   ⚠⚠ **甲方案（用户 2026-10-02 ✓）之后**：`_pos_prev` **不再**固定用这个"未修正"的位置
        #     ✗ —— 命中落位 ⇒ 用**落位后的那个圆** ✓（见下面 `_pos_prev` 那一行 ✓；老纪律
        #     "修正绝不渗进内部状态"已被用户明确修订 ✓ 见 `_adopt_merge_fix` ✓）。
        _pos_int = out.get("pos")
        # ⭐⭐⭐ **融合期的圆落位 =「边归属」**（用户 2026-10-02 ✓ 五档 a~e ✓ 见
        #   `_merge_edge_own` ✓；那套"两段式（就近内接 + 顶边贴边）"已被它取代 ✓）。
        #   ⚠⚠⚠ **纪律变更 = 甲方案（用户 2026-10-02 ✓ 原话："**我期望绿圆就是我们认为的真目标
        #     所处的位置**" + "**改成甲试试 ——『落位点就是我们认定的真目标位置』⇒ 内部也该认它**"
        #     ✓）**：**从"只改报告位置"改成"内部一起认"** ✗✓ —— 命中落位 ⇒ `self.pos` /
        #     `self._raw` / `_pos_prev` 全部 = 落位点 ✓（`_adopt_merge_fix` ✓）⇒ **绿圆 ≡
        #     追踪器心里那个位置** ✓、不再有"圆回跳"✗。
        #   📌 **原纪律的原委留档**（✗ 别丢 —— 这是甲要付的代价）：当年"只改报告位置"是为了不让
        #     修正**经选框反哺**（`_target_box_state` 的"**包含报告位置优先**" ✓ = 用户口径"目标
        #     踩着的那格框" ✓）—— A/B 实测过"直接落位"那版：第 16 帧把圆挪 24.2px ⇒ 第 21 帧
        #     选中的框就换了 ⇒ 到第 27 帧圆跑到 (481.3,317.1)、红框成了另一格的 (462.0,372.0) ✗✗；
        #     而"只改报告位置"⇒ 其余逐帧与改动前一致 ✓。**用户已知代价、明确要试甲** ✓ ⇒ 现在
        #     **接受轨迹分岔** ✓（本轮 A/B 的逐帧差异见汇报 ✓）。
        #   ⚠ 为什么用 `self._tbox`（**持有**的那格 ✓）而不是 `_tbox_now`：用户的说法就是
        #     "**红框在**的时候"（画面上有红框 = `_tbox` 有值 ✓）；框真丢了（`_tbox=None`）
        #     就没有"包围假目标的大红框"可谈了 ✓ 不修正 ✓。
        #   ⚠ 为什么是"**直接落位**"不是"慢慢磨"（`_ease_pos` ✗）：这条是**精确的信念几何关系**
        #     （并集里除假目标之外的那一角 ✓ 与当年"相切落位"同性质 ✓），而且**并集常常只持续
        #     一两拍**（实测第 27 帧那个并集下一拍就没了 ✗）⇒ 渐进式根本磨不到位
        #     （实测 45%/拍 ⇒ 第 27 帧离左上角还差 **30.0px** ✗✗ 而用户要的是"**修正到**左上角" ✓）。
        _fc = None
        _adopted = False
        if _pos_int is not None and self._tbox is not None:
            # ⭐⭐⭐ **「边归属」落位**（用户 2026-10-02 ✓ 五档 a~e ✓）—— 取代旧"就近相接
            #    （仅第一拍）+ 顶边贴边（基线推距）"两段式 ✓：新机制**每拍独立成立** ✓
            #    不需要基线、也不需要第一拍特判 ✓。非并集 ⇒ `None` ⇒ 上面"按预测滑行 +
            #    内接夹取"原样生效 ✓（= 用户"之后每拍绿圆根据轨迹预测走" ✓）。
            _fc = self._merge_edge_own(self._tbox, at=_pos_int)
            # ⭐⭐⭐ **「融合框挑选允许倒退距离」改到"落位那一刻"判**（用户 2026-10-03 ✓ 原话：
            #   "安全闸判的是『落位会不会把圆心往白箭头的反方向拽』**这一条可以移除了**，我们
            #   现在用『**融合框挑选允许倒退距离**』判定" ✓）—— 语义从"**候选框过不了这道闸就
            #   整个淘汰**"✗ 改成"**落位会逆着白箭头拽太远就不落位**"✓：
            #   · 框照样当选 ⇒ 不会再出现"唯一的融合框被闸淘汰 ⇒ 判分离"✗✗（实测 `10月1日.mp4`
            #     帧 54：延续格与上一拍红框重叠 0.91、仍包住参照砖、`_hold_active`=True，只因
            #     **落位预演**判"不安全"就被挡 ⇒ `_first_ok` 空 ⇒ 判分离 ✗✗ = 用户点名 ✓）；
            #   · 判据本身**一字未改**（仍是"落位位移在白箭头方向上的分量 ≥ −允许量" ✓ 见
            #     `_merge_fix_safe` ✓）⇒ 只是**用在哪一步**变了 ✓；
            #   · 判不出方向（白箭头 ≈ 0 ✓）⇒ 回 True ⇒ 照旧落位 ✓（不猜 ✗）。
            if _fc is not None and not self._merge_fix_safe(self._tbox):
                _fc = None
            # ⚠⚠ **分离那一拍不修正** ✗（用户 2026-10-01 ✓ 原话："大红框变成与登记框重叠的
            #   检出框，这是分离的信号，绿圈应该按上一帧的预测走" ✓）：一旦红框塌缩成"假目标
            #   自己那一格"，再把它修正到那格的对角 = **把圆钉到假框上** ✗（真目标已经走了 ✓）
            #   ⇒ 放它按预测滑行 ✓（`_merge_split` 那一拍照走 merge 滑行分支 ✓ 只是不落角 ✓）。
            if _fc is not None and not self._merge_split:
                out["pos"] = _fc
                self._corner_used = True      # ⭐ 本拍位置是"修正"来的（不是按白箭头走 ✓）
                # ⭐⭐⭐ **甲：落位点 ⇒ 内部状态一起认**（用户 2026-10-02 ✓ 见 `_adopt_merge_fix` ✓）
                _adopted = self._adopt_merge_fix(out) is not None
        if _pos_int is not None:
            # ⭐ 起点给下一拍"按白箭头走"用 ✓：**命中落位 ⇒ 用落位后的那个圆** ✓（甲 ✓ —— 否则
            #   下一拍会从"心里那个未修正的点"起滑 ⇒ 与眼前的圆脱节 ✗✗ = 老分叉病 ✓）；没落位
            #   ⇒ 照旧用未修正的位置 ✓（夹取 / 滑行那些拍两边本来就一致 ✓）。
            self._pos_prev = out["pos"] if _adopted else _pos_int
        # ⭐⭐⭐ **「漂移纠正」现在在这里落地**（用户 2026-10-03 ✓ 原话："**把「漂移纠正」挪到闸
        #   判定之后**" ✓ 见上面 `elif self._merge_first:` 那段的说明 ✓）：落位闸已经判过 ⇒ 它看到
        #   的"本拍白箭头"是**目标真实走向**（没被这一支改写过 ✓）；这里才真正改写 `_vel_rel` 并
        #   同步 `_vel`（"绝对 = 自身 + 群体" ✓）。⚠ 必须仍在 `out["vel"]` 回写**之前** ✓（回写在
        #   下面 ✓ 位置安全 ✓）；`_dfv` 拿不到（漂移期没到 / 点算不出 ✓）⇒ 什么都不做 ✓ 不猜 ✗。
        if self._pend_drift is not None:
            # ⭐⭐ **白箭头限幅**（用户 2026-10-03 ✓ "给白箭头加限幅（治本）" ✓）：实测
            #   `10月2日.mp4` 帧 37 就是**这一支**给出的 (1037,−204) ✗（它按"漂移起点 → 修正终点
            #   ÷ 漂移时长"算 ⇒ 时长很短时能爆 ✓）⇒ 限到 400 以内 ✓。
            self._vel_rel = self._rel_cap(self._pend_drift)
            _d5 = float(self._dt_last) if (self._dt_last and 0 < self._dt_last <= 1.0) else 0.1
            _g5 = self._group_vel(_d5) or (0.0, 0.0)
            self._set_vel(self._vel_rel[0] + float(_g5[0]),
                          self._vel_rel[1] + float(_g5[1]))
            self._pend_drift = None

        # ⭐⭐⭐ **修正进白箭头（逐帧 ✓）**（用户 2026-10-01 ✓ 原话："在第26帧的白箭头没有看到
        #   第25帧→26帧位置修正带来的轨迹预测变化" ✓）：融合期圆被钉到"对角修正点"上，这个点每拍
        #   跟着框/群体走 ⇒ 它的**位移**就是"目标按信念在怎么动" ✓ ⇒ 用它（扣掉群体 ✓）更新自身
        #   速度 ✓ —— 否则融合期速度**冻结**（事实 6 ✓）⇒ 白箭头死活不反映修正 ✗✗
        #   （实测 9月30日(1) 第 26 帧：圆 25→26 被修正到左 46px、白箭头还指着旧方向 ✓）。
        #   ⚠ EMA 平滑（`_VEL_KEEP` ✓）防止"修正点换边"那一拍的 46px 跳变把速度打飞 ✗。
        if _fc is not None and ts is not None:
            _cp = getattr(self, "_corner_prev", None)
            _cpt = getattr(self, "_corner_prev_ts", None)
            if _cp is not None and _cpt is not None:
                _dc = float(ts) - float(_cpt)
                if _dc > 0.0:
                    _gv9 = self._group_vel(_dc)
                    if _gv9 is not None:
                        _nv9 = ((_fc[0] - _cp[0]) / _dc, (_fc[1] - _cp[1]) / _dc)
                        _rv9 = (_nv9[0] - _gv9[0], _nv9[1] - _gv9[1])
                        self._vel_rel = self._rel_cap(
                            (self._vel_rel[0] * _VEL_KEEP + _rv9[0] * (1.0 - _VEL_KEEP),
                             self._vel_rel[1] * _VEL_KEEP + _rv9[1] * (1.0 - _VEL_KEEP)))
                        self._set_vel(self._vel_rel[0] + _gv9[0], self._vel_rel[1] + _gv9[1])
            self._corner_prev = tuple(_fc)
            self._corner_prev_ts = ts
        else:
            self._corner_prev = None
            self._corner_prev_ts = None

        # ⭐⭐⭐ **分离后的速度"平滑接管"**（用户 2026-10-01 ✓ 原话："分离那一拍速度从冻结值
        #   **硬切**到实测值，改成**平滑接管**" ✓）：融合期速度是**冻结**的（事实 6 ✓）⇒ 分离
        #   那一拍突然又信实测 ⇒ `vel_rel` **一帧断崖**（实测 `9月30日(1).mp4` 显示帧 22：
        #   `(65.3,137.0)` → `(2.3,36.4)` ⇒ 白箭头 **33px → 8px** ✗✗ 看着就是"箭头丢了" ✓）。
        #   做法：分离后 `_SEP_TAKE_N` 拍里按 `w=(n+1)/N` 让实测值**逐渐接管**冻结值 ✓
        #   （第 1 拍只吃 1/3、第 2 拍 2/3、第 3 拍全量 ✓）。
        #   ⚠⚠ **只接管"自身分量"** ✓：`_vel` = 自身 + 群体 ⇒ 把**差值**补进 `_vel` 即可 ✗
        #     别去动群体那一份（它永远取**当拍实测** ✓ 不滞回 ✓）。
        #   ⚠ 放在**这里**（`_step_track` 之后 ✓）= 实测已经更新完了 ⇒ 接管的是"这一拍的新值" ✓。
        self._sep_takeover()
        # ⭐⭐⭐ **白箭头 = 圆心的曲线预测**（用户 2026-10-01 定稿 ✓ 原话："**箭头不能来自框，
        #   它来自圆心的曲线预测**" + "**曲线预测优先**：把覆盖放到最后（反向旋转之前）——
        #   箭头永远 = 曲线预测那一支；修正/接管只影响圆心位置，不再改箭头" ✓）。
        #   做法：`_path_vel` = `_path_pred`（切向 + 曲率 ✓ 见它 docstring）那一小步 ÷ dt ✓。
        #   ⚠⚠ **必须放在最后**（`_sep_takeover` 之后 ✓）：放中间会被下面这些**逐拍改写**盖掉 ✗
        #     —— ① 融合期"对角修正"的 EMA（`_fc` 有值时 ✓）② 分离后的"平滑接管" ✓
        #     （实测 `9月30日(1).mp4` 帧 11：曲线预测 (214.6,127.1) ⇒ 步长 (21.5,12.7) ✓
        #      与圆心实际走的 (20.2,12.5) 几乎一样 ✓✓，但被①盖成了 (115.5,20.9) ✗ 差 13.6px）；
        #   ③ 本拍"框相对群体/缺口首尾"那条（`_vel_src in ("box","gap")` ✓ —— **框是假目标、
        #      圆心是真目标** ⇒ 拿框的速度当箭头是张冠李戴 ✗ 用户当场看出"第11帧白箭头不对" ✓）。
        #   ⚠ `_path_vel` 给不出（样本不够 / 没 `_raw` ✓）⇒ **保持原值**（不硬造 ✗）。
        #   ⚠⚠ 位置：**`_anti_group_vel` 之前**（反向旋转是最后一步 ✓ 用户 2026-10-01 设计要求 ✓）。
        _pv = self._path_vel(self._dt_last)
        if _pv is not None:
            # ⭐⭐ **模长压到 `_V_MAX`**（与 `_set_vel` 同一把尺 ✓）：曲线预测偶尔给出荒谬的大速度
            #   （实测帧 31：**798 px/s** ✗ ⇒ 圆心"每帧走 80px"✗✗ 一路飞出画面 ✗ = 用户点名的
            #   "第 36 帧已经差的很远了" ✓）。方向不变、只压模长 ✓ —— 超出部分圆心的限速器
            #   根本走不出来 ✓ "白箭头 = 圆心真的会走多少"仍成立 ✓。
            _vsp = math.hypot(float(_pv[0]), float(_pv[1]))
            if _vsp > float(_V_MAX):
                _k6 = float(_V_MAX) / _vsp
                _pv = (float(_pv[0]) * _k6, float(_pv[1]) * _k6)
            # ⭐⭐ **白箭头限幅**（用户 2026-10-03 ✓ "给白箭头加限幅（治本）" ✓）：上面那层是
            #   `_V_MAX`(600) 的"兜底防灾" ✓ 这里再按既有口径 `_REL_V_MAX`(400) 收紧到
            #   "自身分量只该是小量" ✓（两者同向、不冲突 ✓）。
            _pv = self._rel_cap(_pv)
            self._vel_rel = _pv
            _gv8 = self._group_vel(float(self._dt_last)) or (0.0, 0.0)
            self._set_vel(_pv[0] + _gv8[0], _pv[1] + _gv8[1])
        # ⭐⭐⭐ **试验型：自身速度旋转到「群体速度的反向」**（用户 2026-10-01 ✓ 见 `_anti_group_vel` /
        #   `_ANTI_GROUP_VEL` ✓）—— 放在 `_sep_takeover` **之后**、速度回写 `out` **之前** ⇒ 它作用在
        #   "本拍最终生效值"上，且回写出来的就是旋转后的那一支 ✓（白箭头 = 圆圈真的会走多少 ✓）。
        self._anti_group_vel()
        # ⭐⭐⭐ **分离期白箭头模长上限**（用户 2026-10-03 ✓ 新配置「真目标预测最大速度倍率」✓）：
        #   放在**最后**（`_anti_group_vel` 只旋转、保模 ✓ ⇒ 压过的模长不会被它撤销 ✓）、
        #   且**回写 `out` 之前** ✓ ⇒ 演示窗拿到的就是压过的那支 ✓（白箭头 = 圆真的会走多少 ✓）。
        self._sep_vel_cap()

        # ⭐⭐⭐ **把"真正生效的速度"同步回 `out`（修掉"箭头晚一拍" ✓ 用户 2026-10-01 ✓）**：
        #   `out["vel"] / out["vel_rel"]` 是在 `_step_track` 里、**打包那一刻**的快照 ✗ ——
        #   而**漂移纠正速度**是之后在统一出口才写进 `self._vel_rel` 的（`_merge_first` 分支 ✓），
        #   `_try_recapture` 复活（⚠ 已停用 2026-10-02 ✓ 留档 ✓）/ 上面的分离接管也会改写它
        #   ⇒ 快照就**过期**了 ✗。
        #   **实测**（`10月1日.mp4` 显示帧 27，融合第一拍 ✓）：圆圈已经按新速度 `(-84.2,48.6)`
        #   走了，白箭头画的还是旧值 `(-4.8,14.0)` ⇒ 晚整整一拍（帧 28 才跟上）✗✗ ——
        #   与用户口径"**白箭头 = 圆圈真的会走多少**"直接冲突 ✗。
        #   ⇒ 收尾统一按"本拍最终生效值"回写 ✓（连控制器前馈 `Runner:ctl.step(vel=…)` 也一起对上了 ✓）。
        if "vel" in out:                           # 有这个键才回写（不凭空造字段 ✓）
            out["vel"] = tuple(self._vel)
            out["vel_rel"] = tuple(self._vel_rel)
        # ⭐ **本帧最终报告位置**（含对角修正 ✓）⇒ 给下一拍"分离那一拍按白箭头走"当起点 ✓
        #   （用户 2026-10-01 ✓ 原话："任何情况下，都不允许将绿圈往预测方向的反方向跑" ✓）。
        self._report_prev = out.get("pos")
        # ⭐⭐⭐ **"上一拍到底有没有红框"**（用户 2026-10-03 ✓ 「选框速度门」用它划作用域 ✓）：
        #   ⚠ 必须**专门记** ✗ —— `_prev_tbox` / `_tbox_last` 在**丢框期会留着上一次的框** ✓
        #   （那是给"同一格 / 变大"当比较基准用的 ✓）⇒ 拿它们判"上一拍有没有框"永远为真 ✗✗
        #   （实测帧 64：`_prev_tbox` = (252.2,337.7) ✓ 而帧 63 其实没红框 ✗ ⇒ 门被整条绕过 ✗）。
        self._had_tbox_prev = (self._tbox is not None)
        # ⭐⭐⭐ **存"上一拍的白箭头"**（用户 2026-10-03 ✓ 原话澄清："『对比**上一拍的白箭头预测
        #   位置**』意思是**假设本拍按上拍预测走了之后**" ✓）：落位闸（`_merge_fix_safe` ✓）要用
        #   它算基准 = `上拍圆心 + 上拍白箭头 × dt` ✓ —— ⚠ 存的是**这一拍结束时**的值（= 下一拍的
        #   "上一拍"✓），且在所有速度改写（漂移纠正 / 修正进白箭头 / 限幅 ✓）**之后** ✓。
        self._vel_rel_prev = (float(self._vel_rel[0]), float(self._vel_rel[1]))
        # ⭐⭐⭐ **KF 影子模式**（用户 2026-10-03 ✓ 原话："做 KF影子模式 …… 可以**自由选择算法分支
        #   以防污染当前的进展**" ✓ 见 `show_kf` ✓）：把**经典链条这一拍算出来的位置**当观测喂给
        #   卡尔曼 ✓ —— ⚠ **一个字都不改 `out["pos"]`** ✓✓（影子就是影子 ✗），只在 `out["kf"]`
        #   里带上 KF 的位置/速度/**新息**（观测 − 先验 ✓ KF 里最值钱的诊断量 ✓）与"与经典的差" ✓。
        #   `dt` 用**真实时间戳之差** ✓ ⇒ 帧率 / 播放倍速无关 ✓（与 B 型归一化同一纪律 ✓）。
        if (self.show_kf or self.kf_pos) and out.get("pos") is not None:
            if self._kf is None:
                self._kf = KF4()
            _kdt = None
            if self._kf_ts is not None and ts is not None:
                _kdt = float(ts) - float(self._kf_ts)
            _kr = self._kf.step(float(out["pos"][0]), float(out["pos"][1]), _kdt)
            self._kf_ts = ts
            _kp = _kr["pos"]
            _kd = (None if _kp is None
                   else math.hypot(_kp[0] - float(out["pos"][0]),
                                   _kp[1] - float(out["pos"][1])))
            _ki = math.hypot(_kr["innov"][0], _kr["innov"][1])
            if len(self._kf_acc) > 4000:            # 长视频有界（影子日志别吃内存 ✗）
                del self._kf_acc[:len(self._kf_acc) - 4000]
            self._kf_acc.append((float(_kd or 0.0), float(_ki), float(_kr["nis"])))
            # ⭐⭐⭐ **群体系锚定**（用户 2026-10-03 ✓ 原话："**2. KF 青色线没有像白线一样利用群体
            #   速度『刻在背景板上』**" ✓）：白线（`_path_viz` ✓）的做法是"每个历史点**扣掉它自己
            #   那拍的累计群体平移** ✓ 渲染时统一加回**当拍**平移" ✓ ⇒ KF 青线照同一套来 ✓：
            #     · `pos_grp` = KF 位置 − `2×_path_cumT`（**群体系**坐标 ✓ 加工域 ✓ 与白线同域 ✓
            #       —— `_path_cumT` 是**半域** ⇒ ×2 对齐 ✓ 见 `_path_viz` 同一算法 ✓）；
            #     · `cum2` = `2×_path_cumT`（当拍的 ✓ 给前端"加回"用 ✓）。
            #   ⇒ 前端把历史点 `pos_grp + cum2_当拍` 连起来 ⇒ 那条青线就**跟着假目标群一起动** ✓
            #   （不再跟着相机 ✗ 与白线同一视觉口径 ✓）。
            _kcum = getattr(self, "_path_cumT", None) or (0.0, 0.0)
            _kcx, _kcy = 2.0 * float(_kcum[0]), 2.0 * float(_kcum[1])
            out["kf"] = {"pos": _kp, "vel": _kr["vel"], "innov": _kr["innov"],
                         "nis": float(_kr["nis"]), "d_classic": _kd,
                         "pos_grp": (None if _kp is None else (_kp[0] - _kcx, _kp[1] - _kcy)),
                         "cum2": (_kcx, _kcy)}
            # ⭐⭐⭐ **「KF 位置驱动」在这里落地**（用户 2026-10-03 ✓ 原话见 `kf_pos` ✓）：算完就把
            #   位置换成 **KF 估的那个** ✓ 并把内部状态一起认（`self.pos` / `_raw` / `_pos_prev`
            #   / `out["raw_pos"]` ✓ —— 与 `_adopt_merge_fix` 同一套"绿圆 ≡ 内部信念"手法 ✓）。
            #   ⚠ **必须在这里**（而不是更早/更晚）✗✗：更早 ⇒ 会被后面的落位/夹取/白线历史盖掉 ✗；
            #     更晚（比如 `return out` 之后）⇒ **白线历史（紧跟本段 ✓ 见下）已经按经典位置记过
            #     点** ✗✗ ⇒ 白线画的还是经典轨迹、与眼前的绿圆对不上 ✗（那份历史的判据就是
            #     `out["pos"]` ✓）。⇒ 覆盖放在这里 ⇒ 白线 / 下一拍 / 控制器**全部**跟着 KF 走 ✓。
            #   ⚠ `_clamped = True` ✓：这一跳是"估计器给的"、不是目标自己走的 ✗ ⇒ 轨迹样本照旧
            #     不入窗（与夹取/落位同一把尺 ✓ 见 `_CLAMP_SKIP_MIN` 与 `_keep` ✓）。
            if self.kf_pos and _kp is not None:
                out["pos"] = (float(_kp[0]), float(_kp[1]))
                self.pos = out["pos"]
                self._raw = (out["pos"][0] * _SCALE, out["pos"][1] * _SCALE)
                if "raw_pos" in out:
                    out["raw_pos"] = out["pos"]
                self._pos_prev = out["pos"]
                self._clamped = True
        # ⭐⭐ **白线 = 每拍圆心连起来**（用户 2026-10-01 定稿 ✓ "没有任何其他逻辑" ✓）：这里记的是
        #   本拍**最终报告位置**（= 绿圈圆心画的点 ✓ 含对角修正 ✓）⇒ 演示窗直接连折线 ✓。
        #   ⚠ 只在有位置时记（没位置那一拍没点可连 ✓）；只做**长度截断**（`_HIST_N` ✓ 防长视频吃内存 ✓）。
        if out.get("pos") is not None:
            self._hist_pos.append((float(out["pos"][0]), float(out["pos"][1])))
            # ⭐⭐ 同步记**群体系**那份（= 报告位置 − 该拍累计群体平移 ✓）：`_path_cumT` 是
            #   半域 ✓（`_step_track` 里维护 ✓）、报告位置是加工域 ✓ ⇒ 差值 ×2 对齐 ✓。
            #   `dt` 无效那一拍 `_path_cumT` 不动 ✓（= 本拍没走钟 ✓ 群体没动 ✓ 锚照样成立 ✓）。
            _pcum = getattr(self, "_path_cumT", None) or (0.0, 0.0)
            self._hist_grp.append((float(out["pos"][0]) - 2.0 * float(_pcum[0]),
                                   float(out["pos"][1]) - 2.0 * float(_pcum[1])))
            if len(self._hist_pos) > _HIST_N:
                del self._hist_pos[:len(self._hist_pos) - _HIST_N]
            if len(self._hist_grp) > _HIST_N:
                del self._hist_grp[:len(self._hist_grp) - _HIST_N]
            # ⚠⚠ **必须同步刷 `out["path_pts"]`** ✗：那份是 `_step_track` 里**打包那一刻**的快照
            #   （早于本行 ✓）⇒ 不刷就是**晚一拍**（白线末端永远差一个点 ✗ 实测 ✓）。
            #   ⚠⚠⚠ **必须刷成"刻在背景板上"的那份** ✗✗（用户 2026-10-02 ✓："白线像素应该随着
            #     目标群一起运动，**现在是跟着相机，错了**" ✓）—— 上一轮我把 `_path_viz()` 改成
            #     群体系锚定了 ✗ 却漏了这里还在写 `_hist_pos`（**屏幕系** ✗）⇒ 演示窗读到的还是
            #     跟着相机的旧线 ✗✗。⇒ 统一走 `_path_viz()` ✓（群体系 + 当前累计平移 ✓）。
            if "path_pts" in out:
                out["path_pts"] = self._path_viz()
        return out

    # ---- M2b：lost 后的**检测复活**（连续稳定才复活 ✓ 防复活到干扰 ✗）----
    def _try_recapture(self, dets, dt, ts, mt):
        """⭐⭐⭐ **预测态太久后的后台重新捕获**（用户 2026-10-01 ✓ 重构：`lost` 已废除、并进
        **预测态** ✓）。红框连丢 `> _LOST_AFTER` 帧后，在**继续预测（绿圈照画、淡粉框照画）**
        的同时，后台尝试把目标找回来：找到就复活回锁定（返回 True），找不到继续预测（False ✓）。

        ⚠⚠⚠ **已停用**（用户 2026-10-02 ✓ 原话："**停用这个逻辑**" ✓）：`_step_track` 里那处
          调用**已被注释掉** ✗（见它周围的说明 ✓）。**本方法与下面两条路、连同
          `_recap` 队列 / `_RECAP_*` / `_LOST_AFTER` 常量全部原样保留** ✓ —— 要接回就把那两行
          放开即可 ✓。
          停用原因（实测归因 ✓）：路① 用的是 `_update_tracks` 的**当拍运动冠军** `mt`，而它
          **没有任何**"是不是当前认定的目标（`_target_id`）／离预测多远／连续几拍"的门 ✗
          ⇒ 实测 `10月1日.mp4` 显示帧 69 被**画面左缘一条 73×21 的干扰**骗走
          （`mt=(0.0,450.4)`）⇒ 圆心走了个与白箭头几乎垂直的 44.6px 位移 ✗✗。
        ⚠ 绝不碰 `self.state`（一直是 `track` ✓）—— 复活只是把位置/速度/面积拽回目标 ✓。
        ⚠ `mt` = `_step_track` 开头已经算好的运动异常候选（复用 ✗ 别重复调 `_update_tracks` ✓）。
        两条复活路：① 运动判据优先（`mt` 非空 ✓ "有东西运动与众不同"）；② 检测框连续
        `_RECAP_N` 帧"稳定移动"（防复活到干扰 ✗）。
        """
        # ① 运动判据优先（隔着别的图形/丢了很久，只要"运动与众不同"就能认回来 ✓）
        if mt is not None:
            self._set_raw((mt[0] * _SCALE, mt[1] * _SCALE), dt)   # 复活也限速 ✓
            self.area = mt[4]
            self._recap = []
            self.lost_n = 0
            self.pos = self._report_pos(dt)   # ⭐ 报告位置也**限速**（第③问 ✓）
            return True
        pred = self._raw
        if pred is None or not dets:
            self._recap = []
            return False
        # ② 检测框连续稳定
        fx, fy = pred[0] / _SCALE, pred[1] / _SCALE
        best, best_d = None, None
        for cx, cy, _w, _h in dets:
            d = ((cx - fx) ** 2 + (cy - fy) ** 2) ** 0.5
            if d <= _RECAP_GATE and (best is None or d < best_d):
                best, best_d = (cx, cy), d
        if best is None:
            self._recap = []
            return False
        # 门②：与上一帧框**在动且不跳变**（干扰与背景相对静止 ⇒ 位移≈0 被挡 ✓；
        #   位置突变的框是认错对象 ⇒ 按速度上限挡 ✓）
        if self._recap:
            last = self._recap[-1]
            move = ((best[0] - last[0]) ** 2 + (best[1] - last[1]) ** 2) ** 0.5
            vmax = max(_RECAP_MOVE_MIN,
                       (abs(self._vel[0]) + abs(self._vel[1])) * (dt or 0.2) * 3.0)
            if not (move >= _RECAP_MOVE_MIN and move <= vmax):
                self._recap = [best]     # 断了重记（要求**连续**稳定 ✓）
                return False
        self._recap.append(best)
        if len(self._recap) >= _RECAP_N:
            self._raw = (best[0] * _SCALE, best[1] * _SCALE)
            if len(self._recap) >= 2 and dt:
                a, b = self._recap[-2], self._recap[-1]
                self._set_vel((b[0] - a[0]) / dt, (b[1] - a[1]) / dt)
            self.pos = self._report_pos(dt)   # ⭐ 报告位置也**限速**（第③问 ✓）
            self.lost_n = 0
            self._recap = []
            return True
        return False

    # ---- 建档：白色实体 + "它动了" ----
    def _reg_build_now(self, dets, ts):
        """⭐⭐⭐ **转 track 的这一拍就把登记表建起来**（用户 2026-10-02 ✓ 原话："第3帧就应该
        将所有非真目标的检出框登记，不然第4帧真目标右下的假目标框就丢了" ✓）。

        · 病根：原来建表等到**下一拍**的 `_step_track` ✗ —— 而**这一拍**（白块刚锁定 ✓）
          所有砖都是**干净独立**的检出 ✓；到下一拍，贴着目标的砖已经**跟白块并成一格检出**
          ✗（没有独立检出 ⇒ 建表漏掉它 ✗），等它几拍后露出来又被「绿圈门」挡住 ✗✗
          ⇒ 那块砖**永远登记不上** ✗（= 用户看到的"右下假目标框丢了" ✓）。
        · 做法：表还空着 + 有检出 ⇒ 立刻走一次 `reg.step`（`t=None` 首拍不平移 ✓；
          `origin=self.pos` ⇒ **铁律自动排除真目标那格** ✓；`rad=0` ⇒ 绿圈门不生效 ✓
          —— 建表这一拍要的就是"除真目标全登记" ✓）。尺寸带/宽高比/上板判据照旧 ✓
          （碎片仍进不了表 ✓ 贴边的砖仍不上板 ✓）。
        """
        if self._reg.entries or not dets:
            return                                   # 表已建 / 没检出 ⇒ 无事可做 ✓
        self._reg.step(dets, t=None, ts=float(ts or 0.0),
                       origin=self.pos, rad=0.0, wh=self._wh)

    def _step_init(self, bgr, g, small, ts, dets=None):
        # ⚠ 建档期间也把帧喂进缓冲 ⇒ 一进 track 就有足够历史算双窗 ✓
        self._buf.append(small)
        # ⭐⭐ **建档阶段也要维护检测轨迹**（用户 2026-09-30 第②问 ✓ 现场实测：第 6-12 帧
        #   "轨迹 0 条" ⇒ 那个阶段框一漏检就**什么都没得显示** ✗ —— 用户看到的"绿圈右边
        #   速度向量消失"正是这个 ✓）。建档期就养着轨迹 ⇒
        #     ① 一进 track 立刻有速度（不用等 `_TRK_MIN_AGE` 帧 ✓）；
        #     ② 漏检时能画出**粘滞**箭头（老写法在 init 期根本没有轨迹 ⇒ 无从画起 ✗）；
        #     ③ 群体速度互相修正（第③问 ✓）在建档期就生效 ✓。
        #   ⚠ 与 track 段用**同一个** `_prev_ts`（这里也推进它 ✓）⇒ dt 不重复计 ✓。
        dt0 = (ts - self._prev_ts) if (ts is not None and self._prev_ts) else None
        if dt0 is not None and not (0.0 < dt0 <= 1.0):
            dt0 = None
        self._prev_ts = ts or self._prev_ts
        self._update_tracks(dets, dt0, ts)
        self._dt_last = dt0 or self._dt_last
        if len(self._buf) > _BUF_N:
            self._buf.pop(0)
        hsv = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)
        bw = cv2.inRange(hsv, (0, 0, _WHITE_V), (180, _WHITE_SAT, 255))
        bw = cv2.morphologyEx(bw, cv2.MORPH_CLOSE,
                              np.ones((5, 5), np.uint8), iterations=2)
        blobs = _white_blobs(bw, _INIT_AREA, 0.0)          # 运动规则用：**不设填充率** ✓
        #   （合成用例的目标是**五角星**（填充率 0.31 ✗）⇒ 设了会误杀真目标 ✗ 实测 ✓）
        dom = _white_blobs(bw, _INIT_AREA, _INIT_FILL)     # 主导规则用：**要实心块** ✓
        #   （防"一大片浅色背景"被当目标 ✗；视频里幽灵 0.57 ✓ 倒计时数字 0.58 ✓ 都过，
        #    靠**面积主导**（9916 vs 2303 ✓）再分胜负 ✓）
        # ⭐⭐ **白块优先，检测框只当兜底**（2026-09-30 用户报"一开始就定位错目标了"✓）：
        #   检测框在**背景滚动**的画面里全都在动 ✗ ⇒ 拿它们进"谁动了谁是目标"的判据
        #   必然锁错 ✗。抖掉：只有当画面里**一个合格白块都没有**时才用检测框。
        if not blobs:
            for cx, cy, w, h in (dets or []):
                a = float(w) * float(h)
                if not (_INIT_AREA[0] <= a <= _INIT_AREA[1]):
                    continue          # ⚠ 面积过滤必套（25651px² 巨框建错档 ✗ 实测 ✓）
                blobs.append((cx, cy, a))
        for cx, cy, a in blobs:
            hit = None
            for c in self._cands:
                if abs(c["pos"][0] - cx) + abs(c["pos"][1] - cy) < _INIT_MATCH_DIST:
                    hit = c
                    break
            if hit is None:
                self._cands.append({"pos": (cx, cy), "area": a,
                                    "first": (cx, cy), "n": 1, "fts": ts})
            else:
                hit["pos"] = (cx, cy)
                hit["area"] = a
                hit["n"] += 1
        # ⭐ **主导白块直接锁定**（用户 2026-09-30："一开始应该盯着白色的图形"✓）：
        #   目标幽灵在倒计时阶段**还没开始动** ✗（等"动了"才认会拖到数字消失/误锁 ✓），
        #   而它是画面里**唯一的大实心白块** ⇒ 最大 ≥ 次大 × `_INIT_DOMINANT` 且连续
        #   `_INIT_STABLE` 帧关联上 ⇒ 就是它 ✓。仍然要求"稳定"（单帧幻觉不算 ✗）。
        #   ⚠⚠ **主导块的定义收紧 + 优先级提高**（2026-09-30 用户报"一开始目标就追错了"
        #     ✓ 实测）：倒计时数字与目标**会合并成一帧**（现场帧1：两个块并成一个，
        #     质心从 251 跳到 217）—— 那一帧 `fill` 掉到阈值下 ⇒ `dom` **空** ⇒ 代码
        #     落到"谁动了谁是目标"⇒ 锁到**合并质心**、还估出 447px/s 的**假初速度** ✗
        #     ⇒ 超前补偿把它一路往上推（y: 217→62→28→**0**）追到数字/顶部亮背景上 ✗✗。
        #   修：① 达标块没有时**退回最大白块**（合并帧也算主导 ✓）；
        #       ② **有主导块就绝不让"谁动了"抢先** —— 等它 `_INIT_STABLE` 帧稳定 ✓。
        big, second = _dominant_blob(dom, blobs)
        if big is not None:
            if big[2] >= second * _INIT_DOMINANT:
                hit = None
                for c in self._cands:
                    if (abs(c["pos"][0] - big[0]) + abs(c["pos"][1] - big[1])
                            < _INIT_MATCH_DIST):
                        hit = c
                        break
                if hit is None:
                    hit = {"pos": (big[0], big[1]), "area": big[2],
                           "first": (big[0], big[1]), "n": 1, "fts": ts}
                    self._cands.append(hit)
                if hit["n"] >= _INIT_STABLE:
                    self.state = "track"
                    self.pos = hit["pos"]
                    self.area = hit["area"]
                    self.init_t = ts
                    self._set_vel(0.0, 0.0)
                    self._raw = (hit["pos"][0] * _SCALE, hit["pos"][1] * _SCALE)
                    self._reg_build_now(dets, ts)      # ⭐ 转 track 当拍建表 ✓（见下 ✓）
                    return self._out("track")
        if big is not None:
            # ⭐ **有主导块 ⇒ 只等它**（不稳定的那几帧**不许**落到"谁动了"✗ ——
            #   合并帧的质心跳变会被当成"它在动"⇒ 锁错 + 假初速度 ✗ 实测 ✓）
            return self._out("init")
        # 谁动了谁就是目标（干扰 / 倒计时数字都不动 ✓）
        for c in self._cands:
            disp = ((c["pos"][0] - c["first"][0]) ** 2
                    + (c["pos"][1] - c["first"][1]) ** 2) ** 0.5
            if disp >= _INIT_MOVE and c["n"] >= 2:
                self.state = "track"
                self.pos = c["pos"]
                self.area = c["area"]
                self.init_t = ts
                self._reg_build_now(dets, ts)      # ⭐ 转 track 当拍建表 ✓（同上 ✓）
                # ⭐ 建档时**顺手估初速度**（位移 / 实际耗时 ✓）—— 比 0 强得多：
                #   缓冲未满的填充期就靠它滑行，不至位置冻结在建档点 ✗
                #   ⚠ 必须**限幅**（`_INIT_VMAX`）：这一步的位移可能是**块合并/抖动**
                #     造出来的（现场 34px/帧 ⇒ 447px/s ✗）⇒ 不限幅就会被超前补偿放大成
                #     几十 px 的偏移、把关联门引到隔壁白块上 ✗（实测：一路追到倒计时数字 ✗）
                if c.get("fts") is not None and ts is not None and ts > c["fts"]:
                    dt0 = ts - c["fts"]
                    vx = (c["pos"][0] - c["first"][0]) / dt0
                    vy = (c["pos"][1] - c["first"][1]) / dt0
                    m = max(abs(vx), abs(vy))
                    if m > _INIT_VMAX:
                        k = _INIT_VMAX / m
                        vx, vy = vx * k, vy * k
                    self._set_vel(vx, vy)
                self._raw = (c["pos"][0] * _SCALE, c["pos"][1] * _SCALE)
                return self._out("track")
        # ⭐⭐⭐ **建档失败不再翻 `lost`**（用户 2026-10-01 ✓ 重构：`lost` 已废除 ✓）：保持
        #   `init` 继续尝试（`init` 本来就每帧跑 `_step_init` ✓）—— 对外只有 `init`/`track`
        #   两态，认不出目标就一直是 init（= 还在找）✓，不再冒出第三个"失败态" ✗。
        return self._out("init")

    # ---- v2 跟踪：**时序双窗均值差分 + 双基线交集**（用时间换 SNR ✓）----
    # 「过去窗均值」vs「当前窗均值」：噪声被平均压 √N；**静态的背景与干扰在两个
    # 窗里一样 ⇒ 完全抵消**；只有移动过的目标留下"旧位 + 新位"两个残影。
    # ⭐ **单条基线分不开新旧残影**（两个残影都按目标速度移动，预测门咬错就会
    #   永远跟着 ~2s 前的延迟鬼影 ✗ 现场踩过：误差 = 窗距 × 速度 ≈ 100px）⇒
    #   **双基线交集**：短基线（6 帧）与长基线（14 帧）的"新位"残影**重合**
    #   （都是当前窗），"旧位"残影相距 v×(长-短) 很远 ⇒ 交集 = 真位置 ✓。
    def _step_track(self, small, ts, dets=None):
        dt = (ts - self._prev_ts) if (ts is not None and self._prev_ts) else None
        # ⭐ **dt 卫生**（2026-09-30 现场翻车 ✓）：素材时间戳**非单调**（乱序交错 ⇒
        #   dt<0 或巨大 ⇒ 速度/预测被带飞 ✗）—— 只认 0 < dt ≤ 1s，其余当没走钟 ✓。
        if dt is not None and not (0.0 < dt <= 1.0):
            dt = None
        self._vel_src = None                     # ⭐ 本拍"自身速度"由谁给的（每拍复位 ✓ 诊断用 ✓）
        if dt:
            self._dt_last = dt                       # 超前补偿"最多补一帧"的依据 ✓
        self._buf.append(small)
        if len(self._buf) > _BUF_N:
            self._buf.pop(0)
        self._prev_ts = ts or self._prev_ts
        # ⭐⭐⭐ **A 层先跑**（2026-09-30 重构 ✓）：群体平移 `T` + 群体一致性 + 面积事件。
        #   ⚠ 必须在**滑行分支之前**（缓冲没攒够的那几帧也要能用 `T` 当速度 ✗ 否则会
        #   "站在原地不动"直到缓冲满 —— 实测：前 7 帧一动不动、误差线性涨 ✗✗）。
        # ⚠ 副作用 = 给演示窗画箭头 + 维护目标身份（`_target_id` ✓）；**返回值 = 当拍运动冠军**
        #   （原给 `_try_recapture` 的复活① 用 ✓）—— ⚠ **复活已停用（2026-10-02）⇒ 不接收返回值**
        #   ✓（`pyflakes` 也不许留未用变量 ✗）。♻ **要接回**：改回 `_mt = self._update_tracks(...)`
        #   并把 `_step_track` 里那两行放开 ✓。
        self._update_tracks(dets, dt, ts)
        # ⚠⚠⚠ **框格式必须转**（2026-09-30 抓到的真 bug ✗✗）：`GroupMotion.estimate` 只认
        #   `(cx, cy, w, h)` ✓（见它开头那行 ✓），而演示/实时链路喂进来的 `dets` 是
        #   `(cls, cx, cy, w, h[, conf])` ✗ ⇒ 直接传进去等于把 `(cls, cx, cy, w)` 当框 ✗✗
        #   —— `cls` 恒为 0 ⇒ 它算的是"**从 (0, cx) 到 (cy, w)**"这种不存在的位移 ✗ ⇒
        #   A 层的 `T` 一直是**垃圾** ✓（`_diff` 的背景补偿也跟着错 ✗）。
        _dets_l = list(dets or [])         # ⚠ `dets=None` 也要吃得下（离线/自检链路 ✓）
        _gboxes = ([(float(b[1]), float(b[2]), float(b[3]), float(b[4])) for b in _dets_l]
                   if (_dets_l and len(_dets_l[0]) > 4) else
                   [(float(b[0]), float(b[1]), float(b[2]), float(b[3])) for b in _dets_l])
        ev = self._group.estimate(None, _gboxes, self._typ_area,
                                  cur_gray=self._gray_full)   # 灰度已在 process 转好 ✓
        # ⭐⭐⭐ **假目标登记表**（用户 2026-09-30 两条先验 ✓ 见 `perception/lie_registry.py`）：
        #   每拍喂一次（检出 + 群体平移 `T` ✓）⇒ 攒出"在册的假目标" ✓。
        #   ⚠ 目前**只登记、还没参与判位** ✓（先把登记结果画给用户看对不对 ✓ 用户原话：
        #     "将登记的框做个标记显示出来我看看你登记的对不对" ✓）。
        if ev.get("t") is not None:
            self._t_hist.append((ev["t"][0], ev["t"][1]))
            self._t_hist = self._t_hist[-_BUF_N:]     # 只留缓冲长度（`_diff` 最多跨这么多 ✓）
        # ⭐⭐⭐ **假目标登记表**（用户 2026-09-30 ✓ 见 `perception/lie_registry.py` 模块头）：每拍喂
        #   一次（检出 + 群体平移 `T` + 追踪器位置 `pos` ✓）⇒ 攒出"在册的假目标" ✓，
        #   ⚠⚠ 用户 2026-09-30 纠正 ✓："**红框不是『被判真目标』，而是『在这个区域里』**" ✗——
        #     红框是**约束区**（融合期它里面**同时有真目标和假砖** ✓），**不能**拿它当"这格是目标"
        #     的判据 ✗✗。⇒ 判据换成用户给的物理事实："假目标**钉死在背景板上**" ✓（见 `on_board` ✓）。
        #   ⚠⚠⚠ **必须喂在 `_target_box_state` 之前** ✗✗（用户 2026-10-02 ✓ 帧 23 ✓）：登记表
        #     在 `step` 里会把全部条目**平移到本拍坐标系**（随背景板 ✓）—— 若先选框后喂表，
        #     选框时条目还停在**上一拍**坐标（差一个 T ✓）⇒ "属于砖条目"的几何检查**整体失效
        #     一拍** ✗✗（实测帧 23：登记砖的框被判成"未登记相交框"⇒ 误标红 ✗✗）。
        #     ⚠ `step` 的参数（检出/T/pos/rad/wh ✓）**都不依赖选框结果** ✓ ⇒ 前移安全 ✓。
        if dets:
            # 框布局**两种都要吃得下** ✗：演示链路 `(cls, cx, cy, w, h[, conf])` ✓、
            # 自检/离线链路 `(cx, cy, w, h)` ✓ ⇒ 统一转成登记表的规范布局 ✓。
            if len(dets[0]) > 4:
                _rows = [(float(b[1]), float(b[2]), float(b[3]), float(b[4]), int(b[0]),
                          (float(b[5]) if len(b) > 5 else 0.0)) for b in dets]
            else:
                _rows = [(float(b[0]), float(b[1]), float(b[2]), float(b[3]))
                         for b in dets]
            self._reg.step(_rows, t=ev.get("t"), ts=ts, origin=self.pos,
                           rad=float(self._rad or 0.0),
                           wh=self._wh)              # ⭐ 画面尺寸 ✓ 给登记表的"边缘门"用 ✓（用户 ✓）
        # ⭐ 每拍先清"分离信号"✗ —— 由 `_target_box_state` 在判出"框塌缩成砖"时置真 ✓
        #   （必须清在它**之前** ✓：那一拍它直接返回 `None` ⇒ 下面走"丢框那一支"⇒ 若在那里清
        #    就永远读不到真值 ✗ 实测踩过 ✓）。
        self._split_now = False
        self._split_why = None          # ⭐ 同上：分离诊断也每拍清零（`_target_box_state` 里写 ✓）
        self._pick_why = None           # ⭐ 同上：非融合红框的判定留档（同处清零 ✓ 用户 2026-10-03 ✓）
        tstate, tbox = self._target_box_state(dets, ev)
        # ⭐⭐ **后端认定的"真目标所属框"**（用户 2026-09-30：'后台数据到底认为哪个是真目标
        #   所属的框？' ✓）：就是 `_target_box_state` 选出的那格（**包含报告位置**优先 ✓、
        #   否则门内最近 ✓）⇒ 暴露出去给演示窗画**唯一红框** ✓ —— 演示窗**不许自己再判一次**
        #   ✗（那样会带进"拖动方向"这种 UI 状态 ⇒ 同一帧两个答案 ✗✗）。
        self._tbox = tbox
        # 用户 2026-10-01：圆圈半径 = 红框【内切圆】半径 = min(宽,高)/2；丢框后冻结。
        # ⭐⭐ **检出恢复那一拍不更新半径**（用户 2026-10-01 第二轮 ✓ 原话："第 17 帧绿圈
        #   应该**保持红框丢失期的半径**（即第 16 帧的半径）" ✓）：丢框期的冻结半径继续用，
        #   **从下一拍（连续有框）起**才跟着新框走 ✓ —— 否则圆圈在"重新检出"那一瞬间
        #   **突变大小**（新框常是融合并集块，尺寸不可信 ✗）⇒ 位置把圈挪进框了、圈却突然
        #   胖一圈 ⇒ 看着像"框一回来圆就变了" ✗✗。
        #   判据：`_tbox_prev` = **上一拍**的框（在 `_step_track` 末尾才更新 ✓）⇒ 它是
        #   `None` 且这一拍有框 = **检出恢复帧** ✓。
        if tbox is None:
            # ⚠ **丢框期一律不是"融合"**（用户 2026-10-01 ✓）：否则 `_tbox_merged` 一直挂着 True
            #   ⇒ 重新检出那一拍算不出"融合期的**第一拍**" ✗（实测：帧 16 明明是大红框刚回来，
            #   却因为丢框期还记着 True ⇒ `_merge_first` 恒 False ⇒ 不夹取、也不算漂移纠正速度 ✗✗）。
            _was_m = bool(self._tbox_merged)
            self._tbox_merged = False
            self._merge_first = False
            # 融合中 ⇒ 框没了 = **S2 刚分离**（用户事实 7 ✓）⇒ 也走"速度平滑接管" ✓
            self._merge_split = bool(_was_m)
        if tbox is not None:
            # ⚠ **先判融合**（半径要不要更新看它 ✓ 2026-10-01 用户第二轮 ✓）
            self._merge_first = False            # ⚠ 先清（丢框那一拍不该留上一拍的值 ✗）
            _was_m = bool(self._tbox_merged)
            # ⭐⭐ **融合 = 状态机说了算**（用户 2026-10-02 ✓）：规则①②只在"进门"用 ✓，
            #   保持期的框（比掉下阈值 ✓）由 `_target_box_state` 判 "merged" ✓ —— 这里
            #   **不许**再拿 `_is_merged_box` 复判一遍 ✗（那会把保持期误判成"分离" ✗✗）。
            self._tbox_merged = (tstate == "merged")
            # ⭐⭐ **"融合期的第一拍"**（用户 2026-10-01 ✓）：上一拍**不是**融合框（无框 / 小框 ✓）
            #   而这一拍是 ⇒ **就是那一拍** ✓ ⇒ ① 放行信念夹取（圆先进框、与边相切 ✓）
            #   ② 用"漂移期的相对位移 / 时间"算**漂移纠正速度**当白箭头 ✓（见 `_step_track` 末尾 ✓）。
            self._merge_first = bool(self._tbox_merged and not _was_m)
            # 上一拍是融合框、这一拍不是（框缩回"目标自己那格" ✓）⇒ **分离** ✓
            self._merge_split = bool(_was_m and not self._tbox_merged)
            # ⭐⭐⭐ **半径：融合期一律不许变**（用户 2026-10-01 第二轮 ✓ 原话："绿圈第 18 帧
            #   需要**沿用第 17 帧的半径**，没有任何理由让他变半径。已经夹取进红框了就让他以
            #   白箭头的指示运动" ✓）：融合框是并集、尺寸不可信 ✗（拿它当半径 ⇒ 圈忽大忽小 ✗）
            #   ⇒ 一旦进入融合期就**冻住**（= 漂移期/融合第一拍那一刻的值 ✓），
            #   融合结束（框缩回"目标自己那格"✓）才恢复跟随 ✓。
            #   （原来只挡了"检出恢复那一拍"⇒ 第 18 帧就跟着大框变 ✗ 用户当场否掉 ✓。）
            # ⭐⭐ **分离那一拍也不更新**（与"检出恢复那一拍不更新半径"同一理由 ✓）：这一拍的框
            #   是**刚从并集塌缩回来的**（上一拍还在融合 ✓）⇒ 尺寸当场不可信 ✗ —— 实测
            #   `10月1日.mp4` 帧 17：框 `175×194` ⇒ 半径一次跳到 **87.3**（真值 ~70 ✗），而它比
            #   后面几拍的框（`181×169` / `210×172`）的**半个短边还大** ⇒ 内接安全区**退化**
            #   （`2×半径 ≥ 短边` ⇒ 圆根本装不进框 ✗）⇒ "修正到最远内角"整个失效 ✗✗。
            #   ⚠ 判据用 `_merge_split`（上面 2407 行已算好 ✓：上一拍是融合框、这一拍不是 ✓）。
            # ⭐⭐⭐ **半径学习的"面积门"**（用户 2026-10-01 ✓ Q8 拍板"补上" ✓）：只有这格框的
            #   面积像"**一个目标**"（`0.8 ~ 1.3 × 当拍检出中位` ✓ 与演示窗量半径同一套门 ✓）
            #   才许更新 ✓ —— 邻砖的框、并集刚回缩的框（面积明显偏离单个目标 ✗）**不许学** ✓
            #   （否则半径虚大 ⇒ 圆装不进框 ✗ 实测 70 → 87.3 ✗✗）。
            if self._tbox_prev is None and not getattr(self, "_rad_locked", False):
                # ⭐⭐⭐ **真目标红框首次出现 ⇒ 半径内接确定**（用户 2026-10-02 ✓ 原话：
                #   "绿圆的半径在真目标红框首次出现时，就应该内接确定" ✓）：第一次出红框就把
                #   绿圆半径定为红框的**内切圆**（min(宽,高)/2 ✓）—— 原来这一拍被"检出恢复帧
                #   不更新"挡掉 ✗（`_tbox_prev` 尚为 None ✓）⇒ 半径一直停在白块阶段学的面积
                #   等效值 ✗（`10月1日.mp4` = 18px ✗ 圈比红框小一大圈 ✗✗）。
                #   ⚠ `_rad_locked` 区分"**首次**"与"**恢复帧**" ✓（`_tbox_prev` 每次丢框都会
                #     变 None ✗ 恢复帧不在此列 ✓ —— "检出恢复那一拍不更新半径"照旧 ✓）。
                self._rad_locked = True
                self._tbox_rad = min(float(tbox[2]), float(tbox[3])) / 2.0
                self._tbox_wh = (float(tbox[2]), float(tbox[3]))
            elif (not self._tbox_merged and not self._merge_split
                  and self._box_like_target(tbox)):
                self._tbox_rad = min(float(tbox[2]), float(tbox[3])) / 2.0
                self._tbox_wh = (float(tbox[2]), float(tbox[3]))
        # ⭐⭐⭐ **新分离信号：融合期里红框塌缩成"假目标自己那一格"**（用户 2026-10-01 ✓ 原话：
        #   "第27帧→第28帧大红框变成与登记框重叠的检出框，这是分离的信号，绿圈应该按上一帧的
        #   预测走" ✓）：判据见 `_box_is_registered_fake` ✓（框 ≈ 在册假框、且不比它大 ✓）。
        #   ⚠ 只在**非首拍**触发 ✗（首拍那拍还要做"修正到对角" + 算漂移纠正速度 ✗ 别抢 ✓）。
        # ⭐⭐⭐ **但"框里还有绿圈"就不算分离** ✗（用户 2026-10-01 ✓ 规则②："框**同时**包住了砖和
        #   绿圈 ⇒ **即使面积与砖相等也属于融合红框**" ✓）：真分离时**目标已经走了** ⇒ 那格里只剩
        #   砖、绿圈**不在**框里 ✓；框塌缩成砖大小、绿圈**还在里面** ⇒ 那是"目标跟砖叠在一起" ✓
        #   不是分离 ✗（否则规则②永远被这条抢先掐掉 ✗）。
        if (self._tbox_merged and not self._merge_first and tbox is not None
                and self._box_is_registered_fake(tbox) and not self._pos_range_hits(tbox)):
            self._merge_split = True
        # ⭐⭐ **分离 ⇒ 开一段"速度接管期"**：记下**分离前那个冻结值**当起点（`_sep_vel0` ✓）
        #   ⚠⚠ 必须在这里记 ✗：这一段在 `_step_track` 的**速度更新之前**（更新在后面的
        #   `self_resid` / realized 分支 ✓）⇒ 此刻 `_vel_rel` 还是**冻结值** ✓；等到更新之后
        #   再记 ⇒ 记到的已经是"被实测拽过"的值 ⇒ 接管的起点就错了 ✗。
        if self._merge_split:
            self._sep_vel0 = tuple(self._vel_rel)
            self._sep_n = 0
        # ⚠ **融合红框不做信念夹取**（用户 2026-10-01 ✓ 原话："融合大红框后，绿圈继续按
        #   白箭头的指示行动" ✓）：融合框是"目标 + 假目标"的并集 ⇒ 它**框不住目标一个人**
        #   ⇒ 拿它当约束只会把圆拉到并集中心（实测合成台位置误差中位 0.8 → 27.9px ✗✗）。
        #   ⇒ 融合期：**不夹 `_raw`、不夹报告位置** ⇒ 位置完全由预测（白箭头）决定 ✓。
        #   非融合（目标自己那格框 ✓）⇒ 照旧内接约束 ✓（用户上一轮口径 ✓）。
        self._tsus = tstate                        # ⭐ 暴露状态（S0 ok / S1 merged / S3 gone ✓
                                                   #   诊断与演示窗都要看它 ✓）
        # ⭐⭐⭐ **有红框 ⇒ 自身速度直接取"红框相对假目标群的位移"**（用户 2026-10-01 定稿 ✓
        #   原话："**我们对真目标的轨迹预测应该是相对于假目标群的运动**……例如第10帧→第11帧
        #   **红框相对假目标群向下运动**，那么这个运动在12帧丢失红框后**需要延续**" ✓）。
        #   ⚠⚠ 为什么必须换成它 ✗✗（2026-10-01 实测 ✓）：原来 `_vel_rel` 是拿"**观测位置差**"
        #     减群体算的 ✗ —— 而观测被**信念夹取**揉过 ✗ ⇒ 实测帧 11 的真值是 `(+13.3,+12.8)`
        #     px/帧（**向下** ✓ 正是用户看到的那一下 ✓），学到的却是 `(124,-37)` px/s
        #     = `(12.4,-3.7)` px/帧 ⇒ **y 方向符号相反** ✗✗（所以"延续"出来的是向上 ✗）。
        #   而这个量**我们早就在算** ✓ = A 层逐框 `matchTemplate` 的 `self_resid` ✓（每个框
        #   **相对群体**的位移 ✓ 最稳 ✓）—— 之前只在"没观测"的救援分支里用 ✗，等于**恰好错过
        #   了有框的那几拍** ✗✗（有框的拍子恰恰是唯一能测到它的时刻 ✗）。⇒ 提到主路径 ✓。
        #   ⚠ 没有红框（S1 融合 / S2 / S3 漏检）⇒ **不更新、原样延续** ✓（用户："需要延续" ✓）。
        if dt and float(dt) > 0.0 and tbox is not None:
            # ⚠⚠⚠ **这个量怎么量才对 —— 主判/兜底的顺序是实测定下来的** ✗✗（2026-10-01 ✓）：
            #   · **主判 = 红框中心差 − 群体平移** ✓✓（用户 2026-10-01 描述的那个量 ✓ 原话：
            #     "**红框相对假目标群向下运动**，那么这个运动在12帧丢失红框后需要延续" ✓）：
            #     实测帧 11 = **`(+13.3,+12.8)`** px/帧 ✓✓ —— YOLO 给的**框心是真跟着目标走**的 ✓。
            #   · **兜底 = A 层 `self_resid`**（逐框模板匹配 ✗）—— 在**这一格上它并不忠实** ✗✗：
            #     目标的检出框里**大部分是背景**（目标只是框中的一块白/透明块 ✓）⇒ 模板匹配
            #     锁到的是**背景纹理** ⇒ 自身残差≈0 ✗（实测同帧只给 `(3.4,-3.3)` ✗，
            #     并因此把 `_vel_rel` 的 y **符号搞反** ✗）。⇒ 只在主判拿不到时才用它 ✓。
            #   ⚠ 门判"**上下两拍是同一格框**" ✓ = **框尺寸一致**（`0.7~1.4` ✓ —— 融合成并集块
            #     时宽度**翻倍** ✗ ⇒ 自然被挡 ✓）；**不能用 `tstate == "ok"`** ✗✗：实测帧 9/10
            #     被判 `merged`（可框其实是目标自己那格 ✓）⇒ 恰好把**用户要看的那两帧挡掉** ✗。
            # ⭐⭐⭐ **有缺口时：用"丢框期间的首尾两点 / 时间"**（用户 2026-10-01 定稿 ✓ 原话：
            #   "**第17帧红框再次出现**，那么应该用**丢失红框的12帧→17帧的首尾位置/时间**来
            #   预测真目标的轨迹" ✓）。
            #   为什么它比单帧差分强得多 ✓：分母从 **1 帧**变成 **整个缺口**（实测 0.6s ✓）
            #   ⇒ 框心的 ±2~3px 量化抖动被摊薄 6 倍 ✓✓。实测（帧 11 → 帧 17）：
            #     红框 `(350,266)` → `(291,298)`，期间**累计群体 T = (-90,-77)** ✓
            #     ⇒ 相对位移 `(31,+108)` ÷ 0.6s = **(52,+180) px/s** ✓
            #     而单帧版只给 `(97,+49)` ✗ —— **y 差 3 倍** ✗（正是用户看出来的那件事 ✓）。
            #   · 公式：`rel = (框_now − 框_last) − ΣT(缺口期间)` ✓；`ΣT` 逐帧累加 ✓；
            #   · 缺口越长越可信 ⇒ 权重 `_GAP_VEL_KEEP(gap>1)=0.15` ✗、单帧仍用 `_BOX_VEL_KEEP` ✓；
            #   · ⚠ 缺口后重现的框常常是**并集块** ✗（实测帧 17 = 1.47× ✓）⇒ 尺寸门在"有缺口"
            #     时放宽到 **1.8** ✓（它的框心仍带目标走的成分 ✓ 好过放弃整段信息 ✗）。
            _rel0, _keep0 = None, _BOX_VEL_KEEP
            _h0 = int(getattr(self, "_gap_hold", 0))
            _base0 = self._tbox_last if self._tbox_last is not None else self._tbox_prev
            # ⭐⭐⭐ **并集块（融合）里"框心差 − T"是假测量** ✗✗（2026-10-01 合成台 p90 实测 ✓）：
            #   融合期红框 = 目标 ∪ 被压住的假目标 ⇒ **并集框心跟着群体走**（两个成员都只随
            #   群体平移 ✓）⇒ "框心差 − T" ≈ 0 被当成"自身速度 = 0"学进去 ⇒ **把融合前学到的
            #   正确自身速度冲掉** ✗ ⇒ 分离后圆圈只会跟着群体走、目标越走越远（合成台每例
            #   帧 28 起误差线性涨 ~11px/帧 ✗ = 目标自身速度 ✓）。⇒ **上下两拍都是并集块
            #   ⇒ 这一拍不学**（等同"没红框"：不更新、原样延续 ✓ 用户"需要延续" ✓）；
            #   **只一端是并集** ⇒ 差值里仍含目标自身的运动 ⇒ 照学 ✓（真素材帧 17 那个
            #   "缺口首尾两点"的好测量正是这种：缺口前=目标格、重现=并集块 ✓ 不能挡 ✗）。
            #   判"并集块"与融合信号同一把尺：面积 ≥ `_MERGE_RATIO` × 标准面积 ✓。
            # ⭐⭐ **两条"测量有效性"守卫**（2026-10-01 合成台 trace 实锤 ✓，分层别搞混 ✗）：
            #   ① **缺口首点是并集块 ⇒ "首尾两点"测量不学** ✗：首点若是融合并集（框心偏向
            #     被压住的那只 ✗），"首尾差 − ΣT" 混着**并集几何的偏移**（trace：case2 帧 25
            #     靠它把 vel_rel 从正确的 (49.6,32.5) 一拍打到 (-5.8,-35.5) ✗ y 都反号了 ✓）。
            #     真素材的好测量（帧 17）首点是**目标自己的格** ✓ 不受影响 ✗。
            #   ② **单帧兜底要求当前框"完整"** ✗：**碎片框**（面积 < 0.82× 标准 = 被屏幕切
            #     一半 ✓ 登记表「完整尺寸」下限 `_SIZE_LO` 同一把尺 ✓）的框心贴着屏幕边 ⇒
            #     它的移动 ≠ 目标移动（目标出画时碎片框心"滑"向边界 ⇒ 学出反向假速度 ✗
            #     trace：case2 帧 28/29 框 96×32/69×25 学出 (-14,-27)px/s，真值 (50,33) ✗）；
            #     **并集块**（两端都是并集 ✗ 见上 ✓）框心锁在群体上 ⇒ 学出 0 ✗。
            #     ⚠ **不拦缺口首尾测量** ✗：真素材帧 17 重现的框就是并集块（1.47× ✓）而那个
            #       首尾测量正是用户要的 ✓ ⇒ 守卫 ② 只管单帧兜底 ✓。
            _typ0 = float(self._typ_area or 0.0)
            _uni_now, _partial = self._box_flags(tbox)
            _uni_base = bool(_typ0 > 0 and _base0 is not None
                             and self._box_flags(_base0)[0])
            _use_gap = bool(_base0 is not None and self._t_hist and not _uni_base
                            and not _partial)          # ① 首点并集 / 当前碎片 ⇒ 首尾不学 ✗
            if _use_gap:
                _gap1 = int(getattr(self, "_gap_n", 0))          # 缺口帧数（0 = 上一拍也有框 ✓）
                _lim = 1.4 if _gap1 <= 1 else 1.8
                _wr = float(tbox[2]) / max(1e-6, float(_base0[2]))
                _hr = float(tbox[3]) / max(1e-6, float(_base0[3]))
                if 0.7 <= _wr <= _lim and 0.7 <= _hr <= _lim:
                    _T0 = self._t_hist[-1]
                    # 把这一帧的群体平移也加进去（区间 11→17 含 6 次平移 ✓）
                    _sgx = float(self._gapT[0]) + float(_T0[0])
                    _sgy = float(self._gapT[1]) + float(_T0[1])
                    _rel0 = (float(tbox[0]) - float(_base0[0]) - _sgx,
                             float(tbox[1]) - float(_base0[1]) - _sgy)
                    if _gap1 > 1:
                        # ⭐ 缺口 ≥2 帧 ⇒ **强烈采信首尾值** ✓（分母 = 整个缺口 ✓ 见上面注释 ✓）
                        _keep0 = _GAP_VEL_KEEP
                        self._gap_hold = _GAP_HOLD_N
                        # 缺口 ⇒ 分母换成**整段真实耗时** ✓（与 `_ts_last` 配对 ✓）
                        if ts is not None and self._ts_last:
                            _dtg = float(ts) - float(self._ts_last)
                            if _dtg > 1e-6:
                                self._dt_gap = _dtg
                    elif _h0 > 0:
                        # ⭐⭐ **缺口刚补上的几帧：先别急着改** ✗（2026-10-01 实测 ✓）：缺口后
                        #   重现的框常常是**并集块** ✗（实测帧 17~19 = 209×166 / 198×164 ✓）
                        #   ⇒ 它们的**单帧差分**被并集几何的抖动主导 ✗✗（一天就把首尾值
                        #   `(58,161)` 拉回 `(-20,77)` ✗）⇒ 尾随 `_GAP_HOLD_N` 帧**仍用强权重** ✓，
                        #   之后交回单帧 ✓。
                        _keep0 = _GAP_VEL_KEEP
                        self._gap_hold = _h0 - 1
            if _rel0 is None and not (_uni_now or _partial):
                # ⭐ 单帧兜底同样不碰"并集/碎片"的框心（守卫 ② ✓ 见上）
                _rel0 = self._box_self_resid(ev, dets, tbox)
                _keep0 = _BOX_VEL_KEEP
            _dtv = float(getattr(self, "_dt_gap", 0.0) or float(dt))
            if _rel0 is not None and abs(_rel0[0]) + abs(_rel0[1]) <= _BOX_REL_MAX_GAP:
                _rx0, _ry0 = _rel0[0] / _dtv, _rel0[1] / _dtv
                if abs(_rx0) + abs(_ry0) <= _REL_V_MAX:
                    self._vel_rel = (self._vel_rel[0] * _keep0 + _rx0 * (1 - _keep0),
                                     self._vel_rel[1] * _keep0 + _ry0 * (1 - _keep0))
                    self._vel_src = "box" if _keep0 >= _BOX_VEL_KEEP else "gap"
        # ⭐⭐⭐ **缺口记账**（= "距上一次拿到红框"的状态机 ✓ 用户 2026-10-01 口径 ✓）：
        #   · 没框的拍子 ⇒ `_gap_n += 1` ✓、把**这一拍的群体平移累加**进 `_gapT` ✓
        #     （下一拍红框再出现时，用它算"期间群体走了多少" ✓）；
        #   · 拿到框 ⇒ 重置 ✓（`_tbox_last` / `_ts_last` 留着给下一段缺口当"首点" ✓）。
        #   实测（帧 11 有框 → 12~16 无框 → 帧 17 有框）：`_gap_n = 5` ✓、`_gapT = (-83.9,-60.7)` ✓
        #   ⇒ 配上这一帧的 `T` ⇒ `ΣT = (-90,-77)` ✓ 与"首尾两点"严丝合缝 ✓。
        if tbox is None:
            self._gap_n += 1
            if self._t_hist:
                self._gapT[0] += float(self._t_hist[-1][0])
                self._gapT[1] += float(self._t_hist[-1][1])
        else:
            self._tbox_last, self._ts_last = tbox, ts
            self._gapT = [0.0, 0.0]
            self._gap_n = 0
            self._dt_gap = 0.0
        # ⭐ 目标**实际半径**（白块学 ✓ 相切与可视化都用它 ✓ 用户 2026-09-30 口径 ✓）
        self._learn_rad(None if self._white_cur is None else self._white_cur[2], ts)
        # ⚠ `_prev_tbox`（"上一拍的框"✓）原来由已移除的 `_update_edge_own` 维护 ⇒ 现在
        #   直接在这里赋 ✓（`_target_box_state` 的"同一格框 + 明显变大"判据要用它 ✓）；
        #   只在**有框**时更新（与原来一致 ✓ 丢框期留着上次的框当"同一格"的比较基准 ✓）。
        if tbox is not None:
            self._prev_tbox = tbox
        # ⚠ 原来的 `prev_merged`（S2 的"夹进新框"条件 ✓）**已不再需要** ✗：现在"没分离就
        #   一定在框里"由**信念约束**统一承担 ✓（`_clamp_into_tbox` / `_pos_in_tbox` ✓ 用户
        #   2026-09-30 定稿 ✓）—— 留着它就是没用变量 ✗（pyflakes 当场报 ✓）。
        self._was_merged = (tstate == "merged")
        # ⚠⚠⚠ **不许把"群体平移 T"当成目标的速度**（2026-09-30 用户报"第 6 帧就严重偏离"✓
        #   实测根因 ✗✗）：`T` 是**背景/干扰群的平移**（框群每帧走 20~25px ✓），而真目标
        #   在**白块阶段几乎静止**（实测 GIF 2~6 帧白块 (375,249)→(377,252) ✓ 只挪 2px ✓）。
        #   我上一轮加的"速度没建立就用 `T/dt` 起" ✗ 与"长滑行往 `T/dt` 收敛" ✗ 都是**错的
        #   前提**（把事实 2 的"**假目标**相对背景静止"错推广成"真目标跟着群体平移"✗）——
        #   它俩把目标一路往左上传（第 7 帧跑到 147px 外 ✗✗）。已全部删除 ✓。
        # ⚠⚠ **不再在这里"提前 return 去滑行"**（2026-09-30 重构实测踩到 ✗）：缓冲没攒够的
        #   那 ~12 帧原来只能按速度滑 ⇒ 只能按**群体速度**漂 ✗ ⇒ 漂出去之后残差候选被门挡在
        #   外面 ⇒ 越漂越远（实测误差 0.7 → 172px ✗✗）。现在**照走主路径**：残差暂时没有
        #   （`cands` 空 ✓）⇒ 自然落到**检测框观测**那条路（同一套门 ✓）⇒ 从第 1 帧就能跟住 ✓。
        ready = len(self._buf) >= _GAP_SHORT + _REF_N

        def _diff(gap):
            cur = np.mean(self._buf[-_CUR_N:], axis=0)
            ref = np.mean(self._buf[-gap - _REF_N: -gap], axis=0)
            # ⭐⭐⭐ **背景运动补偿**（2026-09-30 用户澄清口径 ✓："假目标相对背景静止、假目标
            #   之间相对静止、而**背景是移动的**" ✓）⇒ 把参考窗按 `T × 帧数` **平移对齐**
            #   再差分 ⇒ 差分里**只剩真目标** ✓✓（不补偿 ⇒ 整片移动的背景纹理全进差分 ⇒
            #   候选全是背景噪声 ✗✗ 这正是"追到背景上"的根源 ✓）。
            #   ⚠ 两个 `T` 的用途不同、别混 ✗：这里用它**对齐背景** ✓；它**绝不当目标速度** ✗
            #     （目标是自己在动的东西 ✓ 用户事实 2 ✓）。
            n = max(1, int(round(gap + (_REF_N - _CUR_N) / 2.0)))
            hist = self._t_hist[-n:] if self._t_hist else []
            tx = sum(t[0] for t in hist)
            ty = sum(t[1] for t in hist)
            if abs(tx) >= 0.6 or abs(ty) >= 0.6:
                ref = _shift_img(ref, int(round(tx * _SCALE)), int(round(ty * _SCALE)))
            resid = cv2.absdiff(cur.astype(np.float32), ref.astype(np.float32))
            _, bw = cv2.threshold(resid, _EMA_TH, 255, cv2.THRESH_BINARY)
            bw = bw.astype(np.uint8)
            bw = cv2.morphologyEx(bw, cv2.MORPH_CLOSE,
                                  np.ones((5, 5), np.uint8), iterations=2)
            return _blobs_of(bw, _BLOB_AREA)

        # ⭐⭐⭐ **重构（2026-09-30 用户认可 ✓ 就地重写）**：**残差为主 + 框群只当事件** ✓
        #   判据：`tools/eval_lie.py`（合成台有真值 ✓）+ `tools/synth_lie.py`。
        #   改动前基线：带检测框 **位置误差中位 147.7px**（≤30px 只 6% ✗）、物理判据
        #   （报告位置局部偏离 T）中位 **0.6px** = 追在**随群体平移的背景/假目标**上 ✗✗；
        #   纯残差 47.5px / ≤30px 25% ✓（但 track 率 40% ✗）。
        #   ⇒ 框只用来：① A 层群体平移 `T` ✓；② **面积事件**（融合/分离/漏检 ⇒ S0~S3 ✓
        #     用户事实 4~7 ✓）；③ **一致性过滤**（"完全随群体走"的框**不许**当目标观测 ✗
        #     —— 那正是把位置拽到背景上的元凶 ✓）。位置/速度主判 = 残差候选 ✓。
        # ⭐⭐⭐ **速度的真源 = 目标自身位移 + 群体平移**（用户事实 2 ✓ + 用户 2026-09-30 第 1 条 ✓
        #   原话："第10帧→第11帧不是有速度吗？这两帧真目标框还在。当真目标框消失且没有融合信号时，
        #   就沿用之前的速度（轨迹预测不就是干这个的吗？）" ✓）。
        #   · A 层用**模板匹配**给出每个框"**相对群体**"的自身位移（`self_resid` ✓ 比框中心差分
        #     稳得多 ✗ 框中心带 ±几 px 抖动 ✓）⇒ 目标**绝对**速度 = `(T + 自身位移)/dt` ✓；
        #   · **只在有框（S0）时学** ✓；**融合期不学**（事实 6 ✓）；**框消失（S3 漏检）也不动它**
        #     ⇒ 沿用上一次的速度 ✓ —— 这正是"轨迹预测"的用处 ✓。
        #   ⚠⚠ 之前踩到的坑：白块期用"位置差"当速度（目标当时确实几乎不动 ⇒ ≈0 ✓）⇒ 一旦框丢了
        #     就**冻住 6 帧** ✗✗（实测 `9月30日(1).mp4` 第 10~15 帧 ✓ 就是你指出的那条 ✓）。
        self._vel_from_box = False
        # ⚠⚠ **框速度这条路已搬到"没有观测"的分支里**（2026-09-30 实测 ✓ 见下面 `else`）：
        #   留在**观测之前**会抢着盖速度 ⇒ 把好速度污染掉 ✗（实测 (19,8)px/s vs 真值 ~(80,26) ✗
        #   ⇒ 位置稳在 15px 外下不来 ✗✗；而**纯残差**路线的位置误差中位只有 **0.6px** ✓✓）。
        # ---- 残差候选（主判 ✓ 与旧版同一套机器 ✓）----
        cands = _diff(_GAP_SHORT) if ready else []
        if len(self._buf) >= _GAP_LONG + _REF_N:
            long_set = _diff(_GAP_LONG)
            cands = [c for c in cands
                     if any(((c[0] - d[0]) ** 2 + (c[1] - d[1]) ** 2) ** 0.5
                            <= _X_RADIUS for d in long_set)]
        # 预测点（半分辨率 ✓；lead 不许混进速度 ✗）
        fx = fy = None
        # ⭐⭐⭐ **圆心严格按白箭头走**（用户 2026-10-01 定稿 ✓ 原话："**圆心严格按白箭头，白箭头
        #   考虑曲率**" ✓）：
        #   步长 = **上一拍最终生效的 `_vel`**（= 白箭头 `vel_rel` + 群体 ✓）—— 而 `vel_rel`
        #   本身就是"**曲线预测**（切向 + 曲率 ✓ 见 `_path_pred`）+ **反向旋转**"的最终值 ✓
        #   ⇒ 圆心的下一步 = **箭尖** ✓✓（契约：箭尖 = 下一帧圆心相对假目标群的位移 ✓）。
        #   ⚠⚠ 老写法在这里**优先用 `_path_pred`**（**没旋转**的曲线预测 ✗）⇒ 圆心走的与箭头
        #     **不是同一条** ✗（实测无红框拍：箭尖与下一帧圆心差 **7~18px** ✗）。
        #   ⚠ 曲线（曲率）没有被丢掉 ✗ —— 它是 `vel_rel` 的**来源**（长度与步长）✓，只是最后
        #     按设计被旋转了 ✓（用户："白箭头考虑曲率" + "反向旋转是设计要求" ✓）。
        _pred_path = False
        if self._raw is not None:
            _dd = float(dt) if dt else 0.0
            fx = self._raw[0] + (self._vel[0] * _dd) * _SCALE
            fy = self._raw[1] + (self._vel[1] * _dd) * _SCALE
        # ⭐ **S1 融合期：位置照残差走、但速度冻结**（事实 6："不用更新轨迹预测 ✓"）
        #   ⚠⚠⚠ **冻结的前提是"手上已经有过速度"** ✗✗（2026-09-30 实测大坑 ✓ 用户第 1 条 ✓）：
        #     事实 6 要的是"**沿用上一帧的轨迹预测**" ✓ —— 如果速度**从来没建立**（恒 0 ✗），
        #     冻结它就等于"永远不动" ✗✗（合成台帧 5~11 位置完美 0.4px 却 vel=0 ⇒ 一出融合
        #     就瞎滑到 144px ✗）。⇒ **速度≈0 时即便在融合期也要先学会** ✓（那时观测是准的 ✓
        #     用户原话："这两帧真目标框还在 ⇒ 有速度" ✓）；学到之后才按事实 6 冻 ✓。
        _fresh = self._speed_of_vel() < 5.0
        frozen = (tstate == "merged") and not _fresh
        # ⭐ 本拍观测**有没有滞后**（残差 = 有 ✓ 白块/检测 = 无 ✓）⇒ 决定 `_lead_pos` 补不补 ✓
        self._obs_lag = True
        best, det_area = None, None
        if fx is not None:
            # ⭐⭐ **门随"不确定度"放宽**（2026-09-30 实测踩到 ✗）：连丢几拍后预测已经漂了
            #   `v×dt×n` ⇒ 还用固定门 ⇒ **真观测永远进不来** ⇒ 越漂越远（0.7→172px ✗✗）。
            #   门 = 基础 + 速度 × 已滑行时间（封顶 3 拍 ✓ 别无限放 ✗）。
            # ⭐⭐⭐ **残差候选观测"纠正位置"这一条：按用户要求删除** ✗✗（2026-10-01 ✓ 原话：
            #   "**把残差候选观测纠正删了**" ✓）。
            #   为什么用户要删 ✓（他当场量出来的 ✓）：残差候选是"**外观差分**"给的 ✓，它会
            #   把位置**拽向候选点** ✗ ⇒ 白箭头刚说"下一帧往右下走 (+7.2,+9.2)" ✓，第 12 帧
            #   位置却被候选拉到 `(−9.6,+14.7)` ✗✗ ⇒ 圆圈根本走不出箭头指示的位移 ✓（用户：
            #   "为什么在第12帧绿圈相对于 #004 没有走出第11帧指示的相对位移" ✓）。
            #   ⇒ 现在**位置只由两件事决定** ✓：① **预测**（上面那一滑 ✓）② **夹取**（框约束 ✓）；
            #     白块观测仍保留 ✓（它是"当前帧的直接观测量"✓ 不是差分猜的 ✓）；检测框救援
            #     也保留 ✓（只在残差连丢 ≥`_DET_RESCUE_N` 拍时接管 ✓）。
            #   ⚠ 原先这里有一句 `best = bd`（门内最近候选 ⇒ 当位置观测 ✗）——**已删** ✗。
            #     记一句后果（便于回退时对照 ✓）：合成台上残差候选是**高精度来源**（中位 0.7px ✓）
            #     ⇒ 删掉后合成台的位置误差**必然变差** ✗，但真素材上"箭头 = 实际走的"才会成立 ✓。
            _ = cands          # 保留候选（`area`/诊断还要用 ✓），但**不当位置观测** ✗
            # ⭐⭐⭐ **白块观测优先**（用户 2026-09-30："第 6 帧真目标都没有变透明还是白的，
            #   算法有错误" ✓）：白块阶段目标就是画面里**唯一的大白块** ✓ ⇒ 直接观测它 ✓
            #   （那时根本不该"猜"✗）。实测根因：白块阶段（GIF 2~6 帧）目标几乎**静止**
            #   （(375,249)→(377,252) ✓ 只挪 2px）而**背景在滚**（框每帧 20~25px ✗）⇒ 只靠
            #   残差/速度猜 ⇒ 一路被背景带走（第 7 帧 147px ✗✗）。
            #   ⚠ 白块只在**离预测不远**时才算（`_white_obs` 里判 ✓ 透明阶段的亮背景碎块
            #     不会正好长在目标旁边 ✓）。
            #   ⚠⚠ **试过"融合期禁用白块观测"（按事实 6 理解）⇒ 反而更差** ✗✗（15.2 → 36.1px
            #   实测 ✓）：合成台里假目标是**暗的**（85~135 ✓）而白块掩码要 V≥185 ✓ ⇒ 白块
            #   **只含真目标本身**（即使被压住也不含假目标 ✓）⇒ 它是**干净观测** ✓ 不该禁 ✗。
            #   （剩下那 ~15px 的偏置另有原因，见下方 TODO ✓ 不是这条 ✓。）
            if self._white_cur is not None:
                best = (self._white_cur[0] * _SCALE, self._white_cur[1] * _SCALE)
                # ⭐ 白块观测 = **当前帧**（无滞后 ✓）⇒ 报告位置**不做超前补偿** ✓（见 `_lead_pos`）
                self._obs_lag = False
            # ⭐⭐⭐ **"目标自己那格红框" ⇒ 圆心 = 红框中心**（用户 2026-10-02 ✓ 定稿 ✓ 原话：
            #   "与绿圈相交且不是砖 ⇒ 目标自己那格红框。对于这种类型的，**绿圈的圆心应该位于
            #   该红框中心位置**（因为**确定红框就是真目标检出**）" ✓）：
            #   这格框被判定 = **真目标检出** ✓ ⇒ 它的中心就是目标位置 ✓ ⇒ **直接当观测** ✓
            #   （优先于白块/残差 ✓；经 `_set_raw` 限速收敛 ✓ 不瞬移 ✓；夹取再把整圈留在框内 ✓）。
            #   ⚠ 只对 `tstate == "ok"` ✓：融合并集框的中心**不是**目标 ✗（那套继续走
            #     "按白箭头走 + 对角修正" ✓）；预测态没有框 ✗ 无从取中心 ✓。
            if tstate == "ok" and tbox is not None:
                best = (float(tbox[0]) * _SCALE, float(tbox[1]) * _SCALE)
                self._obs_lag = False              # 框中心 = 当前帧观测 ✓ 无滞后 ✓
            # ⚠⚠⚠ 除此之外**不给检测框当"位置观测"**（2026-09-30 两次实测的共同结论 ✗✗）：
            #   · 合成台（有真值）：纯残差 **47.5px** vs 带框 **147.7px** ✗；
            #   · 逐帧看：一旦预测漂了几十 px，"门内最近的框"就变成**隔壁假目标**
            #     ⇒ 接管速度 ⇒ 一路被拖着跑到 200px 外 ✗✗。
            #   ⇒ 框**只做三件事**：① A 层群体平移 `T`（**背景速度** ⇒ 用来**补偿背景** ✓
            #     见 `_diff` ✓；**绝不当目标速度** ✗✗）；② **面积事件**（融合/分离/漏检 ⇒
            #     S0~S3 ✓）；③ 分离期的**边界夹取**（事实 7 ✓）。
            #     位置与速度 = 白块观测（白块阶段 ✓）或残差候选（透明阶段 ✓）。
        # ⭐⭐⭐ **① 先听预测**（用户 2026-10-01 定稿 ✓ 原话："**先听预测，后夹取，夹取完再
        #   计算本帧与上一帧的预测**" ✓）：**不管这拍有没有观测**，先把位置按速度滑一帧 ✓
        #   —— 这样"速度"才真的**驱动了位置** ✓（改前速度只当"没观测时的滑行"✗，有框的拍子
        #   位置完全由观测决定 ⇒ 箭头说 (5.8,16.1)、圆圈实际只走 (−2.5,8.7) ✗ 正是用户问的
        #   "为什么与 #004 没有这么多相对位移" ✓）。
        #   ⚠ 放在这里（`fx` 已按"`_raw + vel·dt`"算完之后 ✓）⇒ 两者同值、不会重复计一次 ✓。
        #   ⚠⚠⚠ **只在"这一拍有观测"时才滑** ✗✗（2026-10-01 trace 实测 ✓）：**没有观测**那一拍，
        #     下面的滑行分支**本来就会滑一次**（而且用**刷新后的**群体速度重算 `fx` ✓）⇒ 这里再
        #     滑一次就是**一拍走两段** ✗✗（trace：帧 11/12 各调了 **两次** `_set_raw`：
        #     `184.2→181.9→173.9` ✓、`173.9→164.3→156.3` ✓）⇒ 接着 ③"夹取完再结算"量到的是
        #     **被叠加后的位移** ✗ ⇒ `vel_rel` 被算歪、**x 方向整个反过来** ✗✓（白箭头第 11 帧
        #     报 (+7.2,+9.2) 右下 ✓，第 12 帧却变成 (−5.2,+12.6) 左下 ✗ —— 用户当场看出来的 ✓）。
        if best is not None and self._raw is not None and dt and float(dt) > 0.0:
            self._set_raw((self._raw[0] + self._vel[0] * float(dt) * _SCALE,
                           self._raw[1] + self._vel[1] * float(dt) * _SCALE), dt)
        if best is not None:
            # ⭐⭐⭐ **框消失且没有融合信号 ⇒ 速度必须沿用**（用户 2026-09-30 第 1 条 ✓ 原话：
            #   "当真目标框消失且没有融合信号时，就沿用之前的速度（轨迹预测不就是干这个的吗？）"
            #   ✓ 事实 4：那是 **YOLO 漏检**，目标照旧在动 ✓）。
            #   ⚠⚠ 之前就栽在这 ✗：那时**没有框**（`tbox=None` ✓），但残差/白块观测的
            #     `nv≈0`（观测≈当前位置 ✓）仍会去 EMA 速度 ⇒ **速度被拽回 0** ⇒ 位置冻住
            #     6 帧 ✗✗（实测 `9月30日(1).mp4` 第 11~15 帧 ✓ 就是你看到的那段 ✓）。
            #   ⇒ 没有框、也没有"融合在身"（`_merge_peak` ✓）的时候：**这一拍不动速度** ✓。
            #   ⚠ "融合在身"不能拿 `_merge_peak` 当挡箭牌 ✗：**真融合期框是在的**（只是大 ✓）
            #     ⇒ `tbox is None` 本身就等于"框没了" ✓（实测：峰值因为"没框就不清"而永远留着
            #     ✗ ⇒ 条件恒假 ⇒ 速度照样被拽回 0 ✗✗）。
            _no_box = (tbox is None)
            # ⚠ **有框那一拍，速度已由"框自身位移 + T"决定**（`_vel_from_box` ✓ 更稳 ✓）⇒
            #   不再拿观测差再叠一次 ✗（白块期观测差≈0 会把速度拽回 0 ✗ 实测）。
            # ⭐⭐⭐ **这一支不再拿"观测差"改自身速度** ✗✗（2026-10-01 trace 实锤 ✓）：
            #   `nv = (观测 − raw)/dt` 量到的是**本拍的修正量**（位置贴得紧时 ≈ 0 ✗），
            #   **不是目标速度**（真实自身速度 50px/s 也能量成 0 ✗）⇒ EMA 只会把它拖向
            #   −群体（trace：case1 帧 25~30 把正确的 (49.7,32.6)px/s 一路腐蚀到 (-4,-14)
            #   ✗ 顺带还藏着一处域 bug：`best`/`_raw` 是半域、`_gv` 是小图域 ✗）。
            #   速度的三个来源 = **框相对群体** / **缺口首尾** / **夹取完结算**（③ ✓ 白块
            #   那种"无红框"的拍走 ③ 的 realized 路 ✓ 实测帧 22~24 靠它学到正确速度 ✓）
            #   ⇒ 这里只保留"对外速度 = 自身(沿用) + 群体(当拍)"的刷新 ✓。
            if dt and dt > 0.05 and self._raw is not None and not frozen \
                    and not self._vel_from_box and not _no_box:
                _gv = self._group_vel(dt)
                # 对外速度 = 自身(EMA ✓ 沿用) + 群体(**当拍** ✓ 不滞回 ✓)
                if _gv is None:
                    self._set_vel(self._vel[0], self._vel[1])
                else:
                    self._set_vel(self._vel_rel[0] + _gv[0], self._vel_rel[1] + _gv[1])
            self._set_raw(best, dt)
            # ⭐⭐⭐ **信念约束：没分离之前，目标一定还在那格框里**（用户 2026-09-30 定稿 ✓
            #   原话："你要理解'红框代表我们认为真目标在它里面'，这个认知要保持到'分离'信号的
            #   出现" ✓）。
            #   ⇒ 每拍把内部位置**夹进 `tbox`**（框缩小时 ⇒ 自然被"**拉**"向留下的那一侧 ✓
            #   用户原话："第 18 帧红框面积缩小了，那么它应该'拉着'追踪器的绿圈往左移动" ✓）。
            #   ⚠ 夹的是 `_raw`（源 ✓）⇒ 报告位置照旧过限速 ✓（是"拉"不是瞬移 ✓）。
            #   ⚠ 只在**有框**（`tstate != "gone"` ✓）时夹：没有框 = 后端没答案 ⇒ 不夹 ✓。
            #   ⭐⭐ **融合框（面积 ≥ 「融合框判定阈值」× 标准面积 ✓）不夹**（用户 2026-10-01
            #      ✓ 原话："融合大红框后，绿圈继续按白箭头的指示行动" ✓）—— 并集框框不住
            #      目标一个人 ⇒ 拿它当约束就是把圆往并集中心拉 ✗ ⇒ 位置交给预测 ✓。
            if not self._tbox_merged or self._merge_first:
                self._clamp_into_tbox(tbox)
                # ⭐⭐⭐ **夹取限速（第二处硬夹 ✓ 用户 2026-10-03 ✓ 原话："动手" ✓）**：这一行原来
                #   也是 `_pos_in_tbox` **硬夹** ✗ —— 实测它是**白线跳变的主犯** ✓（只改 `process()`
                #   出口那一处时折角一字不变 ✗ 因为这一处先把 `pos` 一步塞进框里了 ✓）：帧 48 认到
                #   远处那格框 ⇒ 这里一步 97.9px ✗。⇒ 同一把尺（`_clamp_step` ✓ B 型步数比例 ✓
                #   帧率无关 ✓）限速 ✓；圆已在安全区 ⇒ 一动不动 ✓。
                self.pos = self._clamp_step(self._report_pos(dt), tbox, dt)
            self.area = det_area if det_area is not None else \
                self._area_of(cands, best) * (_SCALE ** -2)
            self.lost_n = 0
        else:
            # ⭐ **S1 融合 / S2 刚分离 / S3 漏检：一律"按上一次速度滑行"**（恒定速度 ✓
            #   事实 2/6/7 ✓）—— 目标一帧走 ~一帧的量、平滑 ✓，滑行是最不坏的估计 ✓。
            # ⭐⭐⭐ **丢帧计数只认"连红框都没有"的拍**（用户 2026-10-01 ✓ "40帧绿圈怎么丢了" ✓）：
            #   融合/分离期**红框还在**（`tbox is not None` ✓）⇒ 目标没丢，只是没有"直接位置观测"
            #   （白块没了 + 残差候选观测已删 ✓）⇒ 不该累积 `lost_n` ✗✗ —— 否则融合期连续 ~9 拍
            #   无观测 ⇒ `lost_n > _LOST_AFTER` ⇒ 报 lost ⇒ 绿圈凭空消失（实测帧 40 ✓✓）。
            if tbox is None:
                self.lost_n += 1
            else:
                self.lost_n = 0
            # ⭐⭐ **框速度只当"救援"**（2026-09-30 实测 ✓）：残差**有观测**时它就别插嘴 ✗
            #   —— 实测拿它（`T + 模板自残差`）在有观测的拍上盖速度，会把好速度污染成
            #   (19,8)px/s（真值 ~(80,26) ✗）⇒ 位置稳在 15px 外下不来 ✗✗；而纯残差路线的
            #   位置误差中位只有 **0.6px** ✓✓。⇒ 顺序改成：**先信观测** ✓；观测没了才让框说话 ✓
            #   （这正是用户第 1 条的场景："真目标框还在 ⇒ 有速度" ✓）。
            if tbox is not None and tstate == "ok" and dt and ev.get("t") is not None and dets:
                # ⭐ **同一把测量有效性守卫**（`_box_flags` ✓）：并集块框心锁在群体上（学出 0 ✗）、
                #   碎片/贴边框心被边缘偏置拖着走（学出反向假速度 ✗）⇒ 都不学 ✓
                #   （trace：case1 帧 27~30 靠这条路把 (49.7,32.5) 腐蚀到 (3.1,-3.9) ✗）。
                if self._box_flags(tbox) == (False, False):
                    _sr = self._box_self_resid(ev, dets, tbox)
                else:
                    _sr = None
                if _sr is not None:
                    _vx = (float(ev["t"][0]) + float(_sr[0])) / float(dt)
                    _vy = (float(ev["t"][1]) + float(_sr[1])) / float(dt)
                    if abs(_vx) + abs(_vy) <= _V_MAX:
                        # ⭐ 拆开存：**自身分量** = `self_resid/dt` ✓（A 层模板匹配给的正是
                        #   "目标**相对群体**的自身位移" ✓ 比框中心差分稳 ✓）
                        _rx, _ry = float(_sr[0]) / float(dt), float(_sr[1]) / float(dt)
                        self._vel_rel = self._rel_cap(
                            (self._vel_rel[0] * _VEL_KEEP + _rx * (1 - _VEL_KEEP),
                             self._vel_rel[1] * _VEL_KEEP + _ry * (1 - _VEL_KEEP)))
                        self._set_vel(self._vel_rel[0] + float(ev["t"][0]) / float(dt),
                                      self._vel_rel[1] + float(ev["t"][1]) / float(dt))
            # ⭐⭐⭐ **用"假目标群的平均速度向量"预测轨迹**（用户 2026-10-01 定稿 ✓ 原话：
            #   "**实时计算所有登记假目标群的平均速度向量**"、"然后**用平均速度向量预测轨迹**" ✓）。
            #   为什么这是对的 ✓：假目标**只随背景平移、彼此相对静止** ✓（用户事实 2/3 ✓），而
            #   真目标**也随背景一起走** ✓ —— 所以**没有观测的那一拍**（融合期 / 漏检 ✓）里，
            #   "大家怎么动"就是**最可信的运动先验** ✓✓（比"沿用上一拍的旧速度"更贴 ✓ 因为
            #   背景的平移是**每拍都在变**的 ✓）。
            #   ⚠ 只在**够多条参与**（`avg_vel_n ≥ 3` ✓）时才采信 ✗ —— 一两条算出来的"平均"
            #     没有意义 ✓（会被个别条目的抖动主导 ✓）。
            _gv = getattr(self._reg, "avg_vel", None)
            if (_gv is not None and dt and float(dt) > 0.05
                    and int(getattr(self._reg, "avg_vel_n", 0)) >= 3):
                _gx, _gy = float(_gv[0]) / float(dt), float(_gv[1]) / float(dt)   # px/帧 ⇒ px/s
                if abs(_gx) + abs(_gy) <= _V_MAX:
                    # ⚠⚠ **原来这里是 `_set_vel(_gx,_gy)`** ✗✗ —— 直接把速度**盖成"群体怎么走"**
                    #   ⇒ **丢掉目标自己的运动** ✗（用户 2026-10-01 口径正是要"**相对群体**"✓：
                    #   群体分量用当拍实测 ✓、自身分量沿用 EMA ✓ ⇒ 两者**相加** ✓）。
                    self._gv_now = (_gx, _gy)
                    # ⭐ 群体速度**模长**入窗 + 取中位（实验 2026-10-02 ✓ "白箭头模长 = 假目标
                    #   群体的标准速度模长" ✓）：`_gx/_gy` 是**处理域** px/s ✗ ⇒ ×`_SCALE` 折到
                    #   **小图域** ✓（与 `vel_rel` 同域 ✓ 演示窗才好直接换模长 ✓）。
                    self._set_vel(self._vel_rel[0] + _gx, self._vel_rel[1] + _gy)
                    # 预测点**用新速度重算**（下面 `_set_raw` 走的就是它 ✓）
                    if (not _pred_path) and self._raw is not None:
                        fx = self._raw[0] + (self._vel[0] * dt) * _SCALE
                        fy = self._raw[1] + (self._vel[1] * dt) * _SCALE
            if fx is not None:
                # ⭐ **S2（事实 7）**：融合块**突然变小**⇒ 目标已经**出去了**、且此刻它**就在
                #   这个小框里** ✓ ⇒ 把滑行位置**夹进新框**（只夹不外推 ✗ —— 框给的是**边界
                #   信息** ✓，比继续按速度滑更可信 ✓）。
                self._set_raw((fx, fy), dt)
                # ⭐ **同一套信念约束**（有框就把位置夹进去 ✓ 与"有观测"那条路完全一致 ✓）：
                #   融合期/分离期没有观测时，这条夹取就是"把绿圈拉住"的唯一手段 ✓。
                #   ⚠ 融合框照样除外 ✓（同上：融合 ⇒ 位置按预测走 ✓）。
                if not self._tbox_merged or self._merge_first:
                    _rp7 = self._report_pos(dt)
                    # ⭐⭐⭐ **这里是"认框那一拍"把圆夹进框的唯一一处硬夹**（用户 2026-10-03 ✓
                    #   "选这个融合框后明显会超过白箭头限速" 指的就是它 ⇒ 实测 `10月3日.mp4` 帧 64：
                    #   (223.6,304.3) → (297.1,244.6) = **96.5px**（726 px/s ✗））。
                    #   ⚠⚠ **曾经改成限速版（`_clamp_step`）⇒ 已撤销** ✗（同日实测 ✓ 两条理由）：
                    #     ① **零收益** ✗ —— 那样改**并没有**让帧 64 的折角变小（仍是 **84.3px** ✗，
                    #        折角的来源另在别处 ✓ 待定位 ✓）；
                    #     ② **有代价** ✗ —— 它让"圆**暂时探出框**"出现在本来不会探出的路径上 ⇒
                    #        demo 自检「**红框检出的每一帧绿圈都内接于红框**」（用户 2026-10-01 定稿 ✓）
                    #        当场红 **3 帧**（32 / 46 / 57 ✗）。
                    #   ⇒ 保留**硬夹**（= 老口径"绿圈与红框内接、没有过渡期"✓）；要治帧 64 那一下，
                    #     得先定位折角的真正来源 ✗（不是这里 ✓）。
                    _cp7 = self._pos_in_tbox(_rp7, tbox) if _rp7 is not None else None
                    # ⭐⭐⭐ **分离那一拍：不夹、按白箭头（预测）继续走**（用户 2026-10-01 ✓ 两条口径
                    #   一起看 ✓）：
                    #     · "任何情况下，都不允许将绿圈往预测方向的反方向跑" ✓（原话 ✓）；
                    #     · "第27帧→第28帧大红框变成与登记框重叠的检出框，这是分离的信号，绿圈应该
                    #       **按上一帧的预测走**" ✓（原话 ✓）。
                    #   实测（9月30日(1).mp4 显示帧 39→40 ✓）：分离那一拍红框塌缩到左侧（那是**假
                    #   目标自己那格** ✓）、白箭头却指右下 ⇒ 夹取把圆**向左拽 91px** ✗✗ —— 正是用户
                    #   截图圈出来的那一下 ✓。⇒ 这一拍报告位置 = **预测点** ✓（`_raw` 此刻已是预测点
                    #   ✓ 上面 `_set_raw((fx,fy))` ✓ 没被夹过 ✓）。
                    #   ⚠⚠ **这一拍同时不再对外报红框** ✗（`_split_skip` ✓ 见 `_out` ✓）：圆已经按预测
                    #     跑到框外 ✓ ⇒ 再画红框就与"**绿圈必须内接于红框**"（用户 2026-10-01 定稿 ✓
                    #     `selftest_lie_demo` 第 ⑦ 条 ✓）直接打架 ✗ —— 两条口径不能同时成立 ✓ ⇒ 按用户
                    #     那句"分离 ⇒ 红框消失、进淡粉色**预测态**"处置 ✓。
                    if self._merge_split:
                        self.pos = _rp7 if _rp7 is not None else self.pos
                        self._split_skip = True
                    else:
                        self._clamp_into_tbox(tbox)
                        self.pos = _cp7 if _cp7 is not None else _rp7
            # ⭐⭐⭐ **预测态太久的后台重新捕获（复活）= 已停用**（用户 2026-10-02 ✓ 原话：
            #   "**停用这个逻辑**" ✓）。原实现：红框连丢 `> _LOST_AFTER` 帧 ⇒ 后台试
            #   `_try_recapture`（找到就复活回锁定、找不到继续预测 ✗）—— **绝不翻 state** ✓
            #   （一直是 track ⇒ 绿圈照画、淡粉框照画 ✓）；只在**红框也丢了**（`tbox is None` ✓）
            #   才试（红框还在就谈不上"丢" ✗）。
            #   ✗✗ **为什么停用**（实测归因 ✓ 用户 2026-10-02 问的"10月1日 第 69 帧" ✓）：
            #     复活第①条"运动判据"用的是 `_update_tracks` 的**当拍运动冠军** `mt` ✓ ——
            #     而那个冠军**只要求"这一帧 dev 最大 + 过三道置信闸"** ✗：**没有**任何
            #     "是不是当前认定的目标（`_target_id`）／离预测多远／是否连续几拍"的门 ✗✗。
            #     实测 `10月1日.mp4` 显示帧 69：`lost_n=9 > _LOST_AFTER(8)` ⇒ 复活① 采纳
            #     `mt=(0.0, 450.4, dev=73, 73×21, 面积 1388)` = **画面左缘一条细长干扰**
            #     （真目标不会瞬移到 x=0 ✓）⇒ 位置被拽向它、限速器截成 44.6px ⇒ 圆心走了个
            #     **与白箭头几乎垂直**的位移（139.3° vs 20.9° ✓ 甲/改前两版一致 ⇒ 与"甲"无关 ✓）。
            #   ⚠ 现在的丢框期行为 = **纯预测滑行 + 夹取** ✓（位置只由 ①预测 ②夹取 决定 ✗
            #     没有第三方"把圆拽回目标"的动作 ✓）；目标重新出现时靠**红框判定**
            #     （`_target_box_state` ✓ + 检测吸附 `_DET_GATE` ✓）接回 —— 那两条**没动** ✓。
            #   ♻ **要接回**：放开下面两行即可 ✓ —— `_try_recapture` 方法、`_recap` 队列、
            #     `_RECAP_*` / `_LOST_AFTER` 常量**全部原样保留** ✓（用户选的是"停用"而非"删除" ✓）。
            # if tbox is None and self.lost_n > _LOST_AFTER:
            #     self._try_recapture(dets, dt, ts, _mt)
        # ⭐⭐⭐ **③ 夹取完再结算**（用户 2026-10-01 定稿 ✓ 原话："**夹取完再计算本帧与上一帧
        #   的预测**" ✓）：用"**这一拍实际落在哪**（已预测 + 已夹取 ✓）"与上一拍的位置差 ✓
        #   减去群体速度 ⇒ 才是**圆圈真实走出来的自身速度** ✓✓。
        #   为什么必须这样 ✗（实测 ✓）：改前速度是从**裸观测**算的 ✗（没经过预测/夹取 ✓）
        #   ⇒ 白箭头说 `(+5.8,+16.1)` px，圆圈实际只走 `(−2.5,+8.7)` px ✗✗（用户当场看出来 ✓）；
        #   换成"实际位移"后，**箭头 = 圆圈真的会走多少** ✓（被夹住时也如实反映 ✓ 下一拍就
        #   自动纠正 ✓）。
        # 用户 2026-10-01 定稿：白箭头(预测)与夹取无关，夹取只改本帧圆圈位置。
        # => 这一步只在【无红框】那一拍做（那拍本来就没有夹取，raw 未被污染），
        #    有红框的拍子由【红框相对群体的位移】直接给出（见上面 box 分支）。
        # ⭐⭐⭐ **且只在【这一拍有观测】时结算** ✗✗（2026-10-01 trace 实锤 ✓）：
        #   纯预测滑行那一拍（白块没有、红框没有 ✗），raw 的位移 = **预测本身的回声**
        #   （fx = raw + vel·dt ⇒ "结算"出来的就是 vel 减群体 ⇒ 原样喂回 vel_rel ✗）——
        #   唯一的"新信息"是**群体测量的误差 ε**，每拍以 0.65 增益灌进 vel_rel ⇒
        #   **正反馈随机游走**（trace：case2 帧 30 一拍把 vel_rel 从 (-8,-16) 打到
        #   (-51,-47)，之后一路游走到 (-80,-65) ✗ 目标回到画面里也追不上了 ✗✗）。
        #   真正有信息的是【白块观测来过、把 raw 挪了】的那拍（case3 帧 22~24 靠它学到
        #   正确的 (48.8,32.5)px/s ✓）⇒ 保留 ✓；纯滑行拍⇒ 不动速度（沿用 ✓ 用户"需要延续"✓）。
        if (tbox is None and best is not None and dt and float(dt) > 0.0
                and self._raw is not None and self._raw_prev is not None):
            _gv1 = self._group_vel(float(dt))
            if _gv1 is not None:
                _nv1 = (((self._raw[0] - self._raw_prev[0]) / _SCALE) / float(dt),
                        ((self._raw[1] - self._raw_prev[1]) / _SCALE) / float(dt))
                _rv1 = (_nv1[0] - _gv1[0], _nv1[1] - _gv1[1])
                if abs(_rv1[0]) + abs(_rv1[1]) <= _REL_V_MAX:
                    self._vel_rel = self._rel_cap(
                        (self._vel_rel[0] * _BOX_VEL_KEEP + _rv1[0] * (1 - _BOX_VEL_KEEP),
                         self._vel_rel[1] * _BOX_VEL_KEEP + _rv1[1] * (1 - _BOX_VEL_KEEP)))
                    self._vel_realized = _rv1
                    self._vel_src = "realized"
                    self._set_vel(self._vel_rel[0] + _gv1[0], self._vel_rel[1] + _gv1[1])
        self._raw_prev = self._raw
        # ⭐⭐ **轨迹样本入窗**（用户 2026-10-01 新口径 ✓ 见 `_path_pred` ✓）：用**内部位置**
        #   `_raw`（= 预测 + 夹取后的最优估计 ✓）而不是带限速滞后的 `pos` ✗ ✓。
        if self._raw is not None and ts is not None:
            # ⭐ **这一拍发生过夹取 ⇒ 不入样**（读走并复位 ✓ —— 上一拍统一出口若挪过 raw，
            #    标记留到这一拍消费 ✓）：样本必须是"目标自己的运动" ✓，混进夹取量会把
            #    群体系曲线掰弯 ⇒ 切向拟合被带偏 ✗（trace：case1 帧 25~36 夹取把样本按在
            #    边缘框上 ⇒ 切向速度学成 ≈0 ⇒ 预测退化成"只跟群体" ✗）。
            _was_clamped = bool(getattr(self, "_clamped", False))
            self._clamped = False
            if getattr(self, "_path", None) is None:
                self._path = []
            if getattr(self, "_path_cumT", None) is None:
                self._path_cumT = (0.0, 0.0)       # 累计群体平移（半域 ✓ 独立于样本 ✓）
            # ⭐ **每拍都累计**（样本被过滤跳掉也照累计 ✓）：这一拍的群体平移
            #    （加工域 px/帧 ✓ `_t_hist[-1]` = 本拍实测 ✓）换算到半域 ✓。
            _Tf = ((float(self._t_hist[-1][0]) * _SCALE, float(self._t_hist[-1][1]) * _SCALE)
                   if self._t_hist else (0.0, 0.0))
            _cum = (self._path_cumT[0] + _Tf[0], self._path_cumT[1] + _Tf[1])
            # 域统一：样本元组 = `(ts, x, y, cumTx, cumTy)` —— x/y 是半域 `_raw` ✓，
            # cumT 是"到这一拍为止"累计的群体平移（半域 ✓）⇒ `x - cumTx` = 群体系坐标 ✓，
            # `_path_pred` 的拟合/速度/返回值全部半域 ✓（换算只发生在预测加回群体那一步 ✓）。
            # 突变过滤（相对群体 ✓）：这一拍【相对群体】的位移太大 ⇒ 是限速追赶/错观测，
            # 不是目标运动 ⇒ 丢这个样本（cumT 照常推进 ✓）。
            _keep = not _was_clamped
            _gx = self._raw[0] - _cum[0]          # 群体系当前位置 ✓
            _gy = self._raw[1] - _cum[1]
            if _keep and getattr(self, "_grp_prev", None) is not None:
                _rx = _gx - self._grp_prev[0]
                _ry = _gy - self._grp_prev[1]
                if (_rx * _rx + _ry * _ry) ** 0.5 > _PATH_REL_MAX:
                    _keep = False
            # ⭐⭐ **锚点每帧推进**（无论入不入样 ✓）：原来跟 `_path[-1]` 比 ✗ —— 一帧被拒 ⇒ 之后
            #   全跟那个**旧锚**比 ⇒ 位移越积越大 ⇒ 全被连坐拒掉 ⇒ 路径卡死（实测 9月30日 只剩 2
            #   个样本 ✗✗ 白线画成一点 ✗）。
            self._grp_prev = (_gx, _gy)
            self._path_cumT = _cum
            if _keep:
                self._path.append((float(ts), self._raw[0], self._raw[1], _cum[0], _cum[1]))
            self._path = self._path[-12:]          # 10fps ⇒ 12 帧 ≈ 1.2s ✓ 够 500ms 窗 ✓
        self._tbox_prev = tbox          # ⭐ 记下这拍的红框（下一拍直接用中心差量相对位移 ✓）
        # ⚠⚠ 融合块的"右下相切落位"**不在这里做** ✗ —— 它在 `process` 的**统一出口** ✓
        #   （写在分支里会被后面的限速/观测/夹取覆盖 ✗ 实测第 17 帧就是不生效的那个 ✓）。
        return self._out("track")

    @staticmethod
    def _area_of(cands, pos):
        for cx, cy, a in cands:
            if (cx, cy) == pos:
                return a
        return 0.0

    def _build_merge_log(self):
        """**融合框生成**那一拍的日志载荷（用户 2026-10-02 ✓ 原话："当融合框生成时添加日志，
        显示**相关的砖**以及**解释判定为融合框的计算数据**" ✓；⭐ 2026-10-03 ✓ 用户口径：
        "**融合、分离的信息希望按判定顺序写**，可以写通俗易懂点（**能知道为什么最后判成这样
        了**），**判定之后的就不用写了**" ✓）。

        只在 `_merge_first`（上一拍不是融合框、这一拍是 ✓ 见 `_step_track`）那一拍非空 ✓
        —— 融合**保持期**不重复刷 ✗（保持期的框不再走规则①② ✓ 用户 2026-10-02 口径 ✓）。

        · `text` = **多行中文**（演示窗的深色日志区是 `QPlainTextEdit` ⇒ 多行照收 ✓）：
          第一行给结论 ✓，之后**按判定的先后**把"当时真正算过的量"一条条列出来 ✓
          —— 读者顺着 ①②③ 就能复现"为什么最后判成融合" ✓；
        · `data` = 结构化那份（自检/排查用 ✓）。
        """
        w = getattr(self, "_merge_why_snap", None)
        if not w:
            return None
        _b = w.get("box")
        _rb = w.get("ref_box")
        if _b is None or _rb is None:
            return None
        _rule = w.get("rule") or "?"
        _bid = w.get("ref_bid") or (0, 0)
        _cov = float(w.get("cov", 0.0))
        _ratio = float(w.get("ratio", 0.0))
        _thr = float(w.get("thr", 0.0))
        _ntol = float(w.get("ntol", 0.0))
        _rad = float(w.get("rad", 0.0))
        _pend = "（形状待定中：登记尺寸不可信）" if w.get("ref_pending") else ""
        # ① "这格框里有没有砖" —— 判定的第一步（`_fake_ref` ✓ 覆盖率就是它给的 ✓）
        _l1 = ("  ① 框 (%.1f,%.1f) %.0f×%.0f 里压着一块假目标：参照砖（出生位 %d,%d）现在 "
               "(%.1f,%.1f) %.0f×%.0f%s —— 覆盖率 %.0f%%（≥ 75%% 就算「框包住了砖」✓）"
               % (float(_b[0]), float(_b[1]), float(_b[2]), float(_b[3]),
                  int(_bid[0]), int(_bid[1]), float(_rb[0]), float(_rb[1]),
                  float(_rb[2]), float(_rb[3]), _pend, _cov * 100.0))
        # ②③ 两条规则各自的**判据顺序**（规则② 先判"整圈绿圈"，规则① 判"面积比 + 圆心范围" ✓）
        if _rule == "②":
            _l2 = ("  ② 整圈绿圈（半径 %.1f）完全落在这格框里 ✓" % (_rad,))
            _l3 = ("  ③ 面积比 = 框面积 ÷ 砖面积 = %.3f ≤ %.2f（「面积与砖相等也算融合」那一档 ✓）"
                   % (_ratio, float(w.get("ov_max", 0.0))))
            _tail = "  ⇒ ②③ 都成立 ⇒ 判定**融合**（规则②）"
        elif _rule == "①":
            # ⭐⭐⭐ **文案按新口径写**（用户 2026-10-03 ✓ 原话："把『融合框判定阈值』换成
            #   『**融合框判定 IoU**』：**小于这个 IoU 才行**" ✓）—— ⚠ 用户当场发现："log 没变？
            #   还是逻辑都错了" ✓：**逻辑已改**（`_is_merged_box` 用 `_iou_b < self.merge_iou` ✓）
            #   而**这里漏改** ✗ ⇒ 日志还在写"面积比 ≥ 阈值"、还把 **IoU 阈值当面积比阈值**显示 ✗✗
            #   （例：阈值 0.75 写成"面积比 1.228 ≥ 0.75"⇒ 读起来像对的 ✗ 其实是两把尺混了 ✗）。
            _iou = float(w.get("iou", 0.0))
            _l2 = ("  ② IoU = 框∩砖 ÷ 两者并集 = %.3f **< 阈值 %.2f** ✓（两框**不是同一格** ⇒ "
                   "才算「并集」✓ **越小越严** ✓）" % (_iou, _thr))
            _l3 = ("  ③ 圆心±%.1f px 的范围与这格框相交 ✓（圆心就落在框内 ⇒ 按新口径直接放行 ✓）"
                   % (_ntol,))
            _tail = "  ⇒ ②③ 都成立 ⇒ 判定**融合**（规则①）"
        else:
            _l2 = "  ② （规则代号缺失，见 data）"
            _l3 = ""
            _tail = "  ⇒ 判定**融合**"
        _txt = ("融合判定 ｜ 结论：**融合**（规则%s，这就是「融合框生成」那一拍）\n%s\n%s\n%s%s"
                % (_rule, _l1, _l2, _l3, _tail))
        return {"text": _txt, "data": dict(w)}

    def _build_split_log(self):
        """**融合框消失（分离）**那一拍的日志载荷（用户 2026-10-02 ✓ 原话："把融合框消失
        （分离）的日志**也依据融合的格式**打印出来" ✓；⭐ 2026-10-03 ✓ 用户口径：**按判定顺序
        写、通俗易懂、判定之后的不用写** ✓ 与 `_build_merge_log` 同一规矩 ✓）。

        与 `_build_merge_log` **同一形状**（`text` 给演示窗照原样显示 ✓、`data` 给自检 ✓）：
        第一行 = **因哪条判出去** ✓；之后按该条**判据的先后**把当时算过的量逐条列出 ✓
        （"框 → 参照砖 → 四边差 → 框心方向 → 融合期面积" ✓ = `_box_is_brick_det` 三条的次序 ✓）。

        只在 `_merge_split`（上一拍是融合框、这一拍不是 ✓ 见 `_step_track`）那一拍非空 ✓
        —— 融合保持期不刷 ✗（与融合日志同规矩 ✓）。
        """
        w = getattr(self, "_split_why", None)
        if not w:
            return None
        _b = w.get("box")
        _rb = w.get("ref_box")
        _bid = w.get("ref_bid") or (0, 0)
        _how = w.get("how") or "?"
        _lines = []
        _k = [0]

        def _step(_s):
            """**按实际写出来的条数**编号 ⇒ 中间省略某条时不会跳号 ✓。"""
            _k[0] += 1
            return "  %s %s" % ("①②③④⑤⑥⑦"[min(_k[0] - 1, 6)], _s)

        # 判定第一步：**有没有拿来判的框**（覆盖率/面积比这两个量就在这里 ✓ 与融合日志同一把尺 ✓）
        if _b is None:
            _lines.append(_step("这一拍没有拿来判的框：框 = —（检不出 / 门内一个候选都没有）"))
        else:
            _lines.append(_step(
                "拿来判的框 (%.1f,%.1f) %.0f×%.0f：覆盖率 %s、面积比 %s"
                % (float(_b[0]), float(_b[1]), float(_b[2]), float(_b[3]),
                   ("—" if w.get("ref_cov") is None else "%.2f" % float(w.get("ref_cov"))),
                   ("—" if w.get("ratio") is None else "%.3f" % float(w.get("ratio"))))))
        # 参照砖（判定的锚 ✓）
        _lines.append(_step(
            "参照砖已被回收（登记表里找不到它了）" if _rb is None
            else "参照砖（出生位 %d,%d）现在 (%.1f,%.1f) %.0f×%.0f"
                 % (int(_bid[0]), int(_bid[1]), float(_rb[0]), float(_rb[1]),
                    float(_rb[2]), float(_rb[3]))))
        # 四边差（"框已缩成砖"那条的判据 ✓）—— ⚠⚠ **结论必须按实际值给** ✗✗：实测帧 23 是
        #   "框**不再包住**参照砖"那一支离开的，四边差 `-41.3／-79.0／79.3／83.0` 远超容差 ⇒
        #   不能写"全部 ≤ 容差 ✓"（那就是假结论 ✗）⇒ 用 `_split_diag` 同一次算的 `brick_det` ✓。
        _ed = w.get("edges")
        _ntol = float(w.get("ntol", 0.0))
        if _b is not None:
            if _ed is None:
                _lines.append(_step("四边差 = —（这一拍没有拿来判的框）"))
            else:
                _bd = bool(w.get("brick_det"))
                _lines.append(_step(
                    "四边差（左/右/上/下）= %.1f／%.1f／%.1f／%.1f px（容差 %.1f px）"
                    " ⇒ %s"
                    % (float(_ed[0]), float(_ed[1]), float(_ed[2]), float(_ed[3]), _ntol,
                       "四条边都在容差内 ⇒ **框已缩成砖** ✓" if _bd
                       else "有边超出容差 ⇒ 这格**不是**「缩成砖」那一档")))
        # 分离信号第二条：框中心在白箭头方向上的投影（**按实际值**给结论 ✗ 不写死 ✓）
        _dot = w.get("dot")
        if _dot is not None:
            _lines.append(_step(
                "框中心在白箭头方向上的投影 = %.0f px²/s（%s）"
                % (float(_dot),
                   "反方向 ⇒ 这条成立 ✓" if float(_dot) < 0 else "顺向 ⇒ 这条不成立")))
        # 分离信号第三条：融合期面积有没有"真的缩过"（只对"框已缩成砖"那一档有意义 ✓）
        _amn, _ami = w.get("area_prev_max"), w.get("prev_max_idx")
        _amx = w.get("area_self")
        if _amn is not None and _amx is not None:
            _rr2 = float(w.get("area_ratio") or 0.0)
            _thr2 = float(w.get("sep_ratio", 0.0))
            _lines.append(_step(
                "融合期面积：**历史最小之后的最大 %.0f**（第 %s 拍）≥ 本拍 %.0f × 阈值 %.2f"
                "（比 %.2f ⇒ %s）"
                % (float(_amn), (None if _ami is None else int(_ami) + 1), float(_amx),
                   _thr2, _rr2,
                   "成立 ✓" if _rr2 >= _thr2 else "不成立（本次不是靠这条判的 ✓）")))
        _lines.append("  ⇒ 判定**分离**（%s）" % (_how,))
        _txt = ("融合框消失（分离）｜ 结论：**分离**（%s）\n%s" % (_how, "\n".join(_lines)))
        return {"text": _txt, "data": dict(w)}

    def _build_edge_log(self):
        """**融合期"每拍"的边归属日志**（用户 2026-10-02 ✓ 原话："日志里，融合时期每拍打印
        一下**边的归属（砖或真目标）**" ✓）。

        与 `merge_log` / `split_log` 的差别：那两个**只在"进门/分离"那一拍**给 ✗，这一份是
        **融合期每拍都给** ✓（看的就是"归属怎么一拍拍变过去"✓ —— 融合框缩小的过程里，几条边
        先归回真目标，是判断"快分离了"的直接线索 ✓）。

        内容 = 四条边**逐条**标"砖 / 真目标"（`_edge_ownership` ✓ True = 这条边 ≈ 某块砖的
        对应边、即**归属假目标** ✓）+ 参照砖身份 + 条数统计 + 噪声容差（判归属那把尺 ✓）。
        判据仍在 `_edge_ownership` 里算 ✓ 这里只组句子 ✗（口径一处 ✓）。
        """
        _tb = self._tbox
        if _tb is None:
            return None
        _own = self._edge_ownership(tuple(float(v) for v in _tb))
        _n = sum(1 for _v in _own if _v)
        _ref = self._hold_ref()
        _rb = ("无参照砖" if _ref is None
               else "（出生位 %d,%d）现在 (%.1f,%.1f) %.0f×%.0f"
                    % (int(_ref.bid[0]), int(_ref.bid[1]), float(_ref.x), float(_ref.y),
                       float(_ref.w), float(_ref.h)))
        _sides = " / ".join("%s=%s" % (_s, "砖" if _o else "真目标")
                            for _s, _o in zip(("左", "右", "上", "下"), _own))
        _txt = ("融合期边归属 ｜ 框 (%.1f,%.1f) %.0f×%.0f ｜ 参照砖 %s ｜ %s"
                " ⇒ 归属砖 %d 条 / 真目标 %d 条（容差 %.0f px）"
                % (float(_tb[0]), float(_tb[1]), float(_tb[2]), float(_tb[3]), _rb,
                   _sides, _n, 4 - _n, float(self.noise_tol)))
        return {"text": _txt,
                "data": {"own": [bool(_v) for _v in _own], "n_brick": int(_n),
                         "box": tuple(float(_v) for _v in _tb),
                         "ntol": float(self.noise_tol)}}

    def _build_pick_log(self):
        """**非融合红框**那一拍的日志载荷（用户 2026-10-03 ✓ 原话："在日志加一下**非融合红框
        选择**的判定信息吧" ✓）。

        与 `_build_merge_log` / `_build_split_log` / `_build_edge_log` **同一规矩** ✓（用户
        2026-10-03 口径 ✓）：第一行给**结论** ✓、之后**按判定的先后**把"当时真正算过的量"列
        出来 ✓、**判定之后的就不用写** ✓。

        触发 = 这一拍**出了红框**（`_tbox` 非 None ✓）且**不是融合框**（`_tbox_merged` 假 ✓）
        —— 决策链上就是"**目标自己那格**"那一条（`_circle_hits` ✓）。四条日志互补 ✓：
        `merge`（生成）→ `edge`（融合期每拍边归属）→ `pick`（本条：非融合红框）→ `split`（消失）✓。
        """
        w = getattr(self, "_pick_why", None)
        if not w:
            return None
        _b = w.get("box")
        if _b is None:
            return None
        _a = float(_b[2]) * float(_b[3])
        _inner, _rad = w.get("inner"), float(w.get("rad", 0.0) or 0.0)
        if _inner is None or _rad <= 0.0:
            # ⚠ 半径还没学到那几拍（开局 ✓）⇒ 判据退回"**圆心在框内**"那一档 ✓ 日志照实说 ✓
            #   （别写"垂距比 0.00、半径 0.0"✗ 那看着像真值 ✓ 实测帧 4/5 就是这种 ✓）。
            _l5 = ("  ⑤ 与**绿圈相交**吗？**是** ✓ —— 绿圈半径还没学到（%s）⇒ 退回"
                   "『**圆心在框内**』那一档判定 ✓"
                   % ("拿不到垂距" if _inner is None else "半径 = 0"))
        else:
            _l5 = ("  ⑤ 与**绿圈相交**吗？**是** ✓ —— 绿圈圆心到框最近边的有符号垂距 ÷ 半径"
                   " = **%.2f**（> −1 即相交 ✓；半径 %.1f ✓）" % (float(_inner), _rad))
        _lines = [
            "  ① 门内候选 **%d** 格 ⇒ 沿白箭头依次接触、挑**第一个够格**的"
            % int(w.get("n_cand", 0)),
            "  ② 选中框 (%.1f,%.1f) %.0f×%.0f（面积 %.0f）"
            % (float(_b[0]), float(_b[1]), float(_b[2]), float(_b[3]), _a),
            "  ③ 是**融合框**吗？**否**（是的话走「融合」那支 ⇒ 另有 merge_log ✓）",
            "  ④ 属于某块**已上板砖**吗？**否**（是的话**不出红框** ✓）",
            _l5,
            "  ⑥ 框心离绿圈圆心 **%.1f px**" % float(w.get("d_center", 0.0)),
        ]
        _txt = ("非融合红框选择 ｜ 结论：**出红框**（目标自己那格，非融合）\n%s"
                % "\n".join(_lines))
        return {"text": _txt, "data": dict(w)}

    def kf_summary(self):
        """**KF 影子模式的累计对照**（用户 2026-10-03 ✓ 演示窗状态栏用它 ✓ 纯读 ✓ 不影响任何判定 ✗）。

        返回 `None`（影子模式没跑过 / 没样本 ✓）或 dict：

        | 键 | 含义 |
        |---|---|
        | `n` | 样本数（拍数 ✓）|
        | `d_p50` / `d_p90` | **KF 位置 与 经典位置之差**的分位数（px ✓ —— 越小=越贴近现状 ✓）|
        | `innov_p50` / `innov_p90` | **新息模长**的分位数（px ✓ = 观测 − 先验预测 ✓）—— 它**就是**"经典输出里那部分抖动"的量级 ✓ ⇒ **直接给出观测噪声 σ 该取多大**（现在的默认 σ = 6px ✓ 见 `kf.KF_R_DEF` ✓）|
        | `nis_mean` | 归一化新息平方均值（2 维观测 ⇒ 理论 ≈ **2** ✓；远大于 2 ⇒ 观测里有离群跳变 ✓ 比如夹取那一拍 ✓）|
        """
        _a = getattr(self, "_kf_acc", None) or []
        if not _a:
            return None
        _ds = sorted(float(v[0]) for v in _a)
        _is = sorted(float(v[1]) for v in _a)
        _ns = [float(v[2]) for v in _a]

        def _q(v, p):
            if not v:
                return 0.0
            return float(v[min(len(v) - 1, int(round(p * (len(v) - 1))))])

        return {"n": len(_a), "d_p50": _q(_ds, 0.5), "d_p90": _q(_ds, 0.9),
                "innov_p50": _q(_is, 0.5), "innov_p90": _q(_is, 0.9),
                "nis_mean": float(sum(_ns) / len(_ns))}

    def _bricks_snap(self):
        """**本拍的砖表快照**（`[(bid, x, y, w, h), …]` ✓ 加工域 ✓ 用户 2026-10-03 ✓）。

        为什么逐帧都带 ✗：演示窗里"**点选某个检出框**"时要算"**它和哪块砖 IoU 最大**" ✓
        （用户原话："点选检出框的时候，希望他能显示 **IoU 最大的砖的 IoU**" ✓）—— 而砖表**每拍
        都在动**（跟着群体平移 ✓ 用户 2026-10-01："就算检出框消失了它也存在并跟着群体一起运动" ✓）
        ⇒ 拿"演算**结束**时的表"去算某一帧，位置会差一个累计平移 ✗ ⇒ **必须按那一帧的快照算** ✓。
        ⚠ 成本：每拍十几条 × 5 个数 ✓ 可忽略 ✓（不要在这里做任何判定 ✗ 纯快照 ✓）。
        """
        _reg = getattr(self, "_reg", None)
        if _reg is None:
            return []
        return [(tuple(e.bid), float(e.x), float(e.y), float(e.w), float(e.h))
                for e in (getattr(_reg, "entries", None) or [])]

    def _out(self, state):
        # ⭐⭐ **这一拍"红框到底在不在"**（与演示窗**画不画红框**完全同一口径 ✓）：它才是
        #   "漂移期"（= 淡粉色接力框那段 ✓）的判据 ✓ —— `_tbox` 丢了也**继续持有** ✗
        #   （用户口径"保持到分离" ✓）⇒ 拿它判 ⇒ 漂移期永远进不来 ✗（实测踩到 ✓）。
        self._tbox_now = (self._tbox if state == "track" else None)
        # ⭐⭐ **`_step_track` 交出来的速度**（= 融合期"按白箭头走"真正用的那支 ✓）：`process` 尾部
        #   的 ⑤分离接管 / ⑥曲线预测 / ⑦反向旋转 之后还会再改 `out["vel"]` ✗ ⇒ 那份**不是**这一步
        #   用的值 ✓ —— 诊断/自检要复算"圆心这一步走了多少"必须拿这一支 ✓（用户 2026-10-01 ✓）。
        self._vel_step = tuple(self._vel)
        # ⭐ `vel`（全分辨率 px/s，**已 EMA 平滑** ✓）：M2c 前馈用它 —— 让控制器
        #   别自己拿裸差分当速度（跳变会把前馈甩飞 85px ✗ 闭环实测 ✓）。
        # ⭐ `white`：本帧**白块观测的面积**（有 ⇒ 目标还没透明 ✓）。上层用它量"目标的**实际
        #   半径**"（`sqrt(A/π)` ✓ 用户 2026-09-30 口径 ✓）—— 白块一消失就该**冻结**这个量 ✓
        #   （透明阶段的框会被融合撑大 ✗ 拿它当"目标大小"会忽大忽小 ✗）。
        return {"state": state, "pos": self.pos, "area": self.area,
                "lost_n": self.lost_n, "init": self.init_t, "vel": self._vel,
                # ⭐⭐⭐ **速度的两个分量**（用户 2026-10-01 定稿 ✓ 原话："用**黄色箭头**标圆圈的
                #   **绝对速度**，用**白色箭头**标圆圈**相对于假目标群的速度预测**" ✓）：
                #   · `vel`（= 黄箭头 ✓）= **绝对/屏幕**速度（自身 + 群体 ✓ 控制器前馈用的就是它 ✓）；
                #   · `vel_rel`（= 白箭头 ✓）= **相对假目标群**的自身速度（就是"丢框后要延续"的那个 ✓）；
                #   · `vel_grp` = 本拍**实测**的群体速度（诊断 ✓ 图上不画 ✗）。
                "vel_rel": self._vel_rel,
                "tbox_rad": getattr(self, "_tbox_rad", None),
                "tbox_wh": getattr(self, "_tbox_wh", None),
                "vel_grp": self._gv_now,
                "white": (None if self._white_cur is None else self._white_cur[2]),
                # ⭐ 后端认定的**真目标所属框** `(cx, cy, w, h)`（全分辨率 ✓ 可能 None ✓）：
                #   演示窗的**唯一红框**直接用它 ⇒ 同一帧永远同一个答案 ✓（不受拖动方向影响 ✗）
                #   ⚠ **分离那一拍且圆按预测跑到了框外**（`_split_skip` ✓）⇒ 如实**不报**这格框 ✓
                #     （那一拍"目标已经不在框里"✓ 硬画红框就与"绿圈内接红框"打架 ✗ 见 `_step_track`）。
                "tbox": (self._tbox if (state == "track"
                                        and not getattr(self, "_split_skip", False)) else None),
                # ⭐ 目标**实际半径**（白块学得 ✓ 冻结 ✓）：演示窗的绿圈半径就用它 ✓
                #   （用户 2026-09-30："它代表**真实目标的实际半径**" ✓）
                "rad": getattr(self, "_rad", None),
                # ⭐⭐ **本拍红框是不是「融合框」**（面积 ≥ 「融合框判定阈值」× 标准面积 ✓
                #   用户 2026-10-01 新流程 ✓）：融合 ⇒ 不夹取、位置按预测走 ✓；
                #   给演示窗/自检看（画个标记 / 断言都方便 ✓）。
                "merged": bool(getattr(self, "_tbox_merged", False)),
                # ⭐⭐ **融合框生成**那一拍的日志（用户 2026-10-02 ✓ 原话："当融合框生成时添加
                #   日志，显示相关的砖以及解释判定为融合框的计算数据" ✓）⇒ 给演示窗底部那个
                #   深色日志区用 ✓；`_merge_first` 只在"进门那一拍"为真 ✓（保持期不给 ✗）。
                "merge_log": (self._build_merge_log()
                              if getattr(self, "_merge_first", False) else None),
                # ⭐⭐ **融合框消失（分离）**那一拍的日志（用户 2026-10-02 ✓ 原话："把融合框消失
                #   （分离）的日志**也依据融合的格式**打印出来" ✓）—— **与融合日志同一形状** ✓
                #   （`text` + `data` ✓），演示窗那个深色日志区**照原样一起显示** ✓；判据仍是
                #   `_target_box_state` 里那几条 ✓ 这里只组句子 ✗（口径一处 ✓）。
                #   `_merge_split` = 上一拍是融合框、这一拍不是（含"门内没得挑"/"缩成砖"/
                #   "检出框丢了"三种 ✓ 见它 ✓）。
                "split_log": (self._build_split_log()
                              if getattr(self, "_merge_split", False) else None),
                # ⭐⭐⭐ **融合期"每拍"的边归属**（用户 2026-10-02 ✓ 原话："日志里，融合时期
                #   每拍打印一下**边的归属（砖或真目标）**" ✓）—— 只在**这一拍红框确实是融合框**
                #   （`_tbox_merged` ✓ 含"融合保持"✓）时给 ✓；进门 / 分离那两拍另有 `merge_log`
                #   / `split_log` ✓ 三条互补 ✗（这条看的是"一拍拍怎么变"✓）。
                "edge_log": (self._build_edge_log()
                             if (self._tbox is not None
                                 and getattr(self, "_tbox_merged", False)) else None),
                # ⭐⭐⭐ **非融合红框选择**（用户 2026-10-03 ✓ 原话："在日志加一下**非融合红框
                #   选择**的判定信息吧" ✓）：这一拍**出了红框但不是融合框**时给 ✓（= 决策链上
                #   "**目标自己那格**"那一条 ✓，见 `_build_pick_log` ✓）—— 与 `merge_log` /
                #   `edge_log` / `split_log` **四条互补** ✓（门开那次改动的效果：帧 48 这种
                #   "分离后重新挑到目标自己那格"的红框，以前日志里**看不到**它凭什么被挑 ✓）。
                "pick_log": (self._build_pick_log()
                             if (self._tbox is not None
                                 and not getattr(self, "_tbox_merged", False)) else None),
                # ⭐⭐⭐ **本拍砖表快照**（用户 2026-10-03 ✓ 原话："点选检出框的时候，希望他能
                #   显示 **IoU 最大的砖的 IoU**" ✓）：演示窗点选某格时要按**那一帧**的砖表算
                #   最大 IoU ✓（砖表每拍都在动 ⇒ 不能用"演算结束时的表" ✗ 见 `_bricks_snap` ✓）。
                "bricks": self._bricks_snap(),
                # ⭐ 状态（S0 `ok` / S1 `merged` / S3 `gone` ✓）：诊断"框在不在、是不是融合" ✓
                "tst": getattr(self, "_tsus", None),
                # ⭐⭐ **未加工的"追踪器真实位置"**（全分辨率 ✓）= `_raw`（内部拟合位置 ✓
                #   还没过**超前补偿**、没过**拟人平滑** `_ease_pos` ✓）。
                #   用户 2026-09-30 认知 #3/#4 ✓ 原话："**绿点代表追踪器的真实位置**；如果
                #   绿点不在绿圈圆心了，说明是『**拟人平滑移动**』生效了，此时用**红点**标出
                #   绿圈圆心" ✓ ⇒ 演示窗：**绿点**画它 ✓、**绿圈**画 `pos`（报告位置 ✓）。
                "raw_pos": (None if self._raw is None
                            else (self._raw[0] / _SCALE, self._raw[1] / _SCALE)),
                # ⭐⭐ **纳入预测的轨迹**（用户 2026-10-01 ✓ 原话："用白色的线把纳入预测的轨迹
                #   画出来" ✓）：`_path_pred` 拟合的那条群体相对曲线（加工域 ✓）⇒ 演示窗画白线 ✓。
                "path_pts": self._path_viz(),
                # ⭐⭐ **假目标登记表的快照**（用户 2026-09-30："将登记的框做个标记显示出来我看看
                #   你登记的对不对" ✓）：每条含 `bid/x/y/w/h/hits/conf/cls/ok` ✓
                #   （`bid` = 出生砖位 ✓ 稳定身份 ✓ 见 `lie_registry.Entry.bid`；`ok=True` = 已做实 ✓）。
                #   **只读、不参与判位** ✓。
                "reg": self._reg.snapshot()}
